import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * 테스트: API 클라이언트 레코드의 메타데이터를 PUT으로 수정.
 * 
 * 이 테스트는 여러 메타데이터 필드(연락처 이메일, 설명, 공개키, 활성상태 등)의 수정 기능을 검증한다.
 * 1. 정상 생성된 API 클라이언트 레코드를 PUT으로 일부 메타데이터 수정
 * 2. 응답에 반영된지 확인하고, 데이터가 실제로 변했는지 검증
 * 3. 존재하지 않는 ID로 수정 요청시 404 에러 반환 확인
 * 4. 필수 필드 빠짐/형식 오류 포함시 400 등 검증 실패 응답 확인
 *
 * 과정:
 * 1) 신규 등록 (선행 조건)
 * 2) 부분 메타데이터 변경 PUT 요청 + 필드 단위 검증
 * 3) 비정상 ID로 PUT: 404 확인
 * 4) 필수 값 빠진/잘못된 body PUT: 400 등 검증
 */
export async function test_api_apiClient_update_and_handle_errors(
  connection: api.IConnection,
): Promise<void> {
  // 1. 선행: 정상 등록
  const created: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `test-client-${Date.now()}`,
      contact_email: `contact-${Date.now()}@test.io`,
      public_key: "test-public-key",
      description: "Original description"
    },
  });
  typia.assert(created);

  // 2. 정상 필드 수정 요청
  const updateBody = {
    contact_email: `updated-${Date.now()}@test.io`,
    description: "Updated description",
    public_key: "updated-public-key",
    is_active: false,
  } satisfies IApiClients.IUpdate;
  const updated: IApiClients = await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("contact_email 변경")(
    updateBody.contact_email
  )(updated.contact_email);
  TestValidator.equals("description 변경")(
    updateBody.description
  )(updated.description);
  TestValidator.equals("public_key 변경")(
    updateBody.public_key
  )(updated.public_key);
  TestValidator.equals("is_active 변경")(
    updateBody.is_active
  )(updated.is_active);

  // 3. 잘못된/존재하지 않는 id로 수정: 404
  await TestValidator.httpError("존재하지 않는 ID PUT 시 404 반환됨")(404)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: "ffffffff-ffff-ffff-ffff-ffffffffffff",
      body: updateBody,
    })
  );

  // 4. 필드 조건 위반/누락: 400 등, 이메일 형식 오류 등
  await TestValidator.httpError("이메일 형식이 올바르지 않으면 validation error")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: created.id,
      body: {
        ...updateBody,
        contact_email: "not-an-email-format"
      },
    })
  );
  await TestValidator.httpError("body payload가 아예 비었을 때 (모든 필드 누락)")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: created.id,
      // @ts-expect-error: body가 아예 없을 때
      body: {},
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * Validate soft deletion (deactivation) logic for API clients and confirm proper error handling with invalid IDs.
 *
 * This test ensures that API client records can be successfully soft deleted (marked inactive/deleted) and that errors are correctly produced when attempting deletion with non-existent IDs.
 *
 * 1. Create a new API client with valid onboarding information.
 * 2. Soft delete (deactivate) the API client by its ID.
 *    - Confirm response 'is_active' is false and 'deleted_at' is present (set).
 * 3. Attempt to soft delete an API client with an invalid/non-existing ID and expect an error (e.g., 404 Not Found).
 *
 * Business context: Soft deletion preserves record for auditing and disables further usage by the client. Only privileged users may perform such operations; compliance and correctness are critical.
 */
export async function test_api_client_soft_delete_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new API client
  const created: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `sdk-e2e-client-${Date.now()}`,
      contact_email: `e2e-test-client-${Math.random().toString(36).slice(2,10)}@wrtn.io`,
      public_key: "test-public-key-123456",
      description: "E2E SDK Test Client for soft delete",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(created);

  // 2. Soft delete the client by id
  const deleted: IApiClients = await api.functional.apiOmnichannel.apiClients.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("soft delete sets is_active to false")(false)(deleted.is_active);
  TestValidator.equals("soft delete sets deleted_at timestamp")(false)(!deleted.deleted_at);

  // 3. Attempt soft deletion with an invalid id
  const invalidId: string & tags.Format<"uuid"> = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
  await TestValidator.httpError("soft delete fails for non-existent id")(404)(() =>
    api.functional.apiOmnichannel.apiClients.eraseById(connection, { id: invalidId }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";
import { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";
import { IPageIApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIApiTokens";
import typia from "typia";

/**
 * Validate listing/searching API tokens with filters and pagination.
 *
 * This test ensures the token listing endpoint supports:
 * - Filtering by client, scope, status, date ranges
 * - Pagination mechanics
 * - Robustness to extreme paging/invalid filter values
 *
 * Steps:
 * 1. Register a new API client
 * 2. Issue multiple API tokens for the client (some active, some expired/revoked)
 * 3. Search all tokens (no filter) and check all created tokens appear, verify pagination
 * 4. Search by filters (client, scope, status, date range) and validate filtered results
 * 5. Try extreme pagination settings, check bounds and meta
 * 6. Send invalid filters (bad client ID, negative page), confirm error handling
 */
export async function test_api_token_list_and_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register new API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `test-client-${Date.now()}`,
      contact_email: `test${Date.now()}@wrtn.io`,
      public_key: "public-key-data",
      description: "E2E API token search test client",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Issue multiple tokens for this client
  const now = new Date();
  const tokens: IApiToken[] = [];
  for (let i = 0; i < 4; ++i) {
    const issued_at = new Date(now.getTime() - i * 3600_000).toISOString();
    const expires_at = new Date(now.getTime() + (24 + i) * 3600_000).toISOString();
    const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: {
        api_client_id: client.id,
        scope: i % 2 === 0 ? "read" : "write",
        issued_at: issued_at,
        expires_at: expires_at,
      } satisfies IApiToken.ICreate,
    });
    typia.assert(token);
    tokens.push(token);
  }
  // Revoke one of the tokens
  // (Assumption: There is a revoke endpoint or status, but we simulate by setting revoked_at manually for filter tests)
  const revokedToken: IApiToken = { ...tokens[0], revoked_at: new Date().toISOString() };
  tokens[0] = revokedToken;

  // 3. List/search tokens: no filter
  const allTokensResp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: { api_client_id: client.id } satisfies IApiTokens.IRequest,
  });
  typia.assert(allTokensResp);
  TestValidator.equals("all tokens present")(
    tokens.map(t => t.id).sort()
  )(
    allTokensResp.data
      .filter(t => t.api_client_id === client.id)
      .map(t => t.id)
      .sort()
  );

  // 4. Filter by scope
  for (const scope of ["read", "write"]) {
    const resp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: { api_client_id: client.id, scope } satisfies IApiTokens.IRequest,
    });
    typia.assert(resp);
    for (const t of resp.data) {
      TestValidator.equals("scope filtered")(scope)(t.scope);
      TestValidator.equals("api_client_id filtered")(client.id)(t.api_client_id);
    }
  }
  // 5. Filter by active/inactive (simulate: active=true excludes our manually-revoked token)
  {
    const activeResp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: { api_client_id: client.id, active: true } satisfies IApiTokens.IRequest,
    });
    typia.assert(activeResp);
    for (const t of activeResp.data) {
      TestValidator.equals("active-client")(client.id)(t.api_client_id);
      if (t.id === revokedToken.id) TestValidator.equals("active-revoked-excluded")(undefined)(t.revoked_at);
    }
    const inactiveResp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: { api_client_id: client.id, active: false } satisfies IApiTokens.IRequest,
    });
    typia.assert(inactiveResp);
    // Should include revoked
    TestValidator.equals("revoked-included")(
      true
    )(!!inactiveResp.data.find(x => x.id === revokedToken.id));
  }

  // 6. Date range: issued_from/issued_to
  {
    const issuedFrom = new Date(now.getTime() - 3600_000 * 2).toISOString();
    const resp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: { api_client_id: client.id, issued_from: issuedFrom } satisfies IApiTokens.IRequest,
    });
    typia.assert(resp);
    for (const t of resp.data) {
      TestValidator.equals("issued_from range")(true)(
        new Date(t.issued_at).getTime() >= new Date(issuedFrom).getTime(),
      );
    }
  }

  // 7. Extreme pagination
  {
    const resp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: {
        api_client_id: client.id,
        page: 1,
        limit: 2,
      } satisfies IApiTokens.IRequest,
    });
    typia.assert(resp);
    // Should either contain <=2
    TestValidator.equals("paginated limit <= 2")(true)(resp.data.length <= 2);
    TestValidator.equals("pagination meta")(
      resp.pagination.current
    )(1);
    TestValidator.equals("pagination meta limit")(
      resp.pagination.limit
    )(2);
  }
  // 8. Over-bounds page
  {
    const resp: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: {
        api_client_id: client.id,
        page: 1000,
        limit: 5,
      } satisfies IApiTokens.IRequest,
    });
    typia.assert(resp);
    TestValidator.equals("overbound page empty")(0)(resp.data.length);
  }

  // 9. Invalid filter: bad client ID
  await TestValidator.httpError("non-UUID client id filter ==> 400")(400)(() =>
    api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: {
        api_client_id: "bad-uuid" as any,
      } satisfies IApiTokens.IRequest,
    }),
  );
  // 10. Invalid pagination: negative page
  await TestValidator.httpError("negative page ==> 400")(400)(() =>
    api.functional.apiOmnichannel.apiTokens.patch(connection, {
      body: {
        api_client_id: client.id,
        page: -1 as any,
      } satisfies IApiTokens.IRequest,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";
import { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";

/**
 * Retrieve API token metadata by its ID, and validate error handling for non-existent tokens.
 *
 * This test covers both successful retrieval and negative case for the API token metadata fetch endpoint.
 *
 * Scenario Steps:
 * 1. Create a new API client (to associate a token with)
 * 2. Issue a new API token for that client
 * 3. Retrieve API token metadata by its ID; assert all returned fields and associations
 * 4. Attempt to retrieve API token metadata with a random/non-existent ID and expect an error
 *
 * This scenario confirms correctness of client-token linkage, field completeness, and error reporting for lookup failures.
 */
export async function test_api_token_get_metadata_by_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `Test App "${Date.now()}`,
      contact_email: `dev-${Math.random().toString(36).substr(2, 8)}@wrtn.io`,
      public_key: "MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEAtestkey==",
      description: "Integration test client",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Issue a new API token for the client
  const now = new Date();
  const issued_at = now.toISOString();
  const expires_at = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(); // +1 day

  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:sample write:sample",
      issued_at,
      expires_at,
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);

  // 3. Retrieve API token metadata by token ID
  const metadata: IApiTokens = await api.functional.apiOmnichannel.apiTokens.getById(connection, {
    id: token.id,
  });
  typia.assert(metadata);
  TestValidator.equals("api_client_id matches")(token.api_client_id)(metadata.api_client_id);
  TestValidator.equals("token_id matches")(token.id)(metadata.id);
  TestValidator.equals("scope matches")(token.scope)(metadata.scope);
  TestValidator.equals("issued_at matches")(token.issued_at)(metadata.issued_at);
  TestValidator.equals("expires_at matches")(token.expires_at)(metadata.expires_at);

  // 4. Negative case: Try to retrieve metadata for a random UUID (guaranteed absent)
  await TestValidator.httpError("non-existent token fetch")(404)(() =>
    api.functional.apiOmnichannel.apiTokens.getById(connection, {
      id: "00000000-0000-4000-8000-000000000000" as string & tags.Format<"uuid">,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Validate API token creation with constraint and field validation.
 *
 * This test covers creating a new API token for an API client, checking for duplication,
 * missing field, and foreign key(client) errors. It exercises token lifecycle and server-side rules.
 *
 * 1. Create a new API client to associate the token
 * 2. Create a new API token for that client with valid fields
 * 3. Attempt to create another token with the same data (if system allows, or check for error)
 * 4. Attempt to create token with missing required fields (should fail)
 * 5. Attempt to create a token with invalid (nonexistent) client id (should fail)
 */
export async function test_api_token_create_and_constraint_validation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create API client to attach tokens to
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `api-client-${Date.now()}`,
      contact_email: `client-${Date.now()}@test.com`,
      public_key: "-----BEGIN PUBLIC KEY-----MIIBIjANBgkqhkiG9w0BA...",
      description: "Test E2E client",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Create a new API token for that client
  const issuedAt = new Date().toISOString();
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString();
  const tokenReq: IApiToken.ICreate = {
    api_client_id: client.id,
    scope: "read:widgets,write:widgets",
    issued_at: issuedAt,
    expires_at: expiresAt,
  };
  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: tokenReq,
  });
  typia.assert(token);
  TestValidator.equals("api_client_id")(client.id)(token.api_client_id);

  // 3. Attempt duplicate token creation (depends on backend constraint policy)
  //    Some APIs allow multiple tokens, but we check for either success or error
  try {
    const duplicate: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: tokenReq,
    });
    typia.assert(duplicate); // If allowed, must be valid
    TestValidator.equals("dup api_client_id")(client.id)(duplicate.api_client_id);
  } catch (err) {
    // If error thrown, assert it's a proper error (constraint violation)
    TestValidator.error("duplicate token should throw or succeed")(err);
  }

  // 4. Missing required fields (should fail)
  await TestValidator.error("missing required field, api_client_id")(() =>
    api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: {
        // api_client_id missing
        scope: "read:widgets",
        issued_at: issuedAt,
        expires_at: expiresAt,
        // @ts-expect-error intentional missing
      } as any,
    }),
  );

  // 5. Invalid client id (should fail)
  await TestValidator.error("invalid client id")(() =>
    api.functional.apiOmnichannel.apiTokens.post(connection, {
      body: {
        api_client_id: "00000000-0000-4000-9999-ffffffffffff",
        scope: "read:widgets",
        issued_at: issuedAt,
        expires_at: expiresAt,
      } satisfies IApiToken.ICreate,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";
import typia, { tags } from "typia";

/**
 * E2E Test: Update an API token record by its ID
 *
 * This test validates the process of updating the metadata of an API token, ensuring updates persist correctly,
 * and that error scenarios (such as updating with an invalid or non-existent ID and invalid field values) are handled properly.
 *
 * Process:
 * 1. Create an API client (prerequisite for generating tokens)
 * 2. Create an API token for that client
 * 3. Update the API token metadata (scope, expiry)
 * 4. Attempt to update a non-existent/invalid token ID (should fail)
 * 5. Attempt to update with invalid field values (should fail)
 */
export async function test_api_token_update_metadata_with_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `e2e-client-${Date.now()}`,
      contact_email: `e2e-token-${Date.now()}@test.com`,
      description: "E2E test client for token update step",
      public_key: "test-public-key",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Create an API token for that client
  const issuedAt = new Date();
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24 * 30); // +30 days
  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:all write:all",
      issued_at: issuedAt.toISOString(),
      expires_at: expiresAt.toISOString(),
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);

  // 3. Update the API token metadata (e.g., scope and expiration)
  const newExpiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24 * 60); // +60 days
  const updatedScope = "read:partial";
  const updated: IApiToken = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      scope: updatedScope,
      expires_at: newExpiresAt.toISOString(),
    } satisfies IApiToken.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("id")(token.id)(updated.id);
  TestValidator.equals("scope")(updatedScope)(updated.scope);
  TestValidator.equals("expires_at")(newExpiresAt.toISOString())(updated.expires_at);

  // 4. Attempt to update a non-existent/invalid token ID
  await TestValidator.httpError("update with non-existent id")(404)(() =>
    api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">,
      body: {
        scope: "something",
      },
    })
  );

  // 5. Attempt to update with invalid field values (e.g., invalid expires_at)
  await TestValidator.httpError("update with invalid field values")(400)(() =>
    api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: token.id,
      body: {
        expires_at: "not-a-date" as string & tags.Format<"date-time">,
      },
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Revoke (soft-delete) an API token by its ID and verify it can no longer be used.
 *
 * This e2e test covers the full revocation flow:
 * 1. Create a new API client (for token ownership).
 * 2. Create an API token for the client.
 * 3. Revoke (soft-delete) the token by its id.
 * 4. Validate the token is marked as revoked (revoked_at should be set).
 * 5. Attempt to revoke the same token again, expecting an error as it is already revoked.
 * 6. Attempt to revoke a token using a non-existent/invalid id and expect a not found/invalid error.
 *
 * Background:
 * Revoking an API token is a critical security and audit process. Once revoked, the token must be unusable for API access, and its 'revoked_at' timestamp should preserve auditability, not allow physical deletion. Attempts to revoke invalid or previously deleted ids should produce clear error responses.
 */
export async function test_api_token_revoke_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create API client
  const apiClient: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `client_${Date.now()}`,
      contact_email: `api-tester-${Date.now()}@example.com`,
      public_key: "test-public-key-string",
      description: "E2E test client for token revoke test."
    } satisfies IApiClients.ICreate
  });
  typia.assert(apiClient);

  // 2. Create API token for the client
  const issued = new Date();
  const expires = new Date(issued.getTime() + 1000 * 60 * 60 * 24); // +1 day
  const apiToken: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: apiClient.id,
      scope: "read:all",
      issued_at: issued.toISOString(),
      expires_at: expires.toISOString()
    } satisfies IApiToken.ICreate
  });
  typia.assert(apiToken);
  // Confirm token is not yet revoked
  TestValidator.equals("revoked_at should be null")(null)(apiToken.revoked_at ?? null);

  // 3. Revoke (soft-delete) the token by id
  const revoked: IApiToken = await api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
    id: apiToken.id,
  });
  typia.assert(revoked);
  // revoked_at field should now be a valid date-time string
  if (!revoked.revoked_at)
    throw new Error("Token should be marked as revoked, but revoked_at is missing.");
  // Check that revoked_at is a valid ISO date
  expect(() => new Date(revoked.revoked_at!).toISOString()).not.toThrow();

  // 4. Attempt to revoke the token again - expect error (already revoked)
  await TestValidator.error("revoke an already revoked token should fail")(() =>
    api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
      id: apiToken.id
    })
  );

  // 5. Attempt to revoke a non-existent/invalid token id - expect not found/invalid error
  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("revoke with invalid token id should fail")(() =>
    api.functional.apiOmnichannel.apiTokens.eraseById(connection, {
      id: randomId,
    })
  );
}

