import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";

/**
 * Manually create a new API audit entry with both valid and invalid data.
 *
 * This test covers the API audit manual registration feature. It attempts to create an API audit entry with all required fields supplied properly (expecting success), and also attempts to create entries missing required fields or using invalid data (expecting validation errors).
 *
 * Steps:
 * 1. Prepare valid IApiAudit.ICreate data for all required fields.
 * 2. POST it to /apiOmnichannel/apiAudits and assert the response is IApiAudit and valid.
 * 3. Attempt request(s) omitting required field(s) (e.g., missing api_client_id, endpoint, status_code).
 * 4. Attempt with clearly invalid data (e.g., string instead of uuid, invalid http_method, non-boolean is_success, non-integer status_code, wrong date format, etc.).
 * 5. Validate server returns validation errors (HTTP 400+) for each invalid attempt.
 * 6. Optionally, list/search the api_audits to verify the successful entry appears.
 */
export async function test_api_api_audit_create_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare valid data
  const now = new Date();
  const valid: IApiAudit.ICreate = {
    api_client_id: typia.random<string & typia.tags.Format<"uuid">>(),
    api_token_id: typia.random<string & typia.tags.Format<"uuid">>(),
    endpoint: "/some/endpoint",
    http_method: "POST",
    actor_id: typia.random<string & typia.tags.Format<"uuid">>(),
    is_success: true,
    status_code: 200,
    created_at: now.toISOString(),
  };
  // 2. POST valid entry
  const created: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(
    connection,
    {
      body: valid,
    },
  );
  typia.assert(created);
  // Check important fields are echoed correctly
  TestValidator.equals("api_client_id")(valid.api_client_id)(created.api_client_id);
  TestValidator.equals("endpoint")(valid.endpoint)(created.endpoint);
  TestValidator.equals("status_code")(valid.status_code)(created.status_code);

  // 3. Missing required fields
  const missingApiClient = { ...valid };
  // @ts-expect-error purposely unset required field
  delete missingApiClient.api_client_id;
  await TestValidator.httpError("missing api_client_id")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: missingApiClient }),
  );

  const missingEndpoint = { ...valid };
  // @ts-expect-error purposely unset required field
  delete missingEndpoint.endpoint;
  await TestValidator.httpError("missing endpoint")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: missingEndpoint }),
  );

  // 4. Clearly invalid data
  // Invalid UUID
  const badUuid = { ...valid, api_client_id: "not-a-uuid" };
  await TestValidator.httpError("invalid api_client_id uuid")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: badUuid }),
  );
  // Invalid is_success
  const nonBoolSuccess = { ...valid, is_success: "yes" as any };
  await TestValidator.httpError("non-bool is_success")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: nonBoolSuccess }),
  );
  // Invalid status_code
  const nonIntStatus = { ...valid, status_code: "two-hundred" as any };
  await TestValidator.httpError("non-integer status_code")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: nonIntStatus }),
  );
  // Invalid created_at
  const invalidDatetime = { ...valid, created_at: "yesterday" };
  await TestValidator.httpError("invalid created_at date")(400)(() =>
    api.functional.apiOmnichannel.apiAudits.post(connection, { body: invalidDatetime }),
  );
  // 5. (Optional) Listing to verify appears in log (no endpoint provided)
  // If a `get`/list endpoint is available, implement appearance check here.
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";
import typia, { tags } from "typia";

/**
 * Update metadata in an existing API audit entry by ID and cover edge/error cases.
 *
 * This test covers core update, persistence check, and error/edge scenarios for an API audit log entry.
 * Steps:
 * 1. Create an audit entry using POST /apiOmnichannel/apiAudits
 * 2. Update the entry via PUT /apiOmnichannel/apiAudits/{id} with valid data
 * 3. Attempt update with non-existent or invalid UUID (expect error)
 * 4. Attempt malformed or forbidden field updates (expect schema error)
 *
 * - All responses are validated with typia.assert
 * - Error cases use TestValidator for status and message confirmation
 * - Mainline (normal) update is checked for persistence (fields reflect update)
 */
export async function test_update_api_audit_entry_by_id_and_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an audit entry to update
  const original: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(
    connection,
    {
      body: {
        api_client_id: typia.random<string & tags.Format<"uuid">>(),
        api_token_id: typia.random<string & tags.Format<"uuid">>(),
        integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
        endpoint: "/v1/test/path",
        http_method: "PUT",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        request_hash: "req-hash-v1",
        response_hash: "resp-hash-v1",
        is_success: true,
        status_code: 201,
        created_at: new Date().toISOString(),
      } satisfies IApiAudit.ICreate,
    },
  );
  typia.assert(original);

  // 2. Update allowed metadata fields of the entry
  const updateBody: IApiAudit.IUpdate = {
    api_client_id: original.api_client_id,
    api_token_id: original.api_token_id,
    integration_channel_id: original.integration_channel_id,
    endpoint: "/v1/test/updated",
    http_method: "POST",
    actor_id: original.actor_id,
    decision_log_id: typia.random<string & tags.Format<"uuid">>(),
    request_hash: "req-hash-updated",
    response_hash: "resp-hash-updated",
    is_success: false,
    status_code: 500,
    created_at: original.created_at,
  };
  const updated: IApiAudit = await api.functional.apiOmnichannel.apiAudits.putById(connection, {
    id: original.id,
    body: updateBody,
  });
  typia.assert(updated);
  // Check main mutable fields were changed
  TestValidator.equals("endpoint update")(updateBody.endpoint)(updated.endpoint);
  TestValidator.equals("http_method update")(updateBody.http_method)(updated.http_method);

  // 3. Attempt to update with a non-existent ID
  await TestValidator.httpError("not found audit entry")(404)(() =>
    api.functional.apiOmnichannel.apiAudits.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // very likely not found
      body: updateBody,
    }),
  );

  // 4. Attempt malformed/bad update (missing required field)
  const malformedBody = { ...updateBody };
  // Required: endpoint. So remove it:
  // @ts-expect-error
  delete malformedBody.endpoint;
  await TestValidator.error("missing endpoint required field")(() =>
    api.functional.apiOmnichannel.apiAudits.putById(connection, {
      id: original.id,
      // @ts-expect-error
      body: malformedBody,
    }),
  );

  // 4b. Extra property not allowed
  const withExtra = { ...updateBody, forbidden_field: 12345 } as any;
  await TestValidator.error("forbidden field should not be accepted")(() =>
    api.functional.apiOmnichannel.apiAudits.putById(connection, {
      id: original.id,
      body: withExtra,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";

/**
 * Validate soft-deletion of an API audit entry and error handling for repeated or invalid deletions.
 *
 * This test ensures that a newly created API audit entry can be soft-deleted via eraseById,
 * and that further attempts to delete the same entry or a non-existent one yield appropriate errors.
 * The test fulfills regulatory and compliance requirements without physically removing records.
 *
 * Scenario Steps:
 * 1. Create an API audit entry to act as the deletion target.
 * 2. Soft-delete the created audit entry by its ID.
 * 3. Attempt to soft-delete the same audit entry again; expect an error.
 * 4. Attempt to soft-delete a non-existent (random) UUID; expect an error.
 */
export async function test_api_audit_soft_delete_and_inaccessible_afterwards(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an API audit entry
  const createBody: IApiAudit.ICreate = typia.random<IApiAudit.ICreate>();
  const audit: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(
    connection,
    { body: createBody },
  );
  typia.assert(audit);

  // 2. Soft-delete the created audit entry
  const deleted: IApiAudit = await api.functional.apiOmnichannel.apiAudits.eraseById(
    connection,
    { id: audit.id },
  );
  typia.assert(deleted);
  TestValidator.equals("deleted ID matches")(audit.id)(deleted.id);

  // 3. Attempt to delete same entry again - expect error
  await TestValidator.httpError("repeat delete should fail")(404)(() =>
    api.functional.apiOmnichannel.apiAudits.eraseById(connection, { id: audit.id })
  );

  // 4. Attempt to delete a completely non-existent record
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("deletion of non-existent should fail")(404)(() =>
    api.functional.apiOmnichannel.apiAudits.eraseById(connection, { id: nonExistentId })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
