/**
 * Test listing and searching integration channel records with filter, sort and pagination.
 *
 * This test validates that the list/search endpoint for IntegrationChannel supports:
 * - Population with new test channels
 * - Simple and advanced filter options (channel_code, channel_name, is_active, created_at)
 * - Sort order by various fields (channel_name, created_at, channel_code), asc/desc
 * - Pagination (page, limit) and edge cases (out-of-range)
 * - Graceful error handling for invalid filters
 * - That no data leaks across queries and returned objects match request criteria
 *
 * Steps:
 * 1. Create several unique integration channels
 * 2. List all channels – expect all created
 * 3. Filter by channel_code, expect single exact
 * 4. Filter by partial channel_name, expect correct subset
 * 5. Filter by is_active
 * 6. Filter with created_at window
 * 7. Sort results by various fields and orders
 * 8. Paginate through channels (verify totals and non-overlap)
 * 9. Edge case: page beyond total – expect empty
 * 10. Invalid filter – expect error
 */
export async function test_api_integration_channel_list_and_search_with_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare test data: Create several unique integration channels
  const testChannels: IIntegrationChannel[] = [];
  for (let i = 0; i < 4; ++i) {
    const code = `testcode_${Date.now()}_${i}`;
