    const channel = await api.functional.apiOmnichannel.integrationChannels.post(connection, { body: input });
    typia.assert(channel);
    testChannels.push(channel);
  }

  // Find the latest created_at timestamp
  const latestCreatedAt = testChannels.reduce((a, c) => a > c.created_at ? a : c.created_at, testChannels[0].created_at);

  // 2. List all channels (no filter) – expect at least those just created
  const listAll = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: {} });
  typia.assert(listAll);
  // Must contain all created test channels
  for (const test of testChannels) {
    TestValidator.equals("all channels contains test channel")(
      true
    )(!!listAll.data.find((c) => c.id === test.id));
  }

  // 3. Filter by channel_code (exact search)
  const byCode = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { channel_code: testChannels[0].channel_code } },
  });
  typia.assert(byCode);
  TestValidator.equals("filter by exact channel_code has 1")(
    1
  )(byCode.data.length);
  TestValidator.equals("code matches")(
    testChannels[0].channel_code
  )(byCode.data[0].channel_code);

  // 4. Filter by partial channel_name
  const partialName = testChannels[1].channel_name.slice(0, 8);
  const byPartialName = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { channel_name: partialName } },
  });
  typia.assert(byPartialName);
  TestValidator.equals("partial channel_name filter yields some result")(
    true
  )(byPartialName.data.length >= 1);

  // 5. Filter by is_active (should be true for just-created records)
  const byActive = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { is_active: true } },
  });
  typia.assert(byActive);
  TestValidator.equals("all is_active true")(
    true
  )(byActive.data.every((r) => r.is_active === true));

  // 6. Filter using created_at window
  const byCreatedWindow = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { filters: { created_at: { from: testChannels[0].created_at, to: latestCreatedAt } } },
  });
  typia.assert(byCreatedWindow);
  TestValidator.equals("window includes these test channels")(
    true
  )(testChannels.every((ch) => byCreatedWindow.data.some((r) => r.id === ch.id)));

  // 7. Sort by channel_name desc, channel_code asc
  const bySortNameDesc = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { sort: { by: "channel_name", order: "desc" } },
  });
  typia.assert(bySortNameDesc);
  const sorted = [...bySortNameDesc.data].sort((a, b) => b.channel_name.localeCompare(a.channel_name));
  TestValidator.equals("sort by channel_name desc")(
    sorted.map((v) => v.id)
  )(bySortNameDesc.data.map((v) => v.id));

  const bySortCodeAsc = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { sort: { by: "channel_code", order: "asc" } },
  });
  typia.assert(bySortCodeAsc);
  const sortedCode = [...bySortCodeAsc.data].sort((a, b) => a.channel_code.localeCompare(b.channel_code));
  TestValidator.equals("sort by channel_code asc")(
    sortedCode.map((v) => v.id)
  )(bySortCodeAsc.data.map((v) => v.id));

  // 8. Pagination – get page 1, then 2 (limit 2)
  const firstPage = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { pagination: { page: 1, limit: 2 } },
  });
  typia.assert(firstPage);
  TestValidator.equals("pagination: 1st page size")(
    2
  )(firstPage.data.length);

  const secondPage = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { pagination: { page: 2, limit: 2 } },
  });
  typia.assert(secondPage);
  // Ensure no overlap between page 1 and 2
  const page1Ids = new Set(firstPage.data.map((c) => c.id));
  const page2Ids = new Set(secondPage.data.map((c) => c.id));
  TestValidator.equals("no overlap page 1/2")(
    0
  )([...page1Ids].filter((id) => page2Ids.has(id)).length);

  // 9. Edge: page out-of-range
  const outOfRange = await api.functional.apiOmnichannel.integrationChannels.patch(connection, {
    body: { pagination: { page: 9999, limit: 2 } },
  });
  typia.assert(outOfRange);
  TestValidator.equals("out-of-range yields none or empty")(
    0
  )(outOfRange.data.length);

  // 10. Invalid filter (wrong type)
  await TestValidator.httpError("invalid filter fails validation or errors")(400)(async () => {
    await api.functional.apiOmnichannel.integrationChannels.patch(
      connection,
      { body: { filters: { is_active: "notabool" as any } } }
    );
  });
}

