export async function test_api_integration_channel_update_and_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create integration channel
  const baseChannelName = `Test Channel ${Date.now()}`;
  const createBody: IIntegrationChannel.ICreate = {
    channel_code: `code_${Math.random().toString(36).slice(2)}`,
    channel_name: baseChannelName,
  };
  const created: IIntegrationChannel = await api.functional.apiOmnichannel.integrationChannels.post(connection, { body: createBody });
  typia.assert(created);
  TestValidator.equals("create.channel_name")(baseChannelName)(created.channel_name);

  // 2. Update channel metadata: name, is_active
  const newChannelName = `${baseChannelName} Updated`;
  const updateBody: IIntegrationChannel.IUpdate = {
    channel_name: newChannelName,
    is_active: !created.is_active,
  };
  const updated: IIntegrationChannel = await api.functional.apiOmnichannel.integrationChannels.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("update.channel_name")(newChannelName)(updated.channel_name);
  TestValidator.equals("update.is_active")(!created.is_active)(updated.is_active);
  TestValidator.equals("update.id")(created.id)(updated.id);

  // 3. Try updating with an invalid/non-existent ID
  const fakeId = typia.random<string & typia.tags.Format<"uuid">>();
  await TestValidator.httpError("update not found")(404)(() =>
    api.functional.apiOmnichannel.integrationChannels.putById(connection, {
      id: fakeId,
      body: updateBody,
    })
  );

  // 4. Try update with a malformed payload (e.g. empty object)
  await TestValidator.httpError("update: empty payload")(400)(() =>
    api.functional.apiOmnichannel.integrationChannels.putById(connection, {
      id: created.id,
      body: {} as IIntegrationChannel.IUpdate,
    })
  );

  // Try update with disallowed/extra fields
  // (payload includes channel_code, which is not updatable by contract)
  await TestValidator.httpError("update: forbidden field")(400)(() =>
    api.functional.apiOmnichannel.integrationChannels.putById(connection, {
      id: created.id,
      body: {
        channel_name: "Should fail",
        // @ts-expect-error channel_code is forbidden on update
        channel_code: "malicious_code",
      } as any,
    })
  );
}

