import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";
import { IPageIChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIChannelSession";

/**
 * E2E test: List, filter, and paginate channel sessions.
 *
 * Validates the /apiOmnichannel/channelSessions PATCH endpoint returns correct paginated, filterable results, and errors for invalid requests. Full scenario:
 *
 * 1. Populate test DB by creating multiple channel sessions with varied integration_channel_id, api_token_id, user_id, and session_key fields.
 * 2. Retrieve all sessions with default (empty) search, confirming created sessions are present and pagination metadata is valid.
 * 3. Filter by integration_channel_id, api_token_id, user_id, session_key, confirming responses match expected sessions.
 * 4. Paginate using limit and page; check correct slicing and metadata.
 * 5. Paginate with excessively high page number; expect empty data.
 * 6. Use invalid pagination (page<1, limit>1000, limit<1) and invalid filter formats; expect error or clamping.
 * 7. Type-check and assert structure for all responses.
 * 8. Revalidate each step for compliance with scenario and type correctness.
 */
export async function test_api_channel_session_list_and_search_with_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create N (e.g., 3) sessions with distinct properties for later filtering.
  const sessions: IChannelSession[] = [];
  for (let i = 0; i < 3; i++) {
    const base = typia.random<IChannelSession.ICreate>();
    // purposely tweak for each
    base.integration_channel_id = typia.random<string & typia.tags.Format<"uuid">>();
    base.api_token_id = typia.random<string & typia.tags.Format<"uuid">>();
    base.session_key = `session-key-${i}-${Date.now()}`;
    if (i % 2 === 0) base.user_id = typia.random<string & typia.tags.Format<"uuid">>();
    else base.user_id = null;

    const created = await api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: base,
    });
    typia.assert(created);
    sessions.push(created);
  }

  // 2. Retrieve all sessions, no filter, default pagination
  const allResult = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  TestValidator.equals("pagination type")(typeof allResult.pagination, "object");
  for (const s of sessions) {
    TestValidator.equals("session present")(true)(allResult.data.some(d => d.id === s.id));
  }

  // 3. Filter by integration_channel_id
  const byChannel = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { filters: { integration_channel_id: sessions[0].integration_channel_id } },
  });
  typia.assert(byChannel);
  TestValidator.equals("all match integration_channel_id")(true)(byChannel.data.every(s => s.integration_channel_id === sessions[0].integration_channel_id));

  // 4. Filter by api_token_id
  const byToken = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { filters: { api_token_id: sessions[1].api_token_id } },
  });
  typia.assert(byToken);
  TestValidator.equals("all match api_token_id")(true)(byToken.data.every(s => s.api_token_id === sessions[1].api_token_id));

  // 5. Filter by user_id (handle null)
  const uidTest = sessions[2].user_id;
  const byUser = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { filters: { user_id: uidTest } },
  });
  typia.assert(byUser);
  TestValidator.equals("all match user_id")(true)(byUser.data.every(s => s.user_id === uidTest));

  // 6. Filter by session_key (should get only one)
  const key = sessions[1].session_key;
  const byKey = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { filters: { session_key: key } },
  });
  typia.assert(byKey);
  TestValidator.equals("filtered by session_key len")(byKey.data.length)(1);
  TestValidator.equals("session id matches")(byKey.data[0].id)(sessions[1].id);

  // 7. Paginate with limit=1, page=2 (should get second session if sorted by default order)
  const paged = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { pagination: { limit: 1, page: 2 } },
  });
  typia.assert(paged);
  TestValidator.equals("limit")(paged.pagination.limit)(1);
  TestValidator.equals("page")(paged.pagination.current)(2);
  // Data array length is 1 or 0 if now empty
  TestValidator.equals("length 0 or 1")(paged.data.length <= 1)(true);

  // 8. Paginate out-of-bounds (page >> max)
  const hugePage = await api.functional.apiOmnichannel.channelSessions.patch(connection, {
    body: { pagination: { limit: 1, page: 1000 } },
  });
  typia.assert(hugePage);
  TestValidator.equals("empty data for huge page")(hugePage.data.length)(0);

  // 9. Invalid limit (negative)
  await TestValidator.httpError("invalid limit")(400)(() =>
    api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { limit: -10, page: 1 } },
    })
  );

  // 10. Invalid page (zero)
  await TestValidator.httpError("invalid page")(400)(() =>
    api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { limit: 1, page: 0 } },
    })
  );

  // 11. Excessive limit (should result in error or at least clamp to max 1000)
  await TestValidator.httpError("limit too high")(400)(() =>
    api.functional.apiOmnichannel.channelSessions.patch(connection, {
      body: { pagination: { limit: 2000, page: 1 } },
    })
  );
}

