 * 2. Verify output fields and type correctness.
 * 3. Attempt to create session omitting a required field (e.g., missing session_key): expect validation error.
 * 4. Attempt to create session with invalid UUID in integration_channel_id/api_token_id: expect error.
 * 5. Attempt to create session with bad started_at (non-ISO format): expect error.
 * 6. Create session with duplicate session_key: expect uniqueness/duplication error if enforced.
 */
export async function test_api_channel_session_creation_and_validation(
  connection: api.IConnection
): Promise<void> {
  // 1. Create a valid session
  const validInput: IChannelSession.ICreate = {
    integration_channel_id: typia.random<string & typia.tags.Format<"uuid">>(),
    api_token_id: typia.random<string & typia.tags.Format<"uuid">>(),
