    api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: badStartedAtInput,
    })
  );

  // 6. Duplicate session_key (if system enforces uniqueness)
  const dupeSessionKeyInput = { ...validInput, session_key: validInput.session_key };
  await TestValidator.error("duplicate session_key")(() =>
    api.functional.apiOmnichannel.channelSessions.post(connection, {
      body: dupeSessionKeyInput,
    })
  );
}

