import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";

/**
 * Update a channel session and validate field changes, including error handling.
 *
 * This scenario ensures that an omnichannel session can be updated for valid, allowed fields only, and that persistence holds. Negative cases include updating a non-existent session and sending an invalid payload.
 *
 * 1. Create a channel session via POST (/apiOmnichannel/channelSessions).
 * 2. Update the created session's allowed fields (user_id and/or ended_at) via PUT (/apiOmnichannel/channelSessions/{id}) and confirm changes took effect.
 * 3. Attempt to update a session with a non-existent id; expect appropriate error.
 * 4. Attempt to update with an invalid payload (illegal fields, etc.); expect validation error.
 */
export async function test_api_channel_session_update_and_error_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new channel session
  const createInput: IChannelSession.ICreate = {
    integration_channel_id: typia.random<string & typia.tags.Format<"uuid">>(),
    api_token_id: typia.random<string & typia.tags.Format<"uuid">>(),
    user_id: typia.random<string & typia.tags.Format<"uuid">>(),
    session_key: `session_${Math.random().toString(36).substring(2,10)}`,
    started_at: new Date().toISOString(),
  };
  const session: IChannelSession = await api.functional.apiOmnichannel.channelSessions.post(connection, { body: createInput });
  typia.assert(session);

  // 2. Update allowed fields (user_id, ended_at)
  const newUserId = typia.random<string & typia.tags.Format<"uuid">>();
  const newEndedAt = new Date(Date.now() + 60000).toISOString();
  const updateInput: IChannelSession.IUpdate = {
    user_id: newUserId,
    ended_at: newEndedAt,
  };
  const updated: IChannelSession = await api.functional.apiOmnichannel.channelSessions.putById(connection, {
    id: session.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("updated user_id")(newUserId)(updated.user_id);
  TestValidator.equals("updated ended_at")(newEndedAt)(updated.ended_at);

  // 3. Try to update a non-existent session; expect error
  const nonExistentId = typia.random<string & typia.tags.Format<"uuid">>() + "-notfound";
  await TestValidator.httpError("update non-existent session")(404)(() =>
    api.functional.apiOmnichannel.channelSessions.putById(connection, {
      id: nonExistentId as any,
      body: updateInput,
    })
  );

  // 4. Try to update with invalid payload (illegal field)
  await TestValidator.error("update with invalid payload")(() =>
    api.functional.apiOmnichannel.channelSessions.putById(connection, {
      id: session.id,
      body: {
        not_a_field: "bad" // property not allowed per DTO
      } as any,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";
import typia, { tags } from "typia";

/**
 * Delete (soft-delete/end) a specific channel session by its ID and validate error scenarios.
 *
 * 1. Create a channel session to obtain a valid test target.
 * 2. Delete (soft-delete) the channel session by ID and verify response.
 * 3. Attempt deletion with an invalid (random/non-existent) session ID and expect error.
 * 4. Attempt deletion again on the just-ended session and expect appropriate error.
 */
export async function test_soft_delete_channel_session_and_handle_invalid_case(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new channel session
  const session: IChannelSession = await api.functional.apiOmnichannel.channelSessions.post(connection, {
    body: {
      integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
      api_token_id: typia.random<string & tags.Format<"uuid">>(),
      user_id: null,
      session_key: `test-session-key-${Math.random().toString(36).substring(2, 10)}`,
      started_at: new Date().toISOString(),
    } satisfies IChannelSession.ICreate,
  });
  typia.assert(session);

  // 2. Delete the created channel session
  const deleted: IChannelSession.IDelete = await api.functional.apiOmnichannel.channelSessions.eraseById(connection, {
    id: session.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(session.id)(deleted.id);
  TestValidator.equals("status should indicate archive or end")(
    true,
  )([
    "archived",
    "ended",
    "deleted"
  ].includes(deleted.status));

  // 3. Attempt to delete with a random/non-existent session id
  await TestValidator.httpError("delete non-existent session")(404)(() =>
    api.functional.apiOmnichannel.channelSessions.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. Attempt to delete the already-deleted session
  await TestValidator.httpError("delete already-ended session")(404)(() =>
    api.functional.apiOmnichannel.channelSessions.eraseById(connection, {
      id: session.id,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import typia from "typia";
import api from "@ORGANIZATION/PROJECT-api";
import { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";
import { IPageIWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIWebhookEvent";

/**
 * Validate listing, searching, filtering, and pagination of webhook event records.
 *
 * This test verifies that lists of webhook events are retrievable and filterable
 * by all exposed criteria, including event_type, delivery_status, channel, URL,
 * hash, and creation date range. It also checks pagination, including boundaries
 * and error handling for invalid input.
 *
 * Steps:
 * 1. Create multiple webhook events with different values for event_type,
 *    delivery_status (by overriding default post-create), channel, URLs, and
 *    event_hash to set up test data.
 * 2. List all webhook events and validate the pagination metadata.
 * 3. Search by event_type and validate only relevant events are returned.
 * 4. Filter by delivery_status and integration_channel_id and confirm correct subsets.
 * 5. Search with created_from/created_to range and check time window logic.
 * 6. Paginate the list using different pages/limits and assert page meta/data match.
 * 7. Use bad values (invalid UUID, impossible status, negative page/limit, etc.)
 *    and confirm correct error responses or empty lists as required.
 */
export async function test_api_webhook_event_list_and_search_with_varied_criteria(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create test data: multiple webhook events with variable properties
  const testEvents: IWebhookEvent[] = [];

  // Use 3 distinct integration channels
  const integrationChannels = [
    "818e5105-8fa1-46e8-9322-d6b848a1b0c0",
    "9f6e54d2-a8c6-44b2-927f-ed2809efcb3d",
    "1d5d5add-5b02-4c63-9bd7-6a041d4f9f91"
  ];
  const eventTypes = ["order.updated", "payment.completed", "user.created"];
  const deliveryStatusVariants: Array<IWebhookEvent["delivery_status"]> = ["pending", "success", "failed"];

  for (let i = 0; i < 7; i++) {
    const event: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id: integrationChannels[i % integrationChannels.length],
        event_type: eventTypes[i % eventTypes.length],
        destination_url: `https://webhook-test${i}.example.com/receiver`,
        event_hash: `evidence-hash-${i}`,
      } satisfies IWebhookEvent.ICreate,
    });
    typia.assert(event);
    testEvents.push(event);
  }

  // 2. List all - basic pagination (default)
  const allEvents: IPageIWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {}
  });
  typia.assert(allEvents);
  TestValidator.equals("all-records-count")(allEvents.pagination.records >= 7)(true);
  TestValidator.equals("all-events-listed")(allEvents.data.length >= 7)(true);

  // 3. Search/filter by event_type
  const filterType = eventTypes[0];
  const filteredTypeRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { event_type: filterType },
  });
  typia.assert(filteredTypeRes);
  filteredTypeRes.data.forEach(ev => TestValidator.equals("event_type match")(ev.event_type)(filterType));

  // 4. Search/filter by integration_channel_id and delivery_status (should exist in test data)
  const filterChannel = integrationChannels[1];
  const filterStatus: IWebhookEvent["delivery_status"] = "pending"; // all newly created will be 'pending'
  const filteredChannelStatus = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id: filterChannel, delivery_status: filterStatus },
  });
  typia.assert(filteredChannelStatus);
  filteredChannelStatus.data.forEach(ev => {
    TestValidator.equals("channel id")(ev.integration_channel_id)(filterChannel);
    TestValidator.equals("delivery status")(ev.delivery_status)(filterStatus);
  });

  // 5. Date window filter: created_from and created_to (using current event timestamps)
  const now = new Date();
  const rangeFrom = new Date(now.getTime() - 60 * 60 * 1000).toISOString();
  const rangeTo = new Date(now.getTime() + 60 * 60 * 1000).toISOString();
  const filteredDateWindow = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { created_from: rangeFrom, created_to: rangeTo },
  });
  typia.assert(filteredDateWindow);
  filteredDateWindow.data.forEach(ev => {
    const createdAt = new Date(ev.created_at).getTime();
    TestValidator.equals("created_at within range")(
      createdAt >= new Date(rangeFrom).getTime() && createdAt <= new Date(rangeTo).getTime()
    )(true);
  });

  // 6. Pagination: get first page with tight limit
  const paginated = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(paginated);
  TestValidator.equals("page")(paginated.pagination.current)(1);
  TestValidator.equals("limit")(paginated.pagination.limit)(2);
  TestValidator.equals("data length")(paginated.data.length <= 2)(true);

  // 7. Invalid filters: bad UUID
  await TestValidator.httpError("invalid integration_channel_id format")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { integration_channel_id: "not-a-uuid" as any },
    })
  );

  // 8. Impossible delivery_status
  await TestValidator.httpError("invalid delivery_status enum")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { delivery_status: "unknown-status" as any },
    })
  );

  // 9. Pagination: negative/zero values
  await TestValidator.httpError("negative page")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { page: -1 },
    })
  );
  await TestValidator.httpError("zero limit")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { limit: 0 },
    })
  );
  await TestValidator.httpError("negative limit")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { limit: -10 },
    })
  );
  await TestValidator.httpError("absurdly large limit")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { limit: 999999999 },
    })
  );
}

