import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Validate updating webhook event metadata and error handling for invalid updates.
 *
 * This test verifies full lifecycle and security of webhook event update:
 * 1. Create a valid webhook event (using POST).
 * 2. Successfully update delivery state (PUT) – increment attempt count, mark status as 'success', provide appropriate timestamps.
 * 3. Check returned event fields, confirm persistence of changes.
 * 4. Attempt to update using an invalid (non-existent or malformed) ID – expect HTTP error.
 * 5. Attempt update with forbidden or obviously invalid values in the payload – expect HTTP error.
 * All steps check type safety and response bodies for audit trace correctness.
 */
export async function test_update_webhook_event_metadata_and_handle_errors(connection: api.IConnection): Promise<void> {
  // 1. Create a valid webhook event
  const eventCreate: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.updated",
    destination_url: "https://webhook-receiver.test/update",
    event_hash: "event-hash-test-12345",
  };
  const event: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, { body: eventCreate });
  typia.assert(event);

  // 2. Update delivery state (e.g., mark as delivered, increment attempts)
  const now = new Date();
  const updatePayload: IWebhookEvent.IUpdate = {
    delivery_status: "success",
    attempt_count: (event.attempt_count ?? 0) + 1,
    last_attempted_at: now.toISOString(),
    delivered_at: now.toISOString(),
  };
  const updated: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
    id: event.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("delivery_status")("success")(updated.delivery_status);
  TestValidator.equals("attempt_count")((event.attempt_count ?? 0) + 1)(updated.attempt_count);
  TestValidator.equals("last_attempted_at")(updatePayload.last_attempted_at)(updated.last_attempted_at);
  TestValidator.equals("delivered_at")(updatePayload.delivered_at)(updated.delivered_at);

  // 3. Verifying changed fields are persisted
  // (persistence via another GET would be preferred in a full workflow, but only update/PUT returns present)

  // 4. Attempt update with invalid/malformed ID (should fail)
  await TestValidator.httpError("update with bad ID")(404)(() =>
    api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">,
      body: updatePayload,
    })
  );

  // 5. Attempt update with forbidden payload values (e.g. negative attempts)
  await TestValidator.httpError("update with negative attempt_count")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: event.id,
      body: {
        attempt_count: -2,
      },
    })
  );
  // Optional: More forbidden checks (missing all fields, invalid enum etc)
  await TestValidator.httpError("update with bad delivery_status value")(400)(() =>
    api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: event.id,
      body: {
        delivery_status: "delivered" as any, // not allowed, must be pending/success/failed
      },
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";
import typia, { tags } from "typia";

/**
 * Delete (archive/soft delete) a webhook event by its ID, verifying it is archived for compliance.
 * Also, attempt to delete with an invalid or already-archived ID and check for correct error handling.
 *
 * Scenario Steps
 * 1. Create a webhook event (for deletion test).
 * 2. Delete (soft-delete/archive) the webhook event by its ID.
 * 3. Verify the response contains correct archive information (archived_at/status).
 * 4. Attempt to delete the event again (should fail/return error or indicate already archived).
 * 5. Attempt to delete using invalid (random UUID) ID (should return error).
 */
export async function test_api_webhook_event_delete_and_validate_archival_behavior(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a webhook event
  const createBody: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.updated",
    destination_url: "https://dummy-receiver-webhook-test.io/receiver",
    event_hash: "abcdef012345678998776655112233445544",
  };
  const event: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, { body: createBody });
  typia.assert(event);

  // 2. Delete (archive) the webhook event
  const deleted: IWebhookEvent.IDelete = await api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
    id: event.id,
  });
  typia.assert(deleted);

  // 3. Validate archive response
  TestValidator.equals("archival event id")(event.id)(deleted.id);
  // Expect status to be 'archived' or similar per domain
  TestValidator.equals("archived status")("archived")(deleted.status);
  // archived_at should be an ISO8601 string (date-time)
  TestValidator.type("archived_at is date-time")("string")(typeof deleted.archived_at);

  // 4. Attempt to delete again (should fail, as already archived)
  await TestValidator.httpError("delete already-archived event")
    (404)(() =>
      api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
        id: event.id,
      })
    );

  // 5. Attempt to delete using invalid (random UUID)
  const fakeId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("delete non-existent event")
    (404)(() =>
      api.functional.apiOmnichannel.webhookEvents.eraseById(connection, {
        id: fakeId,
      })
    );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAITrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAITrainingData";
import typia from "typia";

/**
 * Validate creation of a new AI training dataset with a variety of input scenarios.
 *
 * This test ensures the correct behavior and validations when registering a new
 * AI training dataset registry entry. It covers successful creation, field-level
 * validation, and uniqueness enforcement on (name, version, source_uri).
 *
 * Steps:
 * 1. Create a valid AI training dataset (all required fields present and correct)
 * 2. Confirm the response matches IAITrainingData type, and returned values as expected
 * 3. Attempt creation with missing required fields (e.g. name, version, source_uri, schema_hash)
 *    and confirm a validation error is returned
 * 4. Attempt creation of a dataset with the same (name, version, source_uri) as the existing entry
 *    to check uniqueness constraint and receive uniqueness error
 * 5. Attempt creation with invalid field values (e.g., empty name/version, bad URI, negative record count)
 *    and confirm relevant validation errors
 *
 * Satisfies regulatory and audit requirements, as well as system-level input and integrity validation.
 */
export async function test_api_ai_training_data_create_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create valid AI training dataset
  const validDataset: IAITrainingData.ICreate = {
    name: `Dataset-${Date.now()}`,
    version: "v1",
    source_uri: "s3://bucket/datasets/123.csv",
    schema_hash: "abc123def4567890",
    record_count: 1000,
    ai_model_id: undefined,
  };

  const created: IAITrainingData = await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: validDataset,
  });
  typia.assert(created);
  TestValidator.equals("name")(validDataset.name)(created.name);
  TestValidator.equals("version")(validDataset.version)(created.version);
  TestValidator.equals("source_uri")(validDataset.source_uri)(created.source_uri);
  TestValidator.equals("schema_hash")(validDataset.schema_hash)(created.schema_hash);
  if (validDataset.record_count !== undefined)
    TestValidator.equals("record_count")(validDataset.record_count)(created.record_count);

  // 2. Attempt creation with missing required fields (name, version, source_uri, schema_hash)
  const requiredFields = ["name", "version", "source_uri", "schema_hash"];
  for (const field of requiredFields) {
    const invalid: Record<string, any> = { ...validDataset };
    delete invalid[field];
