 * 2. List feature store entries using a filter for a particular model version ID (ai_model_version_id) and check the returned data matches.
 * 3. List feature store entries using a partial name filter (fuzzy search) to confirm filter efficacy.
 * 4. Request a page index far exceeding the available data to confirm an empty result set is returned with correct pagination metadata.
 */
export async function test_api_ai_feature_store_listing_with_filtering_and_pagination(
  connection: api.IConnection,
): Promise<void> {
