  TestValidator.equals("pagination structure")(typeof baseline.pagination.current, "number")(typeof baseline.pagination.current);
  TestValidator.equals("pagination records: presence")(true)(baseline.pagination.records >= 0);
  TestValidator.equals("baseline data is an array")("object")(Array.isArray(baseline.data) ? "object" : typeof baseline.data);

  // If there is no data, skip filter tests as there are no known ids/names
