  const decResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: { decision: decisionValue } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(decResult);
  decResult.data.forEach((log) => TestValidator.equals("decision matches")(decisionValue)(log.decision));

  // Step 7: Combine filters (ai_model_version_id + decision + entity_id)
  const entityId = defaultResult.data[0]?.target_entity_id ?? "00000000-0000-0000-0000-000000000000";
  const intersection: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {
      ai_model_version_id: aiModelVersionId,
      decision: decisionValue,
      target_entity_id: entityId,
    } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(intersection);
  intersection.data.forEach((log) => {
    TestValidator.equals("ai_model_version_id")(aiModelVersionId)(log.ai_model_version_id);
    TestValidator.equals("decision")(decisionValue)(log.decision);
    TestValidator.equals("entity id")(entityId)(log.target_entity_id);
  });

  // Step 8: Date range filters (created_at__gte, __lte)
  if (defaultResult.data.length) {
    const firstDate = defaultResult.data[0].created_at;
    const dateResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: {
        created_at__gte: firstDate,
        created_at__lte: firstDate,
      } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(dateResult);
    dateResult.data.forEach((log) => {
      TestValidator.equals("created_at = firstDate")(firstDate)(log.created_at);
    });
  }

  // Step 9: Order by created_at desc, then asc (if available)
  const pagedDesc = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {
      order_by: "created_at",
      order: "desc",
      limit: 5,
    } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(pagedDesc);
  if (pagedDesc.data.length > 1) {
    for (let i = 1; i < pagedDesc.data.length; ++i) {
      TestValidator.equals("order by desc")(
        pagedDesc.data[i - 1].created_at >= pagedDesc.data[i].created_at,
      )(true);
    }
  }
  // asc
  const pagedAsc = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {
      order_by: "created_at",
      order: "asc",
      limit: 5,
    } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(pagedAsc);
  if (pagedAsc.data.length > 1) {
    for (let i = 1; i < pagedAsc.data.length; ++i) {
      TestValidator.equals("order by asc")(
        pagedAsc.data[i - 1].created_at <= pagedAsc.data[i].created_at,
      )(true);
    }
  }

  // Step 10: Paginate (using limit and page)
  const page2 = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {
      limit: 2,
      page: 2,
    } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("current page")(page2.pagination.current)(2);
  TestValidator.equals("limit")(page2.pagination.limit)(2);

  // Step 11: Out-of-range page (should be empty array)
  const emptyPage = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: {
      limit: 10,
      page: 9999,
    } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty results")(emptyPage.data.length)(0);

  // Step 12: Malformed/invalid filter values (should not crash, should error or return empty)
  let threw = false;
  try {
    await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: {
        page: -1,
        limit: -100,
        order: "nope" as any,
      } satisfies IAIDecisionLog.IRequest,
    });
  } catch (e) {
    threw = true;
  }
  TestValidator.equals("invalid filters throws or returns empty")(typeof threw === "boolean")(true);
}

