import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";
import typia from "typia";

/**
 * Test logging an AI/ML inference event with full context and evidence.
 *
 * This scenario covers successful creation, validation errors for missing/invalid data,
 * and duplicate submission behavior for the AI decision logs endpoint.
 *
 * 1. Create a valid decision log entry (all required fields present)
 * 2. Validate response structure and value echo
 * 3. Attempt creation with missing required fields (expect error)
 * 4. Attempt with invalid UUID or input_snapshot format (expect error)
 * 5. Attempt duplicate log creation if uniqueness constraint applies
 *
 * AI decision logs are append-only and store critical business and model evidence.
 * Negative tests ensure regulatory/integrity controls operate as required.
 */
export async function test_api_ai_decision_log_create_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare valid data
  const valid: IAIDecisionLog.ICreate = {
    ai_model_version_id: typia.random<string & typia.tags.Format<"uuid">>(),
    target_user_id: typia.random<string & typia.tags.Format<"uuid">>(),
    target_entity: "order",
    target_entity_id: typia.random<string & typia.tags.Format<"uuid">>(),
    decision: "approve",
    input_snapshot: JSON.stringify({ feature1: 0.5, feature2: "foo" }),
    rationale: "Model approved order based on rules.",
  };

  // 2. Create log
  const created = await api.functional.advancedAI.aiDecisionLogs.post(connection, { body: valid });
  typia.assert(created);
  TestValidator.equals("ai_model_version_id")(valid.ai_model_version_id)(created.ai_model_version_id);
  TestValidator.equals("target_entity")(valid.target_entity)(created.target_entity);
  TestValidator.equals("target_entity_id")(valid.target_entity_id)(created.target_entity_id);
  TestValidator.equals("decision")(valid.decision)(created.decision);
  TestValidator.equals("input_snapshot")(valid.input_snapshot)(created.input_snapshot);
  TestValidator.equals("rationale")(valid.rationale)(created.rationale);
  // target_user_id is optional, check presence
  if (valid.target_user_id)
    TestValidator.equals("target_user_id")(valid.target_user_id)(created.target_user_id);

  // 3. Attempt missing required field (ai_model_version_id)
  const missingModel: Omit<IAIDecisionLog.ICreate, "ai_model_version_id"> = {
    ...valid,
  };
  // @ts-expect-error: purposely omitting field for negative test
  await TestValidator.httpError("validation: missing ai_model_version_id")(400)(() =>
    api.functional.advancedAI.aiDecisionLogs.post(connection, { body: missingModel as any }),
  );

  // 4. Invalid UUID for target_entity_id
  const invalidUuid = { ...valid, target_entity_id: "not-a-uuid" as any };
  await TestValidator.httpError("validation: invalid UUID")(400)(() =>
    api.functional.advancedAI.aiDecisionLogs.post(connection, { body: invalidUuid }),
  );

  // 5. Invalid input_snapshot format
  const invalidInput = { ...valid, input_snapshot: 1234 as any };
  await TestValidator.httpError("validation: malformed input_snapshot")(400)(() =>
    api.functional.advancedAI.aiDecisionLogs.post(connection, { body: invalidInput }),
  );

  // 6. Attempt duplicate log if system rejects duplicate by composite key
  try {
    await TestValidator.httpError("duplicate entry")(409)(() =>
      api.functional.advancedAI.aiDecisionLogs.post(connection, { body: valid }),
    );
  } catch (err) {
    // If not enforced by schema, allow if duplicate is accepted (at least distinct by ID)
    const second = await api.functional.advancedAI.aiDecisionLogs.post(connection, { body: valid });
    typia.assert(second);
    TestValidator.equals("Not duplicated ID")(false)(second.id === created.id);
  }
}

