import typia from "typia";

/**
 * List and paginate AI feedback records with various filters.
 *
 * This test verifies filtering and pagination capabilities of the AI feedback
 * listing endpoint. It tries different query criteria, edge cases (invalid and excessive values),
 * and validates the output structure, type safety, and logical correctness of results.
 *
 * 1. List feedbacks with an empty filter (all records)
 * 2. List feedbacks by user_id filter
 * 3. List feedbacks by decision_log_id filter
 * 4. List feedbacks by feedback_type
 * 5. Filter feedbacks by time_range_start/time_range_end
 * 6. Paginate results with page/limit (including out-of-range page)
 * 7. Sort results (asc/desc)
 * 8. Submit invalid or edge filter values (bad uuid, negative page, excessive limit)
 * 9. Validate for each test that structure and pagination fields are correct, and filter criteria are respected
 */
export async function test_api_ai_feedback_list_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. List all feedbacks (empty filter)
  const all: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: {} });
  typia.assert(all);
  TestValidator.equals("pagination shape")(true)(!!all.pagination && typeof all.pagination.current === "number");

  // Use a feedback entry's field(s) if available for further filtering
  const first = all.data.length > 0 ? all.data[0] : undefined;

  // 2. List with user_id filter (if available)
  if (first?.user_id) {
    const byUser: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { user_id: first.user_id } });
    typia.assert(byUser);
    for (const fb of byUser.data) TestValidator.equals("user_id match")(first.user_id)(fb.user_id);
  }

  // 3. List with decision_log_id filter
  if (first?.decision_log_id) {
    const byDecisionLog: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { decision_log_id: first.decision_log_id } });
    typia.assert(byDecisionLog);
    for (const fb of byDecisionLog.data) TestValidator.equals("decision_log_id match")(first.decision_log_id)(fb.decision_log_id);
  }

  // 4. List with feedback_type filter
  if (first?.feedback_type) {
    const byType: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { feedback_type: first.feedback_type } });
    typia.assert(byType);
    for (const fb of byType.data) TestValidator.equals("feedback_type match")(first.feedback_type)(fb.feedback_type);
  }

  // 5. List with time range filter
  if (first?.created_at) {
    const byTimeRange: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { time_range_start: first.created_at, time_range_end: first.created_at } });
    typia.assert(byTimeRange);
    // Timestamps must fall within range (sometimes inclusive)
    for (const fb of byTimeRange.data) {
      TestValidator.equals("created_at matches")(first.created_at)(fb.created_at);
    }
  }

  // 6. Pagination: limit/page handling
  const limit = 2;
  const paged: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { limit, page: 1 } });
  typia.assert(paged);
  TestValidator.equals("page/limit persistency")(limit)(paged.pagination.limit);
  if (paged.data.length > 0) {
    // Next page
    const paged2: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { limit, page: 2 } });
    typia.assert(paged2);
  }

  // 7. Sort order (asc/desc by created_at)
  const desc: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { sort_order: "desc", limit: 5 } });
  const asc: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { sort_order: "asc", limit: 5 } });
  typia.assert(desc);
  typia.assert(asc);
  if (desc.data.length >= 2 && asc.data.length >= 2) {
    // Should be reversed order by created_at
    const descFirst = desc.data[0].created_at;
    const ascLast = asc.data[asc.data.length-1].created_at;
    TestValidator.equals("sort order reverse")(descFirst)(ascLast);
  }

  // 8. Invalid/edge: bad uuid, negative page, excessive limit
  await TestValidator.httpError("invalid user_id")(400)(() =>
    api.functional.advancedAI.aiFeedback.patch(connection, { body: { user_id: "not-a-uuid" as any } })
  );
  await TestValidator.httpError("negative page")(400)(() =>
    api.functional.advancedAI.aiFeedback.patch(connection, { body: { page: -1 } })
  );
  await TestValidator.httpError("excessive limit")(400)(() =>
    api.functional.advancedAI.aiFeedback.patch(connection, { body: { limit: 1000000 } })
  );
}

