import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPageISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISecurityEvent";
import { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";
import typia from "typia";

/**
 * Test retrieval, filtering, and pagination of security event logs.
 *
 * This test checks that the security event logs API correctly handles default retrieval,
 * filtering by event type, date ranges and other parameters, and pagination settings.
 * The test also verifies that out-of-range queries return the correct empty responses without error.
 *
 * Step-by-step scenario:
 * 1. Retrieve the first page of security events with no filters (default behavior)
 * 2. Apply filtering by event_type and verify only relevant types are returned
 * 3. Apply a date range filter (from_time, to_time) and assert results fall within window
 * 4. Combine multiple filters (event_type and user_id) and verify results
 * 5. Request a page far past end of data (page=9999) and confirm zero results returned
 * 6. Test result size limit (e.g., limit=2) and verify page size accordingly
 * 7. Change sort_order to asc and desc, verify ordering
 * 8. Provide filters for which no record should exist (e.g., random invalid UUID), verify empty result
 * 9. Validate every response and result set with typia.assert and TestValidator.equals
 */
export async function test_api_security_event_filter_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Retrieve first page without filters
  const respDefault: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
    connection,
    { body: {} satisfies ISecurityEvent.IRequest },
  );
  typia.assert(respDefault);
  TestValidator.equals("pagination.current")(1)(respDefault.pagination.current);

  // Save an event type and user_id for subsequent filtering
  const sampleEvent = respDefault.data[0];
  const eventType = sampleEvent?.event_type;
  const userId = sampleEvent?.user_id;
  const createdAt = sampleEvent?.created_at;

  // 2. Filter by event_type if present
  if (eventType) {
    const respFiltered: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
      connection,
      { body: { event_type: eventType } satisfies ISecurityEvent.IRequest },
    );
    typia.assert(respFiltered);
    for (const ev of respFiltered.data)
      TestValidator.equals("event_type")(eventType)(ev.event_type);
  }
  // 3. Filter by date range (if at least one event present)
  if (createdAt) {
    const from = new Date(createdAt).toISOString();
    const to = from;
    const respTime: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
      connection,
      { body: { from_time: from, to_time: to } satisfies ISecurityEvent.IRequest },
    );
    typia.assert(respTime);
    for (const ev of respTime.data) {
      TestValidator.equals("from_time <= createdAt <= to_time")(
        true
      )(
        ev.created_at >= from && ev.created_at <= to
      );
    }
  }
  // 4. Combine multiple filters (event_type & user_id)
  if (eventType && userId) {
    const respCombo: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
      connection,
      { body: { event_type: eventType, user_id: userId } satisfies ISecurityEvent.IRequest },
    );
    typia.assert(respCombo);
    for (const ev of respCombo.data) {
      TestValidator.equals("event_type")(eventType)(ev.event_type);
      TestValidator.equals("user_id")(userId)(ev.user_id);
    }
  }
  // 5. Query page far past data end: should return empty array
  const respEmpty: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
    connection,
    { body: { page: 9999 } satisfies ISecurityEvent.IRequest },
  );
  typia.assert(respEmpty);
  TestValidator.equals("empty data[]")(0)(respEmpty.data.length);

  // 6. Test limit param (e.g., limit=2)
  const respLimit: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
    connection,
    { body: { limit: 2 } satisfies ISecurityEvent.IRequest },
  );
  typia.assert(respLimit);
  TestValidator.equals("page size <= 2")(
    true,
  )(respLimit.data.length <= 2);

  // 7. Test sort_order asc (if at least 2 events for comparison)
  if (respDefault.data.length > 1) {
    const respAsc: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
      connection,
      { body: { sort_order: "asc", limit: 2 } satisfies ISecurityEvent.IRequest },
    );
    typia.assert(respAsc);
    // Compare order
    if (respAsc.data.length === 2) {
      TestValidator.equals("ascending order")(
        true,
      )(
        respAsc.data[0].created_at <= respAsc.data[1].created_at
      );
    }
  }

  // 8. Out-of-range/invalid filters: random uuid/user_id that shouldn't match, verify empty data
  const badUuid = "11111111-1111-1111-1111-111111111111";
  const respInvalid: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(
    connection,
    { body: { user_id: badUuid } satisfies ISecurityEvent.IRequest },
  );
  typia.assert(respInvalid);
  TestValidator.equals("empty for bad user_id")(0)(respInvalid.data.length);
}

