import { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";
import { IPageICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreConsent";

/**
 * Test listing and searching regulatory consent records with pagination and filters.
 *
 * This test verifies that consent listing/search API correctly filters results by status, user, date, and pagination.
 * It also checks edge cases like empty results, invalid filter parameters, and response structure integrity.
 *
 * 1. Register a consent record with valid data.
 * 2. List all consents with no filters - expect the created entry to appear.
 * 3. Filter by user_id - expect only records for that user.
 * 4. Filter by type - expect only records of that type.
 * 5. Filter by is_granted - expect match on grant status.
 * 6. Filter by granted_at date range - expect time-based filtering.
 * 7. Paginate results (limit=1, page=1, 2) - expect proper pagination meta and data separation.
 * 8. Search with empty criteria - expect all results.
 * 9. Search with criteria matching none - expect empty result set.
 * 10. Use invalid filter structure (trigger error response).
 * 11. (Optional) Simulate large dataset and check paginated meta.
 */
export async function test_api_consent_list_and_search_with_filters_and_pagination(connection: api.IConnection): Promise<void> {
  // 1. Register a consent record
  const now = new Date()
  const userId = typia.random<string & typia.tags.Format<"uuid">>();
  const consentType = "ai_training"
  const grantedAt = now.toISOString();
  const consent: ICoreConsent = await api.functional.core.consents.post(connection, {
    body: {
      user_id: userId,
      type: consentType,
      is_granted: true,
      granted_at: grantedAt,
      revoked_at: null,
    } satisfies ICoreConsent.ICreate,
  });
  typia.assert(consent);
  TestValidator.equals("user_id")(userId)(consent.user_id);

  // 2. List all consents (no filter)
  let page: IPageICoreConsent = await api.functional.core.consents.patch(connection, {
    body: {},
  });
  typia.assert(page);
  TestValidator.equals("should see at least one consent")(true)(page.data.some((c) => c.id === consent.id));

  // 3. Filter by user_id
  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { user_id: userId } },
  });
  typia.assert(page);
  TestValidator.equals("user_id filter")(true)(page.data.every((c) => c.user_id === userId));

  // 4. Filter by type
  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { type: consentType } },
  });
  typia.assert(page);
  TestValidator.equals("type filter")(true)(page.data.every((c) => c.type === consentType));

  // 5. Filter by grant status (is_granted)
  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { is_granted: true } },
  });
  typia.assert(page);
  TestValidator.equals("is_granted true")(true)(page.data.every((c) => c.is_granted));

  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { is_granted: false } },
  });
  typia.assert(page);
  TestValidator.equals("is_granted false")(true)(page.data.every((c) => !c.is_granted));

  // 6. Filter by date range
def filterDateIso(offsetHours: number) {
    return new Date(now.getTime() + offsetHours * 3600000).toISOString();
  }

  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { granted_at: { $gte: filterDateIso(-1), $lte: filterDateIso(1) } } },
  });
  typia.assert(page);
  TestValidator.equals("date range filter")(true)(page.data.some((c) => c.id === consent.id));

  // 7. Paginate (limit=1)
  page = await api.functional.core.consents.patch(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(page);
  TestValidator.equals("page 1, limit 1 meta")(1)(page.pagination.current);
  TestValidator.equals("limit 1 meta")(1)(page.pagination.limit);
  TestValidator.equals("has at most 1 row")(true)(page.data.length <= 1);
  const ids: string[] = page.data.map(c => c.id);
  if (page.pagination.pages > 1) {
    const page2 = await api.functional.core.consents.patch(connection, {
      body: { limit: 1, page: 2 },
    });
    typia.assert(page2);
    TestValidator.equals("page 2 meta")(2)(page2.pagination.current);
    TestValidator.equals("different record on page 2")(true)(!ids.includes(page2.data[0]?.id));
  }

  // 8. Search with empty criteria (should return all)
  page = await api.functional.core.consents.patch(connection, {
    body: { search: null },
  });
  typia.assert(page);
  TestValidator.equals("empty search shows something")(true)(page.data.length > 0);

  // 9. Search with no result
  page = await api.functional.core.consents.patch(connection, {
    body: { filter: { user_id: typia.random<string & typia.tags.Format<"uuid">>() } },
  });
  typia.assert(page);
  TestValidator.equals("no matching results")(0)(page.data.length);

  // 10. Invalid filter structure (should fail)
  await TestValidator.httpError("invalid filter")(400)(() =>
    api.functional.core.consents.patch(connection, {
      body: { filter: 123 as any },
    })
  );

  // 11. (Optional) Large dataset: limited unless test infra supports
}

