import { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";

/**
 * Test registering a new user regulatory consent, ensuring required fields are present
 * and business rules (uniqueness, correct user linkage) are enforced. Also validate
 * negative/edge cases such as malformed payloads and uniqueness violations.
 *
 * Background:
 *  - A new consent can be registered for a user and a particular type (e.g., ai_training).
 *  - Attempts to register multiple consents for the same (user_id, type) should fail with a conflict.
 *  - All required fields (user_id, type, is_granted, granted_at) must be present and formatted correctly.
 *
 * Steps:
 * 1. Register a new valid consent for random user_id/type.
 * 2. Attempt duplicate registration (same user_id/type) to confirm uniqueness constraint.
 * 3. Attempt registrations with missing required fields (e.g., user_id).
 * 4. Attempt malformed granted_at (invalid date format).
 * 5. Attempt registration with missing type or is_granted.
 */
export async function test_api_core_consents_post_valid_and_invalid(connection: api.IConnection): Promise<void> {
  // Step 1: Register a valid consent
  const user_id: string = uuidv4();
  const consentType = "ai_training";
  const now = new Date().toISOString();
  const validPayload: ICoreConsent.ICreate = {
    user_id,
    type: consentType,
    is_granted: true,
    granted_at: now,
    revoked_at: null,
  };
  const created: ICoreConsent = await api.functional.core.consents.post(connection, { body: validPayload });
  typia.assert(created);
  TestValidator.equals("user_id")(user_id)(created.user_id);
  TestValidator.equals("type")(consentType)(created.type);
  TestValidator.equals("is_granted")(true)(created.is_granted);

  // Step 2: Duplicate registration (should fail uniqueness)
  await TestValidator.httpError("duplicate consent should fail")(409)(() =>
    api.functional.core.consents.post(connection, { body: validPayload }),
  );

  // Step 3a: Missing user_id
  const missingUserIdPayload = { ...validPayload };
  delete (missingUserIdPayload as any).user_id;
  await TestValidator.httpError("missing user_id")(400)(() =>
    api.functional.core.consents.post(connection, { body: missingUserIdPayload as any }),
  );

  // Step 3b: Missing type
  const missingTypePayload = { ...validPayload };
