import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";
import { IPageICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreAccessLog";
import typia from "typia";

/**
 * Test listing and filtering access event logs with a variety of filter and pagination inputs.
 *
 * This scenario ensures robust retrieval of access logs and audit events for audit and regulatory use cases,
 * and validates error handling for invalid filter criteria, empty result sets, and large data volumes.
 *
 * 1. Create at least one access log entry (to provide a target for listing and filtering).
 * 2. List all access logs with no filters.
 * 3. Filter by user_id and validate outcome contains only logs for that user.
 * 4. Filter by event_type and validate outcome.
 * 5. Time window filter (occurred_at_from, occurred_at_to).
 * 6. Pagination: retrieve a single-item page and validate.
 * 7. Filter using a non-existent user_id (should return empty data).
 * 8. Combined filters: event_type, success, ip, agent.
 * 9. Request with large limit value (e.g., 1000) to test upper bound.
 * 10. Submit invalid/malformed filter values and expect error or empty result.
 */
export async function test_api_core_accessLog_listing_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an access log entry (setup)
  const baseCreate: ICoreAccessLog.ICreate = {
    user_id: typia.random<string>(),
    session_id: typia.random<string>(),
    event_type: "login",
    ip: "10.10.10.1",
    agent: "e2e-tester",
    success: true,
    occurred_at: new Date().toISOString(),
  };
  const created: ICoreAccessLog = await api.functional.core.accessLogs.post(connection, {
    body: baseCreate,
  });
  typia.assert(created);

  // 2. List all logs with no filters
  const allLogs: IPageICoreAccessLog = await api.functional.core.accessLogs.patch(connection, {
    body: {},
  });
  typia.assert(allLogs);
  TestValidator.equals("at least one record after create")(
    true
  )(allLogs.data.some((log) => log.id === created.id));

  // 3. Filter by user_id
  const userFiltered = await api.functional.core.accessLogs.patch(connection, {
    body: {
      user_id: created.user_id,
    },
  });
  typia.assert(userFiltered);
  TestValidator.equals("filtered contains only right user")(
    true
  )(userFiltered.data.every((log) => log.user_id === created.user_id));

  // 4. Filter by event_type
  const eventFiltered = await api.functional.core.accessLogs.patch(connection, {
    body: {
      event_type: created.event_type,
    },
  });
  typia.assert(eventFiltered);
  TestValidator.equals("filtered contains only right event_type")(
    true
  )(eventFiltered.data.every((log) => log.event_type === created.event_type));

  // 5. Filter by time window
  const from = new Date(Date.now() - 60 * 1000).toISOString();
  const to = new Date(Date.now() + 60 * 1000).toISOString();
  const timeFiltered = await api.functional.core.accessLogs.patch(connection, {
    body: {
      occurred_at_from: from,
      occurred_at_to: to,
    },
  });
  typia.assert(timeFiltered);
  TestValidator.equals("time window covers created record")(
    true
  )(timeFiltered.data.some((log) => log.id === created.id));

  // 6. Pagination: limit=1
  const paged = await api.functional.core.accessLogs.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("limit 1 returns at most 1")(
    true
  )(paged.data.length === 0 || paged.data.length === 1);

  // 7. Non-existent user_id
  const fakeUserFiltered = await api.functional.core.accessLogs.patch(connection, {
    body: {
      user_id: "00000000-0000-0000-0000-000000000000",
    },
  });
  typia.assert(fakeUserFiltered);
  TestValidator.equals("empty for bogus user")(
    0
  )(fakeUserFiltered.data.length);

  // 8. Combined filters
  const comboFiltered = await api.functional.core.accessLogs.patch(connection, {
    body: {
      user_id: created.user_id,
      event_type: created.event_type,
      ip: created.ip,
      agent: created.agent,
      success: created.success,
    },
  });
  typia.assert(comboFiltered);
  TestValidator.equals("combo filter includes created")(
    true
  )(comboFiltered.data.some((log) => log.id === created.id));

  // 9. Large limit
  const largeLimit = await api.functional.core.accessLogs.patch(connection, {
    body: {
      limit: 1000,
    },
  });
  typia.assert(largeLimit);
  TestValidator.equals("large limit <= 1000")(
    true
  )(largeLimit.data.length <= 1000);

  // 10. Invalid/malformed filter: page=0 (should fail or be empty)
  try {
    const invalid = await api.functional.core.accessLogs.patch(connection, {
      body: {
        page: 0,
      },
    });
    typia.assert(invalid);
    TestValidator.equals("invalid page=0 yields empty or error")(
      true
    )(invalid.data.length === 0);
  } catch (err) {
    // Expected error acceptable
  }
}

