/**
 * Test searching and listing products with pagination and filtering
 *
 * This test ensures correctness and robustness of the product catalog search/list endpoint, validating filter, pagination, and boundary conditions.
 * This covers boundary and edge cases including empty sets, filter mismatches, and maximum page size/limits.
 *
 * Steps:
 * 1. Create at least one product to enable meaningful search results.
 * 2. List/search products with no filters and verify the created product is returned.
 * 3. Search using product name filter (exact and partial match).
 * 4. Search with status filter (matching and mismatching statuses).
 * 5. Search with invalid filter fields (expect empty result or proper error handling).
 * 6. Paginate with 'limit' and 'page' (first/last page, 1-per-page, max page size boundary, out-of-range page).
 * 7. Search with filter that matches nothing (should return empty data and valid pagination structure).
 * 8. (Optional) Test very large dataset: create additional products and validate paging integrity at scale.
 */
export async function test_api_product_search_and_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create at least one product for repeatable/filterable searches
  const createBody = {
    created_by_user_id: typia.random<string>(),
    updated_by_user_id: typia.random<string>(),
    name: `TestProduct_${Date.now()}`,
    description: "Primary test product for catalog search/listing",
    internal_code: `TEST_${Math.floor(Math.random() * 100000)}`,
    status: "active",
  } satisfies IProductCatalogProduct.ICreate;
  const product: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, { body: createBody });
  typia.assert(product);

  // 2. List/search products with no filters (should find at least created one)
  const listAll: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, { body: {} });
  typia.assert(listAll);
  TestValidator.equals("includes created product")(
    true,
  )(listAll.data.some((p) => p.id === product.id));

  // 3. Search using product name filter (exact and partial match)
  const byExactName: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { name: createBody.name },
  });
  typia.assert(byExactName);
  TestValidator.equals("exact name match")(
    1,
  )(byExactName.data.filter((p) => p.id === product.id).length);
  // Partial (left substring)
  const partialName = createBody.name.slice(0, 8); // "TestProd"
  const byPartialName: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { name: partialName },
  });
  typia.assert(byPartialName);
  TestValidator.equals("partial name match")(
    true,
  )(byPartialName.data.some((p) => p.id === product.id));

  // 4. Search with status filter (should match)
  const byStatus: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { status: createBody.status },
  });
  typia.assert(byStatus);
  TestValidator.equals("status match includes product")(
    true,
  )(byStatus.data.some((p) => p.id === product.id));
  // Status that should not match
  const byWrongStatus: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { status: "notastatus" },
