 *
 * This test ensures that the product catalog API correctly creates products with valid payloads, rejects invalid or incomplete requests, 
 * and enforces uniqueness on the internal_code field. It covers positive creation, missing/invalid field rejections, and duplicate code handling.
 *
 * Steps:
 * 1. Create a product with a fully valid, unique payload (test typical success path).
 * 2. Attempt to create a product with missing required fields (name, internal_code, status, or user IDs), expecting a validation error.
 * 3. Attempt to create a product with invalid field types (non-UUID for user IDs), expecting a validation error.
 * 4. Attempt to create two products with the same internal_code, expecting a unique constraint violation on the second attempt.
 * 5. Assert output types and structure using typia.assert.
 */
export async function test_api_productCatalog_products_post_create_and_uniqueness_and_required_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid, unique product
  const internal_code = `CODE-${Date.now()}-${Math.floor(Math.random()*10000)}`;
  const createPayload: IProductCatalogProduct.ICreate = {
    created_by_user_id: uuidv4(),
    updated_by_user_id: uuidv4(),
    name: "Test Product",
    description: "A valid test product.",
    internal_code,
    status: "draft",
  };

  const created: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, {
    body: createPayload satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(created);
  TestValidator.equals("internal_code should match")(internal_code)(created.internal_code);
  TestValidator.equals("name should match")("Test Product")(created.name);

  // 2. Create with missing required field: 'name'
