    api.functional.productCatalog.products.post(connection, {
      body: { ...createPayload, name: undefined as any },
    })
  );

  // 3. Create with invalid user id (not a UUID)
  await TestValidator.httpError("invalid user id should fail")(400)(() =>
    api.functional.productCatalog.products.post(connection, {
      body: { ...createPayload, created_by_user_id: "not-a-uuid", updated_by_user_id: "not-a-uuid" },
    })
  );

  // 4. Duplicate internal_code: create another product with same internal_code
  const duplicatePayload: IProductCatalogProduct.ICreate = {
    ...createPayload,
    name: "Test Product Dup",
    description: "Duplicate test product.",
  };
  await TestValidator.httpError("duplicate internal_code should fail")(409)(() =>
    api.functional.productCatalog.products.post(connection, {
      body: duplicatePayload satisfies IProductCatalogProduct.ICreate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";

/**
 * Test updating allowed fields for an existing product and verify that catalog/audit evidence is maintained.
 *
 * Scenario Background & Step-by-step:
 * - A product must exist to update, so we first create a valid catalog product via POST.
 * - We will perform a valid update (e.g., change the name/description/status) and check updated fields and audit evidence (like updated_at/by).
 * - We then attempt updates on a non-existent product and with forbidden/invalid payloads to verify error handling.
 *
 * 1. Create a product (POST /productCatalog/products)
 * 2. Update allowed fields (PUT /productCatalog/products/{id})
 * 3. Assert response: updated fields, audit trails (updated_at, updated_by_user_id), typia.assert
 * 4. Attempt update on non-existent product; expect error (404 or 400)
 * 5. Attempt update missing updated_by_user_id or with forbidden fields (e.g., try changing created_by_user_id), expect error
 */
export async function test_api_product_catalog_update_product_and_validate_catalog_evidence(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid product
  const creatorUserId = typia.random<string & tags.Format<"uuid">>();
  const createPayload: IProductCatalogProduct.ICreate = {
    created_by_user_id: creatorUserId,
    updated_by_user_id: creatorUserId,
    name: "Test Snack Bar V2",
    description: "Energy bar, nutritious snack revolution",
    internal_code: `CODE-${Math.random().toString(36).slice(2, 10)}`,
    status: "active",
  };
  const original: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, { body: createPayload });
  typia.assert(original);
  TestValidator.equals("name after creation")("Test Snack Bar V2")(original.name);

  // 2. Update allowed fields (name, description, status)
  const updatePayload: IProductCatalogProduct.IUpdate = {
    updated_by_user_id: creatorUserId,
    name: "Updated Snack Bar (Limited Edition)",
    description: "Limited run - contains rare minerals",
    status: "draft",
  };
  const updated: IProductCatalogProduct = await api.functional.productCatalog.products.putById(connection, {
    id: original.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("id unchanged")(original.id)(updated.id);
  TestValidator.equals("updated name")("Updated Snack Bar (Limited Edition)")(updated.name);
  TestValidator.equals("updated description")("Limited run - contains rare minerals")(updated.description);
  TestValidator.equals("updated status")("draft")(updated.status);
  TestValidator.equals("updated_by_user_id updated")(updatePayload.updated_by_user_id)(updated.updated_by_user_id);
  TestValidator.notEquals("updated_at reflects edit")(original.updated_at)(updated.updated_at);

  // 3. Negative: Attempt update for non-existent product
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("update for non-existent product")(404)(() =>
    api.functional.productCatalog.products.putById(connection, {
      id: randomId,
      body: updatePayload,
    })
  );

  // 4. Negative: Attempt forbidden/invalid update: changing created_by_user_id
  const forbidden: IProductCatalogProduct.IUpdate & { created_by_user_id: string } = {
    ...updatePayload,
    created_by_user_id: typia.random<string & tags.Format<"uuid">>(), // not allowed!
  };
  await TestValidator.httpError("update with forbidden field: created_by_user_id")(400)(() =>
    api.functional.productCatalog.products.putById(connection, {
      id: original.id,
      body: forbidden as any,
    })
  );

  // 5. Negative: Attempt update missing mandatory updated_by_user_id
  const missingUserId = { ...updatePayload };
  delete (missingUserId as any).updated_by_user_id;
  await TestValidator.httpError("update missing updated_by_user_id")(400)(() =>
    api.functional.productCatalog.products.putById(connection, {
      id: original.id,
      body: missingUserId as any,
    })
  );

  // 6. Negative: Duplicate internal_code if business logic forbids
  const dupPayload: IProductCatalogProduct.IUpdate = {
    updated_by_user_id: creatorUserId,
    internal_code: createPayload.internal_code,
  };
  await TestValidator.httpError("update duplicate internal_code")(400)(() =>
    api.functional.productCatalog.products.putById(connection, {
      id: original.id,
      body: dupPayload,
    })
  );
}

