 *
 * This test validates the complete product variant update lifecycle including auditing and error handling:
 * 1. Create a product variant to update.
 * 2. Update allowed fields (such as price, barcode, and available status), then verify changes.
 * 3. Attempt update with invalid data and expect a validation error.
 * 4. Attempt update with a non-existent variant ID and expect a not-found error.
 */
export async function test_api_product_variant_update_and_audit_changes(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid product variant as prerequisite
  const baseVariant: IProductCatalogProductVariant =
    await api.functional.productCatalog.productVariants.post(connection, {
      body: {
        product_id: typia.random<string & tags.Format<"uuid">>(),
        sku: `SKU-${Math.random().toString(36).slice(2, 8).toUpperCase()}`,
        price: 12345.99,
        barcode: `BARCODE-${Math.floor(Math.random() * 100000)}`,
        available: true,
      } satisfies IProductCatalogProductVariant.ICreate,
    });
  typia.assert(baseVariant);

  // 2. Update allowed fields and verify changes + auditing
  const updatePayload: IProductVariant.IUpdate = {
    price: baseVariant.price + 1000,
    available: false,
    barcode: baseVariant.barcode + "-NEW",
  };
  const updated: IProductVariant =
    await api.functional.productCatalog.productVariants.putById(connection, {
      id: baseVariant.id,
      body: updatePayload,
    });
