  TestValidator.equals("id matches")(baseVariant.id)(updated.id);
  TestValidator.equals("price updated")(updatePayload.price)(updated.price);
  TestValidator.equals("available updated")(updatePayload.available)(updated.available);
  TestValidator.equals("barcode updated")(updatePayload.barcode)(updated.barcode);
  TestValidator.notEquals("updated_at advanced")(baseVariant.updated_at)(updated.updated_at);

  // 3. Update with invalid data (e.g., negative price): expect validation error
  await TestValidator.httpError("update with invalid price")(400)(() =>
    api.functional.productCatalog.productVariants.putById(connection, {
      id: baseVariant.id,
      body: {
        price: -5000, // Invalid negative price
      } satisfies IProductVariant.IUpdate,
    })
