  // 4. Update with non-existent variant ID: expect not-found error
  await TestValidator.httpError("update with non-existent id")(404)(() =>
    api.functional.productCatalog.productVariants.putById(connection, {
      id: "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">,
      body: { price: 10000 } satisfies IProductVariant.IUpdate,
    })
  );
}

