import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";
import { IPageIProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCategory";
import typia from "typia";

/**
 * Validate listing, filtering, and hierarchy of product categories with paging and edge cases.
 *
 * This test covers the following:
 * - Category creation for lookup and hierarchy.
 * - List all categories (empty filter).
 * - List by partial name filter.
 * - List by parent_id for hierarchical query.
 * - Paging, offset/limit, and out-of-bounds edge cases.
 * - Invalid filter parameter types (if server validates/returns error).
 * - Output and hierarchy structure validation.
 *
 * Steps:
 * 1. Create a root product category via POST.
 * 2. Create a child product category with parent_id pointing to the root.
 * 3. List all categories (PATCH, empty filter), expect at least created categories.
 * 4. List by name filter (partial), expect matching categories.
 * 5. List by parent_id for child, expect only direct children.
 * 6. List with limit/offset for paging, check metadata.
 * 7. List with offset > record count (should return empty data array).
 * 8. Attempt invalid filter input (e.g., wrong type), expect validation error if type-checking enforced.
 */
export async function test_api_product_category_list_with_filters_and_hierarchy_check(connection: api.IConnection): Promise<void> {
  // 1. Create a root category
  const rootCat: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: {
      name: `RootCategory-${Date.now()}`,
    } satisfies IProductCategory.ICreate,
  });
  typia.assert(rootCat);

  // 2. Create a child category
  const childCat: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: {
      name: `ChildCategory-${Date.now()}`,
      parent_id: rootCat.id,
    } satisfies IProductCategory.ICreate,
  });
  typia.assert(childCat);
  TestValidator.equals("Child's parent_id matches rootCat.id")(rootCat.id)(childCat.parent_id);

  // 3. List all categories (no filter)
  const resAll: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: {} satisfies IProductCategory.IRequest,
  });
  typia.assert(resAll);
  // Should include both root and child (but maybe not only them if residual test data)
  const foundRoot = resAll.data.some(c => c.id === rootCat.id);
  const foundChild = resAll.data.some(c => c.id === childCat.id);
  TestValidator.equals("Root should be in results")(true)(foundRoot);
  TestValidator.equals("Child should be in results")(true)(foundChild);

  // 4. List categories by partial name match (child category)
  const partialName = childCat.name.slice(0, Math.floor(childCat.name.length/2));
  const resByName: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { name: partialName } satisfies IProductCategory.IRequest,
  });
  typia.assert(resByName);
  // Must include childCat, rootCat may be included if name overlaps
  const foundChildByName = resByName.data.some(c => c.id === childCat.id);
  TestValidator.equals("Child category found by partial name")(true)(foundChildByName);

  // 5. List by parent_id (hierarchy test)
  const resChildren: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { parent_id: rootCat.id } satisfies IProductCategory.IRequest,
  });
  typia.assert(resChildren);
  // Only direct children of rootCat
  const allParentCorrect = resChildren.data.every(c => c.parent_id === rootCat.id);
  TestValidator.equals("All returned have parent_id=rootCat.id")(true)(allParentCorrect);
  const mustIncludeChildCat = resChildren.data.some(c => c.id === childCat.id);
  TestValidator.equals("Result includes child")(true)(mustIncludeChildCat);

  // 6. Paging/limit/offset (smoke test: limit=1, offset=0)
  const resPage1: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { limit: 1, offset: 0 } satisfies IProductCategory.IRequest,
  });
  typia.assert(resPage1);
  TestValidator.equals("Limit is 1")(1)(resPage1.pagination.limit);
  TestValidator.equals("Data length matches limit")(
    Math.min(1, resPage1.pagination.records)
  )(resPage1.data.length);

  // 7. Out-of-bounds offset (offset far past total records)
  const resOffset: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { offset: 10000 } satisfies IProductCategory.IRequest,
  });
  typia.assert(resOffset);
  TestValidator.equals("Offset past record count yields no data")(0)(resOffset.data.length);

  // 8. Invalid filter (if type-check enforced: e.g., non-integer offset)
  try {
    // offset as string should fail if server validates
    await api.functional.productCatalog.productCategories.patch(connection, {
      body: { offset: "NOT_INTEGER" as any } as any,
    });
    // If no error thrown, check if data is empty or what response is
    // (server may coerce or error depending on implementation)
  } catch (err) {
    // Expect error thrown (400 or validation)
    TestValidator.error("Invalid type for offset should throw error")(err);
  }
}

