import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * E2E test: Create product categories (atomic & hierarchical) and validate uniqueness, hierarchy, and error cases.
 *
 * This test verifies the following scenarios:
 * 1. Creation of a root category with a valid unique name.
 * 2. Creation of a child (subcategory) under a parent.
 * 3. Prevention of duplicate category names within the same hierarchy level (same parent_id).
 * 4. Allowing identical names in different hierarchies (distinct parent_id).
 * 5. Proper error response when required fields (e.g., name) are missing.
 *
 * Scenario Background:
 * Product categories must support hierarchical relationships for navigation and faceted search.
 * Category names must be unique within the same parent, but the same name can exist under different parents or at the root.
 * The API enforces these via schema validation and unique constraints at creation time.
 *
 * Steps:
 * 1. Create a root category (no parent_id)
 * 2. Create a subcategory with the root as parent
 * 3. Attempt to create another category with the same name under the same parent (expect error)
 * 4. Create another root category with the same name as the above subcategory (should succeed, since parent is null)
 * 5. Create a sibling subcategory under a different parent with the same name (should succeed)
 * 6. Attempt creation with missing required field (e.g., no name, expect validation error)
 *
 * All positive responses are validated with typia.assert. All error responses validated with TestValidator.httpError as applicable.
 */
export async function test_api_product_category_create_and_validate_hierarchy_and_uniqueness(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a unique root category
  const rootCategoryName = "Electronics-root-" + Date.now();
  const rootCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    {
      body: {
        name: rootCategoryName,
        parent_id: null,
      } satisfies IProductCategory.ICreate,
    },
  );
  typia.assert(rootCategory);
  TestValidator.equals("Root category name matches")(rootCategoryName)(rootCategory.name);
  TestValidator.equals("Root category parent is null")(null)(rootCategory.parent_id);

  // 2. Create a subcategory under the root
  const subCategoryName = "Laptops-sub-" + Date.now();
  const subCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    {
      body: {
        name: subCategoryName,
        parent_id: rootCategory.id,
      } satisfies IProductCategory.ICreate,
    },
  );
  typia.assert(subCategory);
  TestValidator.equals("Subcategory parent matches")(rootCategory.id)(subCategory.parent_id);

  // 3. Attempt to create another subcategory with the same name under the same parent (should fail)
  await TestValidator.httpError("Duplicate category under same parent")(409)(() =>
    api.functional.productCatalog.productCategories.post(connection, {
      body: {
        name: subCategoryName,
        parent_id: rootCategory.id,
      } satisfies IProductCategory.ICreate,
    })
  );

  // 4. Create another root category with the same name as the subcategory (should succeed)
  const rootCategory2: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    {
      body: {
        name: subCategoryName, // intentionally same as subCategoryName
        parent_id: null,
      } satisfies IProductCategory.ICreate,
    },
  );
  typia.assert(rootCategory2);
  TestValidator.equals("Root category with duplicate child name allowed at root")(subCategoryName)(rootCategory2.name);
  TestValidator.equals("Root category parent is null")(null)(rootCategory2.parent_id);

  // 5. Create a sibling subcategory under a different parent with same name (should succeed)
  const subCategory2: IProductCategory = await api.functional.productCatalog.productCategories.post(
    connection,
    {
      body: {
        name: subCategoryName, // same name, new parent
        parent_id: rootCategory2.id,
      } satisfies IProductCategory.ICreate,
    },
  );
  typia.assert(subCategory2);
  TestValidator.equals("Sibling subcategory under different parent allowed")(rootCategory2.id)(subCategory2.parent_id);
  TestValidator.equals("Sibling name matches")(subCategoryName)(subCategory2.name);

  // 6. Attempt to create without required field (e.g., missing name)
  await TestValidator.httpError("Missing required field: name")(400)(() =>
    api.functional.productCatalog.productCategories.post(connection, {
      body: {
        // name missing
        // parent_id can be null or undefined
      } as any,
    })
  );
}

