 * 4. Test pagination: set limit=1, verify correct option per page, and overflow page (expect empty).
 * 5. Query all with high limit, check both created options are present.
 * 6. Pass invalid types (bad product_id, negative page) and check for empty/error.
 * 7. Assert types and exact result set at every step, using typia and TestValidator.
 *
 * Guarantees that option listing/search workflow for admin and onboarding is robust for both happy and unhappy paths.
 */
export async function test_api_product_option_listing_filtering_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two product options with different data
  const option1: IProductOption = await api.functional.productCatalog.productOptions.post(connection, {
    body: {
      product_id: typia.random<string>(),
      option_type: "color",
      value: "Red",
    } satisfies IProductOption.ICreate
  });
  typia.assert(option1);

  const option2: IProductOption = await api.functional.productCatalog.productOptions.post(connection, {
    body: {
      product_id: typia.random<string>(),
      option_type: "size",
      value: "XL",
    } satisfies IProductOption.ICreate
  });
  typia.assert(option2);

  // 2. Filter by exact product_id for option1
  let page: IPageIProductOption = await api.functional.productCatalog.productOptions.patch(connection, {
    body: {
      product_id: option1.product_id,
    }
  });
  typia.assert(page);
  TestValidator.equals("only option1 present")([option1])(page.data);

  // Filter by option_type for option2
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { option_type: option2.option_type }
  });
  typia.assert(page);
  TestValidator.equals("option2 is present, option1 not returned")(
    page.data.map(o => o.id).includes(option2.id) && (!page.data.map(o => o.id).includes(option1.id) || page.data.length === 1)
  )(true);

  // Filter by value for option1
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { value: option1.value }
  });
  typia.assert(page);
  TestValidator.equals("only option1 present by value")([option1])(page.data);

  // 3. Non-existent filter
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { product_id: typia.random<string>(), option_type: "material", value: "Gold" }
  });
  typia.assert(page);
  TestValidator.equals("no result for non-existent combination")([])(page.data);

  // 4. Pagination - limit=1, page=1
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { limit: 1, page: 1 }
  });
  typia.assert(page);
  TestValidator.equals("pagination returns first or second option only")(
    [option1.id, option2.id].includes(page.data[0]?.id)
  )(true);
  TestValidator.equals("pagination: records count >= 2")(
    page.pagination.records >= 2
  )(true);

  // Pagination - page=2
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { limit: 1, page: 2 }
  });
  typia.assert(page);
  TestValidator.equals("pagination returns next option or empty")(
    page.data.length <= 1
  )(true);

  // Pagination - overflow (page > total-pages)
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { limit: 1, page: 100 }
  });
  typia.assert(page);
  TestValidator.equals("overflow page returns empty")([])(page.data);

  // 5. Query with no filters (large limit) - both options present
  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { limit: 100 }
  });
  typia.assert(page);
  TestValidator.equals("both created options returned")(
    page.data.map(o=>o.id).filter(id=>[option1.id, option2.id].includes(id)).length >= 2
  )(true);

  // 6. Invalid filter types (bad product_id UUID, negative page)
  await TestValidator.error("bad product_id uuid")(() =>
    api.functional.productCatalog.productOptions.patch(connection, { body: { product_id: "not-a-uuid" } })
  );

  page = await api.functional.productCatalog.productOptions.patch(connection, {
    body: { page: -1 }
  });
  typia.assert(page);
  // Negative page should produce empty or error
  TestValidator.equals("negative page returns empty or first page")(
    Array.isArray(page.data)
  )(true);

  // 7. Confirm typia.assert invariants
  page.data.forEach(typia.assert);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * E2E: Update Refund Records with Valid and Invalid IDs, including Data Consistency.
 *
 * 1. Create a refund record (POST /paymentsDiscounts/refunds) for update scenario precondition.
 * 2. Update the refund via PUT using valid changes; confirm fields updated in response.
 * 3. Attempt to update a non-existent refund id; expect 404 error (not found).
 * 4. Execute two quick successive updates to the same refund id with different values; confirm latest update is reflected (simulate concurrency).
 *
 * This verifies the core update mechanism, error for not found, and correct state after concurrent-like modifications.
 */
export async function test_api_refund_update_with_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a refund record
  const createPayload: IRefund.ICreate = typia.random<IRefund.ICreate>();
  const refund: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    { body: createPayload },
  );
  typia.assert(refund);

  // 2. Valid update to allowed fields
  const updatePayload: IRefund.IUpdate = {
    amount: (refund.amount ?? 0) + 10,
    status: "processed",
    reason: "Update reason for success path",
  };
  const updated: IRefund = await api.functional.paymentsDiscounts.refunds.putById(
    connection,
    {
      id: refund.id,
      body: updatePayload,
    },
  );
  typia.assert(updated);
  TestValidator.equals("amount updated")(updatePayload.amount)(updated.amount);
  TestValidator.equals("status updated")(updatePayload.status)(updated.status);
  TestValidator.equals("reason updated")(updatePayload.reason)(updated.reason);

  // 3. Attempt to update a non-existent refund id
  await TestValidator.httpError("update not found")(404)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // totally random UUID
      body: updatePayload,
    })
  );

  // 4. Quick successive/concurrent updates to the same refund id
  const concurrentPayload1: IRefund.IUpdate = {
    amount: updated.amount + 1,
    status: "pending",
    reason: "Concurrent update 1",
  };
  const concurrentPayload2: IRefund.IUpdate = {
    amount: updated.amount + 2,
    status: "completed",
    reason: "Concurrent update 2",
  };

  // First update
  const afterFirst: IRefund = await api.functional.paymentsDiscounts.refunds.putById(
    connection,
    { id: refund.id, body: concurrentPayload1 },
  );
  typia.assert(afterFirst);
  TestValidator.equals("concurrent 1, amount")(concurrentPayload1.amount)(afterFirst.amount);
  TestValidator.equals("concurrent 1, status")(concurrentPayload1.status)(afterFirst.status);
  TestValidator.equals("concurrent 1, reason")(concurrentPayload1.reason)(afterFirst.reason);

  // Second update
  const afterSecond: IRefund = await api.functional.paymentsDiscounts.refunds.putById(
    connection,
    { id: refund.id, body: concurrentPayload2 },
  );
  typia.assert(afterSecond);
  TestValidator.equals("concurrent 2, amount")(concurrentPayload2.amount)(afterSecond.amount);
  TestValidator.equals("concurrent 2, status")(concurrentPayload2.status)(afterSecond.status);
  TestValidator.equals("concurrent 2, reason")(concurrentPayload2.reason)(afterSecond.reason);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * Validate that refund update enforces proper type and business validation.
 *
 * This test verifies that the refund update endpoint (`PUT /paymentsDiscounts/refunds/{id}`)
 * rejects requests containing invalid data types or constraint-violating values (e.g., string instead of number, negative amount, excessive nulls, etc.).
 * The refund record itself is established by first calling the refund creation endpoint. Then, we attempt to update this valid record with various invalid payloads.
 *
 * Test Steps:
 * 1. Create a valid refund using the API (`POST /paymentsDiscounts/refunds`).
 * 2. Attempt to update the refund with invalid type data (e.g., non-numeric 'amount', malformed UUID for order_id).
 * 3. Attempt to update the refund with negative or zero "amount" (business logic violation).
 * 4. Attempt to update with clearly invalid/empty/null payloads for required fields in IUpdate.
 * 5. For each invalid update attempt, assert that a validation error or HTTP 400/422 is returned.
 * 6. Confirm that the refund record on the server did not mutate due to these invalid attempts.
 */
export async function test_api_refund_update_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid refund (so there is a target to update).
  const refund: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection, {
      body: {
        payment_id: typia.random<string & tags.Format<"uuid">>(),
        transaction_id: typia.random<string & tags.Format<"uuid">>(),
        order_id: typia.random<string & tags.Format<"uuid">>(),
        amount: 123.45,
        currency: "USD",
        status: "requested",
        reason: "Test setup for negative cases."
      } satisfies IRefund.ICreate,
    }
  );
  typia.assert(refund);

  // 2a. Invalid type: string for numeric amount
  await TestValidator.httpError("amount as string should fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        amount: "not-a-number" as any, // deliberately invalid
      } satisfies Partial<IRefund.IUpdate> as IRefund.IUpdate,
    })
  );

  // 2b. Invalid type: malformed UUID for order_id
  await TestValidator.httpError("order_id malformed should fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        order_id: "fake-uuid" as any,
      } satisfies Partial<IRefund.IUpdate> as IRefund.IUpdate,
    })
  );

  // 3. Business logic failure: negative amount is not supported
  await TestValidator.httpError("negative refund amount should fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        amount: -9999
      } satisfies IRefund.IUpdate,
    })
  );

  // 3b. Optionally: zero amount (if business rule forbids 0 refund)
  await TestValidator.httpError("zero refund amount may fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        amount: 0
      } satisfies IRefund.IUpdate,
    })
  );

  // 4. Invalid/empty/null payloads
  await TestValidator.httpError("null amount should fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        amount: null as any
      } satisfies IRefund.IUpdate,
    })
  );
  await TestValidator.httpError("all fields null should fail")(400)(() =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: refund.id,
      body: {
        amount: null,
        currency: null,
        status: null,
        order_id: null,
        completed_at: null,
        reason: null
      } as any as IRefund.IUpdate,
    })
  );

  // 5. Confirm no mutation: fetch the refund and check not mutated
  const refetched: IRefund = await api.functional.paymentsDiscounts.refunds.post.simulate(
    connection, { body: refund } as any // using simulate for fetching current state
  );
  typia.assert(refetched);
  TestValidator.equals("refund id stable")(refund.id)(refetched.id);
  TestValidator.equals("amount unchanged")(refund.amount)(refetched.amount);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * Soft-delete an existing refund record and verify logical/audit rules.
 *
 * This scenario validates the soft-deletion (archiving) of refund entries.
 * - Ensures that a refund can be soft-deleted (audit preserved, not purged)
 * - Verifies that deleting a non-existent refund returns a 404 error
 * - Idempotency: Deleting the same refund twice does not break integrity/audit
 *
 * Steps:
 * 1. Create a refund event using the creation API.
 * 2. Delete (soft-delete) the refund using the proper endpoint.
 * 3. Attempt to delete a non-existent refund (random UUID) and expect 404 error.
 * 4. Attempt to delete the same refund a second time and verify idempotency.
 */
export async function test_api_refund_soft_delete_and_idempotency(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a refund record
  const refund: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    {
      body: {
        payment_id: typia.random<string & typia.tags.Format<"uuid">>(),
        transaction_id: typia.random<string & typia.tags.Format<"uuid">>(),
        order_id: null,
        amount: 1200.35,
        currency: "USD",
        status: "requested",
        reason: "Test for soft-delete E2E",
      } satisfies IRefund.ICreate,
    }
  );
  typia.assert(refund);

  // 2. Soft-delete the refund
  const deleted: IRefund.IDeleteResult =
    await api.functional.paymentsDiscounts.refunds.eraseById(connection, {
      id: refund.id,
    });
  typia.assert(deleted);
  TestValidator.equals("deleted id matches")(refund.id)(deleted.id);
  TestValidator.equals("delete success true")(true)(deleted.success);
  TestValidator.date("deleted_at valid")(deleted.deleted_at);

  // 3. Try to delete a random UUID (non-existent refund) - should return 404
  await TestValidator.httpError("delete non-existent refund")(404)(() =>
    api.functional.paymentsDiscounts.refunds.eraseById(connection, {
      id: typia.random<string & typia.tags.Format<"uuid">>(),
    })
  );

  // 4. Try to delete the same refund again - system should be idempotent / not fail catastrophically
  // Accept both: (a) another success response or (b) a 404 or soft error (depends on logic)
  try {
    const repeat = await api.functional.paymentsDiscounts.refunds.eraseById(
      connection,
      {
        id: refund.id,
      }
    );
    typia.assert(repeat);
    TestValidator.equals("repeat delete id matches")(refund.id)(repeat.id);
  } catch (err) {
    // Acceptable: 404 error or business logic error
    TestValidator.httpError("repeat delete idempotent")(404)(() => { throw err; });
  }
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";
import { IPageIPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPaymentAudit";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Retrieve a paginated and filtered list of payment audit records.
 *
 * This test verifies that the API correctly returns lists of payment audit logs,
 * with and without filters, and also checks pagination metadata in the response.
 * It covers filtering by entity_id, entity_type, and by timestamp range, and
 * tests the handling when no records match the filter criteria.
 *
 * Steps:
 * 1. Create two new payment audit records with differing entity_type and timestamps.
 * 2. List all payment audits (no filters); verify both new records appear, and check pagination metadata.
 * 3. List payment audits with a filter for the first record's entity_type; only the first should appear.
 * 4. List with a date range including only one record; verify filter works by timestamp.
 * 5. List with a bogus entity_id filter (no matches expected); output list should be empty.
 * 6. Confirm output type safety and data consistency for all queries.
 */
export async function test_api_payment_audit_list_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two payment audit records with distinct attributes
  const now = new Date();
  const earlier = new Date(now.getTime() - 60 * 60 * 1000).toISOString();
  const later = new Date(now.getTime() + 60 * 60 * 1000).toISOString();

  const audit1: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
    body: {
      entity_type: "payment",
      entity_id: typia.random<string>(),
      action: "create",
      new_value: "{\"amount\":100}",
      old_value: null,
      user_id: null,
      timestamp: earlier,
    } satisfies IPaymentAudit.ICreate,
  });
  typia.assert(audit1);

  const audit2: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
    body: {
      entity_type: "discount",
      entity_id: typia.random<string>(),
      action: "apply",
      new_value: "{\"discount\":20}",
      old_value: null,
      user_id: null,
      timestamp: later,
    } satisfies IPaymentAudit.ICreate,
  });
  typia.assert(audit2);

  // 2. No filter: Fetch all audits
  const pageAll: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: {} satisfies IPaymentAudit.IRequest,
  });
  typia.assert(pageAll);
  TestValidator.equals("pagination type")(
    typeof pageAll.pagination.current
  )("number");
  TestValidator.equals("at least contains audit1")(
    pageAll.data.some(x => x.id === audit1.id)
  )(true);
  TestValidator.equals("at least contains audit2")(
    pageAll.data.some(x => x.id === audit2.id)
  )(true);

  // 3. Filter by entity_type = 'payment': Only audit1
  const pageEntityType: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: {
      entity_type: "payment"
    } satisfies IPaymentAudit.IRequest,
  });
  typia.assert(pageEntityType);
  TestValidator.equals("entity_type filter count")(
    pageEntityType.data.every(x => x.entity_type === "payment") && pageEntityType.data.some(x => x.id === audit1.id)
  )(true);

  // 4. Filter by timestamp_from (should only see later entry)
  const pageTimestamp: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: {
      timestamp_from: later
    } satisfies IPaymentAudit.IRequest,
  });
  typia.assert(pageTimestamp);
  TestValidator.equals("timestamp filter matches audit2 only")(
    pageTimestamp.data.some(x => x.id === audit2.id)
  )(true);
  TestValidator.equals("timestamp filter excludes audit1")(
    pageTimestamp.data.some(x => x.id === audit1.id)
  )(false);

  // 5. Filter by bogus entity_id: expect empty
  const pageNone: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
    body: {
      entity_id: "ffffffff-ffff-ffff-ffff-ffffffffffff"
    } satisfies IPaymentAudit.IRequest,
  });
  typia.assert(pageNone);
  TestValidator.equals("empty result for bogus filter")(
    pageNone.data.length
  )(0);
  TestValidator.equals("pagination zero for bogus filter")(
    pageNone.pagination.records
  )(0);
}

