import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import type { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";
import typia from "typia";

/**
 * Validate creation (and schema restrictions) for payment audit records.
 *
 * This test ensures the payment audit logging endpoint accepts valid audit event payloads,
 * enforces field requirements, and protects against writing restricted/sensitive fields.
 *
 * 1. Attempt to create a payment audit record with valid and complete payload.
 * 2. Attempt to create a payment audit record with missing required fields (should error).
 * 3. Attempt to submit a payload specifying restricted fields (like "id") and verify they are either ignored (overridden by server) or rejected.
 * 4. Validate that type-checking and data integrity of successful and failing responses are correct.
 */
export async function test_api_payment_create_payment_audit_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Successful creation with complete payload
  const validPayload: IPaymentAudit.ICreate = {
    // 'user_id' can be omitted or null for system automation
    entity_type: "payment",
    entity_id: typia.random<string>(),
    action: "create",
    old_value: null,
    new_value: JSON.stringify({ amount: 1000, currency: "KRW" }),
    timestamp: new Date().toISOString(),
  };
  const audit: IPaymentAudit =
    await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
      body: validPayload,
    });
  typia.assert(audit);
  // Ensure response fields reflect payload and restricted/autogen fields are handled
  TestValidator.equals("entity_type")(validPayload.entity_type)(audit.entity_type);
  TestValidator.equals("entity_id")(validPayload.entity_id)(audit.entity_id);
  TestValidator.equals("action")(validPayload.action)(audit.action);
  TestValidator.equals("timestamp")(validPayload.timestamp)(audit.timestamp);
  // 'id' must be auto-generated (UUID), not client-supplied
  TestValidator.pass("id is UUID")(typia.is<string & typia.tags.Format<"uuid">>(audit.id));

  // 2. Fail creation with missing required fields
  await TestValidator.httpError("missing required 'entity_type'")(400)(() =>
    api.functional.paymentsDiscounts.paymentAudits.post(connection, {
      body: {
        // entity_type is missing
        entity_id: validPayload.entity_id,
        action: validPayload.action,
        timestamp: validPayload.timestamp,
      } as any, // Intentional bad payload
    })
  );
  await TestValidator.httpError("missing required 'entity_id'")(400)(() =>
    api.functional.paymentsDiscounts.paymentAudits.post(connection, {
      body: {
        entity_type: validPayload.entity_type,
        // entity_id is missing
        action: validPayload.action,
        timestamp: validPayload.timestamp,
      } as any,
    })
  );
  await TestValidator.httpError("missing required 'action'")(400)(() =>
    api.functional.paymentsDiscounts.paymentAudits.post(connection, {
      body: {
        entity_type: validPayload.entity_type,
        entity_id: validPayload.entity_id,
        // action is missing
        timestamp: validPayload.timestamp,
      } as any,
    })
  );
  await TestValidator.httpError("missing required 'timestamp'")(400)(() =>
