import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";

/**
 * Soft-delete (logically delete) an existing payment audit record and verify it
 * is retained for audit but does not appear in active listings. Deleting a
 * non-existent id should return a 404. Repeated deletes on the same id should
 * be idempotent and preserve evidence.
 *
 * Test Scenario:
 * 1. Create a payment audit record (to be deleted).
 * 2. Soft-delete the created payment audit record using its ID.
 * 3. Assert that the returned result contains the correct id and a valid deleted_at timestamp.
 * 4. Soft-delete the same payment audit record again (idempotency test). Assert no error and correct evidence is retained.
 * 5. Attempt to soft-delete a non-existent payment audit record. Assert a 404 is returned.
 *
 * This process ensures evidence is preserved for compliance, all audit actions are logged, and logical deletions are correctly handled.
 */
export async function test_api_paymentsDiscounts_paymentAudits_soft_delete_and_negative_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a payment audit record (for deletion test)
  const createBody: IPaymentAudit.ICreate = {
    user_id: null,
    entity_type: "payment",
    entity_id: typia.random<string & tags.Format<"uuid">>(),
    action: "create",
    old_value: null,
    new_value: JSON.stringify({ amount: 100, currency: "USD" }),
    timestamp: new Date().toISOString(),
  };
  const audit: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
    body: createBody,
  });
  typia.assert(audit);

  // 2. Soft-delete the created payment audit record
  const deleted: IPaymentAudit.IDeleteResult = await api.functional.paymentsDiscounts.paymentAudits.eraseById(connection, {
    id: audit.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(audit.id)(deleted.id);
  TestValidator.notUndefined("deleted_at")(deleted.deleted_at);

  // 3. Soft-delete again (idempotency)
  const secondDeleted: IPaymentAudit.IDeleteResult = await api.functional.paymentsDiscounts.paymentAudits.eraseById(connection, {
    id: audit.id,
  });
  typia.assert(secondDeleted);
  TestValidator.equals("idempotent delete id")(audit.id)(secondDeleted.id);
  TestValidator.notUndefined("deleted_at still present")(secondDeleted.deleted_at);

  // 4. Negative: Delete non-existent id should return 404
  const randomNotExistsId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("delete non-existent payment audit id should 404")(404)(() =>
    api.functional.paymentsDiscounts.paymentAudits.eraseById(connection, {
      id: randomNotExistsId,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IPageIMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessageThread";

/**
 * List message threads using pagination and filters.
 *
 * This test ensures listing and searching message threads works as expected, including filtering by subject, creator, archived status, date ranges, pagination edge cases, and sorting. It validates outputs, pagination info, and that extreme search criteria correctly yield empty result sets.
 *
 * 1. Create a message thread (for predictable presence in query results)
 * 2. List threads with no filter (should include the created thread)
 * 3. Filter by subject (exact/partial match)
 * 4. Filter by created_by_user_id
 * 5. Filter by archived status; test true/false
 * 6. Filter with created_at time range
 * 7. Paginate with limit=1 (check metadata, content)
 * 8. Paginate page 2 (if applicable)
 * 9. Sort with sort_field and sort_order
 * 10. Query with extreme/empty-case filters (nonsense subject, future date, etc.)
 */
export async function test_list_message_threads_with_filters_and_pagination(connection: api.IConnection): Promise<void> {
  // 1. Create a thread
  const created: IMessageThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: `Test Subject ${Date.now()}`,
    },
  });
  typia.assert(created);

  // 2. List with no filter
  const result1: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {},
  });
  typia.assert(result1);
  TestValidator.equals("should contain created thread")(
    true
  )(result1.data.some((th) => th.id === created.id));

  // 3. Filter by subject (exact/partial)
  const bySubjectExact: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: created.subject },
  });
  typia.assert(bySubjectExact);
  TestValidator.equals("thread by subject (exact)")(
    true
  )(bySubjectExact.data.some((th) => th.id === created.id));

  const partial = created.subject.slice(0, Math.floor(created.subject.length / 2));
  const bySubjectPartial: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { subject: partial },
  });
  typia.assert(bySubjectPartial);
  TestValidator.equals("thread by subject (partial)")(
    true
  )(bySubjectPartial.data.some((th) => th.id === created.id));

  // 4. Filter by created_by_user_id
  const byCreator: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { created_by_user_id: created.created_by_user_id },
  });
  typia.assert(byCreator);
  TestValidator.equals("thread by created_by_user_id")(
    true
  )(byCreator.data.some((th) => th.id === created.id));

  // 5. Filter by archived status (false)
  const byActive: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { archived: false },
  });
  typia.assert(byActive);
  TestValidator.equals("active threads should contain created")(
    true
  )(byActive.data.some((th) => th.id === created.id));

  // 5. Filter by archived status (true) -- should normally NOT contain created unless forced
  const byArchived: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { archived: true },
  });
  typia.assert(byArchived);
  TestValidator.equals("archived—should NOT contain created")(
    false
  )(byArchived.data.some((th) => th.id === created.id));

  // 6. Filter by created_at range (should include if range includes created)
  const createdFrom: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { created_from: created.created_at },
  });
  typia.assert(createdFrom);
  TestValidator.equals("created_from filter")(
    true
  )(createdFrom.data.some((th) => th.id === created.id));

  // Use a range in the far future to force empty
  const future: string = new Date(Date.now() + 1000 * 60 * 60 * 24 * 365).toISOString();
  const createdToEmpty: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { created_from: future },
  });
  typia.assert(createdToEmpty);
  TestValidator.equals("future date should be empty")(0)(createdToEmpty.data.length);

  // 7. Pagination: limit=1
  const paged: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("limit=1 metadata")(
    1
  )(paged.pagination.limit);
  TestValidator.equals("limit=1 one thread max")(
    true
  )(paged.data.length <= 1);

  // 8. Pagination page 2
  if (paged.pagination.pages > 1) {
    const nextPage: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
      body: { page: 2, limit: 1 },
    });
    typia.assert(nextPage);
    TestValidator.equals("pagination next page")(
      2
    )(nextPage.pagination.current);
  }

  // 9. Sort by created_at asc/desc
  const firstSorted: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      sort_field: "created_at",
      sort_order: "asc",
      limit: 2,
    },
  });
  typia.assert(firstSorted);
  // If at least 2, test the order
  if (firstSorted.data.length >= 2) {
    TestValidator.equals("sort order asc")(
      firstSorted.data[0].created_at <= firstSorted.data[1].created_at
    )(true);
  }
  const descSorted: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      sort_field: "created_at",
      sort_order: "desc",
      limit: 2,
    },
  });
  typia.assert(descSorted);
  if (descSorted.data.length >= 2) {
    TestValidator.equals("sort order desc")(
      descSorted.data[0].created_at >= descSorted.data[1].created_at
    )(true);
  }

  // 10. Extreme nonsense filters (should be empty)
  const nonsense: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      subject: "nonsense-string-that-should-not-exist-!@#$%",
    },
  });
  typia.assert(nonsense);
  TestValidator.equals("nonsense subject filter#empty")(0)(nonsense.data.length);

  const nonsenseUser: IPageIMessageThread = await api.functional.communicationReview.messageThreads.patch(connection, {
    body: {
      created_by_user_id: "00000000-0000-0000-0000-000000000000",
    },
  });
  typia.assert(nonsenseUser);
  TestValidator.equals("nonsense creator filter#empty")(0)(nonsenseUser.data.length);
}

