/**
 * 테스트 목적: 다양한 필터 및 페이징 옵션으로 메시지 목록 조회/검색 동작을 검증합니다.
 *
 * 메시지 조회 결과가 thread, sender, 날짜, 타입, 상태, full-text, 페이징/정렬 등 여러 필터와 조합을 모두 
 * 정상적으로 지원하며 반환되는지 end-to-end로 확인합니다.
 *
 * [비즈니스 배경]
 * - 실제 메시지 관제/감사 환경에서 Filter/Search/Paging 기능 완전성은 필수입니다.
 * - sender, thread, date, archived 등 모든 조합 필터가 정상 동작하는지 검증합니다.
 *
 * [테스트 상세 시나리오]
 *
 * 1. (사전 작업) 서로 다른 두 thread_id/두 sender_user_id 조합과 다양한 message_type/archived 조합의 메시지 최소 6개 생성
 * 2. 필터 미지정(전체 조회)시 생성된 모든 메시지 조회됨을 검증
 * 3. thread_id로 필터: 해당 스레드 메시지만 반환 확인
 * 4. sender_user_id로 각각 필터: 각 sender별 메시지만 반환 확인
 * 5. sent_from, sent_to로 날짜(시간) 윈도우 필터: 포함/제외 데이터 구간별로 메시지 정확하게 반환
 * 6. message_type별, archived별로 필터: 해당 조건이 맞는 메시지만 반환 확인
 * 7. 페이징(limit/page) 사용: 정상적으로 limit대로 나뉘어 반환되고 여러 페이지 합이 전체 개수와 일치하는지 검증
 * 8. 존재하지 않는 thread, sender, 날짜 범위, content(키워드) 조합으로는 empty 결과/올바른 메타데이터 확인
 * 9. 복합 필터 조합 (sender+type 등)시 교차 결과값 정확성 검증
 * 10. 각 API 응답은 typia.assert()로 타입 검증, 필요시 TestValidator.equals로 데이터/메타 검증
 *
 * (예외/에러 처리)
 * - 존재하지 않는 thread, sender로 검색 시 빈 목록이며 에러 발생하지 않음
 * - 페이징 메타데이터(records/pages/current 등) 정확 검증
 *
 * (후처리)
 * - 메시지는 삭제하지 않음
 */
export async function test_api_message_list_messages_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 메시지 샘플 데이터 6개 생성 (2개 thread, 2개 sender, 다양한 type/archived)
  const THREADS = [
    typia.random<string & typia.tags.Format<"uuid">>(),
    typia.random<string & typia.tags.Format<"uuid">>(),
  ];
  const SENDERS = [
    typia.random<string & typia.tags.Format<"uuid">>(),
    typia.random<string & typia.tags.Format<"uuid">>(),
  ];
  const TYPES = ["user", "system"];

  // 시간 제어: 오늘, 어제, 일주일 전
  const now = new Date();
  const DATES = [
    now.toISOString(),
    new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(),
    new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(),
  ];

  const createdMsgs: IMessage[] = [];
  for (let i = 0; i < 6; ++i) {
    const thread_id = THREADS[i % THREADS.length];
    const sender_user_id = SENDERS[i % SENDERS.length];
    const message_type = TYPES[i % TYPES.length];
    const archived = i % 2 === 0;
    const sent_at = DATES[i % DATES.length];
    const content = `test message ${i} ${message_type} ${archived}`;
    const body: IMessage.ICreate = {
      thread_id,
      content,
      message_type,
      parent_message_id: undefined,
    };
    // 메시지 생성
    let msg: IMessage = await api.functional.communicationReview.messages.post(connection, {
      body,
    });
    // sent_at/archived는 서버에서 관리하므로 응답에서 참조
    typia.assert(msg);
    createdMsgs.push(msg);
  }

  // 2. 전체 메시지 조회(필터 없음)
  const allResult: IPageIMessage = await api.functional.communicationReview.messages.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  createdMsgs.forEach(msg =>
    TestValidator.equals(`msg-exists ${msg.id}`)(
      true,
    )(
      allResult.data.some(m => m.id === msg.id),
    ),
  );

  // 3. thread_id별 필터
  for (const thread_id of THREADS) {
    const r = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id } satisfies IMessage.IRequest,
    });
    typia.assert(r);
    // 해당 thread 메시지만
    TestValidator.equals(`thread:${thread_id} only`)(
      createdMsgs.filter(m => m.thread_id === thread_id).map(m => m.id).sort(),
      r.data.filter(m => m.thread_id === thread_id).map(m => m.id).sort(),
    );
  }
  // 4. sender_user_id별 필터
  for (const sender_user_id of SENDERS) {
    const r = await api.functional.communicationReview.messages.patch(connection, {
      body: { sender_user_id } satisfies IMessage.IRequest,
    });
    typia.assert(r);
    TestValidator.equals(`sender:${sender_user_id} only`)(
      createdMsgs.filter(m => m.sender_user_id === sender_user_id).map(m => m.id).sort(),
      r.data.filter(m => m.sender_user_id === sender_user_id).map(m => m.id).sort(),
    );
  }
  // 5. sent_from, sent_to (날짜) 필터: 가장 최근 메시지만
  const after = new Date(now.getTime() - 12 * 60 * 60 * 1000).toISOString();
  const r5 = await api.functional.communicationReview.messages.patch(connection, {
    body: { sent_from: after } satisfies IMessage.IRequest,
  });
  typia.assert(r5);
  const afterIds = createdMsgs.filter(m => m.sent_at >= after).map(m => m.id).sort();
  TestValidator.equals("sent_from after only")(afterIds)(
    r5.data.filter(m => m.sent_at >= after).map(m => m.id).sort(),
  );
  // sent_to(과거) 필터: 일주일전만
  const weekAgo = new Date(now.getTime() - 6 * 24 * 60 * 60 * 1000).toISOString();
  const r6 = await api.functional.communicationReview.messages.patch(connection, {
    body: { sent_to: weekAgo } satisfies IMessage.IRequest,
  });
  typia.assert(r6);
  const beforeIds = createdMsgs.filter(m => m.sent_at <= weekAgo).map(m => m.id).sort();
  TestValidator.equals("sent_to only")(beforeIds)(
    r6.data.filter(m => m.sent_at <= weekAgo).map(m => m.id).sort(),
  );

  // 6. message_type, archived 별 필터
  for (const type of TYPES) {
    const r = await api.functional.communicationReview.messages.patch(connection, {
      body: { message_type: type } satisfies IMessage.IRequest,
    });
    typia.assert(r);
    TestValidator.equals(`type:${type} only`)(
      createdMsgs.filter(m => m.message_type === type).map(m => m.id).sort(),
      r.data.filter(m => m.message_type === type).map(m => m.id).sort(),
    );
  }
  for (const archived of [true, false]) {
    const r = await api.functional.communicationReview.messages.patch(connection, {
      body: { archived } satisfies IMessage.IRequest,
    });
    typia.assert(r);
    TestValidator.equals(`archived:${archived} only`)(
      createdMsgs.filter(m => m.archived === archived).map(m => m.id).sort(),
      r.data.filter(m => m.archived === archived).map(m => m.id).sort(),
    );
  }
  // 7. 페이징 (limit/page)
  const LIMIT = 2;
  const pages: string[][] = [];
  let foundIds: string[] = [];
  let page = 1;
  while (true) {
    const res = await api.functional.communicationReview.messages.patch(connection, {
      body: { limit: LIMIT, page } satisfies IMessage.IRequest,
    });
    typia.assert(res);
    const ids = res.data.map(m => m.id);
    pages.push(ids);
    foundIds.push(...ids);
    if (res.data.length < LIMIT) break;
    page++;
  }
  // 전체 데이터 쪼개짐 및 합친 값 일치 검증
  TestValidator.equals("paginated concat/all")(createdMsgs.map(m => m.id).sort())(Array.from(new Set(foundIds)).sort());

  // 8. 존재하지 않는 thread_id/sender/content → empty 결과
  const r8a = await api.functional.communicationReview.messages.patch(connection, {
    body: { thread_id: "00000000-0000-0000-0000-000000000000" } satisfies IMessage.IRequest,
  });
  typia.assert(r8a);
  TestValidator.equals("nonexist thread id")(0)(r8a.data.length);
  const r8b = await api.functional.communicationReview.messages.patch(connection, {
    body: { sender_user_id: "00000000-0000-0000-0000-000000000000" } satisfies IMessage.IRequest,
  });
  typia.assert(r8b);
  TestValidator.equals("nonexist sender")(0)(r8b.data.length);
  const r8c = await api.functional.communicationReview.messages.patch(connection, {
    body: { content: "__this_keyword_should_match_nothing__" } satisfies IMessage.IRequest,
  });
  typia.assert(r8c);
  TestValidator.equals("keyword empty")(0)(r8c.data.length);

  // 9. 복합 필터 조합 (sender+type 등)
  for (const sender_user_id of SENDERS) {
    for (const message_type of TYPES) {
      const r = await api.functional.communicationReview.messages.patch(connection, {
        body: { sender_user_id, message_type } satisfies IMessage.IRequest,
      });
      typia.assert(r);
      TestValidator.equals(
        `filter combo sender+type: ${sender_user_id}+${message_type}`,
      )(
        createdMsgs
          .filter(
            m => m.sender_user_id === sender_user_id && m.message_type === message_type,
          )
          .map(m => m.id)
          .sort(),
        r.data
          .filter(
            m => m.sender_user_id === sender_user_id && m.message_type === message_type,
          )
          .map(m => m.id)
          .sort(),
      );
    }
  }
  // 최종적으로 전체 응답 페이징 메타/카운트가 일관성 있는지 확인
  const total = createdMsgs.length;
  const metaCheck = await api.functional.communicationReview.messages.patch(connection, {
    body: { limit: total } satisfies IMessage.IRequest,
  });
  typia.assert(metaCheck);
  TestValidator.equals("meta total count")(total)(metaCheck.pagination.records);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
