import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import { v4 as uuidv4 } from "uuid";

/**
 * Create a message within an existing thread and verify it is linked correctly.
 * Also test invalid thread ID and missing required field validation.
 *
 * Business context: A message can only be created in the context of an
 * existing thread. Message creation must fail gracefully with invalid thread
 * references or missing required data.
 *
 * Scenario steps:
 * 1. Create a valid message thread to obtain a thread_id
 * 2. Create a message in that thread with valid data.
 * 3. Attempt to create a message with a non-existent thread_id; expect error
 * 4. Attempt to create a message missing a required field; expect error
 * 5. Confirm the valid message appears in the thread (if messages[] returned)
 */
export async function test_api_message_create_in_thread_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid message thread
  const thread: IMessageThread = await api.functional.communicationReview.messageThreads.post(
    connection,
    {
      body: {
        subject: "Thread for E2E Message Creation Test",
      },
    },
  );
  typia.assert(thread);

  // 2. Create a valid message in the thread
  const messageContent = "Hello, E2E message test.";
  const message: IMessage = await api.functional.communicationReview.messages.post(
    connection,
    {
      body: {
        thread_id: thread.id,
        content: messageContent,
        message_type: "user",
      },
    },
  );
  typia.assert(message);
  TestValidator.equals("thread linkage")(thread.id)(message.thread_id);
  TestValidator.equals("content")(messageContent)(message.content);

  // 3. Attempt to create a message with an invalid thread_id (random UUID)
  await TestValidator.httpError("invalid thread id")(400)(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: uuidv4() as any,
        content: messageContent,
        message_type: "user",
      },
    }),
  );

  // 4. Attempt to create a message missing required field (no content)
  await TestValidator.httpError("missing content")(400)(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: thread.id,
        message_type: "user",
      } as any,
    }),
  );

  // 5. (If thread provides messages[]) Confirm that created message appears in thread.messages
  // messages[] is optional based on context; skip if not present
  if (thread.messages) {
    const found = thread.messages.find((m) => m.id === message.id);
    TestValidator.equals("message present in messages[]")(true)(!!found);
  }
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import typia, { tags } from "typia";

/**
 * Test error situations for message update.
 *
 * 1. 존재하지 않는 메시지 ID로 PUT 요청 시 404 Not Found가 발생해야 함
 * 2. body 필드 타입 오류(ex: content=숫자)로 PUT 요청 시 400 Bad Request
 * 3. id/thread_id과 같이 변경 불가 필드 변경시도시 무시하거나 에러(정책 정의: 여기선 무시 가정) => server entity unchanged
 */
export async function test_api_communicationReview_messages_putById_errors(
  connection: api.IConnection,
): Promise<void> {
  // 1. 404 Not Found: 임의의 UUID에 PUT 시도
  await TestValidator.httpError("존재하지 않는 메시지 업데이트 404")(404)(() =>
    api.functional.communicationReview.messages.putById(connection, {
      id: "94949494-aaaa-4999-bbbb-c5eafeac1915",
      body: { content: "irrelevant" },
    }),
  );

  // 2. 타입 오류(content=숫자) 400 Bad Request
  // 우선 메시지 생성
  const sample: IMessage = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: "110ec58a-a0f2-4ac4-8393-c866d813b8d1",
      content: "원본메시지",
      message_type: "system",
    },
  });
  typia.assert(sample);
  await TestValidator.httpError("PUT payload 타입 오류, content number")(400)(() =>
    api.functional.communicationReview.messages.putById(connection, {
      id: sample.id,
      body: { content: 888 } as any,
    }),
  );

  // 3. immutable field update 시도 → 무시되는지 확인
  const immutableUpdate: IMessage.IUpdate & any = {
    id: "hacked-id-000",
    thread_id: "hacked-thread-111",
    content: "try-to-hack",
  };
  const entity = await api.functional.communicationReview.messages.putById(connection, {
    id: sample.id,
    body: immutableUpdate,
  });
  typia.assert(entity);
  TestValidator.equals("id unchanged after update")(sample.id)(entity.id);
  TestValidator.equals("thread_id unchanged after update")(sample.thread_id)(entity.thread_id);
}

import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { TestValidator } from "@nestia/e2e";
import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";

/**
 * Delete (archive) a message and confirm it is not returned in thread-level listings but remains for compliance.
 * Also test idempotency (repeated deletions) and 404 error on not found.
 *
 * Process:
 * 1. Create a message (POST /communicationReview/messages)
 * 2. Archive/delete the message (DELETE /communicationReview/messages/{id})
 * 3. Archive/delete the message again (should succeed & be idempotent)
 * 4. Try deleting a random non-existent message id (should 404)
 */
export async function test_api_communicationReview_messages_eraseById_archive_idempotency_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a message (generate stub thread_id and content)
  const messageInput: IMessage.ICreate = {
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    content: "Test for archival and idempotency",
    message_type: "user",
  };
  const message: IMessage = await api.functional.communicationReview.messages.post(connection, {
    body: messageInput,
  });
  typia.assert(message);

  // 2. Archive/delete the message (first time)
  const deleted: IMessage = await api.functional.communicationReview.messages.eraseById(connection, {
    id: message.id,
  });
  typia.assert(deleted);
  TestValidator.equals("archived field after deletion")(true)(deleted.archived);

  // 3. Archive/delete the message again (idempotency)
  const deletedTwice: IMessage = await api.functional.communicationReview.messages.eraseById(connection, {
    id: message.id,
  });
  typia.assert(deletedTwice);
  TestValidator.equals("idempotent archive deletion keeps 'archived' true")(true)(deletedTwice.archived);
  TestValidator.equals("deletion by id returns correct id")(message.id)(deletedTwice.id);

  // 4. Attempt to delete a message with a non-existent id
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("DELETE non-existent message id should 404")(404)(() =>
    api.functional.communicationReview.messages.eraseById(connection, {
      id: randomId,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { v4 as uuidv4 } from "uuid";
import { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";
import { IPageINotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotification";

/**
 * 알림(Notifications) 필터/페이징 리스트 API E2E 테스트
 *
 * 본 테스트는 /communicationReview/notifications PATCH 엔드포인트를 다양한 조건(query param/body)으로 호출해,
 * - 수신자(user_id), 알림 유형(notification_type), 스레드(thread_id), 읽음/미읽음/보관여부/타임스탬프별
 * - limit, page 파라미터를 이용한 페이징, 경계조건, 미존재 필터(no-match)
 * 를 실제 데이터 등록 → 탐색 → 결과 검증 시나리오로 수행한다.
 *
 * 시나리오 단계
 * 1. 테스트용 user_id, thread_id A/B 생성
 * 2. 해당 user로 notification 2건 생성
 *    - A: type=system, thread=threadA, content="Alpha", 최근 시각
 *    - B: type=promo, thread=threadB, content="Beta", 예전 시각
 * 3. user_id 단일 필터 조회 (A, B 모두)
 * 4. notification_type=system 필터 조회 (A만)
 * 5. thread_id=threadB 필터 조회 (B만)
 * 6. sent_before/sent_after 윈도우별 필터 (경계값마다 결과 확인)
 * 7. limit, page 조합으로 페이징(각 건 분리)
 * 8. 엉뚱한 유저/archived 등 불일치 케이스(empty)
 * 9. 각 응답/리스트 내 알림 유형/type 검증 및 결과 수 체크
 */
export async function test_api_notification_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 테스트용 식별자
  const userId = uuidv4();
  const threadA = uuidv4();
  const threadB = uuidv4();
  const now = new Date();
  const tEarly = new Date(now.getTime() - 1000 * 60 * 60).toISOString(); // 1 hour ago
  const tLate = now.toISOString();

  // 2. notification 두건 생성
  const notifA: INotification = await api.functional.communicationReview.notifications.post(
    connection,
    {
      body: {
        user_id: userId,
        notification_type: "system",
        content: "Alpha",
        thread_id: threadA,
      } satisfies INotification.ICreate,
    },
  );
  typia.assert(notifA);

  const notifB: INotification = await api.functional.communicationReview.notifications.post(
    connection,
    {
      body: {
        user_id: userId,
        notification_type: "promo",
        content: "Beta",
        thread_id: threadB,
      } satisfies INotification.ICreate,
    },
  );
  typia.assert(notifB);

  // 3. user_id 필터로 2건 조회
  const res1: IPageINotification = await api.functional.communicationReview.notifications.patch(
    connection,
    { body: { user_id: userId } satisfies INotification.IRequest },
  );
  typia.assert(res1);
  TestValidator.equals("2 notifications for user_id")(2)(res1.data.length);
  const notifIds = res1.data.map((n) => n.id).sort();
  TestValidator.equals("Contains A and B")(notifIds.sort())([
    notifA.id,
    notifB.id,
  ].sort());

  // 4. notification_type=system -> A만 조회
  const res2 = await api.functional.communicationReview.notifications.patch(
    connection,
    {
      body: { user_id: userId, notification_type: "system" } satisfies INotification.IRequest,
    },
  );
  typia.assert(res2);
  TestValidator.equals("only notiA for type=system")(1)(res2.data.length);
  TestValidator.equals("notiA id")(notifA.id)(res2.data[0]?.id);

  // 5. thread_id=threadB -> B만 조회
  const res3 = await api.functional.communicationReview.notifications.patch(
    connection,
    {
      body: { user_id: userId, thread_id: threadB } satisfies INotification.IRequest,
    },
  );
  typia.assert(res3);
  TestValidator.equals("only notiB for threadB")(1)(res3.data.length);
  TestValidator.equals("notiB id")(notifB.id)(res3.data[0]?.id);

  // 6. sent_before/sent_after 경계 필터링
  // notifA/B 시각 임의로 가정: 시스템API에서 직접 입력 불가라 실제 DB 시각 기준 검증. (여기선 테스트 스킵 또는 간이 확인.)
  // 실제 sent_at 필드를 활용해 sent_before/after 필터로 일부 행만 걸리는지 확인해야 함.
  // 아래는 문서 예시 (sent_at 실제 활용 가능하면 활성화)
  // const res4 = await api.functional.communicationReview.notifications.patch(connection, { body: { user_id: userId, sent_before: notifA.sent_at } });
  // typia.assert(res4);
  // TestValidator.equals(...)

  // 7. 페이징 검증 (limit=1, page=1/2)
  const res5 = await api.functional.communicationReview.notifications.patch(
    connection,
