import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Delete (archive) a notification and verify archival, idempotency, and not-found behavior.
 *
 * Test scenario reflects full compliance and audit traceability requirements.
 * All logical flows (normal, idempotent, error) are validated:
 *
 * 1. Create a notification (to be deleted later).
 * 2. Soft-delete (archive) the notification by ID.
 *    - Validate that 'archived' becomes true, and core fields remain consistent.
 * 3. Delete same notification again to test idempotency.
 *    - Expect same result; still archived, no error.
 * 4. Delete with an unknown/non-existent notification ID.
 *    - Must respond with 404 Not Found (or equivalent error indication).
 *
 * This ensures that archived notifications are omitted from ordinary lookups, but preserved for audit/evidence, and that repeated deletions or bad-IDs are predictably handled.
 */
export async function test_api_notification_delete_archive_idempotency_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new notification
  const newNotification: INotification = await api.functional.communicationReview.notifications.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        notification_type: "system",
        content: "Archive me, please.",
      } satisfies INotification.ICreate,
    },
  );
  typia.assert(newNotification);

  // 2. Delete (archive) the notification by ID
  const archived: INotification = await api.functional.communicationReview.notifications.eraseById(
    connection,
    {
      id: newNotification.id,
    },
  );
  typia.assert(archived);
  TestValidator.equals("archived field should be true")(true)(archived.archived);
  // Key fields remain unchanged except for archived
  TestValidator.equals("id consistency")(newNotification.id)(archived.id);
  TestValidator.equals("content consistency")(newNotification.content)(archived.content);
  TestValidator.equals("user_id consistency")(newNotification.user_id)(archived.user_id);

  // 3. Attempt to delete again (idempotency)
  const secondDelete: INotification = await api.functional.communicationReview.notifications.eraseById(
    connection,
    {
      id: newNotification.id,
    },
  );
  typia.assert(secondDelete);
  TestValidator.equals("idempotent archive")(archived)(secondDelete);

  // 4. Attempt to delete a non-existing ID
  await TestValidator.httpError("delete non-existent notification should 404")(404)(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // fresh random UUID unlikely to clash
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";
import { IPageIReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReview";
import typia from "typia";

/**
 * Review list/search filters and pagination tests.
 *
 * This E2E test validates the PATCH /communicationReview/reviews endpoint, covering its ability to:
 * - List all reviews
 * - Filter by reviewer/user, product, language, verified_purchase flag, archived status, parent review, and creation date
 * - Properly support paging and extreme/edge filter combinations
 *
 * Steps:
 * 1. Create a review record using POST /communicationReview/reviews for setup
 * 2. Basic list: no filters—should list at least the created review
 * 3. Filter by user_id
 * 4. Filter by product_id
 * 5. Filter by language_code
 * 6. Filter by verified_purchase (true)
 * 7. Filter by verified_purchase (false)
 * 8. Filter by archived (false)
 * 9. Filter by parent_review_id (null)
 * 10. Filter by creation date (after/before boundaries)
 * 11. Paging: limit 1, cycle pages
 * 12. Extreme: impossible filter—expect zero results
 */
export async function test_api_review_list_search_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create baseline review for test dataset
  const reviewInput: IReview.ICreate = {
    user_id: crypto.randomUUID(),
    product_id: crypto.randomUUID(),
    content: "Test review content for filter search.",
    language_code: "ko",
    verified_purchase: true,
  };
  const review: IReview = await api.functional.communicationReview.reviews.post(
    connection,
    { body: reviewInput }
  );
  typia.assert(review);

  // 2. Basic list (no filters)
  const basicList: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: {} }
  );
  typia.assert(basicList);
  TestValidator.equals("should include created review")(
    true
  )(basicList.data.map(r => r.id).includes(review.id));

  // 3. user_id filter
  const byUser: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { user_id: review.user_id } }
  );
  typia.assert(byUser);
  for(const r of byUser.data) {
    TestValidator.equals("user_id filter")(review.user_id)(r.user_id);
  }

  // 4. product_id filter
  const byProduct: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { product_id: review.product_id } }
  );
  typia.assert(byProduct);
  for(const r of byProduct.data) {
    TestValidator.equals("product_id filter")(review.product_id)(r.product_id);
  }

  // 5. language_code filter
  const byLang: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { language_code: review.language_code } }
  );
  typia.assert(byLang);
  for(const r of byLang.data) {
    TestValidator.equals("language_code filter")(review.language_code)(r.language_code);
  }

  // 6. verified_purchase: true
  const byPurchase: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { verified_purchase: true } }
  );
  typia.assert(byPurchase);
  for(const r of byPurchase.data) {
    TestValidator.equals("verified_purchase=true filter")(true)(r.verified_purchase);
  }

  // 7. verified_purchase: false
  const byNotPurchase: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { verified_purchase: false } }
  );
  typia.assert(byNotPurchase);
  for(const r of byNotPurchase.data) {
    TestValidator.equals("verified_purchase=false filter")(false)(r.verified_purchase);
  }

  // 8. archived: false
  const byNotArchived: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { archived: false } }
  );
  typia.assert(byNotArchived);
  for(const r of byNotArchived.data) {
    TestValidator.equals("archived=false filter")(false)(r.archived);
  }

  // 9. parent_review_id: null (top-level only)
  const byTopLevel: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { parent_review_id: null } }
  );
  typia.assert(byTopLevel);
  for(const r of byTopLevel.data) {
    TestValidator.equals("parent_review_id=null filter")(null)(r.parent_review_id ?? null);
  }

  // 10. created_after/created_before
  // after, expect review NOT included
  const after = new Date(Date.now() + 1000).toISOString();
  const afterRes: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { created_after: after } }
  );
  typia.assert(afterRes);
  TestValidator.equals("created_after-no match")(false)(afterRes.data.some(r => r.id === review.id));
  // before, expect review IS included
  const before = new Date(Date.now() + 100000).toISOString();
  const beforeRes: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { created_before: before } }
  );
  typia.assert(beforeRes);
  TestValidator.equals("created_before match")(true)(beforeRes.data.some(r => r.id === review.id));

  // 11. Paging (limit 1, test multiple pages)
  const paged: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { limit: 1, page: 1 } }
  );
  typia.assert(paged);
  TestValidator.equals("paging: limit")(1)(paged.pagination.limit);
  // If there is more than 1, page 2 should exist
  if (paged.pagination.pages > 1) {
    const paged2: IPageIReview = await api.functional.communicationReview.reviews.patch(
      connection,
      { body: { limit: 1, page: 2 } }
    );
    typia.assert(paged2);
    TestValidator.equals("paging: second page")(2)(paged2.pagination.current);
  }

  // 12. Extreme: impossible filter
  const impossible: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    { body: { user_id: crypto.randomUUID(), product_id: crypto.randomUUID() } }
  );
  typia.assert(impossible);
  TestValidator.equals("extreme filter: no match")(0)(impossible.data.length);
}

