/**
 * Update a review's content or allowed fields, and check that the update persists.
 * Attempt to update restricted fields or with invalid data and verify errors.
 * Update a non-existent review (404 expected).
 *
 * 1. Create a review to update.
 * 2. Update review content and allowed fields; validate response and persistence.
 * 3. Attempt to update restricted/immutable fields and confirm validation or rejection.
 * 4. Try invalid update bodies (malformed data, wrong type) and expect validation error.
 * 5. Attempt to update a non-existent review and expect 404 error.
 */
export async function test_api_review_update_valid_invalid_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a review (setup)
  const reviewInput: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    content: "Initial review content.",
    language_code: "en",
    verified_purchase: true,
  };
  const review: IReview = await api.functional.communicationReview.reviews.post(
    connection,
    { body: reviewInput },
  );
  typia.assert(review);

  // 2. Update allowed (mutable) fields and check persistence
  const updateBody: IReview.IUpdate = {
    content: "Updated review content.",
    language_code: "fr",
    verified_purchase: false,
    archived: true,
  };
  const updated: IReview = await api.functional.communicationReview.reviews.putById(
    connection,
    { id: review.id, body: updateBody },
  );
  typia.assert(updated);
  TestValidator.equals("updated content")(updateBody.content)(updated.content);
  TestValidator.equals("updated language_code")(updateBody.language_code)(updated.language_code);
  TestValidator.equals("updated verified_purchase")(updateBody.verified_purchase)(updated.verified_purchase);
  TestValidator.equals("updated archived")(updateBody.archived)(updated.archived);
  // Immutable fields should not change
  TestValidator.equals("user_id immutable")(review.user_id)(updated.user_id);
  TestValidator.equals("product_id immutable")(review.product_id)(updated.product_id);

  // 3. Attempt update with restricted/immutable field (should be ignored or error)
  const illegalUpdate: any = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    content: "Illegal update ignored.",
  };
  await TestValidator.httpError("updating immutable fields should fail or be ignored")(400)(() =>
    api.functional.communicationReview.reviews.putById(connection, { id: review.id, body: illegalUpdate }),
  );

  // 4. Try invalid update bodies and expect validation error
  // Empty object
  await TestValidator.httpError("empty update body should fail")(400)(() =>
    api.functional.communicationReview.reviews.putById(connection, { id: review.id, body: {} }),
  );
