import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";

/**
 * E2E Test: Archive (soft-delete) a review and verify idempotency and error cases.
 *
 * This scenario ensures that archiving a review via soft-delete sets the `archived` flag
 * and that deletion is idempotent (subsequent deletions return same archived state and no error).
 * Also verifies error behavior when deleting a non-existent or invalid id.
 *
 * 1. Create a new review entry (prerequisite).
 * 2. Soft-delete the created review via DELETE /communicationReview/reviews/:id
 *    - Check the response contains the same review with `archived: true`.
 * 3. Attempt to soft-delete the same review again.
 *    - Check the system responds with the same archived state (idempotent, `archived: true`).
 * 4. Attempt to soft-delete a non-existent review (random UUID).
 *    - Should return 404 error.
 * 5. Attempt to soft-delete with an invalid id (bad UUID format).
 *    - Should return 404 (or potentially 400 depending on validation logic).
 */
export async function test_api_review_soft_delete_idempotency_and_error(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new review entry (prerequisite)
  const created: IReview = await api.functional.communicationReview.reviews.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      content: "Soft-deletion review test - initial.",
      language_code: "en",
      verified_purchase: true,
    } satisfies IReview.ICreate,
  });
  typia.assert(created);
  TestValidator.equals("archived flag before delete")(false)(created.archived);

  // 2. Soft-delete the created review via DELETE
  const deleted: IReview = await api.functional.communicationReview.reviews.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("id after delete")(created.id)(deleted.id);
  TestValidator.equals("archived flag after delete")(true)(deleted.archived);

  // 3. Attempt to delete the same review again (idempotency)
  const deletedTwice: IReview = await api.functional.communicationReview.reviews.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deletedTwice);
  TestValidator.equals("id after repeated delete")(created.id)(deletedTwice.id);
  TestValidator.equals("archived remains true after repeated delete")(true)(deletedTwice.archived);

  // 4. Try to delete a non-existent review (random unused UUID)
  await TestValidator.httpError("delete non-existing review should return 404")(404)(() =>
    api.functional.communicationReview.reviews.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Try to delete with invalid id (bad UUID format)
  await TestValidator.httpError("delete invalid id should return 404 or 400, depending on implementation")(404)(() =>
    api.functional.communicationReview.reviews.eraseById(connection, {
      id: "invalid-uuid-format" as any,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
