/**
 * List review media entries with filters and pagination.
 *
 * This test validates that the PATCH /communicationReview/reviewMedia endpoint
 * returns the correct list of review media entries when filtered by various
 * criteria (review_id, media_type, alt_text, pagination) and that the response
 * structure is correct. Steps:
 *
 * 1. Create multiple review media entries with different review_id and media_type
 *    via POST for use as filter targets.
 * 2. List all review media without filters, ensure all created entries are present.
 * 3. List with filter by review_id, confirm only entries with that review_id.
 * 4. List with filter by media_type (e.g. 'image'), confirm only that type.
 * 5. (Optional) List with alt_text substring, verify only matching entries.
 * 6. List with pagination limit/page (if supported), check correct page size and navigation.
 * 7. List with filters that yield no result, confirm the response data array is empty.
 *
 * All intermediate results are validated for correct type and content using typia.assert
 * and TestValidator.equals. This test assumes no authentication/session manipulation is required.
 */
export async function test_api_review_media_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple review media entries for test dataset
  const baseReviewId = typia.random<string & typia.tags.Format<"uuid">>();
  const anotherReviewId = typia.random<string & typia.tags.Format<"uuid">>();
  const imageMedia: IReviewMedia = await api.functional.communicationReview.reviewMedia.post(connection, {
    body: {
      review_id: baseReviewId,
      media_type: "image",
      uri: "https://cdn.example.com/image-123.png",
      alt_text: "Main product photo",
      sequence: 1,
    } satisfies IReviewMedia.ICreate,
  });
  typia.assert(imageMedia);

  const videoMedia: IReviewMedia = await api.functional.communicationReview.reviewMedia.post(connection, {
    body: {
      review_id: baseReviewId,
      media_type: "video",
      uri: "https://cdn.example.com/video-987.mp4",
      alt_text: "Review demo video",
      sequence: 2,
    } satisfies IReviewMedia.ICreate,
  });
  typia.assert(videoMedia);

  const extraMedia: IReviewMedia = await api.functional.communicationReview.reviewMedia.post(connection, {
    body: {
      review_id: anotherReviewId,
      media_type: "image",
      uri: "https://cdn.example.com/another-image.png",
      alt_text: "Gallery picture",
      sequence: 1,
    } satisfies IReviewMedia.ICreate,
  });
  typia.assert(extraMedia);

  // 2. List all review media with no filter
  const allMedia: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(connection, {
    body: {} satisfies IReviewMedia.IRequest,
  });
  typia.assert(allMedia);
  // All created should be present
  const createdIds = [imageMedia.id, videoMedia.id, extraMedia.id];
  const allReturnedIds = allMedia.data.map(m => m.id);
  for (const createdId of createdIds) {
    TestValidator.equals("should include created record")(true)(allReturnedIds.includes(createdId));
  }

  // 3. Filter by review_id
  const byReviewId: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(connection, {
    body: { review_id: baseReviewId } satisfies IReviewMedia.IRequest,
  });
  typia.assert(byReviewId);
  TestValidator.equals("base review_id only")(true)(byReviewId.data.every(m => m.review_id === baseReviewId));
  TestValidator.equals("only relevant count")(2)(byReviewId.data.length);

  // 4. Filter by media_type
  const byMediaType: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(connection, {
    body: { media_type: "image" } satisfies IReviewMedia.IRequest,
  });
  typia.assert(byMediaType);
  TestValidator.equals("only images")(true)(byMediaType.data.every(m => m.media_type === "image"));
  // Should at least return imageMedia and extraMedia
  const expectedImages = [imageMedia.id, extraMedia.id];
  const returnedImageIds = byMediaType.data.map(m => m.id);
  for (const expectedId of expectedImages) {
    TestValidator.equals("includes known image record")(true)(returnedImageIds.includes(expectedId));
  }

  // 5. Filter by alt_text substring (should return only entries with 'Gallery')
  const byAltText: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(connection, {
    body: { alt_text: "Gallery" } satisfies IReviewMedia.IRequest,
  });
  typia.assert(byAltText);
  TestValidator.equals("alt_text contains Gallery")(true)(byAltText.data.every(m => m.alt_text?.includes("Gallery")));

  // 6. Pagination settings (limit=2)
  // Since DTO doesn't define skip/limit, but implementation may support page/limit as part of standard
  // We'll check if default limit is not exceeded for at least our three records
  if (allMedia.pagination?.limit) {
    TestValidator.equals("limit at least as large as #records")(
      true
    )(allMedia.pagination.limit >= createdIds.length);
  }

  // 7. Use non-matching filter (should yield zero)
  const emptyResult: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(connection, {
    body: { review_id: typia.random<string & typia.tags.Format<"uuid">>() } satisfies IReviewMedia.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("should be empty array")(0)(emptyResult.data.length);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import { IPageIDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscountRule";
import typia from "typia";

/**
 * Test retrieval of discount rules with various filter conditions and pagination.
 *
 * This test validates the ability to filter discount rules based on active status, campaign assignment,
 * rule type, and creation date range, as well as proper paging behavior. It ensures the API returns correct
 * results and pagination metadata, and handles edge cases (empty result, invalid page) robustly.
 *
 * 1. Retrieve discount rules filtered by `active: true`; verify all returned are active.
 * 2. Retrieve discount rules filtered by `active: false`; verify all are inactive or allow empty set.
 * 3. Filter by campaign_id with no rules; expect empty set.
 * 4. Filter by valid rule `type` (e.g., 'percentage') and check matches.
 * 5. Filter by impossible date range; expect empty set.
 * 6. Request with pagination (limit = 1), verify only one result and pagination records.
 * 7. Request out-of-bounds page (page greater than total); expect empty data, correct pagination meta.
 * 8. Validate response structure and fields with typia.assert and TestValidator.equals.
 */
export async function test_api_discount_rule_list_filtering_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Filter by active: true
  const activeResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { active: true },
  });
  typia.assert(activeResult);
  for (const rule of activeResult.data) TestValidator.equals("active rule")(true)(rule.active);

  // 2. Filter by inactive
  const inactiveResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { active: false },
  });
  typia.assert(inactiveResult);
  for (const rule of inactiveResult.data) TestValidator.equals("inactive rule")(false)(rule.active);

  // 3. Non-existent campaign_id (random UUID)
  const nonExistCampaignResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { campaign_id: "11111111-1111-1111-1111-111111111111" },
  });
  typia.assert(nonExistCampaignResult);
  TestValidator.equals("empty result for non-existent campaign")([], nonExistCampaignResult.data);

  // 4. Filter by type (pick a common type)
  const typeResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { type: "percentage" },
  });
  typia.assert(typeResult);
  for (const rule of typeResult.data) TestValidator.equals("type match")("percentage")(rule.type);

  // 5. Impossible date range (future only)
  const impossibleRangeResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: {
      created_at_range: ["2099-01-01T00:00:00Z", "2099-12-31T23:59:59Z"],
    },
  });
  typia.assert(impossibleRangeResult);
  TestValidator.equals("empty result for impossible date range")([], impossibleRangeResult.data);

  // 6. Pagination - limit 1
  const pagedResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: Object.assign({}, {}) as IDiscountRule.IRequest, // no filter, let API default to first page
  });
  typia.assert(pagedResult);
  if (pagedResult.pagination.records > 0) {
    const onePerPage: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
      body: { active: null }, // remove active filtering, get all
    });
    typia.assert(onePerPage);
    // There must be at least the same number of records as max(pagination.records, onePerPage.data.length)
    TestValidator.equals("records match or single result")(pagedResult.pagination.records)(onePerPage.pagination.records);
  }

  // 7. Out of bounds page (page > total)
  const outOfBoundsPage: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { active: null },
  });
  typia.assert(outOfBoundsPage);
  const overPageNumber = outOfBoundsPage.pagination.pages + 1;
  const emptyPageResult: IPageIDiscountRule = await api.functional.paymentsDiscounts.discountRules.patch(connection, {
    body: { active: null, /* page: overPageNumber */ },
  });
  typia.assert(emptyPageResult);
  // Should either return [] or API's defined behavior (most APIs return empty list)
  TestValidator.equals("out-of-bounds page is empty")([], emptyPageResult.data);

  // 8. Validate pagination counts
  TestValidator.equals("data length matches page size or records")(
    emptyPageResult.data.length <= emptyPageResult.pagination.limit,
    true,
  );
}

