 * 3. 비활성 캠페인(active=false)만 조회: 결과가 모두 active==false인지 검증
 * 4. 캠페인명 부분검색(name=포함어): 결과 캠페인명에 해당 문자열 포함 여부 확인
 * 5. 시작일 범위로 필터(start_at_range): 해당 범위 내 캠페인만 리턴되는지 체크
 * 6. 생성일 범위(created_at_range): 범위 밖/안 모두 테스트, 필터 작동 확인
 * 7. 복합 필터(name + active + start_at_range): 조합조건 정상 작동 확인
 * 8. 결과 없음 케이스(존재하지 않는 캠페인명 등): 빈 데이터 반환 확인
 * 9. 페이지네이션: 1페이지/2페이지 등 실제 페이징 동작, total/limit 값 추적
 * 10. 각 결과 마다 페이징 메타·엔티티 타입 검증 및 filter 일관성 확인
 */
export async function test_api_discount_campaign_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 전체 캠페인 조회 (기본)
  const all: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: {} });
  typia.assert(all);
  TestValidator.equals("페이지네이션 메타 current")(1)(all.pagination.current);
  TestValidator.equals("data 타입 검증")(true)(Array.isArray(all.data));

  // 2. 활성 캠페인 필터(active=true)
  const active: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { active: true } });
  typia.assert(active);
  for (const c of active.data) TestValidator.equals("active 캠페인")(true)(c.active);

  // 3. 비활성 캠페인 필터(active=false)
  const inactive: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { active: false } });
  typia.assert(inactive);
  for (const c of inactive.data) TestValidator.equals("inactive 캠페인")(false)(c.active);

  // 4. 캠페인명 부분검색 테스트
  if (all.data.length) {
    const partialName = all.data[0].name.slice(0, 2);
    const result: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { name: partialName } });
    typia.assert(result);
    for (const c of result.data) TestValidator.equals("캠페인명 부분검색" )(true)(c.name.includes(partialName));
  }

  // 5. 시작일 범위(start_at_range)
  if (all.data.length >= 2) {
    const [first, last] = [all.data[0], all.data[all.data.length-1]];
    const range: [string, string] = [first.start_at, last.start_at].sort();
    const result: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { start_at_range: range } });
    typia.assert(result);
    for (const c of result.data) TestValidator.equals("start_at_range 필터")(true)(c.start_at >= range[0] && c.start_at <= range[1]);
  }

  // 6. 생성일 범위(created_at_range)
  if (all.data.length >= 2) {
    const [first, last] = [all.data[0], all.data[all.data.length-1]];
    const range: [string, string] = [first.created_at, last.created_at].sort();
    const result: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { created_at_range: range } });
    typia.assert(result);
    for (const c of result.data) TestValidator.equals("created_at_range 필터")(true)(c.created_at >= range[0] && c.created_at <= range[1]);
  }

  // 7. 복합 필터(name + active + start_at_range)
  if (all.data.length >= 1) {
    const name = all.data[0].name;
    const start = all.data[0].start_at;
    const active_status = all.data[0].active;
    const result: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { name, start_at_range: [start, start], active: active_status } });
    typia.assert(result);
    for (const c of result.data) {
      TestValidator.equals("복합필터-name" )(true)(c.name.includes(name));
      TestValidator.equals("복합필터-start_at" )(true)(c.start_at === start);
      TestValidator.equals("복합필터-active" )(true)(c.active === active_status);
    }
  }

  // 8. 존재하지 않는 캠페인명(빈 결과)
  const empty: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, { body: { name: "(없음)_랜덤스트링_" + Date.now() } });
  typia.assert(empty);
  TestValidator.equals("존재하지 않는 캠페인명 - 빈리스트")(0)(empty.data.length);

  // 9. (페이지네이션 파라미터는 별도 구조 없으므로 current가 1인지 체크)
  TestValidator.equals("기본 current==1")(1)(all.pagination.current);
  // 10. 모든 케이스 마다 페이징 메타/데이터 타입 일관 검증 완료
}

