}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * Validate creation and field constraints for discount campaigns, including uniqueness and rule association.
 *
 * This test ensures discount campaign creation works with required attributes, properly handles required field validation, and enforces campaign name uniqueness. It covers all business scenarios and compliance requirements for campaign launches.
 *
 * 1. Create a discount rule (prerequisite for associating to a campaign if required).
 * 2. Create a new discount campaign with all valid, unique fields (name, times, active).
 * 3. Assert that the campaign is correctly created and the returned data matches the payload.
 * 4. Test missing required fields (e.g., "name", "start_at"), and validate the API rejects incomplete input.
 * 5. Test for uniqueness constraint: Attempt to create a second campaign with the same name, expect a validation error.
 * 6. Bonus: Attempt creation with invalid date window (end_at < start_at), validate error.
 */
export async function test_api_discount_campaign_create_validation_and_uniqueness(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create discount rule (prerequisite for business association)
  const discountRule: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "fixed",
      value: -1000,
      active: true,
    } satisfies IDiscountRule.ICreate,
  });
  typia.assert(discountRule);

  // 2. Create a valid unique discount campaign
  const campaignPayload = {
    name: `Summer Sale ${Date.now()}`,
    description: "Biggest midyear event.",
    start_at: new Date(Date.now() + 3600_000).toISOString(), // 1 hour in future
    end_at: new Date(Date.now() + 48*3600_000).toISOString(), // +2 days
    active: true,
  } satisfies IDiscountCampaign.ICreate;

  const campaign: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: campaignPayload,
  });
  typia.assert(campaign);
  TestValidator.equals("campaign name")(campaignPayload.name)(campaign.name);
  TestValidator.equals("active flag")(true)(campaign.active);
  TestValidator.equals("start_at")(campaignPayload.start_at)(campaign.start_at);

  // 3. Try creating campaign with missing required fields
  await TestValidator.httpError("missing name should 400")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        // name is missing
        start_at: campaignPayload.start_at,
        active: true,
      } as any,
    })
  );
  await TestValidator.httpError("missing start_at should 400")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: `Spring Sale ${Date.now()}`,
        active: true,
      } as any,
    })
  );

  // 4. Uniqueness: Creating campaign with duplicate name
  await TestValidator.httpError("duplicate campaign name rejected")(409)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: { ...campaignPayload, start_at: new Date(Date.now() + 7200_000).toISOString() } as IDiscountCampaign.ICreate,
    })
  );

  // 5. Invalid date range: end_at < start_at
  await TestValidator.httpError("invalid date range, end_at before start_at")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: `Backward Dates ${Date.now()}`,
        start_at: new Date(Date.now() + 10_000).toISOString(),
        end_at: new Date(Date.now() - 10_000).toISOString(),
        active: true,
      } satisfies IDiscountCampaign.ICreate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * Update campaign details and check business logic enforcement for discount campaigns.
 *
 * This test validates editing/updating a discount campaign while enforcing unique campaign naming, window constraints, and immutable business rules.
 *
 * 1. Create a discount campaign (valid, eligible for update)
 * 2. Update campaign details (description, name, date range, active status)
 * 3. Verify update reflects on the campaign.
 * 4. Attempt to change an immutable field (should be restricted or ignored)
 * 5. Attempt to update a finished campaign (past window) and expect error.
 * 6. Create and attempt to overlap window of another active campaign (expect error)
 * 7. Ensure business rules are enforced: no overlap, unique name, date validity.
 */
export async function test_api_discount_campaign_update_and_business_rule_enforcement(
  connection: api.IConnection,
) {
  // 1. Create a discount campaign
  const now = new Date();
  const start_at = new Date(now.getTime() + 60 * 60 * 1000).toISOString(); // +1h
  const end_at = new Date(now.getTime() + 5 * 60 * 60 * 1000).toISOString(); // +5h
  const campaign: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: `e2e-campaign-${Date.now()}`,
      description: "Initial campaign for E2E update test",
      start_at,
      end_at,
      active: true,
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign);

  // 2. Update campaign details
  const updatedName = `${campaign.name}-updated`;
  const newDescription = "Updated description by E2E test";
  const newStartAt = new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString(); // +2h
  const newEndAt = new Date(now.getTime() + 6 * 60 * 60 * 1000).toISOString(); // +6h

  const updated: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
    id: campaign.id,
    body: {
      name: updatedName,
      description: newDescription,
      start_at: newStartAt,
      end_at: newEndAt,
      active: false,
    } satisfies IDiscountCampaign.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("name")(updatedName)(updated.name);
  TestValidator.equals("description")(newDescription)(updated.description);
  TestValidator.equals("active")(false)(updated.active);
  TestValidator.equals("start_at")(newStartAt)(updated.start_at);
  TestValidator.equals("end_at")(newEndAt)(updated.end_at);

  // 3. Attempt to change an immutable field (created_at)
  // (created_at should never change via update - try malicious change)
  const maliciousCreatedAt = new Date(now.getTime() + 10 * 60 * 60 * 1000).toISOString();
  const immutableFieldUpdate = await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
    id: campaign.id,
    body: {
      created_at: maliciousCreatedAt, // should be ignored or error
    } as any, // forcibly insert
  });
  typia.assert(immutableFieldUpdate);
  TestValidator.equals("created_at does not change")(campaign.created_at)(immutableFieldUpdate.created_at);

  // 4. Attempt update on a finished campaign (simulate a past campaign)
  const finishedStart = new Date(now.getTime() - 10 * 60 * 60 * 1000).toISOString();
  const finishedEnd = new Date(now.getTime() - 5 * 60 * 60 * 1000).toISOString();
  const finishedCampaign: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: `e2e-finished-campaign-${Date.now()}`,
      description: "Past finished campaign (should not allow update)",
      start_at: finishedStart,
      end_at: finishedEnd,
      active: false,
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(finishedCampaign);
  // Try to update finished campaign
  await TestValidator.httpError("Cannot update finished campaign")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: finishedCampaign.id,
      body: {
        description: "Should fail to update finished campaign",
      } satisfies IDiscountCampaign.IUpdate,
    })
  );

  // 5. Create overlapping campaign and try to update overlap (expect error)
  const overlapBaseName = `e2e-campaign-overlap-${Date.now()}`;
  // Active campaign 1
  const overlapStart = new Date(now.getTime() + 10 * 60 * 60 * 1000).toISOString(); // +10h
  const overlapEnd = new Date(now.getTime() + 12 * 60 * 60 * 1000).toISOString(); // +12h
  const overlapCampaign1: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: overlapBaseName,
      description: "Overlap base",
      start_at: overlapStart,
      end_at: overlapEnd,
      active: true,
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(overlapCampaign1);
  // Campaign 2 to overlap the interval and use same name
  await TestValidator.httpError("Cannot create campaign with overlapping window or name")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: overlapBaseName,
        description: "Overlap attempt",
        start_at: new Date(now.getTime() + 11 * 60 * 60 * 1000).toISOString(), // overlaps by 1h
        end_at: new Date(now.getTime() + 13 * 60 * 60 * 1000).toISOString(),
        active: true,
      } satisfies IDiscountCampaign.ICreate,
    })
  );
  // Try to update first campaign to overlap with a new interval
  const extraCampaign: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: `${overlapBaseName}-extra`,
      description: "Extra for overlapping update test",
      start_at: new Date(now.getTime() + 14 * 60 * 60 * 1000).toISOString(),
      end_at: new Date(now.getTime() + 15 * 60 * 60 * 1000).toISOString(),
      active: true,
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(extraCampaign);
  await TestValidator.httpError("Cannot update to overlap other campaign period")(400)(() =>
    api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: extraCampaign.id,
      body: {
        name: overlapBaseName,
        start_at: overlapStart,
        end_at: overlapEnd,
        active: true,
      } satisfies IDiscountCampaign.IUpdate,
    })
  );
}

