import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IPageITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITransaction";
import { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";

/**
 * E2E test for transaction search with filters and pagination.
 *
 * Background: PaymentsDiscounts.transactions supports advanced filtering,
 * audit logging, pagination, and business analytics. This function ensures
 * search output follows spec, pagination works, filters are enforced, and all
 * audit fields are present in the response. It covers key use cases for query,
 * trace, compliance, and analytics pipelines. Edge paths and invalid inputs are
 * included.
 *
 * 1. Search transactions with no filters, check pagination/defaults.
 * 2. Filter by user_id.
 * 3. Filter by order_id.
 * 4. Filter by transaction type.
 * 5. Filter by date range (created_after, created_before).
 * 6. Use valid pagination: page and limit.
 * 7. Edge: request too high page (expect empty data, valid meta).
 * 8. Edge: impossible filter (random uuid for user/order returns empty).
 * 9. Edge: invalid page/limit input (expect error or safe handling).
 * 10. For all responses, validate presence of id, user_id, type, created_at.
 */
export async function test_api_transaction_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Basic unfiltered search (should paginate default)
  const all: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: {},
    });
  typia.assert(all);
  TestValidator.equals("pagination present")(typeof all.pagination)("object");
  TestValidator.equals("data array")(Array.isArray(all.data))(true);
  if (all.data.length > 0) {
    all.data.forEach((tx, idx) => {
      typia.assert<ITransaction>(tx);
      TestValidator.equals("id present")(typeof tx.id)("string");
      TestValidator.equals("user_id present")(typeof tx.user_id)("string");
      TestValidator.equals("type present")(typeof tx.type)("string");
      TestValidator.equals("created_at present")(typeof tx.created_at)("string");
    });
  }

  // Utility: Pick first transaction for targeted filter tests
  const firstTx = all.data[0];
  if (!firstTx) return; // Skip next tests if data is empty

  // 2. Filter by user_id
  const byUser: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { user_id: firstTx.user_id } satisfies ITransaction.IRequest,
    });
  typia.assert(byUser);
  if (byUser.data.length > 0)
    byUser.data.forEach((tx) => TestValidator.equals("user_id filter")(tx.user_id)(firstTx.user_id));

  // 3. Filter by order_id, if present
  if (firstTx.order_id) {
    const byOrder: IPageITransaction =
      await api.functional.paymentsDiscounts.transactions.patch(connection, {
        body: { order_id: firstTx.order_id } satisfies ITransaction.IRequest,
      });
    typia.assert(byOrder);
    if (byOrder.data.length > 0)
      byOrder.data.forEach((tx) => TestValidator.equals("order_id filter")(tx.order_id)(firstTx.order_id));
  }

  // 4. Filter by type
  const byType: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { type: firstTx.type } satisfies ITransaction.IRequest,
    });
  typia.assert(byType);
  if (byType.data.length > 0)
    byType.data.forEach((tx) => TestValidator.equals("type filter")(tx.type)(firstTx.type));

  // 5. Filter by date range: created_after and created_before
  const CA = new Date(firstTx.created_at).toISOString();
  const CB = new Date(Date.now() + 1000 * 60).toISOString(); // future
  const byRange: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { created_after: CA, created_before: CB } satisfies ITransaction.IRequest,
    });
  typia.assert(byRange);
  if (byRange.data.length > 0) for (const tx of byRange.data) {
    TestValidator.equals("range after")(tx.created_at >= CA)(true);
    TestValidator.equals("range before")(tx.created_at <= CB)(true);
  }

  // 6. Pagination: page = 1, limit = 2
  const paged: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: 1, limit: 2 } satisfies ITransaction.IRequest,
    });
  typia.assert(paged);
  TestValidator.equals("page 1")(paged.pagination.current)(1);
  TestValidator.equals("limit 2")(paged.pagination.limit)(2);
  TestValidator.equals("data array should match page size or be less")(paged.data.length <= 2)(true);

  // 7. Edge: request excessive page (empty data)
  const hugePage = paged.pagination.pages + 50;
  const empty: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: hugePage, limit: 1 } satisfies ITransaction.IRequest,
    });
  typia.assert(empty);
  TestValidator.equals("empty page data")(empty.data.length)(0);
  TestValidator.equals("pages match")(empty.pagination.pages)(paged.pagination.pages);

  // 8. Edge: impossible filter (random uuid for user_id)
  const { v4: uuidv4 } = require("uuid");
  const none: IPageITransaction =
    await api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { user_id: uuidv4() } satisfies ITransaction.IRequest,
    });
  typia.assert(none);
  TestValidator.equals("no results random uuid")(none.data.length)(0);

  // 9. Edge: invalid page/limit values (page=0, limit=0)
  await TestValidator.error("rejects page=0")(() =>
    api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: 0, limit: 1 } satisfies ITransaction.IRequest,
    }),
  );
  await TestValidator.error("rejects limit=0")(() =>
    api.functional.paymentsDiscounts.transactions.patch(connection, {
      body: { page: 1, limit: 0 } satisfies ITransaction.IRequest,
    }),
  );

  // 10. Audit field presence for paged responses already checked above.
}

