import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";

/**
 * Test logical deletion (soft-delete) of a transaction record by ID, enforcing audit compliance and error handling standards.
 *
 * Scenario:
 * 1. Create a new transaction with valid data (as a deletion candidate).
 * 2. Delete (soft-delete) the transaction by its ID using eraseById.
 * 3. Attempt redundant deletion of the same transaction (should fail).
 * 4. Attempt deletion with a non-existent (random) transaction ID (should fail).
 *
 * Notes:
 * - Tests proper handling of normal, repeated, and invalid (non-existent) deletion requests.
 * - Output responses are asserted for type and negative paths.
 * - Compliance with audit/evidence flow is assumed by endpoint implementation.
 */
export async function test_api_transaction_soft_delete_behavior(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new transaction as input
  const txCreate: ITransaction = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        order_id: typia.random<string & tags.Format<"uuid">>(),
        type: "purchase",
        created_at: new Date().toISOString() as string & tags.Format<"date-time">,
        description: "Test transaction for soft-delete behavior",
      } satisfies ITransaction.ICreate,
    },
  );
  typia.assert(txCreate);

  // 2. Delete (soft-delete) transaction by ID
