import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";
import { IPageIVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIVoucher";
import typia from "typia";

/**
 * List vouchers with multiple filters and pagination validation.
 *
 * Retrieves a paginated, filtered list of voucher records from the PaymentsDiscounts.vouchers API.
 * Tests filter combinations including issued-to (user), redeemed/unused status, date ranges, campaign assignment, and code match.
 * Validates successful filtering, edge responses for empty results, and conformance of pagination meta.
 *
 * 1. Ensure there is a representative mix of vouchers in DB (manual/test data or via seed; test is agnostic but expects variety).
 * 2. Query using user_id, redeemed=false, expires_after=now, limit=5. Assert each result matches all filters. Confirm pagination correctness.
 * 3. Query redeemed=true and check all results have non-null redeemed_at.
 * 4. Query with expires_before and expires_after. Validate expiry window works.
 * 5. Query filter by code (exact). Validate only correct voucher(s) returned.
 * 6. Query a page that returns zero results (e.g., very high page number or restrictive filter). Assert empty data, proper pagination meta.
 * 7. Query using page beyond last page to ensure empty result, meta correctness.
 * 8. For all responses: validate structure strictly via typia.assert, check that pagination meta aligns with expected logic.
 * 9. Validate data integrity and type-safety.
 */
export async function test_api_voucher_list_with_multiple_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Fetch all vouchers, pick reference data for later filter values.
  const allVouchers: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {} as IVoucher.IRequest,
  });
  typia.assert(allVouchers);
  const data = allVouchers.data;
  if (!data.length)
    throw new Error("Test requires at least one voucher in the system");

  const firstVoucher = data[0];
  const usedVoucher = data.find(v => v.redeemed_at != null) ?? firstVoucher;
  const unusedVoucher = data.find(v => v.redeemed_at == null) ?? firstVoucher;
  const userId = firstVoucher.user_id;
  const voucherCode = firstVoucher.code;
  const now = new Date().toISOString();

  // 2. Query with user_id, redeemed=false, expires_after=now, limit=5
  const response1: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      user_id: userId,
      redeemed: false,
      expires_after: now,
      limit: 5,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response1);
  response1.data.forEach(vch => {
    TestValidator.equals("filter:user_id")(userId)(vch.user_id);
    TestValidator.equals("filter:unused")(null)(vch.redeemed_at);
    TestValidator.equals("filter:expires_after")(true)(!vch.expires_at || vch.expires_at > now);
  });
  TestValidator.equals("pagination.limit")(5)(response1.pagination.limit);

  // 3. Query with redeemed=true
  const response2: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      redeemed: true,
      limit: 10,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response2);
  response2.data.forEach(vch => {
    TestValidator.equals("filter:redeemed")(false)(vch.redeemed_at == null);
  });

  // 4. Query with expires_before and expires_after
  const after = data.find(v => v.expires_at)?.expires_at || now;
  const before = data.find(v => v.expires_at && v.expires_at > after)?.expires_at || new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const response3: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      expires_after: after,
      expires_before: before,
      limit: 10,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response3);
  response3.data.forEach(vch => {
    TestValidator.equals("filter:expires_window")(true)(!vch.expires_at || (vch.expires_at > after && vch.expires_at < before));
  });

  // 5. Query by code (exact filter)
  const response4: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      code: voucherCode,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response4);
  response4.data.forEach(vch => {
    TestValidator.equals("filter:code")(voucherCode)(vch.code);
  });

  // 6. Empty result: very restrictive filter
  const response5: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      code: "non-existent-code-value",
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response5);
  TestValidator.equals("empty result")(0)(response5.data.length);
  TestValidator.equals("pagination matches empty")(0)(response5.pagination.records);

  // 7. Query page beyond last page
  const pageHigh = (allVouchers.pagination.pages ?? 1) + 100;
  const response6: IPageIVoucher = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      page: pageHigh,
      limit: 2,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(response6);
  TestValidator.equals("empty page result")(0)(response6.data.length);

  // 8/9: Validate pagination meta and type-safety globally
  [response1, response2, response3, response4, response5, response6].forEach(res => {
    typia.assert(res);
    TestValidator.equals("pagination current >= 1")(true)(res.pagination.current >= 1);
    TestValidator.equals("pagination limit > 0")(true)(res.pagination.limit > 0);
    TestValidator.equals("pagination pages >= 1")(true)(res.pagination.pages >= 1);
    TestValidator.equals("pagination records >= 0")(true)(res.pagination.records >= 0);
  });
}

