import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * E2E test for voucher creation with enforcement of all business rules.
 *
 * Validates the correct creation of a voucher, and enforcement of required field,
 * value, and uniqueness business constraints.
 *
 * 1. Create a voucher with all required and valid fields (happy path).
 * 2. Create a voucher with a missing user_id (should fail).
 * 3. Create a voucher with a negative balance (should fail).
 * 4. Create a voucher with an already-used code (should fail).
 * 5. Create a voucher with an unsupported currency code (should fail).
 * 6. Validate behaviour for null optional fields and edge expiry value.
 *
 * Assert correct value and error validations after each operation.
 */
export async function test_api_voucher_create_with_success_and_business_rule_enforcement(connection: api.IConnection): Promise<void> {
  // 1. Happy path - valid voucher
  const validVoucherInput: IVoucher.ICreate = {
    user_id: "00000000-0000-4000-8000-000000000001",
    code: `TEST-VOUCHER-${Math.random().toString(36).slice(2, 10)}`,
    balance: 1000,
    currency: "USD",
    expires_at: new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString(),
  };
  const voucher = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: validVoucherInput });
  typia.assert(voucher);

  // 2. Missing user_id
  await TestValidator.httpError("missing user_id")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, user_id: undefined } as any,
    })
  );

  // 3. Negative balance
  await TestValidator.httpError("negative balance")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, code: `NEGATIVE-${Math.random()}`, balance: -100 },
    })
  );

  // 4. Duplicate code
  await TestValidator.httpError("duplicate code")(409)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput },
    })
  );

  // 5. Unsupported currency
  await TestValidator.httpError("unsupported currency")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, code: `BADCUR-${Math.random()}`, currency: "ZZZ" },
    })
  );

  // 6. Optional fields as null, expiry in the past
  const nullOptional: IVoucher.ICreate = {
    user_id: "00000000-0000-4000-8000-000000000002",
    code: `NULL-OPTIONAL-${Math.random()}`,
    balance: 50,
    currency: "USD",
    campaign_id: null,
    payment_method_id: null,
    expires_at: null,
  };
  const resultNullOptional = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: nullOptional });
  typia.assert(resultNullOptional);
  // Expiry in the past (should fail)
  await TestValidator.httpError("expiry in the past")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, code: `PASTEXP-${Math.random()}`, expires_at: new Date(Date.now() - 24*60*60*1000).toISOString() }
    })
  );
}

