import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * Soft delete (revoke) a voucher by ID, verifying it cannot be redeemed after deletion and ensuring it is excluded from active queries.
 *
 * Scenario:
 * 1. Create a voucher (issue to user)
 * 2. Soft-delete (revoke) the voucher by ID
 * 3. Attempt to delete again to assert idempotency or proper error semantics
 * 4. Attempt to delete a non-existent voucher to verify error response
 *
 * Evidence chains, error and compliance trails included.
 * Assumes GET and redemption APIs are not directly available; tests only what is surfaced by current API surface.
 */
export async function test_api_voucher_delete_revocation_behavior(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a voucher (POST)
  const voucherCreateBody: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: `TEST-${Date.now()}-${Math.floor(Math.random()*100000)}`,
    balance: 10000,
    currency: "KRW",
  };
  const created: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(connection, {
    body: voucherCreateBody,
  });
  typia.assert(created);

  // 2. Soft-delete (revoke) the voucher
  const revoked: IVoucher = await api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
    id: created.id,
  });
  typia.assert(revoked);
  TestValidator.equals("Voucher ID after revoke")(created.id)(revoked.id);
  // Check: revoked.redeemed_at or revocation evidence must now be non-null (if so per business logic)
  // Can't enforce, but if there is such a field, optionally assert:
  // TestValidator.notNull("revoked.redeemed_at")(revoked.redeemed_at!);

  // 3. Attempt to delete again (should be idempotent or error)
  try {
    const revokedAgain: IVoucher = await api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
      id: created.id,
    });
    typia.assert(revokedAgain);
    TestValidator.equals("Voucher ID after 2nd revoke")(created.id)(revokedAgain.id);
    // If system returns final voucher state, this is considered idempotent. Optionally check evidence.
  } catch (err) {
    // If error is thrown, check that it's appropriate (404 or already-deleted business error)
    await TestValidator.httpError("delete already-revoked")(404)(async () => { throw err; });
  }

  // 4. Attempt to delete a non-existent voucher (should error)
  await TestValidator.httpError("delete non-existent")
    (404)(() =>
      api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      })
    );
}

