/**
 * Validate creation and business rule enforcement for loyalty points event ledger entries.
 *
 * Test all major compliance requirements:
 * - Proper payload allows point award (success)
 * - Negative/Above-max points rejected (input validation)
 * - Missing required fields rejected (input validation)
 * - Repeat awards for same txn/user/rule: checks business uniqueness compliance
 *
 * 1. Create a valid loyalty point earn event (all required fields present, positive point value)
 * 2. Attempt to create event with negative points value (expect failure)
 * 3. Attempt to create event with extremely high points value (simulate above maximum, expect failure)
 * 4. Attempt to create event missing required fields (e.g., user_id, type)
 * 5. Issue multiple entries for the same transaction/user/type/campaign, check uniqueness or proper aggregation as per business rule
 *
 * Each branch asserts response structure or error.
 */
export async function test_api_loyalty_point_create_validation_and_business_rules(
  connection: api.IConnection,
): Promise<void> {
  // Setup: base UUIDs
  const user_id = uuid();
  const txn_id = uuid();
  const campaign_id = uuid();

  // 1. Valid event
  const validPayload: ILoyaltyPoint.ICreate = {
    user_id,
    transaction_id: txn_id,
    campaign_id,
    points: 50,
    type: "earn",
  };
  const validRes: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: validPayload });
  typia.assert(validRes);
  TestValidator.equals("user_id")(user_id)(validRes.user_id);
  TestValidator.equals("type")("earn")(validRes.type);
  TestValidator.equals("points")(50)(validRes.points);

  // 2. Negative points (failure expected)
  const negPayload: ILoyaltyPoint.ICreate = {
    ...validPayload,
    points: -100,
  };
  await TestValidator.error("negative points rejected")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: negPayload })
  );

  // 3. Above-maximum points (simulate; assume 1000 max)
  const highPayload: ILoyaltyPoint.ICreate = {
    ...validPayload,
    points: 1000000,
  };
  await TestValidator.error("above-maximum points rejected")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: highPayload })
  );

  // 4. Missing required fields: user_id
  const { user_id: _omit, ...noUserPayload } = validPayload;
  // @ts-expect-error
  await TestValidator.error("missing user_id")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: noUserPayload })
  );

  // 4b. Missing required fields: type
  const { type: _omit2, ...noTypePayload } = validPayload;
  // @ts-expect-error
  await TestValidator.error("missing type")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: noTypePayload })
  );

  // 5. Repeat event: same user, txn, type, campaign
  const repeatPayload: ILoyaltyPoint.ICreate = {
    ...validPayload,
    points: 20,
  };
  // First award
  const repeatRes1 = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: repeatPayload });
  typia.assert(repeatRes1);
  // Duplicate (should fail or aggregate depending on business rule)
  await TestValidator.error("duplicate loyalty point event rejected")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.post(connection, { body: repeatPayload })
  );
}

