 * are included. Each refund and pagination object are validated structurally.
 *
 * 1. Query with no filter: expect all refunds with basic pagination
 * 2. Filter by status (e.g., 'requested', 'completed'): all returned refunds must match status
 * 3. Filter by date/time ranges: all refunds' date fields should fall within requested bounds
 * 4. Filter by payment_id, order_id, transaction_id: only refunds referencing these
 * 5. Pagination test: page=1/limit=2 and page=2/limit=2 yields correct splitting/ordering
 * 6. Invalid/nonexistent filter: expect empty result
 * 7. Overreaching page: expect empty but paginated response
 * 8. Data/shape validation: every refund result has all evidence/audit key fields
 * 9. Pagination information is present and accurate
 */
export async function test_api_refund_list_refunds_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // [1] Query all refunds (no filter)
  const allRefunds: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: {} });
  typia.assert(allRefunds);
  TestValidator.equals("pagination.records >= data.length")(true)(allRefunds.pagination.records >= allRefunds.data.length);

  // If there are refunds to base filters on, pick one for further filter tests
  const ref = allRefunds.data[0];

  // [2] Filter by status if any exists
  if (ref) {
    const statusFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { status: ref.status } });
    typia.assert(statusFiltered);
    for (const refund of statusFiltered.data) {
      TestValidator.equals("status matches")(ref.status)(refund.status);
    }
  }

  // [3] Filter by requested_at range
  if (ref) {
    const rangeFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { requested_from: ref.requested_at, requested_to: ref.requested_at } });
    typia.assert(rangeFiltered);
    for (const refund of rangeFiltered.data) {
      TestValidator.equals("requested_at in range")(ref.requested_at)(refund.requested_at);
    }
  }

  // [4] Filter by payment_id/order_id/transaction_id
  if (ref) {
    const paymentFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { payment_id: ref.payment_id } });
    typia.assert(paymentFiltered);
    for (const refund of paymentFiltered.data) {
      TestValidator.equals("payment_id matches")(ref.payment_id)(refund.payment_id);
    }

    if (ref.order_id) {
      const orderFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { order_id: ref.order_id } });
      typia.assert(orderFiltered);
      for (const refund of orderFiltered.data) {
