      }
    }

    const transactionFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { transaction_id: ref.transaction_id } });
    typia.assert(transactionFiltered);
    for (const refund of transactionFiltered.data) {
      TestValidator.equals("transaction_id matches")(ref.transaction_id)(refund.transaction_id);
    }
  }

  // [5] Pagination test: limit 2 per page, walk 2 pages (if enough refunds)
  const page1: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { page: 1, limit: 2 } });
  typia.assert(page1);
  TestValidator.equals("limit")(2)(page1.pagination.limit);
  if (page1.data.length === 2) {
    const page2: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { page: 2, limit: 2 } });
    typia.assert(page2);
    // If enough records: records should not overlap
    if (page2.data.length > 0) {
      TestValidator.equals("non-overlapping first id")(true)(page1.data[0].id !== page2.data[0].id);
    }
  }

  // [6] Invalid/nonexistent filter should return empty data
  const noneFiltered: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { status: "definitely-not-a-valid-status" } });
  typia.assert(noneFiltered);
  TestValidator.equals("empty array")(0)(noneFiltered.data.length);

  // [7] Overreaching page: request a page way beyond, expect empty data but valid pagination
  const farPage: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(connection, { body: { page: 1000, limit: 2 } });
  typia.assert(farPage);
  TestValidator.equals("empty page data")(0)(farPage.data.length);
  TestValidator.equals("pagination validity")(1000)(farPage.pagination.current);

  // [8] Validate all refund results have essential fields and shapes
  function checkRefundShape(refund: IRefund) {
    typia.assert(refund);
    ["id","payment_id","transaction_id","status","amount","currency","requested_at"].forEach((key) => {
      if (!(key in refund)) throw new Error(`Refund is missing key: ${key}`);
    });
  }
  allRefunds.data.forEach(checkRefundShape);
}

