import typia from "typia";

/**
 * Create a new refund event with all requisite metadata and compliance evidence, and validate idempotency and business logic enforcement.
 *
 * - Ensures proper creation of refund record when provided with valid atomic evidence and all required fields
 * - Validates that negative amounts, duplicate refund attempts, and missing fields are properly rejected
 * - Checks idempotency by re-posting identical refund creation data, expecting consistent enforcement (no duplicates)
 *
 * Steps
 * 1. Construct valid payload for creating a refund event (complete metadata, positive amount, valid payment/transaction IDs)
 * 2. POST /paymentsDiscounts/refunds with valid data; assert creation & structure (evidence fields present)
 * 3. Attempt creating refund with missing required fields (e.g. omit payment_id, transaction_id, amount, currency, status) and expect error on each
 * 4. Attempt creating with negative refund amount; expect validation error
 * 5. Attempt refund with already-refunded payment_id (simulate business rule)
 * 6. Check idempotency: re-submit same payload and confirm compliance (either idempotent result or duplicate rejection)
 * 7. Optionally, attempt concurrent identical refund requests, verify only one record created
 */
export async function test_api_refund_create_with_metadata_and_idempotency_checks(connection: api.IConnection): Promise<void> {
  // 1. Prepare a valid refund creation payload
  const validRefund: IRefund.ICreate = {
    payment_id: typia.random<string>(),
    transaction_id: typia.random<string>(),
    order_id: typia.random<string>(),
    amount: 6500.5,
    currency: "USD",
    status: "requested",
    reason: "Order cancelled by customer"
  } satisfies IRefund.ICreate;

  // 2. Create refund event - valid request
  const created: IRefund = await api.functional.paymentsDiscounts.refunds.post(connection, {
    body: validRefund
  });
  typia.assert(created);
  TestValidator.equals("amount")(validRefund.amount)(created.amount);
  TestValidator.equals("status")(validRefund.status)(created.status);
  TestValidator.equals("currency")(validRefund.currency)(created.currency);
  TestValidator.equals("reason")(validRefund.reason)(created.reason);
  TestValidator.equals("payment_id")(validRefund.payment_id)(created.payment_id);
  TestValidator.equals("transaction_id")(validRefund.transaction_id)(created.transaction_id);
  TestValidator.equals("order_id")(validRefund.order_id)(created.order_id);

  // 3. Invalid - missing required fields
  for (const missingField of ["payment_id", "transaction_id", "amount", "currency", "status"] as const) {
    const invalid = { ...validRefund } as any;
    delete invalid[missingField];
    await TestValidator.error(`missing ${missingField}`)(async () =>
      api.functional.paymentsDiscounts.refunds.post(connection, { body: invalid })
    );
  }

  // 4. Invalid - negative refund amount
  const badAmount = { ...validRefund, amount: -100 };
  await TestValidator.error("negative amount")(async () =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: badAmount })
  );

  // 5. Invalid - duplicate refund for same payment
  await TestValidator.error("duplicate refund for payment_id")(async () =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: validRefund })
  );

  // 6. Idempotency re-test: retry same payload
  await TestValidator.error("idempotent duplicate create")(async () =>
    api.functional.paymentsDiscounts.refunds.post(connection, { body: validRefund })
  );

  // 7. (Optional) - Concurrent identical requests (typically not covered here; would use promise.all etc)
}

