import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";
import { IPageIProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductTag";
import typia from "typia";

/**
 * List and search product tags using different filters and pagination parameters.
 *
 * - This test validates the listing, filtering, and pagination of product tags in the product catalog module.
 * - Tags are created, then listed via PATCH /productCatalog/productTags, using different filter/search/pagination scenarios.
 * - Edge cases such as searching with no results, retrieving first page with a minimal limit, and querying with invalid/extreme filter values are covered.
 *
 * 1. Create 3 unique product tags via POST /productCatalog/productTags
 * 2. List all product tags without any filter (should include all created tags)
 * 3. Search tags by partial value (use substring of a value, expect matching tag in response)
 * 4. List tags with minimal pagination limit (limit=1), expect single tag in data, check pagination meta
 * 5. Search with a value filter that matches nothing (e.g., 'xxNONExx'), expect empty data
 * 6. List with an extremely high page number (page=10000), expect no result
 * 7. Try invalid/edge filter values (empty string, null, negative page/limit), expect success/failure response as per validation rules
 * 8. Validate all results with typia.assert and TestValidator.equals/checks
 */
export async function test_api_product_tag_list_and_search_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create 3 unique product tags
  const values = [
    `tag-e2e-${Date.now()}-alpha`,
    `tag-e2e-${Date.now()}-beta`,
    `tag-e2e-${Date.now()}-gamma`,
  ];
  const tags: IProductTag[] = [];
  for (const value of values) {
    const tag = await api.functional.productCatalog.productTags.post(connection, {
      body: { value } satisfies IProductTag.ICreate,
    });
    typia.assert(tag);
    tags.push(tag);
  }
  // 2. List all product tags (no filter). Should include the created tags.
  const all = await api.functional.productCatalog.productTags.patch(connection, {
    body: {},
  });
  typia.assert(all);
  for (const value of values) {
    TestValidator.equals("created tag present in list")(
      true,
    )(
      all.data.some((t) => t.value === value),
    );
  }

  // 3. Search tags by partial value (substring)
  const partial = values[0].slice(4, 10); // get a substring of the first tag
  const filtered = await api.functional.productCatalog.productTags.patch(
    connection,
    {
      body: { value: partial },
    },
  );
  typia.assert(filtered);
  TestValidator.equals("at least one match for partial search")(
    true,
  )(filtered.data.some((t) => t.value.includes(partial)));

  // 4. Pagination: minimal limit (limit=1)
  const paged = await api.functional.productCatalog.productTags.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("paged.data.length === 1")(1)(paged.data.length);
  TestValidator.equals("paged.pagination.limit == 1")(1)(paged.pagination.limit);
  TestValidator.equals("paginated result has valid meta")(
    true,
  )(paged.pagination.records >= paged.data.length);

  // 5. Search with value filter matching nothing
  const emptySearch = await api.functional.productCatalog.productTags.patch(
    connection,
    { body: { value: "xxNONExx" } },
  );
  typia.assert(emptySearch);
  TestValidator.equals("no results for non-matching filter")(
    0,
  )(emptySearch.data.length);

  // 6. Extremely high page number
  const highPage = await api.functional.productCatalog.productTags.patch(
    connection,
    { body: { page: 10000 } },
  );
  typia.assert(highPage);
  TestValidator.equals("empty or minimal data for high page number")(
    0,
  )(highPage.data.length);

  // 7. Invalid/edge filter values
  // 7a. value: empty string
  const emptyValue = await api.functional.productCatalog.productTags.patch(
    connection,
    { body: { value: "" } },
  );
  typia.assert(emptyValue);
  // Should behave as 'no filter' (so, some results returned)
  TestValidator.equals("data for empty value filter")(
    true,
  )(emptyValue.data.length > 0);

  // 7b. value: null (should work as 'no filter')
  const nullValue = await api.functional.productCatalog.productTags.patch(
    connection,
    { body: { value: null } },
  );
  typia.assert(nullValue);
  TestValidator.equals("data for null value filter")(
    true,
  )(nullValue.data.length > 0);

  // 7c. Negative page/limit (should fail or default to first page/system default)
  // Depending on API: If error is thrown, catch and check; if not, check paging meta
  let negPageOk = false;
  try {
    await api.functional.productCatalog.productTags.patch(connection, {
      body: { page: -1 },
    });
    negPageOk = true;
  } catch (err) {
    negPageOk = false;
  }
  TestValidator.equals("negative page or validation fail allows no error")(
    true,
  )(negPageOk || true); // Accept both behaviors as valid

  let negLimitOk = false;
  try {
    await api.functional.productCatalog.productTags.patch(connection, {
      body: { limit: -5 },
    });
    negLimitOk = true;
  } catch (err) {
    negLimitOk = false;
  }
  TestValidator.equals("negative limit or validation fail allows no error")(
    true,
  )(negLimitOk || true); // Accept both behaviors as valid
}

