/**
 * Fetch a specific product tag by its valid ID and verify correctness.
 *
 * 1. Create a new product tag for test purposes.
 * 2. Fetch the created product tag using its valid ID and verify all data fields match.
 * 3. Attempt to fetch a tag by a non-existent ID and verify that a 404 error is returned.
 *
 * - Tags are immutable records; no cleanup is required in this test.
 */
export async function test_api_product_tag_get_by_id_with_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new product tag
  const testValue = `test-tag-${Date.now()}`;
  const created: IProductTag = await api.functional.productCatalog.productTags.post(connection, {
    body: {
      value: testValue,
    } satisfies IProductTag.ICreate,
  });
  typia.assert(created);

  // 2. Fetch the created product tag by its ID
  const fetched: IProductTag = await api.functional.productCatalog.productTags.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  // Validate all fields match exactly
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("value")(created.value)(fetched.value);
