import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";
import { IDeleteResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResponse";

/**
 * Soft-delete a product tag and verify correct error handling for non-existent/already-deleted IDs.
 *
 * This test covers the full soft-delete lifecycle for ProductCatalog product tag records:
 *
 * 1. Create a new product tag to provide a valid, deletable ID to target.
 * 2. Soft-delete the created product tag by its ID using DELETE endpoint.
 * 3. Validate that the response contains the expected UUID, status ('deleted'), and an ISO-format deletedAt timestamp.
 * 4. Attempt to delete the same tag again to confirm the API returns an appropriate error for already-deleted IDs.
 * 5. Attempt to delete a truly non-existent UUID and assert API returns the correct error (typically 404 Not Found).
 *
 * Notes:
 * - If list/search endpoints were available, a check would ensure the deleted tag is not returned there, but that is omitted due to unavailable endpoints.
 * - The soft-deleted tag should still exist in storage for audit, by business logic design.
 *
 * This sequence guarantees both business correctness and robust error handling for edge cases around audit-preserving soft-delete operations.
 */
export async function test_api_productTag_soft_delete_and_handle_nonexistent_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new product tag
  const createBody: IProductTag.ICreate = {
    value: `test-e2e-tag-${Date.now()}`,
  };
  const tag: IProductTag = await api.functional.productCatalog.productTags.post(connection, {
    body: createBody,
  });
  typia.assert(tag);

  // 2. Soft-delete the created product tag
  const deleteResult: IDeleteResponse = await api.functional.productCatalog.productTags.eraseById(connection, {
    id: tag.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("deleted tag id")(tag.id)(deleteResult.id);
  TestValidator.equals("deleted status")("deleted")(deleteResult.status);
  TestValidator.schema("deletedAt ISO 8601")("string & Format<\"date-time\">")(deleteResult.deletedAt);

  // 3. Try to delete the same tag again: should return error
  await TestValidator.httpError("already-deleted product tag")(404)(() =>
    api.functional.productCatalog.productTags.eraseById(connection, { id: tag.id })
  );

  // 4. Try to delete a non-existent random UUID tag: should return error
  const nonExistentId = "11111111-0000-4000-b000-000000000999" as string & tags.Format<"uuid">;
  await TestValidator.httpError("non-existent product tag")(404)(() =>
    api.functional.productCatalog.productTags.eraseById(connection, { id: nonExistentId })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";
