import { IPageIProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductMedia";
import typia from "typia";

/**
 * E2E test for listing and searching product media records with various filters and pagination.
 *
 * - Creates various product media entries with different media types, product IDs, locales, alt-texts, and timestamps.
 * - For each filterable field (media_type, product_id, locale, alt_text, date range), performs a search and validates correct results.
 * - Tests combined filters for correctness.
 * - Validates pagination (limit, offset) and checks proper order with sorting.
 * - Checks edge cases: empty result (filter matching 0), invalid input.
 * - Validates response structure and types with typia.assert().
 *
 * Steps:
 * 1. Create 5+ product media records covering various field combinations.
 * 2. Search by media_type, locale, product_id, alt_text, created_from, created_to independently and verify results.
 * 3. Test pagination (limit/offset) and sorting, and verify total counts and returned data consistency.
 * 4. Test combined filters (e.g., media_type+locale), and check intersections.
 * 5. Search with filters guaranteeing 0 results.
 * 6. Attempt search with invalid UUID/date and observe error handling or empty results.
 * 7. All responses checked using typia.assert and TestValidator.equals for content validation.
 */
export async function test_api_product_media_list_and_search_with_various_filters(
  connection: api.IConnection
): Promise<void> {
  // 1. Create several distinct product media records
  const testMedia: IProductMediaType[] = [];
  const now = new Date();
  const baseProductId = "13991739-4fa1-41a7-a868-414cda0de484";

  const mediaDefinitions: Array<Partial<IProductMediaType.ICreate>> = [
    { media_type: "image", locale: "en-US", alt_text: "A product shot", uri: "https://cdn/a.jpg" },
    { media_type: "video", locale: "ko-KR", alt_text: "Korean demo", uri: "https://cdn/b.mp4" },
    { media_type: "image", locale: "ja-JP", alt_text: "Japanese image", uri: "https://cdn/c.jpg" },
    { media_type: "pdf",   locale: "en-US", alt_text: "User manual", uri: "https://cdn/d.pdf" },
    { media_type: "image", locale: "zh-CN", alt_text: "중국 이미지", uri: "https://cdn/e.jpg" },
  ];

  // Assign shared/fixed product_id for easier queries
  for (let i = 0; i < mediaDefinitions.length; ++i) {
    const body: IProductMediaType.ICreate = {
      product_id: baseProductId,
      uri: mediaDefinitions[i].uri!,
      media_type: mediaDefinitions[i].media_type!,
      locale: mediaDefinitions[i].locale!,
      alt_text: mediaDefinitions[i].alt_text!,
    };
    const created = await api.functional.productCatalog.productMedia.post(connection, { body });
    typia.assert(created);
    testMedia.push(created);
    // Stagger created_at by assigning system timestamps (not strictly necessary since assigned by backend)
  }

  // 2. Single-field search tests
  // (a) By media_type
  for (const mt of ["image", "video", "pdf"]) {
    const out = await api.functional.productCatalog.productMedia.patch(connection, {
      body: { media_type: mt },
    });
    typia.assert(out);
    for (const item of out.data) {
      TestValidator.equals("media_type filter")(mt)(item.media_type);
    }
  }

  // (b) By locale
  for (const locale of ["en-US", "ko-KR", "ja-JP", "zh-CN"]) {
    const out = await api.functional.productCatalog.productMedia.patch(connection, {
      body: { locale },
    });
    typia.assert(out);
    for (const item of out.data) {
      TestValidator.equals("locale filter")(locale)(item.locale);
    }
  }

  // (c) By product_id
  const outByProd = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { product_id: baseProductId },
  });
  typia.assert(outByProd);
  TestValidator.equals("all with same product_id")(testMedia.length)(outByProd.data.length);

  // (d) By alt_text (partial match via substring expectation)
  const outByAltText = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { alt_text: "User" },
  });
  typia.assert(outByAltText);
  for (const item of outByAltText.data) {
    TestValidator.equals("alt_text should include")(
      true
    )(item.alt_text.includes("User"));
  }

  // (e) By created_from/created_to
  {
    const firstItem = testMedia[0];
    const lastItem = testMedia[testMedia.length - 1];
    const outFrom = await api.functional.productCatalog.productMedia.patch(connection, {
      body: { created_from: firstItem.created_at },
    });
    typia.assert(outFrom);
    for (const item of outFrom.data) {
      TestValidator.equals("created_from filter")(true)(
        item.created_at >= firstItem.created_at
      );
    }

    const outTo = await api.functional.productCatalog.productMedia.patch(connection, {
      body: { created_to: lastItem.created_at },
    });
    typia.assert(outTo);
    for (const item of outTo.data) {
      TestValidator.equals("created_to filter")(true)(
        item.created_at <= lastItem.created_at
      );
    }
  }

  // 3. Pagination tests
  // (a) limit/count
  const outPaginate = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { limit: 2, sort: "created_at asc" },
  });
  typia.assert(outPaginate);
  TestValidator.equals("pagination limit")(2)(outPaginate.data.length);

  // (b) offset/limit
  const outPaginate2 = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { offset: 2, limit: 2, sort: "created_at asc" },
  });
  typia.assert(outPaginate2);
  // Validate offset (the items after first two)
  // If enough items, they should not match the first two
  if (outPaginate2.data.length > 0) {
    TestValidator.equals("offset starts after N")(testMedia[2].uri)(
      outPaginate2.data[0].uri
    );
  }

  // 4. Combined filters (media_type+locale)
  for (const combo of [
    { media_type: "image", locale: "en-US" },
    { media_type: "pdf", locale: "en-US" },
    { media_type: "image", locale: "zh-CN" },
  ]) {
    const out = await api.functional.productCatalog.productMedia.patch(connection, {
      body: combo,
    });
    typia.assert(out);
    for (const item of out.data) {
      TestValidator.equals("combo filter: media_type")(combo.media_type)(item.media_type);
      TestValidator.equals("combo filter: locale")(combo.locale)(item.locale);
    }
  }

  // 5. Search that returns zero results (use nonsense alt_text)
  const outZero = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { alt_text: "zzzz-nonexistent" },
  });
  typia.assert(outZero);
  TestValidator.equals("zero result")(0)(outZero.data.length);

  // 6. Invalid filter values: (a) invalid product_id uuid, (b) invalid created_from (bad date)
  // Assuming implementation returns empty for non-existing UUID
  const outInvalidUuid = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { product_id: "aaaaaaaa-bbbb-cccc-dddd-111111111111" },
  });
  typia.assert(outInvalidUuid);
  TestValidator.equals("invalid uuid returns zero")(0)(outInvalidUuid.data.length);

  // (b) Malformed date string: API spec may error or empty result – here expecting empty
  const outInvalidDate = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { created_from: "not-a-date" as any },
  });
  typia.assert(outInvalidDate);
  TestValidator.equals("invalid date returns zero")(0)(outInvalidDate.data.length);
}

