import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IInventory";
import { IPageIInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIInventory";
import typia from "typia";

/**
 * Validate listing and searching inventory records using various filters.
 *
 * This test covers the full listing and search capabilities of the ProductCatalog.inventory resource,
 * by preparing controlled inventory entries and then searching with different filtering and paging parameters.
 *
 * Scenario steps:
 * 1. Prepare product variant IDs for inventory creation (using mock or pre-determined UUIDs).
 * 2. Create several inventory records with known attributes (product_variant_id, stock_count, last_modified_at).
 * 3. Retrieve all inventory records without any filter; check that all created records are present.
 * 4. Search by specific product_variant_id and ensure only the relevant record returns.
 * 5. Search by stock_count range (stock_from/stock_to) and check that only qualifying records appear.
 * 6. Search by last_modified_at range and validate correct temporal filtering.
 * 7. Use pagination fields (offset, limit) to get valid pages, as well as test for an empty page.
 * 8. Search with a non-existent product_variant_id or out-of-bounds filter to confirm an empty result.
 * 9. Validate all response payloads' structure by typia.assert, and data content by TestValidator.equals where appropriate.
 */
export async function test_api_inventory_list_and_search_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare mock product variant UUIDs
  const variantIds = [
    "11111111-1111-1111-1111-111111111111",
    "22222222-2222-2222-2222-222222222222",
    "33333333-3333-3333-3333-333333333333",
  ];

  const now = new Date();
  const dateA = new Date(now.getTime() - 120 * 1000).toISOString(); // 2 min ago
  const dateB = new Date(now.getTime() -  60 * 1000).toISOString(); // 1 min ago
  const dateC = now.toISOString();

  // 2. Create multiple inventory records in controlled order
  const inventories: IInventory[] = [];
  const stockValues = [10, 20, 30];
  const dates = [dateA, dateB, dateC];

  for (let i = 0; i < 3; ++i) {
    const created: IInventory = await api.functional.productCatalog.inventory.post(connection, {
      body: {
        product_variant_id: variantIds[i],
        stock_count: stockValues[i],
        last_modified_at: dates[i],
      } satisfies IInventory.ICreate,
    });
    typia.assert(created);
    inventories.push(created);
  }

  // 3. List inventories with no filter (expect all just created)
  const listAll: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: {} satisfies IInventory.IRequest,
  });
  typia.assert(listAll);
  for (const rec of inventories) {
    TestValidator.equals(`unfiltered inventory contains: ${rec.product_variant_id}`)(
      true,
    )(!!listAll.data.find(r => r.id === rec.id));
  }

  // 4. Filter by product_variant_id (expect only matching record)
  for (let i = 0; i < 3; ++i) {
    const byVariant: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
      body: { product_variant_id: variantIds[i] } satisfies IInventory.IRequest,
    });
    typia.assert(byVariant);
    TestValidator.equals("single result for exact variant ID")(1)(byVariant.data.length);
    TestValidator.equals("stock for filtered variant")(stockValues[i])(byVariant.data[0].stock_count);
    TestValidator.equals("product_variant_id")(variantIds[i])(byVariant.data[0].product_variant_id);
  }

  // 5. Filter by stock_from/stock_to
  const byStockRange: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: { stock_from: 15, stock_to: 25 } satisfies IInventory.IRequest,
  });
  typia.assert(byStockRange);
  TestValidator.equals("stock_count in 15..25 only")(
    [20]
  )(byStockRange.data.map(r => r.stock_count));

  // 6. Filter by last_modified_at window
  const byDateRange: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: {
      last_modified_from: dateB,
      last_modified_to: dateC,
    } satisfies IInventory.IRequest,
  });
  typia.assert(byDateRange);
  // Should include records with dateB, dateC
  const expectedIds = [inventories[1].id, inventories[2].id].sort();
  const actualIds = byDateRange.data.map(x => x.id).sort();
  TestValidator.equals("IDs for date range")(expectedIds)(actualIds);

  // 7. Pagination/empty-page edge cases
  const paged0: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: { offset: 0, limit: 2 } satisfies IInventory.IRequest,
  });
  typia.assert(paged0);
  TestValidator.equals("first page, limit 2")(2)(paged0.data.length);
  const paged1: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: { offset: 2, limit: 2 } satisfies IInventory.IRequest,
  });
  typia.assert(paged1);
  // There should be at most 1 record if 3 in total
  TestValidator.equals("second page, limit 2")(inventories.length - 2)(paged1.data.length);
  const pagedEmpty: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: { offset: 5, limit: 2 } satisfies IInventory.IRequest,
  });
  typia.assert(pagedEmpty);
  TestValidator.equals("empty page")(0)(pagedEmpty.data.length);

  // 8. Empty results: unmatchable variant
  const notFound: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, {
    body: { product_variant_id: "99999999-9999-9999-9999-999999999999" } satisfies IInventory.IRequest,
  });
  typia.assert(notFound);
  TestValidator.equals("no result for impossible variant ID")(0)(notFound.data.length);
}

