 * For both auditability and commerce reliability, it must be possible to retrieve an exact inventory record by UUID,
 * and the system must reliably return 404 for requests for records that do not exist.
 *
 * Steps:
 * 1. Create a valid inventory record using POST /productCatalog/inventory
 * 2. Assert returned response structure, extract inventory ID
 * 3. Retrieve the record using GET /productCatalog/inventory/{id}
 * 4. Assert the GET response fully matches the POST output
 * 5. Attempt GET /productCatalog/inventory/{id} with a random, non-existent id
 * 6. Assert that a 404 Not Found error is returned
 */
export async function test_api_inventory_getById_with_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid inventory record
  const createInput: IInventory.ICreate = {
