  await TestValidator.httpError("malformed uuid")(400)(() =>
    api.functional.productCatalog.inventory.post(connection, {
      body: {
        // deliberately invalid UUID string
        product_variant_id: "not-a-uuid",
        stock_count: 10,
      },
