import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IImportFeed";
import { IPageIImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIImportFeed";

/**
 * List and search import feed records using filtering and pagination parameters.
 *
 * This test validates comprehensive search and listing features of the import feed endpoint.
 * Multiple feeds are created with varying parameters, then the list (PATCH) endpoint is used
 * to fetch, filter, and paginate results. It ensures both correct match logic and API evidence policies.
 *
 * 1. Create multiple import feed records with different source_names, source_uris, and timestamps.
 * 2. List all feeds without filters and verify all created records are present.
 * 3. List feeds for a specific source_name and verify only proper records returned.
 * 4. List feeds within a time window using imported_from and imported_to; check correct slicing.
 * 5. List feeds using the search string; verify fuzzy search.
 * 6. Use limit/page sorting to ensure pagination fields and items are correct.
 * 7. Request non-existent filter to confirm empty result and metadata.
 */
export async function test_api_import_feed_list_and_search_with_various_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create import feeds
  const now = new Date();
  const feedsToCreate: IImportFeed.ICreate[] = [
    {
      source_name: "Google Shopping",
      source_uri: "https://feeds.google.com/partner.xml",
      imported_at: new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000).toISOString(),
    },
    {
      source_name: "Partner ERP Feed",
      source_uri: "https://erp.example.com/export-feed.xml",
      imported_at: new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString(),
    },
    {
      source_name: "Test Fuzzy Search",
      source_uri: "https://partner.example.com/searchable_source.xml",
      imported_at: new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000).toISOString(),
    },
  ];
  const createdFeeds: IImportFeed[] = [];
  for (const createBody of feedsToCreate) {
    const created = await api.functional.productCatalog.importFeeds.post(connection, {
      body: createBody,
    });
    typia.assert(created);
    createdFeeds.push(created);
  }

  // 2. List all feeds, no filters
  const allFeedsResp: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: {},
  });
  typia.assert(allFeedsResp);
  const allFeedIds = createdFeeds.map(f => f.id).sort();
  const returnedIds = (allFeedsResp.data ?? []).map(f => f.id).filter(id => allFeedIds.includes(id)).sort();
  TestValidator.equals("all imported feeds present")(allFeedIds)(returnedIds);

  // 3. Filter by source_name
  const filterSourceName = feedsToCreate[1].source_name;
  const filteredByNameResp: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: { source_name: filterSourceName },
  });
  typia.assert(filteredByNameResp);
  const nameReturn = filteredByNameResp.data ?? [];
  TestValidator.equals("filter by source_name count")(1)(nameReturn.length);
  if (nameReturn[0]) TestValidator.equals("source_name matches")(filterSourceName)(nameReturn[0].source_name);

  // 4. Filter by time window
  const imported_from = feedsToCreate[0].imported_at;
  const imported_to = feedsToCreate[1].imported_at;
  const filteredByTimeResp: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: { imported_from, imported_to },
  });
  typia.assert(filteredByTimeResp);
  const matchedIds = [createdFeeds[0].id, createdFeeds[1].id].sort();
  const timeReturn = (filteredByTimeResp.data ?? []).map(f => f.id).filter(id => matchedIds.includes(id)).sort();
  TestValidator.equals("imported_at window")(matchedIds)(timeReturn);

  // 5. Fuzzy search: use partial string from name and uri
  const fuzzySearchResp = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: { search: "fuzzy" },
  });
  typia.assert(fuzzySearchResp);
  const fuzzyReturn = fuzzySearchResp.data ?? [];
  TestValidator.equals("fuzzy search at least 1")(true)(fuzzyReturn.some(f => f.source_name === "Test Fuzzy Search"));

  // 6. Pagination: set limit (e.g., 2) & page (2)
  const paged2 = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: { limit: 2, page: 2, sort: "imported_at-desc" },
  });
  typia.assert(paged2);
  TestValidator.equals("limit enforced")(2)(paged2.pagination?.limit);
  TestValidator.equals("current page = 2")(2)(paged2.pagination?.current);

  // 7. Search for truly non-existent record
  const emptyResp = await api.functional.productCatalog.importFeeds.patch(connection, {
    body: { source_name: "Definitely Not Present", imported_from: "2000-01-01T00:00:00Z", imported_to: "2000-01-02T00:00:00Z" },
  });
  typia.assert(emptyResp);
  TestValidator.equals("empty data array for non-existing filter")(0)(emptyResp.data?.length ?? 0);
}

