import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import { IPageICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICatalogEvent";

/**
 * List and search catalog event records with various filtering and pagination conditions.
 *
 * This test covers creation of catalog event records and listing/searching them using different filter options, to validate both positive and edge case behaviors.
 *
 * Scenario steps:
 * 1. Create several catalog event records with diverse `event_type`, `user_id`, and `product_id` values.
 * 2. Retrieve list of all catalog events with no filters, confirm all records appear.
 * 3. Filter by a specific `event_type`, confirm only matching events are returned.
 * 4. Filter by a specific `user_id`, and confirm only that user's events returned.
 * 5. Filter by `product_id` and (if used) `product_variant_id`.
 * 6. Query using a time window (`from`/`to`) on `occurred_at` field.
 * 7. Search by keyword in `description` or `event_type` fields, confirm result.
 * 8. Paginate with a small `limit`, check pagination mechanics (multiple pages if needed).
 * 9. Request very high page number, expect empty result.
 * 10. Pass invalid filters (nonsense values), expect empty result, no server error.
 * 11. Check sorted queries (`occurred_at-asc`, `occurred_at-desc`).
 * 12. On each query, assert correct filtering, pagination metadata, and data integrity.
 * 13. Confirm edge/empty cases are handled gracefully.
 */
export async function test_api_catalog_event_list_and_search_various_conditions(connection: api.IConnection): Promise<void> {
  // 1. Create catalog event records for testing
  const testUserA = typia.random<ICatalogEvent.ICreate>();
  const testUserB = { ...typia.random<ICatalogEvent.ICreate>(), event_type: "import" };
  const testUserC = { ...typia.random<ICatalogEvent.ICreate>(), event_type: "update" };

  // Three events, intentionally have two different event_type and distinct user_ids
  const eventA: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, { body: testUserA });
  typia.assert(eventA);

  const eventB: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, { body: testUserB });
  typia.assert(eventB);

  const eventC: ICatalogEvent = await api.functional.productCatalog.catalogEvents.post(connection, { body: testUserC });
  typia.assert(eventC);

  // 2. List all catalog events (no filter)
  const allEvents: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: {} });
  typia.assert(allEvents);
  TestValidator.equals("all records include the created records")(
    true
  )(
    (allEvents.data ?? []).some(ev => ev.id === eventA.id) &&
    (allEvents.data ?? []).some(ev => ev.id === eventB.id) &&
    (allEvents.data ?? []).some(ev => ev.id === eventC.id)
  );

  // 3. Filter by specific event_type ("import")
  const filterByEventType: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { event_type: "import" } });
  typia.assert(filterByEventType);
  TestValidator.equals("filtered by event_type")([
    eventB.id
  ])((filterByEventType.data ?? []).map(ev => ev.id));

  // 4. Filter by specific user_id
  const filterByUser: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { user_id: testUserA.user_id } });
  typia.assert(filterByUser);
  TestValidator.equals("filtered by user_id")(
    (allEvents.data ?? []).filter(ev => ev.user_id === testUserA.user_id).map(ev => ev.id)
  )(
    (filterByUser.data ?? []).map(ev => ev.id)
  );

  // 5. Filter by product_id (from eventC)
  if (eventC.product_id) {
    const filterByProduct: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { product_id: eventC.product_id } });
    typia.assert(filterByProduct);
    TestValidator.equals("filtered by product_id")(
      (allEvents.data ?? []).filter(ev => ev.product_id === eventC.product_id).map(ev => ev.id)
    )(
      (filterByProduct.data ?? []).map(ev => ev.id)
    );
  }

  // 6. Time window query
  const fromTime = eventA.occurred_at;
  const toTime = eventC.occurred_at;
  const filterByTime: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: { from: fromTime, to: toTime },
  });
  typia.assert(filterByTime);
  for (const ev of filterByTime.data ?? []) {
    TestValidator.equals("within time range")(
      true
    )(
      (ev.occurred_at >= fromTime) && (ev.occurred_at <= toTime)
    );
  }

  // 7. Search by keyword (in event_type, description)
  const keyword = eventA.event_type.slice(0, 3); // partial string
  const searchByKeyword: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, {
    body: { search: keyword },
  });
  typia.assert(searchByKeyword);
  TestValidator.equals("search results include expected records")(
    true
  )(
    (searchByKeyword.data ?? []).some(
      ev => ev.id === eventA.id || ev.event_type.includes(keyword) || ev.description.includes(keyword)
    )
  );

  // 8. Paginate with small limit (limit = 1)
  const paged: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { limit: 1, page: 1 } });
  typia.assert(paged);
  TestValidator.equals("only 1 record returned for limit=1")(
    1
  )(paged.data?.length ?? 0);

  // 9. Very high page (expect empty)
  const maxPageQuery: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { page: 99999 } });
  typia.assert(maxPageQuery);
  TestValidator.equals("no records for high page number")(
    0
  )(maxPageQuery.data?.length ?? 0);

  // 10. Nonsense/invalid filters
  const nonsense: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { event_type: "qqqq---no-such-event-type" } });
  typia.assert(nonsense);
  TestValidator.equals("no records for nonsense event_type")(
    0
  )(nonsense.data?.length ?? 0);

  // 11. Sorted queries: occurred_at-asc, occurred_at-desc
  const sortedAsc: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { sort: "occurred_at-asc" } });
  typia.assert(sortedAsc);
  const ascArr = sortedAsc.data ?? [];
  for (let i = 1; i < ascArr.length; ++i) {
    TestValidator.equals("ascending sort")(
      true
    )(ascArr[i - 1].occurred_at <= ascArr[i].occurred_at);
  }
  const sortedDesc: IPageICatalogEvent = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { sort: "occurred_at-desc" } });
  typia.assert(sortedDesc);
  const descArr = sortedDesc.data ?? [];
  for (let i = 1; i < descArr.length; ++i) {
    TestValidator.equals("descending sort")(
      true
    )(descArr[i - 1].occurred_at >= descArr[i].occurred_at);
  }
}

