 * 2. Create an order status for the valid order using valid data.
 * 3. Verify the status is created and fields are validated.
 * 4. Attempt to create order status without required fields (should fail).
 * 5. Attempt to create order status with invalid status value (should fail).
 *
 * This test verifies both the happy path and required field/state validation for order status creation.
 */
export async function test_api_order_status_create_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid order
  const order: ICartOrderOrder = await api.functional.cartOrder.order.post(
