    {
      body: {
        user_id: "11111111-1111-1111-1111-111111111111",
        cart_id: "22222222-2222-2222-2222-222222222222",
      } satisfies ICartOrderOrder.ICreate,
    }
  );
  typia.assert(order);

  // 2. Create a valid order status
  const now = new Date().toISOString();
  const validStatus: IOrderStatus.ICreate = {
    order_id: order.id,
    status_code: "pending",
