import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";
import { IPageIOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderLog";
import typia from "typia";

/**
 * Search and page through order log records with different filtering criteria.
 *
 * This test covers searching by orderId, event_type, actor_id, date ranges, and paginates over multiple pages.
 * Includes edge cases for empty result sets (nonexistent order) and out-of-range pagination.
 * Checks that permission boundaries (user/auditor context) are respected, and only authorized records are visible to each actor.
 *
 * Steps:
 * 1. Create multiple order_log records (varied order_id, event_type, actor_id, timestamps)
 * 2. For a specific order_id, search and page over logs, checking result integrity and pagination structure
 * 3. Filter by event_type and confirm filtered accuracy
 * 4. Filter by actor_id and confirm filtered accuracy
 * 5. Filter by date range using from_time and to_time
 * 6. Edge case: extremely high page number yields empty array
 * 7. Edge case: non-existent order_id yields empty array
 * 8. Permission: (if implemented) user only sees their logs, auditor sees all
 *
 * All responses are typia.assert validated, and core result unions checked for integrity.
 */
export async function test_api_order_log_list_and_filter_with_pagination_and_permissions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a set of order_logs for multiple orders, actors, event_types, and dates
  const uniqueOrderIds = [typia.random<string>(), typia.random<string>()];
  const uniqueActorIds = [typia.random<string>(), typia.random<string>()];
  const now = new Date();
  const historic = new Date(now.getTime() - 1000 * 60 * 60 * 24); // 1 day ago
  const eventTypes = ["create", "update", "status_change"];

  const makeLog = async (order_id: string, event_type: string, actor_id: string, time: Date) =>
    await api.functional.cartOrder.orderLog.post(connection, {
      body: {
        order_id,
        event_type,
        event_time: time.toISOString(),
        actor_id,
      } satisfies IOrderLog.ICreate,
    });
  // Create 6 logs (3 for each order, each by a different actor, varied types/time)
  const createdLogs: IOrderLog[] = [];
  for (const order_id of uniqueOrderIds) {
    for (let i = 0; i < eventTypes.length; ++i) {
      createdLogs.push(
        await makeLog(order_id, eventTypes[i], uniqueActorIds[i%2], i === 2 ? now : historic)
      );
    }
  }

  // Fetch full logs for first order for comparison
  const allForOrder1 = createdLogs.filter(l => l.order_id === uniqueOrderIds[0]);

  // 2. Search for order1 with pagination (limit=2)
  let output: IPageIOrderLog = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      order_id: uniqueOrderIds[0],
      page: 1,
      limit: 2,
    },
  });
  typia.assert(output);
  TestValidator.equals("pagination/current")(1)(output.pagination.current);
  TestValidator.equals("pagination/limit")(2)(output.pagination.limit);
  TestValidator.equals("total records")(3)(output.pagination.records);
  TestValidator.equals("data length")(2)(output.data.length);
  // Page 2 should have up to 1 remaining log
  const output2 = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      order_id: uniqueOrderIds[0],
      page: 2,
      limit: 2,
    },
  });
  typia.assert(output2);
  TestValidator.equals("pagination/current-2")(2)(output2.pagination.current);
  TestValidator.equals("data length-2")(1)(output2.data.length);
  // Union equals the set
  const combined = [...output.data, ...output2.data];
  TestValidator.equals("combined logs")(allForOrder1.map(l=>l.id).sort())(combined.map(l=>l.id).sort());

  // 3. Filter by event_type
  const out_update = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      event_type: "update",
      limit: 100,
    },
  });
  typia.assert(out_update);
  for(const l of out_update.data) TestValidator.equals("event_type-filter")("update")(l.event_type);

  // 4. Filter by actor
  const out_actor = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      actor_id: uniqueActorIds[0],
      limit: 100,
    },
  });
  typia.assert(out_actor);
  for(const l of out_actor.data) TestValidator.equals("actor_id-filter")(uniqueActorIds[0])(l.actor_id);

  // 5. Date range test (historic only)
  const out_hist = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      from_time: historic.toISOString(),
      to_time: now.toISOString(),
      limit: 100,
    },
  });
  typia.assert(out_hist);
  for(const l of out_hist.data) {
    TestValidator.equals("range-from")(true)(new Date(l.event_time) >= historic);
    TestValidator.equals("range-to")(true)(new Date(l.event_time) < now);
  }

  // 6. Out-of-range page
  const out_empty = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { order_id: uniqueOrderIds[0], page: 99, limit: 5 },
  });
  typia.assert(out_empty);
  TestValidator.equals("empty-page")(0)(out_empty.data.length);

  // 7. Search with non-existent order_id
  const out_none = await api.functional.cartOrder.orderLog.patch(connection, {
    body: { order_id: "never-exist-id", limit: 10 },
  });
  typia.assert(out_none);
  TestValidator.equals("empty-none")(0)(out_none.data.length);

  // 8. Permissions: These would require login context switching, stubbed here. In a real suite, repeat patch with restricted user and check only their logs visible, then as auditor/admin check visibility of all logs.
}

