import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";
import typia from "typia";

/**
 * Update the metadata of an existing order log event, validating that updates apply only to allowed fields.
 *
 * 1. Create an order event/audit log entry (POST /cartOrder/orderLog).
 * 2. Update permitted mutable fields (event_description, event_type, actor_id, evidence_id, event_time) using PUT /cartOrder/orderLog/{id}.
 *    - Check that these fields are updated correctly.
 * 3. Attempt to update non-existent or immutable fields (id, order_id) by including them in update body.
 *    - Confirm response does not change immutable fields, or that the API rejects the request with appropriate error.
 * 4. Validate that only fields specified in IOrderLog.IUpdate are considered for updates, with other fields either ignored or unmodified.
 * 5. typia.assert all API responses for runtime type validation.
 */
export async function test_api_order_log_update_and_validate_allowed_fields(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create an order_log event for testing
  const createInput: IOrderLog.ICreate = {
    order_id: typia.random<string>(),
    event_type: "create",
    event_description: "Original event description.",
    event_time: new Date().toISOString(),
    actor_id: typia.random<string>(),
  };
  const created: IOrderLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // Step 2: Update mutable fields (description, event_type, actor_id, evidence_id, event_time)
  const updateInput: IOrderLog.IUpdate = {
    event_description: "Updated description", // new description
    event_type: "status_change", // changed event type
    event_time: new Date(Date.now() + 60000).toISOString(), // time moved 1 min forward
    actor_id: typia.random<string>(),
    evidence_id: typia.random<string>(),
  };
  const updated: IOrderLog = await api.functional.cartOrder.orderLog.putById(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);
  // Validation: Ensure fields are properly updated
  TestValidator.equals("event_description")(updateInput.event_description)(updated.event_description);
  TestValidator.equals("event_type")(updateInput.event_type)(updated.event_type);
  TestValidator.equals("event_time")(updateInput.event_time)(updated.event_time);
  TestValidator.equals("actor_id")(updateInput.actor_id)(updated.actor_id);
  TestValidator.equals("evidence_id")(updateInput.evidence_id)(updated.evidence_id);
  // And that immutable fields did not change
  TestValidator.equals("order_id")(created.order_id)(updated.order_id);
  TestValidator.equals("id")(created.id)(updated.id);

  // Step 3: Attempt to update immutable fields (id and order_id) via update body -- must have no effect or throw error
  const forbiddenUpdate: IOrderLog.IUpdate & { id: string; order_id: string } = {
    event_description: "Forbidden update attempt!", // still allowed
    id: "00000000-0000-0000-0000-000000000000", // fake new id
    order_id: "00000000-0000-0000-0000-000000000000", // fake new order_id
  };
  const forbiddenUpdatePromise = api.functional.cartOrder.orderLog.putById(connection, {
    id: created.id,
    // @ts-expect-error: purposely sending forbidden fields, should be ignored by DTO validator or cause error
    body: forbiddenUpdate,
  });
  await TestValidator.error("Should not allow mutation of id/order_id")(() => forbiddenUpdatePromise);

  // Step 4: Confirm final state is unchanged for immutable fields
  const final: IOrderLog = await api.functional.cartOrder.orderLog.putById(connection, {
    id: created.id,
    body: {},
  });
  typia.assert(final);
  TestValidator.equals("order_id not changed")(created.order_id)(final.order_id);
  TestValidator.equals("id not changed")(created.id)(final.id);
}

