  const evidenceSeed: Array<Omit<IOrderEvidence, "id">> = [
    {
      order_id: orderIdA,
      evidence_type: "invoice",
      evidence_uri: "https://evidence.io/documents/invoice1.pdf",
      provided_at: new Date(baseTime).toISOString(),
      provided_by: providerA,
    },
    {
      order_id: orderIdA,
      evidence_type: "signature",
      evidence_uri: "https://evidence.io/signature1.jpg",
      provided_at: new Date(baseTime.getTime() + 1000).toISOString(),
      provided_by: providerB,
    },
    {
      order_id: orderIdB,
      evidence_type: "invoice",
      evidence_uri: "https://evidence.io/documents/invoice2.pdf",
      provided_at: new Date(baseTime.getTime() + 2000).toISOString(),
      provided_by: providerA,
    },
    {
      order_id: orderIdB,
      evidence_type: "photo",
      evidence_uri: "https://evidence.io/photo1.png",
      provided_at: new Date(baseTime.getTime() + 3000).toISOString(),
      provided_by: providerB,
    },
  ];
  // Actually create each evidence
  const createdEvidence: IOrderEvidence[] = [];
  for (const e of evidenceSeed) {
    const ev: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(
      connection,
      {
        body: {
          ...e,
        } satisfies IOrderEvidence.ICreate,
      },
    );
    typia.assert(ev);
    createdEvidence.push(ev);
  }

  // -------------------------------------
  // 2. Query with no filters (all data)
  // -------------------------------------
  const allResults: IPageIOrderEvidence =
    await api.functional.cartOrder.orderEvidence.patch(connection, {
      body: {} satisfies IOrderEvidence.IRequest,
    });
  typia.assert(allResults);
  // Should include all test evidence created
  const returnedIds = allResults.data.map((x) => x.id).sort();
  const expectedIds = createdEvidence.map((x) => x.id).sort();
  TestValidator.equals("all inserted evidence returned")(expectedIds)(returnedIds);

  // -------------------------------------------
  // 3. Query filtering by order_id (orderIdA)
  // -------------------------------------------
  const resOrderA = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id: orderIdA,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(resOrderA);
  TestValidator.equals("only orderIdA evidence returned")(
    createdEvidence.filter((x) => x.order_id === orderIdA).map((x) => x.id).sort(),
  )(resOrderA.data.map((x) => x.id).sort());

  // ----------------------------------------------
  // 4. Query filtering by evidence_type ('invoice')
  // ----------------------------------------------
  const resInvoice = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      evidence_type: "invoice",
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(resInvoice);
  TestValidator.equals("only invoice evidence")(
    createdEvidence.filter((x) => x.evidence_type === "invoice").map((x) => x.id).sort(),
  )(resInvoice.data.map((x) => x.id).sort());

  // --------------------------------------------------
  // 5. Query filtering by provided_by (providerB)
  // --------------------------------------------------
  const resProviderB = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      provided_by: providerB,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(resProviderB);
  TestValidator.equals("only providerB evidence")(
    createdEvidence.filter((x) => x.provided_by === providerB).map((x) => x.id).sort(),
  )(resProviderB.data.map((x) => x.id).sort());

  // -------------------------------------------
  // 6. Date range (from_time/to_time)
  // -------------------------------------------
  // Find window for just last two evidence records
  const fromTime = evidenceSeed[2].provided_at;
  const toTime = new Date(new Date(evidenceSeed[3].provided_at).getTime() + 1).toISOString();
  const resDateRange = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      from_time: fromTime,
      to_time: toTime,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(resDateRange);
  const expectedRange = createdEvidence
    .filter(
      (x) => x.provided_at >= fromTime && x.provided_at < toTime,
    )
    .map((x) => x.id)
    .sort();
  TestValidator.equals("date range evidence")(
    expectedRange,
  )(resDateRange.data.map((x) => x.id).sort());

  // ---------------------------------
  // 7. Pagination (limit = 2, page 1)
  // ---------------------------------
  const page1 = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      limit: 2,
      page: 1,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("pagination: page 1 length")(2)(page1.data.length);
  TestValidator.equals("pagination: total records")(
    createdEvidence.length,
  )(page1.pagination.records);
  TestValidator.equals("pagination: current page")(1)(page1.pagination.current);

  // ---------------------------------
  // 8. Pagination (limit = 2, page 2)
  // ---------------------------------
  const page2 = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      limit: 2,
      page: 2,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(page2);
  // On page 2 the count might be less than 2 for remainder
  TestValidator.equals("pagination: page 2 length")(
    Math.max(0, createdEvidence.length - 2),
  )(page2.data.length);
  TestValidator.equals("pagination: current page")(2)(page2.pagination.current);

  // -----------------------------------
  // 9. Negative/edge: impossible order_id
  // -----------------------------------
  const impossibleOrderId = typia.random<string & typia.tags.Format<"uuid">>();
  const impossibleRes = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id: impossibleOrderId,
    } satisfies IOrderEvidence.IRequest,
  });
  typia.assert(impossibleRes);
  TestValidator.equals("impossible order_id returns empty")([], impossibleRes.data);
  TestValidator.equals("pagination empty records")(
    0,
  )(impossibleRes.pagination.records);

  // ----------------------------------------------------------
  // 10. (Auth) Evidence for unattainable order (If supported)
  // ----------------------------------------------------------
  // For demonstration, simulate forbidden (HTTP 403 or empty), if API supports
  // access restrictions – this part is optional and left as a comment/example
  // await TestValidator.httpError("forbidden order evidence fetch")(403)(() =>
  //   api.functional.cartOrder.orderEvidence.patch(connection, {
  //     body: { order_id: "some-forbidden-order-id" } satisfies IOrderEvidence.IRequest,
  //   })
  // );
}

