import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";
import typia from "typia";

/**
 * Test updating metadata for order evidence records, covering both valid and invalid modifications.
 *
 * Ensures allowed metadata fields are updatable, rejects invalid changes, and properly handles non-existent records.
 * Workflow required for audit, legal, and compliance chains within CartOrder.order_evidence.
 *
 * 1. Create an order_evidence record to update.
 * 2. Update evidence_type, evidence_uri, provided_by successfully with allowed data.
 * 3. Validate updated fields are correctly reflected, and originals replaced.
 * 4. Attempt to update with invalid data (too long uri, missing required field, etc.) and check error.
 * 5. Attempt to update a non-existent record, expect a 404 or not found error.
 * 6. Attempt update with immutable fields (id/order_id/provided_at), verify such changes are rejected or ignored.
 */
export async function test_api_order_evidence_update_metadata(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an order_evidence record
  const createBody: IOrderEvidence.ICreate = {
    order_id: typia.random<string>(),
    evidence_type: "photo",
    evidence_uri: "https://evidence-bucket.valid/asset/photo1.jpg",
    provided_at: new Date().toISOString(),
    provided_by: typia.random<string>(),
  };
  const evidence: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: createBody,
  });
  typia.assert(evidence);

  // 2. Update evidence_type, evidence_uri, provided_by
  const updateBody: IOrderEvidence.IUpdate = {
    evidence_type: "receipt",
    evidence_uri: "https://evidence-bucket.valid/asset/receipt2.pdf",
    provided_by: typia.random<string>(),
  };
  const updated = await api.functional.cartOrder.orderEvidence.putById(connection, {
    id: evidence.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("evidence_type")(updateBody.evidence_type)(updated.evidence_type);
  TestValidator.equals("evidence_uri")(updateBody.evidence_uri)(updated.evidence_uri);
  TestValidator.equals("provided_by")(updateBody.provided_by)(updated.provided_by);
  TestValidator.equals("id unchanged")(evidence.id)(updated.id);
  TestValidator.equals("order_id unchanged")(evidence.order_id)(updated.order_id);
  TestValidator.equals("provided_at unchanged")(evidence.provided_at)(updated.provided_at);

  // 3. Attempt update with an excessively long evidence_uri (invalid)
  const tooLongUri = "https://x.y/z/" + "a".repeat(80001);
  await TestValidator.httpError("too long evidence_uri should fail")(400)(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: evidence.id,
      body: { ...updateBody, evidence_uri: tooLongUri },
    }),
  );

  // 4. Attempt update with missing required field (evidence_type missing)
  // @ts-expect-error (simulate missing field)
  await TestValidator.error("missing evidence_type fails")(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: evidence.id,
      body: {
        evidence_uri: updateBody.evidence_uri,
        provided_by: updateBody.provided_by,
      },
    }),
  );

  // 5. Attempt to update a non-existent order_evidence record
  await TestValidator.httpError("update non-existent evidence fails")(404)(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: "00000000-0000-4000-8000-000000000000",
      body: updateBody,
    }),
  );

  // 6. Attempt to update immutable fields (should be ignored or rejected)
  // Try to pass id, order_id, provided_at in the update body (should not be allowed)
  // @ts-expect-error (simulate forbidden field update)
  await TestValidator.error("immutable fields not allowed in update")(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: evidence.id,
      body: {
        ...updateBody,
        id: "new-id-not-allowed",
        order_id: "new-order-id-not-allowed",
        provided_at: "2022-01-01T00:00:00Z",
      },
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";

/**
 * Soft-delete an order evidence record and validate audit compliance steps.
 *
 * Business context:
 * Evidence records are attached to orders for compliance/legal audit. These are immutable in data, and DELETE marks them as soft-deleted so they're removed from standard search/export but still available for audit.
 *
 * Test Scenario:
 * 1. Create a new evidence record (POST /cartOrder/orderEvidence).
 * 2. Soft-delete the record (DELETE /cartOrder/orderEvidence/{id}).
 * 3. Attempt soft-delete again on the same id (should error or be idempotent).
 * 4. Attempt soft-delete on a completely non-existent id (should error).
 * Note: No clean-up is needed -- evidence is soft-deleted only.
 */
export async function test_api_cartOrder_orderEvidence_softDelete_auditTrail(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create new evidence record
  const evidenceCreate: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: {
      order_id: typia.random<string>(),
      evidence_type: "invoice",
      evidence_uri: "https://cdn.example.com/invoice/123456.pdf",
      provided_at: new Date().toISOString(),
      provided_by: null
    } satisfies IOrderEvidence.ICreate
  });
  typia.assert(evidenceCreate);

  // 2. Soft-delete the created evidence
  const evidenceDeleted: IOrderEvidence = await api.functional.cartOrder.orderEvidence.eraseById(connection, {
    id: evidenceCreate.id
  });
  typia.assert(evidenceDeleted);
  TestValidator.equals("Soft-deleted evidence id matches")(evidenceCreate.id)(evidenceDeleted.id);

  // 3. Attempt to soft-delete already-deleted evidence
  await TestValidator.error("Soft-delete already-deleted evidence should error")(
    () => api.functional.cartOrder.orderEvidence.eraseById(connection, { id: evidenceCreate.id })
  );

  // 4. Attempt to soft-delete a non-existent evidence record (random UUID)
  const randomId = typia.random<string>();
  await TestValidator.error("Soft-delete non-existent evidence should error")(
    () => api.functional.cartOrder.orderEvidence.eraseById(connection, { id: randomId })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import { IPageIPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPayment";

/**
 * Test searching and paginating the payments list by different filters such as range of dates, user, amount, and payment status.
 *
 * This validates that /paymentsDiscounts/payments PATCH endpoint correctly filters and paginates payment records.
 * The scenario is crucial for dashboards, reconciliation, compliance evidence, and analytics, ensuring operators/users/financial systems can retrieve the exact subset of payment records as intended by filter/search conditions.
 *
 * The tests will seed multiple payment records, filter by various criteria, test pagination and sorting, and cover negative cases (invalid filters, out-of-range values, etc).
 *
 * Step-by-step process:
 * 1. Seed at least 5 payments with different users, status, amounts, currencies, date ranges, etc. (POST)
 * 2. For each filterable field (user_id, transaction_id, status, currency, payment_method_id, initiated_at/completed_at ranges):
 *    a. Request list with single filter, assert all returned records fit the criterion.
 *    b. Request with two filters combined, assert only intersection is returned.
 * 3. Test pagination (limit, page) and verify boundary/empty page behavior.
 * 4. Test sort (initiated_at desc, amount asc, etc.).
 * 5. Negative/edge cases: nonexistent IDs, invalid formats, empty results, improper page.
 * 6. All responses validated with typia.assert and values with TestValidator.equals()
 */
export async function test_api_paymentsDiscounts_payments_search_and_paginate_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seed 5 payments with different values
  const baseTime = new Date().toISOString();
  const user_ids = [
    "95ec8099-9755-4dc9-924f-e4c06daabda1",
    "c0a8012f-fb32-4a5a-83be-c9b927918aaf",
    "f25ce953-f252-4274-a364-16dd337ea9e8",
  ];
  const trx_ids = [
    "4b8e2b44-ca71-433e-8be3-21f6602e4abb",
    "b309d7a0-4976-47bb-b52e-5e8e3beeb4e6",
  ];
  const method_ids = [
    "d811a616-12c7-4b13-895e-4cb29f1438d7",
    "a5e3d976-6542-4cab-8b3a-f9b4c40c3578",
  ];
  const payments: IPayment[] = [];
  for (let i = 0; i < 5; ++i) {
    const body: IPayment.ICreate = {
      transaction_id: trx_ids[i % trx_ids.length],
      payment_method_id: method_ids[i % method_ids.length],
      amount: 100 * (i + 1),
      currency: i % 2 === 0 ? "KRW" : "USD",
      description: `Seed payment #${i + 1}`,
    };
    const payment = await api.functional.paymentsDiscounts.payments.post(
      connection,
      { body },
    );
    typia.assert(payment);
    // for testing, assign a fake user_id (depending on DTO/API this may be immutable, so could be part of setup/mocks)
    // Simulate user_id by local variable (in reality, payments may have this set by backend logic; test here for filtering)
    (payment as any).user_id = user_ids[i % user_ids.length];
    payments.push(payment);
  }
  // Helper: last item for negative test
  const not_existing_user_id = "00000000-0000-0000-0000-000000000000";
  const not_existing_trx_id = "ffffffff-ffff-ffff-ffff-ffffffffffff";

  // 2. Filter: by user_id
  for (const user_id of user_ids) {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { user_id } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    for (const item of output.data) {
      TestValidator.equals(`filter user_id=${user_id}`)(user_id)((item as any).user_id);
    }
  }

  // 3. Filter: by transaction_id
  for (const transaction_id of trx_ids) {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { transaction_id } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    for (const item of output.data) {
      TestValidator.equals(`filter trx_id=${transaction_id}`)(transaction_id)(item.transaction_id);
    }
  }

  // 4. Filter: by currency
  for (const currency of ["KRW", "USD"]) {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { currency } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    for (const item of output.data) {
      TestValidator.equals(`filter currency=${currency}`)(currency)(item.currency);
    }
  }

  // 5. Combined filter (user_id + status)
  const status = "completed";
  {
    const user_id = user_ids[0];
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { user_id, status } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    for (const item of output.data) {
      TestValidator.equals("user_id")(user_id)((item as any).user_id);
      TestValidator.equals("status")(status)(item.status);
    }
  }

  // 6. Pagination (limit=2, page=2)
  {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { limit: 2, page: 2 } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("pagination limit")(2)(output.pagination.limit);
    TestValidator.equals("pagination page")(2)(output.pagination.current);
    // Should not have more than 2 items per page
    TestValidator.equals("paged data count")(output.data.length <= 2)(true);
  }

  // 7. Pagination: page out of range (should return empty array)
  {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { limit: 2, page: 99 } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("empty page data")(0)(output.data.length);
  }

  // 8. Sorting by amount desc
  {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { sort: "amount:desc" } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    // amounts descending
    for (let i = 1; i < output.data.length; ++i) {
      TestValidator.equals("descending order")(
        true,
      )(output.data[i - 1].amount >= output.data[i].amount);
    }
  }

  // Negative/edge cases
  // 9. Nonexistent user_id (should return empty)
  {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { user_id: not_existing_user_id } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("nonexistent user_id")(0)(output.data.length);
  }
  // 10. Nonexistent transaction_id
  {
    const output = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { transaction_id: not_existing_trx_id } satisfies IPayment.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("nonexistent trx_id")(0)(output.data.length);
  }
  // 11. Invalid input: malformed UUID (simulate error handling, expect error or empty)
  await TestValidator.error("malformed user_id")(() =>
