/**
 * Update metadata on an existing payment and enforce integrity constraints.
 *
 * Scenario: Ensures mutation of permitted payment fields (payment_method_id, description, completed_at) works, but illegal
 * changes to immutable attributes (amount, transaction_id, status) or non-existent payments are properly rejected.
 *
 * Step by step:
 * 1. Seed a payment via POST /paymentsDiscounts/payments
 * 2. Update mutable fields using PUT /paymentsDiscounts/payments/{id} and verify changes
 * 3. Attempt illegal/immutable field updates and expect errors
 * 4. Attempt update on a non-existent payment and expect an error
 * 5. Confirm immutable fields remain unchanged after update
 */
export async function test_api_payment_update_metadata_and_enforce_integrity(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a payment (seed record)
  const originalPayment: IPayment = await api.functional.paymentsDiscounts.payments.post(connection, {
    body: {
      // you can replace with fixed values for reproducibility
      transaction_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method_id: typia.random<string & tags.Format<"uuid">>(),
      amount: 10500.50,
      currency: "KRW",
      description: "init metadata -- original",
    } satisfies IPayment.ICreate,
  });
  typia.assert(originalPayment);

  // 2. Perform valid update for allowed fields (description and completed_at)
  const newDescription = "Updated via test - legal update";
  const newCompletedAt = new Date().toISOString();
  const updatePayload = {
    description: newDescription,
    completed_at: newCompletedAt,
    // Note: payment_method_id can also be tested for update
  } satisfies IPayment.IUpdate;

  const updatedPayment: IPayment = await api.functional.paymentsDiscounts.payments.putById(connection, {
    id: originalPayment.id,
    body: updatePayload,
  });
  typia.assert(updatedPayment);

  // 3. Validation: mutable fields updated, immutable remain the same
  TestValidator.equals("id unchanged")(originalPayment.id)(updatedPayment.id);
  TestValidator.equals("transaction_id unchanged")(originalPayment.transaction_id)(updatedPayment.transaction_id);
  TestValidator.equals("amount unchanged")(originalPayment.amount)(updatedPayment.amount);
  TestValidator.equals("description updated")(
    newDescription
  )(updatedPayment.description);
  TestValidator.equals("completed_at updated")(
    newCompletedAt
  )(updatedPayment.completed_at);

  // 4. Attempt to mutate an immutable field (amount), expect error
  await TestValidator.httpError("illegal attempt to update payment amount")(400)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: originalPayment.id,
      body: {
        amount: 999.99, // Illegal, not in IPayment.IUpdate, but attempt anyway
      } as any, // Force type bypass to simulate illegal client
    }),
  );

  // 5. Attempt to mutate transaction_id, expect error
  await TestValidator.httpError("illegal attempt to update transaction_id")(400)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: originalPayment.id,
      body: {
        transaction_id: typia.random<string & tags.Format<"uuid">>(),
      } as any,
    }),
  );

  // 6. Attempt update to non-existent payment (random id), expect error
  await TestValidator.httpError("edit of non-existent payment")(404)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { description: "should fail" },
    }),
  );

  // 7. Confirm immutable fields remain unchanged after all legal edits
  // (already validated above; can optionally reload and recheck for persistence here if API allows GET)
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";

/**
 * Soft-delete a payment record and validate error handling for repeated/invalid deletions.
 *
 * This test ensures payment records can be soft-deleted as intended and errors are returned for invalid operations. Soft-delete means the record is no longer part of normal queries but remains for audit/compliance.
 *
 * Steps:
 * 1. Create a new payment record with valid details.
 * 2. Soft-delete the payment record by its ID. Validate the deleted payment object.
 * 3. Attempt to delete the same payment again, expecting an error (already deleted).
 * 4. Attempt to delete a non-existent payment ID, expecting an error.
 *
 * These steps verify both proper deletion and protective error handling per API contract.
 */
export async function test_api_payment_soft_delete_and_handle_invalid_deletion_attempts(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a payment record
  const input: IPayment.ICreate = {
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    payment_method_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 123.45,
    currency: "USD",
    description: "Test payment for soft-delete E2E"
  } satisfies IPayment.ICreate;

  const payment: IPayment = await api.functional.paymentsDiscounts.payments.post(connection, {
    body: input,
  });
  typia.assert(payment);

  // 2. Soft-delete the payment record
  const deleted: IPayment = await api.functional.paymentsDiscounts.payments.eraseById(connection, {
    id: payment.id,
  });
  typia.assert(deleted);
  TestValidator.equals("soft deleted id")(payment.id)(deleted.id);

  // 3. Attempt to delete the same payment again, expecting error (should not succeed)
  await TestValidator.httpError("repeat delete returns error")(404)(() =>
    api.functional.paymentsDiscounts.payments.eraseById(connection, {
      id: payment.id,
    })
  );

  // 4. Attempt to delete with random non-existent ID, expecting error
  await TestValidator.httpError("delete non-existent id returns error")(404)(() =>
    api.functional.paymentsDiscounts.payments.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

