  TestValidator.equals("pagination: <= 1 per page")(true)(response.data.length <= 1);
  TestValidator.equals("pagination: correct page")(
    1,
  )(response.pagination.current);

  // 8. Try userA requesting payment methods with user_id=userB; expect forbidden/empty (simulate empty for now)
  response = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
    body: { user_id: userB } satisfies IPaymentMethod.IRequest,
