  TestValidator.equals("cross-user request: empty list")(true)(
    response.data.every((m) => m.user_id === userB) &&
    (userA !== userB ? response.data.length >= 0 : true),
  );

  // 9. Check shape/type of all returned items (already validated by typia.assert)
}

