    masked_detail: "5555****6666",
    provider: "Toss",
    active: false,
  };
  const updated: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.putById(
    connection,
    { id: created.id, body: updateBody },
  );
  typia.assert(updated);
  // 3. Assert relevant field changes, and immutable fields remain
  TestValidator.equals("updated.masked_detail")(
    updateBody.masked_detail,
  )(updated.masked_detail);
  TestValidator.equals("updated.provider")(updateBody.provider)(
    updated.provider,
  );
  TestValidator.equals("updated.active")(updateBody.active)(updated.active);
  TestValidator.equals("type unchanged")(created.type)(updated.type);
  TestValidator.equals("user_id unchanged")(created.user_id)(updated.user_id);

  // 4. Try updating a non-existent payment method, expect error
  await TestValidator.httpError("non-existent update")(404)(() =>
    api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
      id: typia.random<string>(), // very likely non-existent UUID
      body: { masked_detail: "0000****1111" },
    }),
  );

  // 5. Try forbidden field (type) update - should be rejected (validation)
  // Since the API only allows IUpdate, type/user_id can't be sent; test illegal update using 'as any'.
  await TestValidator.error("forbidden field update fail")(() =>
    api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
      id: created.id,
      body: {
        masked_detail: "7777****8888",
        type: "CRYPTO",
      } as any, // intentional breaking test
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * Test soft-delete (deactivation) of a payment method and negative edge cases.
 *
 * This test ensures that a payment method can be soft-deleted (deactivated) and that it is
 * properly excluded from active payment flows, but the record remains retrievable for audit/compliance.
 * It further verifies that deletion of already-inactive or non-existent methods returns appropriate errors.
 *
 * Scenario Steps:
 * 1. Create a new payment method for a test user.
 * 2. Soft-delete (deactivate) the payment method using DELETE.
 * 3. Assert the method is now inactive (`active: false`) but record is otherwise preserved.
 * 4. Attempt to delete the same method again — expect appropriate error (or idempotent response).
 * 5. Attempt to delete a non-existent payment method (random UUID) — expect error (404/410).
 * 6. Optionally, query or assert compliance record persists for audit.
 *
 * Rationale:
 * Required for PCI compliance: audit, non-repudiation, and historic traceability.
 * Must assure soft-deleted records don't interfere with user experience or checkout flows.
 */
export async function test_api_payment_method_soft_delete_and_inactive_missing_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new payment method
  const created: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        type: "visa",
        masked_detail: "**** **** **** 4242",
        provider: "Stripe",
        active: true,
      } satisfies IPaymentMethod.ICreate,
    },
  );
  typia.assert(created);

  // 2. Soft-delete (deactivate) the method
  const deleted: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.eraseById(
    connection,
    {
      id: created.id,
    },
  );
  typia.assert(deleted);
  TestValidator.equals("method should now be inactive")(false)(deleted.active);
  TestValidator.equals("record id remains")(created.id)(deleted.id);
  TestValidator.equals("user_id preserved")(created.user_id)(deleted.user_id);

  // 3. Attempt to delete already-inactive method
  await TestValidator.httpError("already inactive method deletion should error")(400)(() =>
    api.functional.paymentsDiscounts.paymentMethods.eraseById(
      connection,
      {
        id: created.id,
      },
    ),
  );

  // 4. Attempt to delete entirely non-existent method
  await TestValidator.httpError("non-existent payment method deletion should 404")(404)(() =>
    api.functional.paymentsDiscounts.paymentMethods.eraseById(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
      },
    ),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import { IPageIDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscount";
import typia from "typia";

/**
 * 복수의 서로 다른 할인(discount) 레코드를 생성하고,
 * /paymentsDiscounts/discounts PATCH 엔드포인트로 상태, 룰, 캠페인, 금액, 타임스탬프 등 다양한 필터·페이징 조건을 검증합니다.
 *
 * 비즈니스 목적:
 * 관리, 감사, 데이터 분석 시 실시간 할인의 정책별 조회 및 분석이 필수적입니다. 모든 필터 옵션과 페이징 조작이 올바로 동작하는지,
 * 그리고 예상치 않거나 부정확한 값을 넣었을 때도 견고하게 처리되는지 검증합니다.
 * 예외 상황(잘못된 ID, 비정상 범위 등)과 비어있는 결과에도 올바른 응답 구조를 확인합니다.
 *
 * [시나리오 단계]
 * 1. 서로 다른 특성을 가진 discount 레코드 N개 생성 (룰/주문/캠페인/amount/status 등 조합)
 * 2. 각각의 discount_rule_id, order_id, campaign_id, 금액, applied_at, status 정보 기록
 * 3. 다양한 필터 조합으로 PATCH 검색 API 호출
 *   - discount_rule_id, order_id, campaign_id로 개별 검색
 *   - 금액 범위, 적용 시점(applied_at) 범위, status별 검색
 *   - 복수 필드(or/and) 복합 필터, 페이지네이션(page, limit) 조합 테스트
 * 4. 결과로 리턴된 discounts가 반드시 요청한 조건을 모두 충족하는지 assert
 * 5. status가 removed 등 비활성화인 할인은 active 조회 시 결과에 포함되지 않는지 확인
 * 6. 필터에 맞는 discount가 없으면 빈 배열/카운트 0인지 확인 (엣지, 없는 order_id 등)
 * 7. 잘못된 입력(존재하지 않는 ID, 금액 범위 꼬임 등) → 빈 결과 or valid error
 * 8. 모든 응답 타입 assert 및 pagination 메타데이터 검증
 */
export async function test_api_discount_search_and_filter_discounts_with_rules_and_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. N개의 discount 레코드 생성: 변수 최대 다양성 확보
  const discountInputs: IDiscount.ICreate[] = [];
  const uniqueRuleIdA = typia.random<string & typia.tags.Format<"uuid">>();
  const uniqueRuleIdB = typia.random<string & typia.tags.Format<"uuid">>();
  const uniqueOrderIdA = typia.random<string & typia.tags.Format<"uuid">>();
  const uniqueOrderIdB = typia.random<string & typia.tags.Format<"uuid">>();
  const campaignIdA = typia.random<string & typia.tags.Format<"uuid">>();
  const campaignIdB = typia.random<string & typia.tags.Format<"uuid">>();

  // 기본 5건: 활성, 제거, 다양한 캠페인/룰/amount, 일부 status/notes 변화
  const now = new Date();
  function offset(sec: number) {
    return new Date(now.getTime() + sec * 1000).toISOString();
  }
  const specials: (Partial<IDiscount.ICreate> & { status?: string; campaign_id?: string })[] = [
    // Active, campaign A, rule A
    { discount_rule_id: uniqueRuleIdA, order_id: uniqueOrderIdA, amount: -1000, notes: "active and campaign A", campaign_id: campaignIdA, status: "active" },
    // Removed (will not show in active), rule B, campaign B
    { discount_rule_id: uniqueRuleIdB, order_id: uniqueOrderIdA, amount: -1200, notes: "removed", campaign_id: campaignIdB, status: "removed" },
    // Active, unique order, campaign B
    { discount_rule_id: uniqueRuleIdA, order_id: uniqueOrderIdB, amount: -3000, notes: "active B", campaign_id: campaignIdB, status: "active" },
    // Active, rule B, old timestamp
    { discount_rule_id: uniqueRuleIdB, order_id: uniqueOrderIdB, amount: -500, notes: "active old", status: "active" },
    // Active, big amount, campaign A
    { discount_rule_id: uniqueRuleIdA, order_id: uniqueOrderIdA, amount: -50000, notes: "big active", campaign_id: campaignIdA, status: "active" },
  ];
  // 각 할인 생성 + field 모음(후속 필터용 메모)
  const created: (IDiscount & { campaign_id?: string; status?: string })[] = [];
  for (const [idx, s] of specials.entries()) {
    // discount 생성(discount_rule_id, order_id, amount 등 특성 조합)
    const body: IDiscount.ICreate = {
      ...s,
      discount_rule_id: s.discount_rule_id!,
      order_id: s.order_id!,
      amount: s.amount!,
      notes: s.notes ?? undefined,
    } satisfies IDiscount.ICreate;
    const output: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, { body });
    typia.assert(output);
    created.push({ ...output, campaign_id: s.campaign_id, status: s.status });
  }

  // 2. campaign_id 별 필터링
  for (const campaign_id of [campaignIdA, campaignIdB]) {
    const out: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
      body: { campaign_id } satisfies IDiscount.IRequest,
    });
    typia.assert(out);
    for (const d of out.data) TestValidator.equals("campaign_id")(campaign_id)(created.find(c => c.id === d.id)?.campaign_id);
  }

  // 3. discount_rule_id, order_id 필터 모든 조합
  for (const rule_id of [uniqueRuleIdA, uniqueRuleIdB]) {
    const out = await api.functional.paymentsDiscounts.discounts.patch(connection, {
      body: { discount_rule_id: rule_id } satisfies IDiscount.IRequest,
    });
    typia.assert(out);
    for (const d of out.data) TestValidator.equals("discount_rule_id")(rule_id)(d.discount_rule_id);
  }
  for (const order_id of [uniqueOrderIdA, uniqueOrderIdB]) {
    const out = await api.functional.paymentsDiscounts.discounts.patch(connection, {
      body: { order_id } satisfies IDiscount.IRequest,
    });
    typia.assert(out);
    for (const d of out.data) TestValidator.equals("order_id")(order_id)(d.order_id);
  }

  // 4. 금액 amount 범위
  const outAmt = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { amount_from: -1200, amount_to: -100 } satisfies IDiscount.IRequest,
  });
  typia.assert(outAmt);
  for (const d of outAmt.data) TestValidator.equals("amount >= -1200 && < -100")(true)(d.amount >= -1200 && d.amount < -100);

  // 5. 적용 시점(applied_at) 범위
  const recentStart = new Date(now.getTime() - 60 * 1000).toISOString();
  const after = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { applied_from: recentStart } satisfies IDiscount.IRequest,
  });
  typia.assert(after);
  for (const d of after.data) TestValidator.equals("applied_at >= recentStart")(true)(d.applied_at >= recentStart);
  // 범위 없는 시점(미래)
  const futureStart = new Date(now.getTime() + 3600 * 1000).toISOString();
  const future = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { applied_from: futureStart } satisfies IDiscount.IRequest,
  });
  typia.assert(future);
  TestValidator.equals("future => no data")(0)(future.data.length);

  // 6. status(active/removed 등) 필터
  const outActive = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { status: "active" } satisfies IDiscount.IRequest,
  });
  typia.assert(outActive);
  for (const d of outActive.data) TestValidator.equals("only active")(true)(created.find(c => c.id === d.id)?.status === "active");
  // removed 포함 테스트 (removed는 결과에 안나와야 함)
  for (const d of outActive.data) TestValidator.equals("not removed")(false)(created.find(c => c.id === d.id)?.status === "removed");

  // 7. 복수 조건 & 페이징
  const multi = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { status: "active", campaign_id: campaignIdA, page: 1, limit: 1 } satisfies IDiscount.IRequest,
  });
  typia.assert(multi);
  TestValidator.equals("pagination: 1 per page")(1)(multi.data.length);
  TestValidator.equals("pagination page")(1)(multi.pagination.current);
  TestValidator.equals("pagination limit")(1)(multi.pagination.limit);

  // 8. 빈 결과(비존재 order_id)
  const nonExistingId = typia.random<string & typia.tags.Format<"uuid">>();
  const empty = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { order_id: nonExistingId } satisfies IDiscount.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("empty data")(0)(empty.data.length);

  // 9. 금액 꼬인 입력(amount_from > amount_to): 빈 데이터
  const invAmt = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { amount_from: -100, amount_to: -1200 } satisfies IDiscount.IRequest,
  });
  typia.assert(invAmt);
  TestValidator.equals("amount_from > to = empty")(0)(invAmt.data.length);

  // 10. 기타 모든 결과: 타입/pagination 1/N 검증
  const all = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { page: 1, limit: 100 } satisfies IDiscount.IRequest,
  });
  typia.assert(all);
  TestValidator.equals("total >=5")(true)(all.data.length >= 5);
  TestValidator.equals("pagination meta present")(true)(
    typeof all.pagination.current === "number" && typeof all.pagination.records === "number"
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import typia, { tags } from "typia";

/**
 * 할인 레코드의 ID 기반 단일 조회 E2E 테스트.
 *
 * - 성공 케이스: 할인 생성 후 UUID로 정상 조회가 되는지, 모든 필드 일치 여부까지 검증
 * - 실패 케이스1: 잘못된(형식 오류) UUID로 조회 시 적절한 오류 응답 반환 및 검증
 * - 실패 케이스2: 존재하지 않는(올바른 포맷이지만 없는) UUID 조회 시 not found 등 오류 응답 검증
 *
 * 1. /paymentsDiscounts/discounts POST로 할인 생성 (정상 필드 입력)
 * 2. 생성된 할인 id로 /paymentsDiscounts/discounts/{id} GET (정상)
 *    - 반환 필드가 모두 일치하는지 확인
 * 3. 잘못된 UUID(id)로 GET (형식 오류) → 에러 발생 검증
 * 4. 존재하지 않는 UUID로 GET (존재하지 않음) → 404 등 에러 발생 검증
 *
 * @author
 */
export async function test_api_discount_get_by_id_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. 할인 레코드 생성
  const createInput: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -5000,
    notes: "E2E test case", // 부연 설명
  };
  const created: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: createInput satisfies IDiscount.ICreate,
  });
  typia.assert(created);

  // 2. 생성된 ID로 단일 할인 조회
  const found: IDiscount = await api.functional.paymentsDiscounts.discounts.getById(connection, {
    id: created.id,
  });
  typia.assert(found);
  TestValidator.equals("discount record ID")(created.id)(found.id);
  TestValidator.equals("discount_rule_id")(created.discount_rule_id)(found.discount_rule_id);
  TestValidator.equals("order_id")(created.order_id)(found.order_id);
  TestValidator.equals("amount")(created.amount)(found.amount);
  TestValidator.equals("notes")(created.notes ?? "")(found.notes ?? "");

  // 3. 잘못된(형식 오류) UUID로 조회 시
  await TestValidator.error("invalid UUID")(() =>
    api.functional.paymentsDiscounts.discounts.getById(connection, {
      id: "not-a-uuid-format" as any,
    }),
  );

  // 4. 존재하지 않는(포맷만 올바름) UUID로 조회 시
  const unusedId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("not found")(404)(() =>
    api.functional.paymentsDiscounts.discounts.getById(connection, {
      id: unusedId,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import { IDiscountRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountRule";
import typia from "typia";

/**
 * Create a discount with both minimal and full required data, assigning it to a rule or order.
 *
 * Also, attempt creating discounts with missing, invalid, or duplicate data to ensure error handling works as intended.
 *
 * Steps:
 * 1. Create a valid discount rule (to link in discounts)
 * 2. Create a discount with minimal data (required fields only)
 * 3. Create a discount with all fields (notes, negative float, large value)
 * 4. Attempt discount creation with missing fields (rule, order, amount)
 * 5. Attempt discount creation with invalid UUIDs
 * 6. Test for duplicate discount for same rule/order
 * 7. Use edge/odd values for amount
 * 8. Validate all responses (structure, error codes)
 */
export async function test_api_discount_create_with_rule_assignment_and_invalid_data_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid discount rule
  const rule1: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "fixed",
      value: -1000,
      active: true
    } satisfies IDiscountRule.ICreate
  });
  typia.assert(rule1);

  // 2. Create a discount with minimal data
  const minimal_discount: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: rule1.id,
      order_id: typia.random<string & typia.tags.Format<"uuid">>(),
      amount: -1000
    } satisfies IDiscount.ICreate
  });
  typia.assert(minimal_discount);
  TestValidator.equals("discount_rule_id")(rule1.id)(minimal_discount.discount_rule_id);

  // 3. Create a discount with all fields (notes, edge-case amount)
  const rule2: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "percentage",
      value: 20,
      active: true
    } satisfies IDiscountRule.ICreate
  });
  typia.assert(rule2);

  const order2 = typia.random<string & typia.tags.Format<"uuid">>();
  const all_fields_discount: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: rule2.id,
      order_id: order2,
      amount: -99999.99,
      notes: "Black Friday Special: Applied extra"
    } satisfies IDiscount.ICreate
  });
  typia.assert(all_fields_discount);
  TestValidator.equals("notes")("Black Friday Special: Applied extra")(all_fields_discount.notes);

  // 4. Attempt discount creation with missing required fields
  await TestValidator.httpError("missing discount_rule_id")(400)(() =>
    api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        order_id: typia.random<string & typia.tags.Format<"uuid">>(),
        amount: -500
      } as any
    })
  );
  await TestValidator.httpError("missing order_id")(400)(() =>
    api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        discount_rule_id: rule1.id,
        amount: -500
      } as any
    })
  );
  await TestValidator.httpError("missing amount")(400)(() =>
    api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        discount_rule_id: rule1.id,
        order_id: typia.random<string & typia.tags.Format<"uuid">>()
      } as any
    })
  );

  // 5. Attempt discount creation with invalid UUIDs
  await TestValidator.httpError("invalid discount_rule_id")(400)(() =>
    api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        discount_rule_id: "not-a-uuid",
        order_id: typia.random<string & typia.tags.Format<"uuid">>(),
        amount: -500
      } as any
    })
  );
  await TestValidator.httpError("invalid order_id")(400)(() =>
    api.functional.paymentsDiscounts.discounts.post(connection, {
      body: {
        discount_rule_id: rule1.id,
        order_id: "123-invalid-uuid",
        amount: -500
      } as any
    })
  );

  // 6. Duplicate discount for same rule and order (should fail: business collision)
  const unique_order = typia.random<string & typia.tags.Format<"uuid">>();
  const rule3: IDiscountRule = await api.functional.paymentsDiscounts.discountRules.post(connection, {
    body: {
      type: "fixed",
      value: -888,
      active: true
    } satisfies IDiscountRule.ICreate
  });
  typia.assert(rule3);

  // 6-a. First creation should succeed
  const first_discount: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: rule3.id,
      order_id: unique_order,
      amount: -888
    } satisfies IDiscount.ICreate
  });
  typia.assert(first_discount);

  // 6-b. Second (duplicate) should fail
