import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";

/**
 * Test updating allowable fields of a discount record and preventing mutation of immutable or non-existent records.
 *
 * This test validates the business policy that only permitted fields (such as 'notes' and, in exception, 'amount') can be updated for existing discount records.
 * All immutable fields (e.g., 'id', 'discount_rule_id', 'order_id', 'applied_at') must not be updatable. Additionally, attempts to update a non-existent record must be rejected.
 * Follows the full update lifecycle: create, valid mutation, forbidden mutation, and error cases.
 *
 * Steps:
 * 1. Create a discount for update testing.
 * 2. Update the 'notes' field and validate success.
 * 3. (If permitted) Update the 'amount' field and validate.
 * 4. Attempt forbidden mutation of immutable fields and expect failure.
 * 5. Attempt updating a non-existent discount and expect failure.
 * 6. Validate all type and value integrity.
 */
export async function test_api_discount_update_valid_and_immutable_enforcement(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a discount for update testing.
  const createInput: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -1234.56,
    notes: "Initial discount for update test",
  };
  const discount: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: createInput,
  });
  typia.assert(discount);
  TestValidator.equals("discount_rule_id")(createInput.discount_rule_id)(discount.discount_rule_id);
  TestValidator.equals("order_id")(createInput.order_id)(discount.order_id);
  TestValidator.equals("amount")(createInput.amount)(discount.amount);
  TestValidator.equals("notes")(createInput.notes)(discount.notes);

  // 2. Update 'notes' field (allowed field)
  const updatedNotes = "Updated discount note";
  const updated1: IDiscount = await api.functional.paymentsDiscounts.discounts.putById(connection, {
    id: discount.id,
    body: {
      notes: updatedNotes,
    } satisfies IDiscount.IUpdate,
  });
  typia.assert(updated1);
  TestValidator.equals("id")(discount.id)(updated1.id);
  TestValidator.equals("notes")(updatedNotes)(updated1.notes);
  TestValidator.equals("amount") (discount.amount)(updated1.amount);

  // 3. Update 'amount' field (if allowed: for the test, try update)
  const updatedAmount = discount.amount - 100;
  const updated2: IDiscount = await api.functional.paymentsDiscounts.discounts.putById(connection, {
    id: discount.id,
    body: {
      amount: updatedAmount,
    } satisfies IDiscount.IUpdate,
  });
  typia.assert(updated2);
  TestValidator.equals("amount updated")(updatedAmount)(updated2.amount);
  TestValidator.equals("notes") (updated1.notes)(updated2.notes);

  // 4. Attempt forbidden mutation (e.g., change id, discount_rule_id, order_id, applied_at)
  // These fields must not be updatable; try mocking mutation by sending forbidden fields (simulate forbidden field via cast for negative test)
  const forbiddenPatch: any = {
    id: typia.random<string & tags.Format<"uuid">>(),
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    applied_at: new Date().toISOString(),
    notes: "Should be forbidden"
  };
  await TestValidator.httpError("forbidden immutable field mutation")(400)(() =>
    api.functional.paymentsDiscounts.discounts.putById(connection, {
      id: discount.id,
      body: forbiddenPatch,
    }),
  );

  // 5. Attempt to update a non-existent discount ID
  await TestValidator.httpError("update non-existent discount")(404)(() =>
    api.functional.paymentsDiscounts.discounts.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // Assume not existing
      body: {
        notes: "Trying to update non-existent discount",
      } satisfies IDiscount.IUpdate,
    }),
  );
}

