 *
 * This test verifies proper functionality and error handling of GET /core/users/{id}, ensuring:
 * 1. A valid created user's data can be retrieved by their ID, field-level values match expected outputs.
 * 2. Requests to a non-existent ID yield a 404 or explicit not-found error, with no data leakage in the response body.
 *
 * Step-by-step:
 * 1. Create a user (to secure a valid user ID for the retrieval success case).
 * 2. Fetch the user by their ID; validate all fields and type (IUser) mapping.
 * 3. Fetch a user by a random (non-existent) UUID; expect and assert a not-found error (HTTP 404).
 */
export async function test_api_user_get_by_id_with_valid_and_invalid_id(connection: api.IConnection): Promise<void> {
  // 1. Create a user.
  const newUser: IUser = await api.functional.core.users.post(connection, {
    body: {
      role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `user_${Math.random().toString(36).substring(2, 10)}`,
      email: `test_${Date.now()}@wrtn.io`,
      password: "StrongPassword123!",
    } satisfies IUser.ICreate,
  });
  typia.assert(newUser);

  // 2. Retrieve the same user by ID.
  const fetched: IUser = await api.functional.core.users.getById(connection, {
    id: newUser.id,
  });
  typia.assert(fetched);
  TestValidator.equals("user.id")(newUser.id)(fetched.id);
  TestValidator.equals("user.username")(newUser.username)(fetched.username);
  TestValidator.equals("user.email")(newUser.email)(fetched.email);
  TestValidator.equals("user.role_id")(newUser.role_id)(fetched.role_id);
  // organization_id may be undefined if not sent
  if (newUser.organization_id)
    TestValidator.equals("user.organization_id")(newUser.organization_id)(fetched.organization_id);
  TestValidator.equals("is_active")(true)(fetched.is_active);
  TestValidator.equals("deleted_at")(undefined)(fetched.deleted_at);

  // 3. Try fetching a user with a random, truly non-existent UUID
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  // Loop until we get a UUID that doesn't collide with the new user's ID
  const notFoundId = randomUuid === newUser.id ? typia.random<string & tags.Format<"uuid">>() : randomUuid;
  await TestValidator.httpError("user not found should return 404")(404)(() =>
    api.functional.core.users.getById(connection, { id: notFoundId })
  );
}

