/**
 * Validate soft-deletion of a user and edge conditions for audit compliance.
 *
 * This test ensures that users can be soft-deleted correctly using the Core Users API. It verifies that after deletion,
 * the record receives a `deleted_at` timestamp, is not available for subsequent normal access, and
 * checks system responses to deleting non-existent and already deleted users.
 *
 * Steps:
 * 1. Create a new user for deletion via POST /core/users
 * 2. Soft-delete the user by ID via DELETE /core/users/{id}; check ISoftDelete results
 * 3. Attempt to delete the same user again; expect error or proper no-op result
 * 4. Attempt to delete a random non-existent ID; expect not-found or proper error
 * 5. Optionally, confirm deleted user no longer visible in main user queries (read/list not tested as SDK not provided here)
 */
export async function test_api_user_soft_delete_and_edge_cases(connection: api.IConnection): Promise<void> {
  // 1. Create user
  const user: IUser = await api.functional.core.users.post(connection, {
    body: {
      organization_id: typia.random<string & tags.Format<"uuid">>(),
      role_id: typia.random<string & tags.Format<"uuid">>(),
      username: `soft-delete-e2e-" + Math.random().toString(16).slice(2),
      email: `soft-delete-e2e-" + Math.random().toString(16).slice(2) + "@test.com`,
      password: "StrongTestPw#1",
      phone: null,
    } satisfies IUser.ICreate
  });
  typia.assert(user);

  // 2. Soft-delete user
  const softDelete: IUser.ISoftDelete = await api.functional.core.users.eraseById(connection, { id: user.id });
  typia.assert(softDelete);
  TestValidator.equals("id preserved after soft-delete")(user.id)(softDelete.id);
