import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IUserProfile";

/**
 * Update an existing user profile's metadata and validate audit logging, as well as error flows.
 *
 * Scenario:
 * 1. Create a user profile for update/audit testing.
 * 2. Update several profile fields via PUT /core/userProfiles/{id}, e.g., locale_id, full_name, avatar_url, timezone, bio, a11y_prefs.
 * 3. Reload and assert the profile reflects all updated fields and audit (updated_at changed, etc).
 * 4. Attempt to update forbidden fields (e.g. id, user_id) and expect validation or authorization error.
 * 5. Attempt to update a non-existent profile and expect not-found error.
 */
export async function test_api_user_profile_update_with_audit_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create user profile (prerequisite)
  const createBody: IUserProfile.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    full_name: "Original Name",
    avatar_url: "https://images.wrtn.io/avatar.jpg",
    locale_id: typia.random<string & tags.Format<"uuid">>(),
    timezone: "Asia/Seoul",
    bio: "This is the first profile bio.",
    a11y_prefs: '{"contrast":true}',
  };
  const profile: IUserProfile = await api.functional.core.userProfiles.post(connection, {
    body: createBody,
  });
  typia.assert(profile);

  // 2. Update (valid case): several fields
  const updateBody: IUserProfile.IUpdate = {
    full_name: "Updated Name",
    avatar_url: "https://images.wrtn.io/avatar-new.png",
    bio: "This bio was updated.",
    timezone: "Asia/Busan",
    a11y_prefs: '{"contrast":false}',
  };
  const updated: IUserProfile = await api.functional.core.userProfiles.putById(connection, {
    id: profile.id,
    body: updateBody,
  });
  typia.assert(updated);
  for (const [k, v] of Object.entries(updateBody)) {
    if (typeof v !== "undefined")
      TestValidator.equals(`Update field: ${k}`)(v)((updated as any)[k]);
  }
  TestValidator.equals("user_id invariant")(profile.user_id)(updated.user_id);
  TestValidator.equals("id invariant")(profile.id)(updated.id);
  TestValidator.notEquals("updated_at should be changed")(profile.updated_at)(updated.updated_at);

  // 3. Negative (forbidden field): try to update id or user_id—should fail validation or authorization
  // These fields do not exist in IUpdate type, so simulate by casting for test
  await TestValidator.httpError("Reject forbidden id/user_id mutation")(400)(() =>
    api.functional.core.userProfiles.putById(connection, {
      id: profile.id,
      // @ts-expect-error Deliberate extra properties
      body: { ...(updateBody as any), id: "fake-id", user_id: "other-user" },
    }),
  );

  // 4. Not-found: Update random UUID profile that doesn't exist
  await TestValidator.httpError("not found for invalid profile id")(404)(() =>
    api.functional.core.userProfiles.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    }),
  );
}

