 *
 * Scenario:
 * 1. Create multiple organizations with unique names and codes for retrieval and filtering coverage.
 * 2. Fetch organizations with default, custom, and edge pagination settings. Validate list and pagination metadata.
 * 3. Query using name and code filters, ensuring only matching organizations are returned.
 * 4. Use invalid pagination/filter parameters and verify validation error responses.
 * 5. Confirm behavior for filters that yield no results.
 */
export async function test_api_organization_list_pagination_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create organizations for baseline and filtering
  const orgs: IOrganization[] = [];
  for (const [name, code] of [
    ["Wrtn Corp", "wrtn-corp"],
    ["Stabled Diffusion Inc", "stabled-diff"],
    ["ZeroGPT Org", "zerogpt-org"],
  ]) {
    const org: IOrganization = await api.functional.core.organizations.post(connection, {
      body: { name, code } satisfies IOrganization.ICreate,
    });
    typia.assert(org);
    orgs.push(org);
  }

  // 2. Retrieve paginated list with default parameters
  const page1: IPageIOrganization = await api.functional.core.organizations.patch(connection, { body: {} });
  typia.assert(page1);
  TestValidator.equals("pagination current")(1)(page1.pagination.current);
  TestValidator.equals("limit default")(100)(page1.pagination.limit); // default limit if not specified
  // Validate that our organizations appear in the data (could contain extra due to DB)
  for (const created of orgs) {
    const match = page1.data.find(x => x.id === created.id);
    TestValidator.equals("organization present in list")(created.id)(match?.id);
  }

  // 3. Test pagination with explicit limit (e.g., 2)
  const pageLimited: IPageIOrganization = await api.functional.core.organizations.patch(connection, {
    body: { page: 1, limit: 2 } satisfies IOrganization.IRequest,
  });
  typia.assert(pageLimited);
  TestValidator.equals("limit applied")(2)(pageLimited.pagination.limit);
  TestValidator.equals("at most 2 results")(true)(pageLimited.data.length <= 2);

  // 4. Filter by name
  const byName: IPageIOrganization = await api.functional.core.organizations.patch(connection, {
    body: { name: orgs[0].name } satisfies IOrganization.IRequest,
  });
  typia.assert(byName);
  for (const org of byName.data) {
    TestValidator.equals("name filter match")(orgs[0].name)(org.name);
  }

  // 5. Filter by code
  const byCode: IPageIOrganization = await api.functional.core.organizations.patch(connection, {
    body: { code: orgs[1].code } satisfies IOrganization.IRequest,
  });
  typia.assert(byCode);
  for (const org of byCode.data) {
    TestValidator.equals("code filter match")(orgs[1].code)(org.code);
  }

  // 6. Filter by name that yields no results
  const noResult: IPageIOrganization = await api.functional.core.organizations.patch(connection, {
    body: { name: "NON_EXISTENT_ORG_NAME" } satisfies IOrganization.IRequest,
  });
  typia.assert(noResult);
  TestValidator.equals("no result")(0)(noResult.data.length);

  // 7. Invalid pagination: negative page number
  await TestValidator.httpError("negative page invalid")(400)(() =>
    api.functional.core.organizations.patch(connection, {
      body: { page: -1 } satisfies IOrganization.IRequest,
    })
  );

  // 8. Invalid pagination: too large a limit
  await TestValidator.httpError("overlarge limit invalid")(400)(() =>
    api.functional.core.organizations.patch(connection, {
      body: { limit: 10000000 } satisfies IOrganization.IRequest,
    })
  );
}

