import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";
import { IPageIRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRole";
import typia from "typia";

/**
 * Retrieve a paginated and filterable list of roles and verify all filter and pagination logic.
 *
 * 1. Create at least 3 roles with different names, codes, and organization_id (two distinct orgs).
 * 2. Retrieve all roles without filters, verify completeness.
 * 3. Filter by organization_id; only roles from that org should be returned.
 * 4. Filter by name and code; check correct roles are returned.
 * 5. Test pagination (page, limit) and metadata accuracy.
 * 6. Test invalid/excessive parameters (e.g., negative page/limit).
 */
export async function test_api_role_list_with_pagination_and_filtering(connection: api.IConnection): Promise<void> {
    // 1. Create at least 3 roles under 2 orgs
    const orgId1 = typia.random<string & typia.tags.Format<"uuid">>();
    const orgId2 = typia.random<string & typia.tags.Format<"uuid">>();
    const roleA: IRole = await api.functional.core.roles.post(connection, {
        body: {
            organization_id: orgId1,
            name: "Admin",
            code: "ADMIN",
            description: "admin role for testing",
        } satisfies IRole.ICreate,
    });
    typia.assert(roleA);

    const roleB: IRole = await api.functional.core.roles.post(connection, {
        body: {
            organization_id: orgId1,
            name: "Manager",
            code: "MANAGER",
            description: "manager, org 1",
        } satisfies IRole.ICreate,
    });
    typia.assert(roleB);

    const roleC: IRole = await api.functional.core.roles.post(connection, {
        body: {
            organization_id: orgId2,
            name: "Customer",
            code: "CUSTOMER",
            description: "customer role, org 2",
        } satisfies IRole.ICreate,
    });
    typia.assert(roleC);

    // 2. Retrieve all roles, validate all present
    const allRolesRes: IPageIRole = await api.functional.core.roles.patch(connection, { body: {} });
    typia.assert(allRolesRes);
    const allRoleIds = allRolesRes.data.map(role => role.id);
    TestValidator.equals("all roles present")(true)(
        allRoleIds.includes(roleA.id) && allRoleIds.includes(roleB.id) && allRoleIds.includes(roleC.id)
    );

    // 3. Filter by organization_id (orgId1)
    const org1Res: IPageIRole = await api.functional.core.roles.patch(connection, { body: { organization_id: orgId1 } });
    typia.assert(org1Res);
    TestValidator.equals("org1 roles only")(
        [roleA.id, roleB.id].sort()
    )(
        org1Res.data.map(r => r.id).sort()
    );
    org1Res.data.forEach(r => TestValidator.equals("org1 only")(orgId1)(r.organization_id));

    // 4. Filter by name and code
    const adminRes: IPageIRole = await api.functional.core.roles.patch(connection, { body: { name: "Admin" } });
    typia.assert(adminRes);
    TestValidator.equals("admin by name")(1)(adminRes.data.filter(r => r.name === "Admin").length);
    TestValidator.equals("admin id")(roleA.id)(adminRes.data[0]?.id);

    const customerRes: IPageIRole = await api.functional.core.roles.patch(connection, { body: { code: "CUSTOMER" } });
    typia.assert(customerRes);
    TestValidator.equals("customer by code")(1)(customerRes.data.filter(r => r.code === "CUSTOMER").length);
    TestValidator.equals("customer id")(roleC.id)(customerRes.data[0]?.id);

    // 5. Pagination tests
    const paged1: IPageIRole = await api.functional.core.roles.patch(connection, { body: { limit: 2, page: 1 } });
    typia.assert(paged1);
    TestValidator.equals("paged1 limit")(2)(paged1.pagination.limit);
    TestValidator.equals("paged1 page")(1)(paged1.pagination.current);
    TestValidator.equals("paged1 records or less")(true)(paged1.data.length <= 2);

    const paged2: IPageIRole = await api.functional.core.roles.patch(connection, { body: { limit: 2, page: 2 } });
    typia.assert(paged2);
    TestValidator.equals("paged2 limit")(2)(paged2.pagination.limit);
    TestValidator.equals("paged2 page")(2)(paged2.pagination.current);

    TestValidator.equals("pagination total records")(
        allRolesRes.pagination.records
    )(
        paged1.pagination.records
    );

    // 6. Invalid parameters (negative page/limit)
    await TestValidator.httpError("negative page")(
        400
    )(() => api.functional.core.roles.patch(connection, { body: { page: -1 } }));

    await TestValidator.httpError("negative limit")(
        400
    )(() => api.functional.core.roles.patch(connection, { body: { limit: -5 } }));
}

