import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import { IPageISession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISession";

/**
 * E2E test for session listing with pagination/filtering in Core sessions API.
 *
 * Validates the following sequence:
 * 1. Creates several sessions with unique user IDs, device fingerprints, expiry times, and IPs.
 * 2. Lists all sessions with default pagination (PATCH /core/sessions).
 * 3. Lists sessions with custom pagination (page, limit) to verify boundary behavior.
 * 4. Lists sessions using filter parameters: user_id, device_fingerprint, expires_before, expires_after, ip.
 * 5. Submits invalid query values (e.g., negative page, malformed user_id, malformed dates) and expects validation failures.
 *
 * This verifies both functional behavior and error handling of paginated, filtered search on the sessions resource.
 */
export async function test_api_session_list_with_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create 3 sessions with distinct user_id, device, expiry, IP
  const now = new Date();
  const sessionInputs: ISession.ICreate[] = [
    {
      user_id: typia.random<string>(), // Valid UUID
      token: "token_a",
      expires_at: new Date(now.getTime() + 60 * 60 * 1000).toISOString(), // +1 hour
      device_fingerprint: "deviceA",
      ip: "1.2.3.4",
    },
    {
      user_id: typia.random<string>(),
      token: "token_b",
      expires_at: new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString(), // +2 hours
      device_fingerprint: "deviceB",
      ip: "5.6.7.8",
    },
    {
      user_id: typia.random<string>(),
      token: "token_c",
      expires_at: new Date(now.getTime() + 3 * 60 * 60 * 1000).toISOString(), // +3 hours
      device_fingerprint: "deviceC",
      ip: "9.10.11.12",
    },
  ];
  const sessions: ISession[] = [];
  for (const input of sessionInputs) {
    const created = await api.functional.core.sessions.post(connection, {
      body: input,
    });
    typia.assert(created);
    sessions.push(created);
  }

  // 2. List all sessions with default pagination
  const listAll: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: {}, // default params
  });
  typia.assert(listAll);
  TestValidator.equals("pagination.records")(listAll.pagination.records >= sessions.length)(true);
  // Check all created session tokens are present in results
  const allTokens = listAll.data.map((s) => s.token);
  for (const input of sessionInputs) {
    TestValidator.equals(`session token present`)({ found: true })({ found: allTokens.includes(input.token) });
  }

  // 3. Custom pagination (page=2, limit=1)
  const paged: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { page: 2, limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("limit")(paged.pagination.limit)(1);
  TestValidator.equals("current page")(paged.pagination.current)(2);

  // 4. Filtering: by user_id, device_fingerprint, expires_before, expires_after, ip
  // Filter by user_id
  const filterByUser: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { user_id: sessions[0].user_id },
  });
  typia.assert(filterByUser);
  for (const s of filterByUser.data) {
    TestValidator.equals("filter user_id")(s.user_id)(sessions[0].user_id);
  }
  // Filter by device_fingerprint
  const filterByDevice: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { device_fingerprint: sessions[1].device_fingerprint! },
  });
  typia.assert(filterByDevice);
  for (const s of filterByDevice.data) {
    TestValidator.equals("filter device")(s.device_fingerprint)(sessions[1].device_fingerprint);
  }
  // Filter by expires_before
  const expiresBefore = new Date(now.getTime() + 2.5 * 60 * 60 * 1000); // +2.5hrs
  const filterByExpiresBefore: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { expires_before: expiresBefore.toISOString() },
  });
  typia.assert(filterByExpiresBefore);
  for (const s of filterByExpiresBefore.data) {
    TestValidator.equals("filter expires_before")(new Date(s.expires_at) < expiresBefore)(true);
  }
  // Filter by expires_after
  const expiresAfter = new Date(now.getTime() + 1.5 * 60 * 60 * 1000); // +1.5hrs
  const filterByExpiresAfter: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { expires_after: expiresAfter.toISOString() },
  });
  typia.assert(filterByExpiresAfter);
  for (const s of filterByExpiresAfter.data) {
    TestValidator.equals("filter expires_after")(new Date(s.expires_at) > expiresAfter)(true);
  }
  // Filter by ip
  const filterByIp: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { ip: sessions[2].ip! },
  });
  typia.assert(filterByIp);
  for (const s of filterByIp.data) {
    TestValidator.equals("filter ip")(s.ip)(sessions[2].ip);
  }

  // 5. Negative: invalid input cases
  // Negative page
  await TestValidator.httpError("negative page")(400)(() =>
    api.functional.core.sessions.patch(connection, { body: { page: -1 } })
  );
  // Invalid user_id
  await TestValidator.httpError("invalid user_id")(400)(() =>
    api.functional.core.sessions.patch(connection, { body: { user_id: "not-a-uuid" } })
  );
  // Malformed date in expires_before
  await TestValidator.httpError("invalid expires_before")(400)(() =>
    api.functional.core.sessions.patch(connection, { body: { expires_before: "invalid-date" } })
  );
  // Malformed IP
  await TestValidator.httpError("invalid ip")(400)(() =>
    api.functional.core.sessions.patch(connection, { body: { ip: "invalid-ip-%%" } })
  );
}

