import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";

/**
 * Test session update functionality with valid, invalid, and not-found scenarios.
 *
 * This test ensures that session metadata can be updated, validation is enforced on bad input,
 * and correct errors are thrown for nonexistent session IDs.
 *
 * 1. Create a valid session (POST /core/sessions).
 * 2. Update the session metadata (PUT /core/sessions/{id}) and check fields are changed.
 * 3. Attempt to update with invalid data and expect validation failure.
 * 4. Attempt to update a nonexistent session ID and expect not-found error.
 */
export async function test_api_session_update_with_valid_invalid_and_nonexistent_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a session
  const sessionInput: ISession.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    token: "tok-" + Math.random().toString(36).slice(2),
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
    device_fingerprint: "device-" + Math.random().toString(36),
    ip: "192.168.1.100",
  };
  const created: ISession = await api.functional.core.sessions.post(connection, {
    body: sessionInput,
  });
  typia.assert(created);

  // 2. Update the session metadata: new expiry, new device
  const updateData: ISession.IUpdate = {
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString(),
    device_fingerprint: "new-device-" + Math.random().toString(36),
    ip: "10.0.0.99",
    revoked_at: null,
  };
  const updated: ISession = await api.functional.core.sessions.putById(
    connection,
    {
      id: created.id,
      body: updateData,
    },
  );
  typia.assert(updated);
  TestValidator.equals("session.id should match")(created.id)(updated.id);
  TestValidator.equals("user_id should remain unchanged")(created.user_id)(updated.user_id);
  TestValidator.equals("expires_at changed")(updateData.expires_at)(updated.expires_at);
  TestValidator.equals("device_fingerprint changed")(updateData.device_fingerprint)(updated.device_fingerprint);
  TestValidator.equals("ip changed")(updateData.ip)(updated.ip);

  // 3. Attempt to update with invalid data (invalid date format)
  await TestValidator.error("invalid expires_at format should cause error")(() =>
    api.functional.core.sessions.putById(connection, {
      id: created.id,
      body: { expires_at: "not-a-date" as any },
    }),
  );

  // 4. Attempt to update nonexistent session
  await TestValidator.httpError("not found")(404)(() =>
    api.functional.core.sessions.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateData,
    }),
  );
}

