/**
 * Test deletion (revocation) of user sessions, covering both successful and error scenarios.
 *
 * This test validates that:
 * 1. A session can be properly created and deleted by its ID.
 * 2. Deleting a session that does not exist results in an appropriate error.
 * 3. Attempting to delete the same session twice produces correct idempotency or error.
 *
 * Detailed Steps:
 * 1. Create a new session using /core/sessions POST.
 * 2. Assert structure and content of the created session.
 * 3. Delete the session by its ID.
 * 4. Assert that ICoreSession.IDeleteResult reports success and correct IDs/timestamp.
 * 5. Attempt to delete the same session again and validate error/idempotency policy.
 * 6. Attempt to delete a wholly non-existent session and verify error response.
 */
export async function test_api_session_delete_and_error_cases(connection: api.IConnection): Promise<void> {
    // 1. Create a session to delete
    const newSession: ISession = await api.functional.core.sessions.post(connection, {
        body: typia.random<ISession.ICreate>(),
    });
    typia.assert(newSession);

    // 2. Delete the session just created
