import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";
import { IPageICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreLocale";
import typia from "typia";

/**
 * E2E: Validates locale list pagination and filtering scenarios.
 *
 * This test ensures that locales can be listed with correct pagination,
 * search, and error behaviors. Locales must be created first, then the test validates
 * list operations with/without filtering, verifies paging metadata, checks for correct inclusion/exclusion,
 * and confirms proper error handling for invalid pagination inputs.
 *
 * 1. Create multiple locale entries for a diverse set of language/region codes.
 * 2. List all locales without filters (baseline check).
 * 3. List locales using pagination (limit, page) and verify correct slices per page.
 * 4. List with a search filter (partial code substring) and verify matched records only.
 * 5. List with a name-based search and verify expected results.
 * 6. Attempt to fetch with invalid page/limit and validate proper error response.
 */
export async function test_api_locale_list_locales_with_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create several distinct locales
  const locales: ICoreLocale[] = [];
  const toCreate = [
    { code: "en-US", name: "English (United States)" },
    { code: "ko-KR", name: "Korean (Korea)" },
    { code: "ja-JP", name: "Japanese (Japan)" },
    { code: "fr-FR", name: "French (France)" },
    { code: "es-ES", name: "Spanish (Spain)" },
  ];
  for (const locale of toCreate) {
    const created: ICoreLocale = await api.functional.core.locales.post(
      connection,
      {
        body: locale satisfies ICoreLocale.ICreate,
      },
    );
    typia.assert(created);
    locales.push(created);
  }

  // 2. List all locales, verify all created are present
  const listAll: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: { limit: 100 },
    },
  );
  typia.assert(listAll);
  for (const locale of toCreate) {
    TestValidator.equals(locale.code)(!!listAll.data.find(l => l.code === locale.code));
    TestValidator.equals(locale.name)(!!listAll.data.find(l => l.name === locale.name));
  }

  // 3. Paging: page size 2, get first page
  const page1: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      },
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 count")(2)(page1.data.length);
  TestValidator.equals("page 1 current")(1)(page1.pagination.current);

  //    Get second page
  const page2: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: {
        limit: 2,
        page: 2,
      },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 count")(2)(page2.data.length);
  TestValidator.equals("page 2 current")(2)(page2.pagination.current);

  //    Get third page
  const page3: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: {
        limit: 2,
        page: 3,
      },
    },
  );
  typia.assert(page3);
  // There should be only 1 record left on third page (5 total, 2 per page => pages: 3)
  TestValidator.equals("page 3 count")(1)(page3.data.length);
  TestValidator.equals("page 3 current")(3)(page3.pagination.current);

  // 4. Filter: search by code substring ("en") 
  const searchEn: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: { search: "en" },
    },
  );
  typia.assert(searchEn);
  TestValidator.equals("code substring: en")(true)(!!searchEn.data.find(l => l.code === "en-US"));
  TestValidator.equals("no unrelated codes")(false)(searchEn.data.some(l => l.code === "ko-KR"));

  // 5. Filter: search by name substring ("French")
  const searchFr: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    {
      body: { search: "French" },
    },
  );
  typia.assert(searchFr);
  TestValidator.equals("name substring: French")(true)(!!searchFr.data.find(l => l.name === "French (France)"));
  TestValidator.equals("no unrelated names")(false)(searchFr.data.some(l => l.name === "Korean (Korea)"));

  // 6. Attempt to fetch with invalid page/limit (negative, zero, excessively large)
  await TestValidator.httpError("negative page")(400)(() =>
    api.functional.core.locales.patch(connection, { body: { limit: 2, page: -1 } })
  );
  await TestValidator.httpError("zero limit")(400)(() =>
    api.functional.core.locales.patch(connection, { body: { limit: 0, page: 1 } })
  );
  await TestValidator.httpError("excessively large page")(400)(() =>
    api.functional.core.locales.patch(connection, { body: { limit: 2, page: 9999 } })
  );
}

