/**
 * Validates creation of a new locale and related error scenarios.
 *
 * This test covers the following:
 * 1. Successfully create a locale with valid BCP 47 code and name
 * 2. Attempt creation with missing required fields (code or name)
 * 3. Attempt creation with invalid (malformed) locale code
 * 4. Attempt creation of a duplicate locale code (should fail)
 *
 * Why this matters:
 * Locale entries are critical for proper i18n and UI localization. Enforcing validation and unique codes protects user experience and prevents data integrity issues in downstream logic.
 * All inputs must conform to BCP 47, and duplicate codes should be impossible to create.
 *
 * Stepwise procedure:
 * 1. Create a locale with a unique, valid code and name
 *    - Assert success, type correctness, field values
 * 2. Try creating with empty code or name (missing fields)
 *    - Expect 400/422 error (validation failure)
 * 3. Try creating with an invalid (malformed) code format
 *    - Expect 400 error (validation failure)
 * 4. Try creating with a code already used in step 1
 *    - Expect 409 error (uniqueness constraint)
 */
export async function test_api_locale_create_with_valid_invalid_and_duplicate_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Successfully create a locale
  const uniqueCode = `fr-CA-${Math.random().toString(36).substr(2, 8)}`;
  const localeName = "French (Canada)";
  const payload: ICoreLocale.ICreate = {
    code: uniqueCode,
    name: localeName,
  };
