  await TestValidator.httpError("missing name")(400)(() =>
    api.functional.core.locales.post(connection, {
      body: { code: "it-IT" } as any,
    }),
  );

  // 3. Attempt creation with invalid code format
  await TestValidator.httpError("invalid code format")(400)(() =>
    api.functional.core.locales.post(connection, {
      body: { code: "INVALID_CODE", name: "Some language" },
    }),
  );

  // 4. Attempt to create duplicate locale code
  await TestValidator.httpError("duplicate code")(409)(() =>
    api.functional.core.locales.post(connection, {
      body: { code: uniqueCode, name: "Another Name" },
    }),
  );
}

