import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewMedia";

/**
 * Validate soft-deletion (archival) of review media entries and proper error handling for repeated and invalid deletes.
 *
 * This test ensures that review media can be soft-deleted (archived, but never fully erased), and correct errors are returned on repeated or invalid deletes, fulfilling all audit, compliance, and evidence preservation policies.
 *
 * Steps:
 * 1. Create a review media entry via POST /communicationReview/reviewMedia.
 * 2. Soft-delete (archive) it via DELETE /communicationReview/reviewMedia/:id. Assert the returned object
 *    is present (not physically removed).
 * 3. Attempt to soft-delete the same ID again. Assert appropriate error (404 or business error) is returned.
 * 4. Attempt to soft-delete a random, non-existent review media ID. Expect 404 error and assert response.
 */
export async function test_api_review_media_soft_delete_and_error_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a review media entry
  const createInput: IReviewMedia.ICreate = {
    review_id: "11111111-1111-4111-8111-111111111111", // Use a plausible valid UUID for referential integrity
    media_type: "image",
    uri: "https://cdn.example.com/review_assets/test_image.png",
