import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewModeration";
import { IPageIReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReviewModeration";
import typia from "typia";

/**
 * List review moderation records with filters and pagination and validate correct system response.
 *
 * This test ensures that:
 * - Listing with no filters returns all records (paginated)
 * - Filtering by review_id, moderator_user_id, or action_type returns only matching records
 * - Filtering by created_at_range works for matched and unmatched queries
 * - Pagination (limit, page) restricts the dataset and metadata appropriately
 * - Requests for out-of-bounds pages return empty data
 * - Type assertions and data validation are performed for all responses
 *
 * Steps:
 * 1. Create multiple review moderation entries with diverse review_id, moderator_user_id, and action_type values (remove, restore, flag, etc.)
 * 2. List (PATCH) with no filters, validate that all created records are returned in paginated format
 * 3. Filter by review_id, validate only relevant records are returned
 * 4. Filter by moderator_user_id, validate only relevant records are returned
 * 5. Filter by action_type, validate only relevant records are returned
 * 6. Filter by created_at_range in the future (no records), and today (matches)
 * 7. Filter with mismatching review_id (expect 0 results)
 * 8. Paginate with limit lower than total, check limited data/page metadata
 * 9. Request page beyond last page, expect empty data
 * 10. Assert types for all outputs and check actual data match expected subset
 */
export async function test_api_communication_review_list_review_moderations_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create diverse moderation records
  const now = new Date();
  const reviewIds = [
    crypto.randomUUID(),
    crypto.randomUUID(),
  ];
  const moderatorIds = [
    crypto.randomUUID(),
    crypto.randomUUID(),
  ];
  const actionTypes = ["remove", "restore", "flag"];

  const entries: IReviewModeration[] = [];
  // Three records per review-moderator combination
  for (let i = 0; i < reviewIds.length; ++i) {
    for (let j = 0; j < moderatorIds.length; ++j) {
      for (let k = 0; k < actionTypes.length; ++k) {
        const moderation: IReviewModeration =
          await api.functional.communicationReview.reviewModerations.post(
            connection,
            {
              body: {
                review_id: reviewIds[i],
                moderator_user_id: moderatorIds[j],
                action_type: actionTypes[k],
                rationale: `Rationale ${i}${j}${k}`,
              } satisfies IReviewModeration.ICreate,
            }
          );
        typia.assert(moderation);
        entries.push(moderation);
      }
    }
  }
  // At this point, entries length = 2 reviews x 2 moderators x 3 actions = 12

  // 2. List with no filters (should get all entries paginated)
  const listAll: IPageIReviewModeration = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {}, // no filters
    },
  );
  typia.assert(listAll);
  TestValidator.equals("records count -- all")(entries.length)(listAll.pagination.records);
  // Disregard page,limit - default assumed
  TestValidator.equals("data count -- all")(entries.length)(listAll.data.length);
  // Type check on all
  for (const record of listAll.data) typia.assert(record);

  // Helper: filter expected records by criteria
  const filterExpected = (f: Partial<{review_id: string, moderator_user_id: string, action_type: string}>) =>
    entries.filter(
      r => (f.review_id ? r.review_id === f.review_id : true) &&
           (f.moderator_user_id ? r.moderator_user_id === f.moderator_user_id : true) &&
           (f.action_type ? r.action_type === f.action_type : true),
    );

  // 3. Filter by review_id
  const reviewIdFilt = reviewIds[0];
  const listByReview: IPageIReviewModeration = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        review_id: reviewIdFilt,
      },
    },
  );
  typia.assert(listByReview);
  const expectedReviewList = filterExpected({review_id: reviewIdFilt});
  TestValidator.equals("review_id filtered count")(expectedReviewList.length)(listByReview.data.length);
  for (const record of listByReview.data) {
    typia.assert(record);
    TestValidator.equals("match review_id")(reviewIdFilt)(record.review_id);
  }

  // 4. Filter by moderator_user_id
  const moderatorIdFilt = moderatorIds[1];
  const listByModerator = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        moderator_user_id: moderatorIdFilt,
      },
    },
  );
  typia.assert(listByModerator);
  const expectedModeratorList = filterExpected({moderator_user_id: moderatorIdFilt});
  TestValidator.equals("moderator filtered count")(expectedModeratorList.length)(listByModerator.data.length);
  for (const record of listByModerator.data) {
    typia.assert(record);
    TestValidator.equals("match moderator")(moderatorIdFilt)(record.moderator_user_id);
  }

  // 5. Filter by action_type
  const actionTypeFilt = actionTypes[2];
  const listByActionType = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        action_type: actionTypeFilt,
      },
    },
  );
  typia.assert(listByActionType);
  const expectedActionList = filterExpected({action_type: actionTypeFilt});
  TestValidator.equals("action_type filtered count")(expectedActionList.length)(listByActionType.data.length);
  for (const record of listByActionType.data) {
    typia.assert(record);
    TestValidator.equals("match action_type")(actionTypeFilt)(record.action_type);
  }

  // 6. Filter by created_at_range (future - expect none, now - expect some)
  // 6.1. Future window
  const futureFrom = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
  const listFuture = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        created_at_range: {
          from: futureFrom,
          to: new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString(),
        },
      },
    },
  );
  typia.assert(listFuture);
  TestValidator.equals("future range count")(0)(listFuture.data.length);
  TestValidator.equals("future records")(0)(listFuture.pagination.records);

  // 6.2. Current window (should match all entries; sloppy but should suffice)
  const windowFrom = new Date(now.getTime() - (1 * 60 * 1000)).toISOString();
  const windowTo = new Date(now.getTime() + (5 * 60 * 1000)).toISOString();
  const listWindow = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        created_at_range: {
          from: windowFrom,
          to: windowTo,
        },
      },
    },
  );
  typia.assert(listWindow);
  // Lax test: at least some data returned
  TestValidator.equals("current window nonzero")(entries.length)(listWindow.data.length);

  // 7. Mismatching review_id (expect 0 results)
  const listNoResult = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        review_id: crypto.randomUUID(),
      },
    },
  );
  typia.assert(listNoResult);
  TestValidator.equals("no match")(0)(listNoResult.data.length);
  TestValidator.equals("no match records")(0)(listNoResult.pagination.records);

  // 8. Pagination: custom limit < total entry count
  const pageLimit = 5;
  const paged = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        // Nothing but will be limited by page size (assume system default is larger than 5)
        // If not, adjust as needed.
        limit: pageLimit,
      } as any, // patched -- structure does not support, but server may accept extra field
    },
  );
  typia.assert(paged);
  TestValidator.equals("paged count")(Math.min(entries.length, pageLimit))(paged.data.length);

  // 9. Pagination: request past last page
  const tooBigPageNum = 9999;
  const pagedTooFar = await api.functional.communicationReview.reviewModerations.patch(
    connection,
    {
      body: {
        page: tooBigPageNum,
      } as any, // as above: assuming page param is accepted
    },
  );
  typia.assert(pagedTooFar);
  TestValidator.equals("paged past end empty")(0)(pagedTooFar.data.length);

  // 10. All types and key logic already asserted above.
}

