import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewSentiment";
import { IPageIReviewSentiment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReviewSentiment";

/**
 * List review sentiment analysis records with various filters and pagination.
 *
 * This test validates the /communicationReview/reviewSentiments PATCH endpoint's support for:
 *   - Correct pagination structure and accuracy (current, limit, records, pages).
 *   - Advanced search/filtering using review_id, ai_model_version_id, sentiment, score range, and analyzed_at ranges.
 *   - Edge cases such as no matching results and requesting out-of-bounds pages (e.g., page > total pages).
 *
 * Steps:
 * 1. Create multiple review sentiment entries with varying review_id, ai_model_version_id, sentiment, score, and analyzed_at fields.
 * 2. Retrieve first page using default pagination. Validate response structure, pagination, and all returned entries exist in created set.
 * 3. Query with custom limit and specific page number. Check slicing is correct and response matches expectations.
 * 4. Use filters (review_id, ai_model_version_id, sentiment, score_min, score_max, analyzed_at_from, analyzed_at_to) to verify only matching records are returned.
 * 5. Query with filters that should match no records; expect empty data array and valid pagination fields.
 * 6. Query with out-of-bounds page; expect empty or correctly handled data, consistent pagination meta.
 * 7. For each response, assert type correctness and filtering accuracy.
 * 8. Confirm total records/pages in response match filter and data counts.
 */
export async function test_api_review_sentiment_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create test records
  const baseTime = new Date();
  const sentiments = ["positive", "negative", "neutral"];
  const reviewIds = [typia.random<string>(), typia.random<string>()];
  const modelIds = [typia.random<string>(), typia.random<string>()];

  const createdRecords: IReviewSentiment[] = [];
  for (let i = 0; i < 8; ++i) {
    const rec: IReviewSentiment = await api.functional.communicationReview.reviewSentiments.post(connection, {
      body: {
        review_id: reviewIds[i % reviewIds.length],
        ai_model_version_id: modelIds[i % modelIds.length],
        sentiment: sentiments[i % sentiments.length],
        score: 0.6 + 0.1 * i,
        analyzed_at: new Date(baseTime.getTime() + i * 1_000).toISOString(),
      } satisfies IReviewSentiment.ICreate,
    });
    typia.assert(rec);
    createdRecords.push(rec);
  }

  // 2. Basic pagination test
  let resp: IPageIReviewSentiment = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: {},
  });
  typia.assert(resp);
  TestValidator.equals("records length")(createdRecords.length)(resp.pagination.records);
  TestValidator.equals("data count")(createdRecords.length <= resp.pagination.limit ? createdRecords.length : resp.pagination.limit)(resp.data.length);
  for (const r of resp.data) typia.assert(r);

  // 3. Query with custom limit and page
  resp = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { limit: 3, page: 2 },
  });
  typia.assert(resp);
  TestValidator.equals("limit")(3)(resp.pagination.limit);
  TestValidator.equals("page")(2)(resp.pagination.current);
  TestValidator.equals("data on page 2")(
    Math.max(0, createdRecords.length - 3)
  )(resp.data.length);
  resp.data.forEach((r) => typia.assert(r));

  // 4. Filter by review_id, ai_model_version_id, sentiment, score
  const filter = {
    review_id: reviewIds[0],
    ai_model_version_id: modelIds[1],
    sentiment: "positive",
    score_min: 0.7,
    score_max: 1.0,
    analyzed_at_from: new Date(baseTime.getTime()).toISOString(),
    analyzed_at_to: new Date(baseTime.getTime() + 10_000).toISOString(),
  } satisfies IReviewSentiment.IRequest;
  resp = await api.functional.communicationReview.reviewSentiments.patch(connection, { body: filter });
  typia.assert(resp);
  for (const r of resp.data) {
    typia.assert(r);
    TestValidator.equals("review_id")(reviewIds[0])(r.review_id);
    TestValidator.equals("ai_model_version_id")(modelIds[1])(r.ai_model_version_id);
    TestValidator.equals("sentiment")("positive")(r.sentiment);
    TestValidator.equals("score meets min")(true)(r.score >= 0.7);
    TestValidator.equals("score meets max")(true)(r.score <= 1.0);
    TestValidator.equals("analyzed_at range")(
      true
    )(
      new Date(r.analyzed_at) >= new Date(filter.analyzed_at_from!) &&
      new Date(r.analyzed_at) <= new Date(filter.analyzed_at_to!)
    );
  }

  // 5. Edge: Empty result
  resp = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { sentiment: "nonexistent" },
  });
  typia.assert(resp);
  TestValidator.equals("empty data")(0)(resp.data.length);

  // 6. Out-of-bounds page
  resp = await api.functional.communicationReview.reviewSentiments.patch(connection, {
    body: { page: 1000 },
  });
  typia.assert(resp);
  TestValidator.equals("out-of-bounds data")(0)(resp.data.length);
}

