import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { ISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ISentimentAnalysisLog";
import { IPageISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISentimentAnalysisLog";

/**
 * List and search sentiment analysis log entries with various filters and paginations.
 *
 * This test validates the log listing functionality under various filter and pagination conditions, ensuring compliance, audit, and analytic workflows are robust.
 * It covers filtering by model_version, review_id, input_match, and time ranges, as well as pagination behavior including zero results and over-paging.
 *
 * Test process:
 * 1. Create several sentiment analysis log records with unique/overlapping test data.
 * 2. Search by model_version; expect only relevant logs returned.
 * 3. Filter by review_id; verify result accuracy.
 * 4. Filter by time_from/time_to using distinct analyzed_at.
 * 5. Filter with non-existent (random) input_match; expect zero results.
 * 6. Use pagination (limit=2); cycle through pages, confirm page/record counts and correct data on each page.
 * 7. Use input_match for partial matching against raw_input.
 * 8. Confirm returned data and pagination metadata with typia.assert and structural validation.
 * 9. Confirm excessive page requests yield empty result data (data.length===0).
 */
export async function test_api_sentiment_analysis_log_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create several sentiment analysis log entries
  const baseReviewId = typia.random<string & typia.tags.Format<"uuid">>();
  const altReviewId = typia.random<string & typia.tags.Format<"uuid">>();
  const versionA = "model-vA";
  const versionB = "model-vB";
  const now = new Date();
  const logs: ISentimentAnalysisLog[] = [];
  // Distinct test data
  for (let i = 0; i < 5; ++i) {
    const entry: ISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.post(connection, {
      body: {
        review_id: i < 3 ? baseReviewId : altReviewId,
        ai_model_version_id: typia.random<string & typia.tags.Format<"uuid">>(),
        model_version: i < 3 ? versionA : versionB,
        raw_input: `input_text_${i}`,
        output: `output_text_${i}`,
        analyzed_at: new Date(now.getTime() - (4 - i)*1000).toISOString(),
      } satisfies ISentimentAnalysisLog.ICreate,
    });
    typia.assert(entry);
    logs.push(entry);
  }

  // Ref: [0,1,2]: versionA, baseReviewId; [3,4]: versionB, altReviewId
  // 2. Search by model_version = versionA
  {
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { model_version: versionA },
    });
    typia.assert(output);
    output.data.forEach(record => TestValidator.equals("model_version")(versionA)(record.model_version));
  }
  // 3. Filter by review_id (use altReviewId)
  {
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { review_id: altReviewId },
    });
    typia.assert(output);
    output.data.forEach(record => TestValidator.equals("review_id")(altReviewId)(record.review_id));
  }
  // 4. Filter by time range
  {
    // time_from just after 0th entry
    const anchorEntry = logs[1];
    const laterEntries = logs.filter(l => l.analyzed_at >= anchorEntry.analyzed_at);
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { time_from: anchorEntry.analyzed_at },
    });
    typia.assert(output);
    TestValidator.equals("filtered by time_from")(output.data.length)(laterEntries.length);
    output.data.forEach(r => TestValidator.equals("time_from-ok")(true)(r.analyzed_at >= anchorEntry.analyzed_at));
  }
  // 5. Filter with non-match (should return zero)
  {
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { input_match: "no-matching-input-zzz" },
    });
    typia.assert(output);
    TestValidator.equals("no result from random input_match")(output.data.length)(0);
  }
  // 6. Pagination: limit=2, cycle through pages
  {
    const limit = 2;
    let page = 1;
    let seenIds: Set<string> = new Set();
    while (true) {
      const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
        body: { limit, page },
      });
      typia.assert(output);
      if (output.data.length === 0) {
        // Reached beyond available pages
        TestValidator.equals("pagination end: empty")(output.data.length)(0);
        break;
      }
      // Aggregating IDs
      output.data.forEach(r => seenIds.add(r.id));
      // Check metadata
      TestValidator.equals("pagination meta: page")(page)(output.pagination.current);
      TestValidator.equals("pagination meta: limit")(limit)(output.pagination.limit);
      // Records/paging
      TestValidator.equals("pagination sum not less than so far")(seenIds.size <= output.pagination.records)(true);
      ++page;
    }
  }
  // 7. input_match: partial text
  {
    const partial = "input_text_2";
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { input_match: partial },
    });
    typia.assert(output);
    output.data.forEach(r => TestValidator.equals("partial raw_input match")(true)(r.raw_input.includes(partial)));
  }
  // 8. Confirm page result/count metadata
  {
    const output: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(connection, {
      body: { },
    });
    typia.assert(output);
    TestValidator.equals("records meta")(logs.length)(output.pagination.records);
    // pages calculation: ceil(total / default limit); often default limit=100
    TestValidator.equals("pages meta")(output.pagination.pages >= 1)(true);
  }
}

