import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import { IFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavorite";
import { IPageIFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIFavorite";

/**
 * Test the retrieval of favorite records with various filters and pagination.
 *
 * This test verifies the full workflow and edge cases for favorites listing. It ensures
 * that query filters, combination of filters, pagination, and boundary conditions are all
 * honored, and checks that only matching favorite records are returned. It also covers
 * invalid filter criteria, requests for out-of-range pages, and empty-results scenarios.
 *
 * Steps:
 * 1. Create multiple favorite records associated with different user IDs, product IDs, and timestamps.
 * 2. Retrieve a list of favorites with a specific filter (user_id only).
 * 3. Retrieve with filter (product_id only).
 * 4. Retrieve using both filters (user_id and product_id).
 * 5. Retrieve with a created_at date range filter.
 * 6. Retrieve soft-deleted results by deleted=true.
 * 7. Paginate the results (page, limit) and verify correct slicing of records.
 * 8. Attempt retrieval with invalid filter criteria (e.g., non-existent user_id).
 * 9. Attempt retrieval for an empty-result scenario (excessive page number).
 */
export async function test_api_favorites_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple favorite records with different combinations
  const userA = typia.random<string & typia.tags.Format<"uuid">>();
  const userB = typia.random<string & typia.tags.Format<"uuid">>();
  const productX = typia.random<string & typia.tags.Format<"uuid">>();
  const productY = typia.random<string & typia.tags.Format<"uuid">>();
  const now = new Date();

  // Helper: create favorite via API
  async function createFavorite(user_id: string, product_id: string) {
    const result = await api.functional.favoritesPersonalization.favorites.post(connection, {
      body: { user_id, product_id } satisfies IFavoritesPersonalization.IFavoriteCreate,
    });
    typia.assert(result);
    return result;
  }

  // Create records with varying time for created_at range test
  const fav1 = await createFavorite(userA, productX); // t0
  await new Promise((r) => setTimeout(r, 20));
  const fav2 = await createFavorite(userA, productY); // t1
  await new Promise((r) => setTimeout(r, 20));
  const fav3 = await createFavorite(userB, productX); // t2

  // Soft-deleted record (simulate deletion by setting deleted_at in direct DB or via API if endpoint exists)
  // For test, we assume API does not expose delete so we skip this; but we show structure for completeness

  // 2. Retrieve by user_id
  let out: IPageIFavorite = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { user_id: userA } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("user_id filter count")(2)(out.data.length);
  TestValidator.equals("user_id filter matches")(true)(out.data.every((f) => f.user_id === userA));

  // 3. Retrieve by product_id
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { product_id: productX } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("product_id filter count")(2)(out.data.length);
  TestValidator.equals("product_id filter matches")(true)(out.data.every((f) => f.product_id === productX));

  // 4. Retrieve using both filters
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { user_id: userA, product_id: productX } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("user+product filter count")(1)(out.data.length);
  TestValidator.equals("user+product filter matches")(true)(out.data.every((f) => f.user_id === userA && f.product_id === productX));

  // 5. Retrieve by created_at_from/to (we use the known created_at on fav2)
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { created_at_from: fav2.created_at } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("created_at_from")(2)(out.data.length);
  TestValidator.equals("created_at_from >= fav2")(true)(out.data.every(f => f.created_at >= fav2.created_at));

  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { created_at_to: fav2.created_at } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("created_at_to")(2)(out.data.length);
  TestValidator.equals("created_at_to <= fav2")(true)(out.data.every(f => f.created_at <= fav2.created_at));

  // 6. Soft-deleted filter: should be zero as we didn't delete anything
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { deleted: true } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("deleted filter gives 0")(0)(out.data.length);

  // 7. Pagination
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 2, page: 1 } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("page 1 count")(2)(out.data.length);
  TestValidator.equals("pagination current")(1)(out.pagination.current);
  TestValidator.equals("pagination total records")(3)(out.pagination.records);
  TestValidator.equals("pagination pages")(2)(out.pagination.pages); // 3 records, 2 per page => 2 pages

  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 2, page: 2 } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("page 2 count")(1)(out.data.length);
  TestValidator.equals("pagination current")(2)(out.pagination.current);

  // 8. Invalid filter (random non-existent user_id)
  const bogus = typia.random<string & typia.tags.Format<"uuid">>();
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { user_id: bogus } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("bogus filter yields 0")(0)(out.data.length);

  // 9. Excessive page (should yield 0)
  out = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 2, page: 999 } satisfies IFavorite.IRequest,
  });
  typia.assert(out);
  TestValidator.equals("page overflow yields 0")(0)(out.data.length);
}

