/**
 * Lists bookmarks using various filters and pagination, validating correct results and response metadata.
 *
 * - Ensures listing supports all advanced filters (product, custom_folder, tag, note, created_at, deletion status)
 * - Checks correct subset selection with limit/page, and pagination metadata integrity
 * - Examines edge cases: empty results, out-of-range pages, strict filtering
 *
 * Steps:
 * 1. Create multiple bookmarks for a realistic user, varying product_id, tag, folder, note, and creation date
 * 2. List bookmarks with no filter (expect all, paginated)
 * 3. List with each filter (product_id, custom_folder, tag, note), confirm correct set
 * 4. Paginate: request second page and verify results
 * 5. List with deleted filter (simulate delete, check inclusion/exclusion)
 * 6. Out-of-range page (expect empty), very restrictive filter (expect empty)
 * 7. Assert types and pagination fields
 */
export async function test_api_favoritesPersonalization_bookmarks_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Prepare test user and product IDs
  const testUser = typia.random<string & typia.tags.Format<"uuid">>();
  const testProducts = [
    typia.random<string & typia.tags.Format<"uuid">>(),
    typia.random<string & typia.tags.Format<"uuid">>(),
    typia.random<string & typia.tags.Format<"uuid">>(),
  ];
  // Create diverse bookmarks
  const bookmarks: IFavoritesPersonalization.IBookmark[] = [];
  for (let i = 0; i < 7; ++i) {
    const b = await api.functional.favoritesPersonalization.bookmarks.post(connection, {
      body: {
        user_id: testUser,
        product_id: testProducts[i % testProducts.length],
        custom_folder: i % 2 === 0 ? `folder${i % 3}` : null,
        tag: i % 3 === 0 ? `tag${i % 2}` : null,
        note: i % 2 === 1 ? `note${i}` : null,
      } satisfies IFavoritesPersonalization.IBookmarkCreate,
    });
    typia.assert(b);
    bookmarks.push(b);
  }

  // 1. List all bookmarks (no filter, limit 3)
  let res = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: { user_id: testUser, limit: 3 } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
  });
  typia.assert(res);
  TestValidator.equals("all bookmarks, paginated count")(3)(res.data.length);
  TestValidator.equals("total bookmarks count")(bookmarks.length)(res.pagination.records);
  TestValidator.equals("pagination fields present")(true)(!!res.pagination.current && !!res.pagination.pages);

