import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * Update bookmark metadata or details by ID and confirm that updates are reflected.
 *
 * Scenarios:
 * 1. Create a new bookmark for a user and product.
 * 2. Update bookmark metadata (custom_folder, tag, note) and confirm changes.
 * 3. Attempt to update a bookmark using an invalid or deleted ID and expect a 404 error.
 * 4. Try modifying immutable fields (user_id, product_id) and verify that validation errors are returned.
 *
 * Test covers successful update, error handling for invalid/deleted IDs, and ensures immutable fields cannot be changed.
 */
export async function test_api_favoritesPersonalization_bookmarks_update_with_various_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new bookmark
  const bookmarkCreate: IFavoritesPersonalization.IBookmarkCreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    custom_folder: "wishlist",
    tag: "gifts",
    note: "Birthday gift idea",
  };
  const created: IFavoritesPersonalization.IBookmark = await api.functional.favoritesPersonalization.bookmarks.post(connection, {
    body: bookmarkCreate,
  });
  typia.assert(created);
  TestValidator.equals("user_id matches inputs")(bookmarkCreate.user_id)(created.user_id);
  TestValidator.equals("product_id matches inputs")(bookmarkCreate.product_id)(created.product_id);

  // 2. Update bookmark metadata
  const updateBody: IFavoritesPersonalization.IBookmarkUpdate = {
    custom_folder: "presents",
    tag: "special",
    note: "Anniversary present updated",
  };
  const updated: IFavoritesPersonalization.IBookmark = await api.functional.favoritesPersonalization.bookmarks.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("id unchanged after update")(created.id)(updated.id);
  TestValidator.equals("updated custom_folder")(updateBody.custom_folder)(updated.custom_folder);
  TestValidator.equals("updated tag")(updateBody.tag)(updated.tag);
  TestValidator.equals("updated note")(updateBody.note)(updated.note);
  TestValidator.equals("user_id unchanged")(created.user_id)(updated.user_id);
  TestValidator.equals("product_id unchanged")(created.product_id)(updated.product_id);

  // 3. Attempt update with invalid or deleted ID
  await TestValidator.httpError("update non-existent bookmark")(404)(() =>
    api.functional.favoritesPersonalization.bookmarks.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { custom_folder: "should fail" },
    })
  );

  // 4. Try modifying immutable fields (not accepted by API by spec, but simulate attempt)
  // Attempt to update user_id or product_id is not allowed - API does not accept these in update body
  // But if implementation ignores extra keys, this should be tested for safety.
  const forbiddenUpdate: any = {
    custom_folder: "forbidden-test",
    user_id: typia.random<string & tags.Format<"uuid">>(), // Attempted overwrite (should be ignored or error)
    product_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const forbiddenResult = await api.functional.favoritesPersonalization.bookmarks.putById(connection, {
    id: created.id,
    body: forbiddenUpdate,
  });
  typia.assert(forbiddenResult);
  // Ensure immutable fields were not changed
  TestValidator.equals("user_id remains unchanged")(created.user_id)(forbiddenResult.user_id);
  TestValidator.equals("product_id remains unchanged")(created.product_id)(forbiddenResult.product_id);
}

