 * testing multiple filter/sort options. Ensure that search parameters correctly
 * limit and order results. Include tests for empty results, boundary page
 * values, and invalid filter criteria (e.g., unrecognized filter field).
 *
 * Scenario:
 * 1. Fetch all records with no filter, verify structure and basic pagination.
 * 2. Query evidence filtered by catalog_event_id and validate results.
 * 3. Query evidence filtered by reference_uri, validate correct subset returned.
 * 4. Query by description, check filtering works as intended.
 * 5. Use created_at_from and created_at_to to restrict by creation date.
 * 6. Use pagination (page, limit) to test boundary cases (first, middle, last, overflow page).
 * 7. Query with random/invalid values and check for empty results or error handling.
 * 8. For every query, validate with typia.assert and check filter intent is held for returned data.
 */
export async function test_api_catalog_evidence_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Fetch all records (no filters)
  const all: IPageICatalogEvidence =
    await api.functional.productCatalog.catalogEvidence.patch(connection, {
      body: {} satisfies ICatalogEvidence.IRequest,
    });
  typia.assert(all);
  if (all.data && all.data.length > 0) {
    for (const record of all.data) typia.assert(record);
  }

  // Select values for next filters, if data exists
  const sample = all.data && all.data.length > 0 ? all.data[0] : undefined;

  // 2. Query by catalog_event_id
  if (sample && sample.catalog_event_id) {
    const byEvent: IPageICatalogEvidence =
      await api.functional.productCatalog.catalogEvidence.patch(connection, {
        body: { catalog_event_id: sample.catalog_event_id } satisfies ICatalogEvidence.IRequest,
      });
    typia.assert(byEvent);
    if (byEvent.data) for (const rec of byEvent.data) TestValidator.equals("catalog_event_id")(sample.catalog_event_id)(rec.catalog_event_id);
  }

  // 3. Query by reference_uri
  if (sample) {
    const byRef: IPageICatalogEvidence =
      await api.functional.productCatalog.catalogEvidence.patch(connection, {
        body: { reference_uri: sample.reference_uri } satisfies ICatalogEvidence.IRequest,
      });
    typia.assert(byRef);
    if (byRef.data) for (const rec of byRef.data) TestValidator.equals("reference_uri")(sample.reference_uri)(rec.reference_uri);
  }

  // 4. Query by description
  if (sample) {
    const byDesc: IPageICatalogEvidence =
      await api.functional.productCatalog.catalogEvidence.patch(connection, {
        body: { description: sample.description } satisfies ICatalogEvidence.IRequest,
      });
    typia.assert(byDesc);
    if (byDesc.data) for (const rec of byDesc.data) TestValidator.equals("description")(sample.description)(rec.description);
  }

  // 5. Query by creation window (created_at_from/created_at_to)
  if (sample) {
    const windowed: IPageICatalogEvidence =
      await api.functional.productCatalog.catalogEvidence.patch(connection, {
        body: {
          created_at_from: sample.created_at,
          created_at_to: sample.created_at,
        } satisfies ICatalogEvidence.IRequest,
      });
    typia.assert(windowed);
    if (windowed.data)
      for (const rec of windowed.data)
        TestValidator.equals("created_at window")(sample.created_at)(rec.created_at);
  }

  // 6. Pagination: use page and limit
  const limit = 2;
  const page1: IPageICatalogEvidence =
    await api.functional.productCatalog.catalogEvidence.patch(connection, {
      body: { page: 1, limit } satisfies ICatalogEvidence.IRequest,
    });
  typia.assert(page1);
  if (page1.pagination) {
    TestValidator.equals("limit")(limit)(page1.pagination.limit);
    TestValidator.equals("current page")(1)(page1.pagination.current);
  }

  // Try to request out-of-bounds page
  if (page1.pagination && page1.pagination.pages > 0) {
    const overflow: IPageICatalogEvidence =
      await api.functional.productCatalog.catalogEvidence.patch(connection, {
        body: {
          page: page1.pagination.pages + 1,
          limit,
        } satisfies ICatalogEvidence.IRequest,
      });
    typia.assert(overflow);
    TestValidator.equals("empty result: overflow page")([])(overflow.data ?? []);
  }

  // 7. Query with random non-existent reference_uri
  const none: IPageICatalogEvidence =
    await api.functional.productCatalog.catalogEvidence.patch(connection, {
      body: { reference_uri: "never-existent-uuid-or-uri-value-1234567890" } satisfies ICatalogEvidence.IRequest,
    });
  typia.assert(none);
  TestValidator.equals("empty result: non-existent reference_uri")([])(none.data ?? []);

  // 8. Test with malformed filter (e.g., numeric as string for page)
  // Should safely error or ignore invalid type, here simply check that query doesn't crash
  try {
    const malformed = await api.functional.productCatalog.catalogEvidence.patch(connection, {
      body: { page: "invalid-str" as any } satisfies ICatalogEvidence.IRequest,
    });
    typia.assert(malformed);
  } catch (exp) {
    // Acceptable to error on malformed input, pass
  }
}

