import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import { IPageICart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICart";
import typia from "typia";

/**
 * List carts with various pagination and filter options, confirming soft-delete handling.
 *
 * This test validates the core cart listing and search endpoint for CartOrder.cart, ensuring that filtering and pagination works and that soft-deleted carts are hidden from normal results but may be retrieved with proper admin-like filtering.
 *
 * Steps:
 * 1. Create several cart records for different users/sessions
 * 2. List all carts (no filters), verify all records are present
 * 3. List carts by user_id filter, verify correct subset
 * 4. List carts by session_id filter, verify correct subset
 * 5. Soft-delete one cart
 * 6. List carts (no filter), confirm deleted cart is absent
 * 7. List carts with deleted_at_exists=true, confirm only deleted carts
 * 8. List carts with deleted_at_exists=false, confirm only live carts
 * 9. List carts with user_id+deleted_at_exists filters, check intersection
 * 10. Query with impossible filter (e.g., wrong uuid), expect no results
 * 11. Optionally test pagination (page/limit)
 * 12. Assert types on all API outputs
 */
export async function test_api_cartOrder_cart_patch_filters_and_deleted(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create several carts for different users/sessions
  const userId1 = typia.random<string & typia.tags.Format<"uuid">>();
  const userId2 = typia.random<string & typia.tags.Format<"uuid">>();
  const sessionId1 = typia.random<string & typia.tags.Format<"uuid">>();
  const sessionId2 = typia.random<string & typia.tags.Format<"uuid">>();

  const cart1: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId1,
      session_id: sessionId1,
    } satisfies ICart.ICreate,
  });
  typia.assert(cart1);

  const cart2: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId1,
      session_id: sessionId2,
    } satisfies ICart.ICreate,
  });
  typia.assert(cart2);

  const cart3: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: {
      user_id: userId2,
      session_id: sessionId1,
    } satisfies ICart.ICreate,
  });
  typia.assert(cart3);

  // 2. List all carts (no filters), verify all
  const allCarts: IPageICart = await api.functional.cartOrder.cart.patch(
    connection,
    { body: {} satisfies ICart.IRequest },
  );
  typia.assert(allCarts);
  TestValidator.equals("all carts exist")(true)(
    [cart1.id, cart2.id, cart3.id].every(id => allCarts.data?.some(c => c.id === id))
  );

  // 3. List carts filtered by user_id
  const user1Carts: IPageICart = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { user_id: userId1 } satisfies ICart.IRequest },
  );
  typia.assert(user1Carts);
  TestValidator.equals("user_id filter")(true)(
    user1Carts.data?.every(c => c.user_id === userId1)
  );
  // userId1 owns cart1, cart2
  TestValidator.equals("user1 cart count")(2)(user1Carts.data?.length ?? 0);

  // 4. List carts filtered by session_id (sessionId1 yields cart1 and cart3)
  const session1Carts: IPageICart = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { session_id: sessionId1 } satisfies ICart.IRequest },
  );
  typia.assert(session1Carts);
  TestValidator.equals("session filter")(true)(
    session1Carts.data?.every(c => c.session_id === sessionId1)
  );
  TestValidator.equals("session1 cart count")(2)(session1Carts.data?.length ?? 0);

  // 5. Soft-delete cart2
  const delResult = await api.functional.cartOrder.cart.eraseById(connection, {
    id: cart2.id,
  });
  typia.assert(delResult);
  TestValidator.equals("deleted id match")(cart2.id)(delResult.id);

  // 6. List carts again (no filter): deleted cart should be absent
  const afterDeleteAll = await api.functional.cartOrder.cart.patch(
    connection,
    { body: {} satisfies ICart.IRequest },
  );
  typia.assert(afterDeleteAll);
  TestValidator.equals("deleted cart gone")(false)(
    afterDeleteAll.data?.some(c => c.id === cart2.id)
  );

  // 7. List carts with deleted_at_exists=true (only deleted)
  const deletedCarts = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { deleted_at_exists: true } satisfies ICart.IRequest },
  );
  typia.assert(deletedCarts);
  TestValidator.equals("deleted only list")(true)(
    deletedCarts.data?.every(c => c.deleted_at != null) ?? false
  );
  TestValidator.equals("deleted cart in deleted list")(true)(
    deletedCarts.data?.some(c => c.id === cart2.id) ?? false
  );

  // 8. List carts with deleted_at_exists=false (only live carts)
  const liveCarts = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { deleted_at_exists: false } satisfies ICart.IRequest },
  );
  typia.assert(liveCarts);
  TestValidator.equals("live only list")(true)(
    liveCarts.data?.every(c => c.deleted_at == null) ?? false
  );
  TestValidator.equals("deleted cart in live list")(false)(
    liveCarts.data?.some(c => c.id === cart2.id) ?? false
  );

  // 9. List with combined user_id + deleted_at_exists=true
  const user1Deleted = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { user_id: userId1, deleted_at_exists: true } satisfies ICart.IRequest },
  );
  typia.assert(user1Deleted);
  TestValidator.equals("user1 + deleted only")(true)(
    user1Deleted.data?.every(c => c.user_id === userId1 && c.deleted_at != null) ?? false
  );
  TestValidator.equals("user1's deleted cart present")(true)(
    user1Deleted.data?.some(c => c.id === cart2.id) ?? false
  );

  // 10. Query with impossible filter
  const none = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { user_id: typia.random<string & typia.tags.Format<"uuid">>() } satisfies ICart.IRequest },
  );
  typia.assert(none);
  TestValidator.equals("impossible filter is empty")(0)(none.data?.length ?? 0);

  // 11. Pagination check (page=1, limit=1)
  const paged = await api.functional.cartOrder.cart.patch(
    connection,
    { body: { page: 1, limit: 1 } satisfies ICart.IRequest },
  );
  typia.assert(paged);
  TestValidator.equals("pagination works")(1)(paged.data?.length ?? 0);
}

