import { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";

/**
 * Validate retrieval of a cart by ID, including error handling for invalid and deleted IDs.
 *
 * This test covers:
 * 1. Creation of a new cart to guarantee a valid retrievable id.
 * 2. Fetching the cart by its id and validating all fields per ICart DTO (including evidence timestamps).
 * 3. Attempting to fetch a cart with an invalid/random UUID and confirming correct error code (404).
 * 4. Soft-deleting the cart, checking the deleted_at field.
 * 5. Attempting to fetch the now-deleted cart, confirming error handling (404 or forbidden).
 * 6. Ensures no extra or sensitive fields are exposed according to the schema.
 */
export async function test_api_cart_get_by_id_and_validate_deleted_and_invalid_case(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create new cart
  const user_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const createInput: ICart.ICreate = {
    user_id,
    session_id: null,
  };
  const cart: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: createInput,
  });
  typia.assert(cart);
  TestValidator.equals("user_id matches")(user_id)(cart.user_id);
  TestValidator.equals("not deleted")(null)(cart.deleted_at ?? null);

  // Step 2: Fetch cart by id and validate fields
  const fetched: ICart = await api.functional.cartOrder.cart.getById(connection, {
    id: cart.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(cart.id)(fetched.id);
  TestValidator.equals("user_id matches")(cart.user_id)(fetched.user_id);
  TestValidator.equals("created_at")(cart.created_at)(fetched.created_at);
  TestValidator.equals("updated_at")(cart.updated_at)(fetched.updated_at);
  TestValidator.equals("not deleted")(null)(fetched.deleted_at ?? null);
  // Fields check: "id", "user_id", "session_id", "created_at", "updated_at", "deleted_at"
  TestValidator.object_keys(["id", "user_id", "session_id", "created_at", "updated_at", "deleted_at"])(fetched);

  // Step 3: Fetch invalid (random) id, expect error
  const invalid_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("Fetch with invalid id should 404")(404)(() =>
    api.functional.cartOrder.cart.getById(connection, {
      id: invalid_id,
    })
  );

  // Step 4: Soft-delete the cart
  const deleted: ICart.IDeleteResult = await api.functional.cartOrder.cart.eraseById(connection, {
    id: cart.id,
  });
  typia.assert(deleted);
  TestValidator.equals("id matches")(cart.id)(deleted.id);
  // deleted_at should be present + ISO string

  // Step 5: Fetch deleted cart, expect 404
  await TestValidator.httpError("Fetch of soft-deleted cart should 404")(404)(() =>
    api.functional.cartOrder.cart.getById(connection, {
      id: cart.id,
    })
  );
}

