 */
export async function test_api_cartOrder_list_orders_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple orders for distinct users/carts:
  const users = [typia.random<string>(), typia.random<string>()];
  const carts = [typia.random<string>(), typia.random<string>()];
  const createdAt = [
    new Date(Date.now() - 1000000).toISOString(),
    new Date().toISOString(),
  ];
  // Prepare order creation data
  const orders: ICartOrderOrder[] = [];
  for (let i = 0; i < 4; ++i) {
    const body = {
      user_id: users[i % 2],
      cart_id: carts[i % 2],
    } satisfies ICartOrderOrder.ICreate;
    const order = await api.functional.cartOrder.order.post(connection, { body });
    orders.push(order);
  }

  // 2. List all orders (no filters):
  const outputAll: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: {},
  });
  typia.assert(outputAll);
  TestValidator.equals("order count")(
    orders.length <= outputAll.pagination.records
  )(true);

  // 3. Filter by user_id
  const outUser: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { user_id: users[0] },
  });
  typia.assert(outUser);
  for (const ord of outUser.data) {
    TestValidator.equals("user_id matches")(ord.user_id)(users[0]);
