  // 4. Filter by cart_id
  const outCart: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { cart_id: carts[1] },
  });
  typia.assert(outCart);
  for (const ord of outCart.data) {
    TestValidator.equals("cart_id matches")(ord.cart_id)(carts[1]);
  }

  // 5. Filter by time (created_after)
  const outAfter: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { created_after: createdAt[0] },
  });
  typia.assert(outAfter);
  for (const ord of outAfter.data) {
    TestValidator.equals("created_after")(
      new Date(ord.created_at).getTime() >= new Date(createdAt[0]).getTime()
    )(true);
  }

  // 6. Pagination boundaries
  const outPaginated: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(outPaginated);
  TestValidator.equals("paginated result count")(
    outPaginated.data.length <= 2
  )(true);

  // 7. Filter by status (expect empty -- no specific status set in mock data)
  const outStatus: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { status: "_nonexistent_status_" },
  });
  typia.assert(outStatus);
  TestValidator.equals("empty result for invalid status")(outStatus.data.length)(0);

  // 8. Invalid page/limit - negative page, limit over max
  const outNeg: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { page: -5, limit: 9999 },
  });
  typia.assert(outNeg);
  // Implementation may clamp or correct invalid - check it did not fail

  // 9. Nonexistent user/cart
  const outNonexistent: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: {
      user_id: "255f7dc8-b69b-4539-8b18-ce78c449c19e",
      cart_id: "d08b02f1-3bc9-4f95-bbff-aac8dfe25280",
    },
  });
  typia.assert(outNonexistent);
  TestValidator.equals("empty data for nonexistent user/cart")(outNonexistent.data.length)(0);

  // 10. Validate type shape of all results
  for (const resp of [outputAll, outUser, outCart, outAfter, outPaginated, outStatus, outNeg, outNonexistent]) {
    typia.assert(resp);
    TestValidator.equals("has pagination")(typeof resp.pagination === "object")(true);
    TestValidator.equals("has data array")(Array.isArray(resp.data))(true);
  }
}

