import { IPageICartOrderOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICartOrderOrderItem";

/**
 * Comprehensive end-to-end test of CartOrder.order_item list (PATCH) endpoint for search, filters, pagination, and soft-deleted item handling.
 *
 * Context: Listing order item records in CartOrder environment with various filtering logic, pagination, and soft-deletion (if applicable). Ensures API contract for advanced analytics, audit chains, and robust evidence preservation.
 *
 * Stepwise process:
 * 1. Create two orders (order_id_1, order_id_2) to diversify parent linkage.
 * 2. Create three order items under order_id_1 (different product_variant_id and quantity).
 * 3. Create two more order items under order_id_2 (different product_variant_id and quantity).
 * 4. List all order items (no filter) and validate all 5 just-created items appear, page metadata is correct.
 * 5. List with order_id_1 filter, expect exactly 3 matching records (validate all belong to order_id_1).
 * 6. List with product_variant_id filter (pick one created variant), expect only correct subset.
 * 7. List with quantity_range, expect only items in specified range.
 * 8. List with added_at_range for time window (pick time bounds from created items), check returned set.
 * 9. List with empty filter object, expect all records.
 * 10. List with invalid/fake UUID (order_id/product_variant_id), expect zero results.
 * 11. (If applicable) Mark one item as soft-deleted (if SDK/API supports), then list (confirm it is hidden), and (if flag exists) list including soft-deleted, confirming hidden item reappears.
 * 12. Validate all responses using typia.assert, and use TestValidator for precise record and logic validation.
 * 13. Step through returned items and check all belong to created set and pass filter contract.
 */
export async function test_api_order_item_list_with_search_and_soft_delete_behavior(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare two synthetic orders (simulate by creating unique random UUIDs for test)
  const order_id_1: string = typia.random<string & { [Format in "uuid"]: any }>();
  const order_id_2: string = typia.random<string & { [Format in "uuid"]: any }>();

  // 2. Create five different order items (3 in first order, 2 in second)
  const now = new Date();
  // Product variants as UUIDs for distinction
  const product_variant_1 = typia.random<string & { [Format in "uuid"]: any }>();
  const product_variant_2 = typia.random<string & { [Format in "uuid"]: any }>();
  const product_variant_3 = typia.random<string & { [Format in "uuid"]: any }>();

  // Order items for first order
  const item1 = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order_id_1,
      product_variant_id: product_variant_1,
      quantity: 2,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item1);
  const item2 = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order_id_1,
      product_variant_id: product_variant_2,
      quantity: 4,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item2);
  const item3 = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order_id_1,
      product_variant_id: product_variant_3,
      quantity: 1,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item3);
  // Order items for second order
  const item4 = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order_id_2,
      product_variant_id: product_variant_1,
      quantity: 10,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item4);
  const item5 = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order_id_2,
      product_variant_id: product_variant_3,
      quantity: 3,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item5);

  // Accumulate all for later reference
  const allItems = [item1, item2, item3, item4, item5];

  // 3. Patch-list with no filter (should see all)
  const listAll = await api.functional.cartOrder.orderItem.patch(connection, {
    body: {},
  });
  typia.assert(listAll);
  TestValidator.equals("all items count")(5)(listAll.data.length);
  for (const item of allItems) {
    const found = listAll.data.find((it) => it.id === item.id);
    TestValidator.equals(`present: ${item.id}`)(item.id)(found?.id);
  }

  // 4. Filter by order_id_1: Should return only those items
  const listOrder1 = await api.functional.cartOrder.orderItem.patch(connection, {
    body: { order_id: order_id_1 },
  });
  typia.assert(listOrder1);
  TestValidator.equals("order_id_1 items")(3)(listOrder1.data.length);
  for (const res of listOrder1.data) TestValidator.equals("order_id")(order_id_1)(res.order_id);

  // 5. Filter by product_variant_1 (appears in both orders)
  const listVariant1 = await api.functional.cartOrder.orderItem.patch(connection, {
    body: { product_variant_id: product_variant_1 },
  });
  typia.assert(listVariant1);
  TestValidator.equals("product_variant_1 count")(2)(listVariant1.data.length);
  for (const res of listVariant1.data) TestValidator.equals("product_variant_id")(product_variant_1)(res.product_variant_id);

  // 6. Filter by quantity_range: 2~4 (should return items with 2 and 4)
  const listQuantity = await api.functional.cartOrder.orderItem.patch(connection, {
    body: { quantity_range: [2, 4] },
  });
  typia.assert(listQuantity);
  const expected_quantity_ids = allItems.filter(it => it.quantity >= 2 && it.quantity <= 4).map(it => it.id);
  TestValidator.equals("quantity_range count")(expected_quantity_ids.length)(listQuantity.data.length);
  for (const res of listQuantity.data) TestValidator.equals("quantity within range")(true)(res.quantity >= 2 && res.quantity <= 4);

  // 7. Filter by added_at_range (start with earliest added_at, end with now)
  // Get min/max from items
  const min_ts = allItems.reduce((min, cur) => cur.added_at < min ? cur.added_at : min, allItems[0].added_at);
  const max_ts = new Date().toISOString();
  const listAddedAt = await api.functional.cartOrder.orderItem.patch(connection, {
    body: { added_at_range: [min_ts, max_ts] },
  });
  typia.assert(listAddedAt);
  // All created within bounds
  for (const res of listAddedAt.data) {
    TestValidator.equals("added_at in range")(true)(res.added_at >= min_ts && res.added_at <= max_ts);
  }

  // 8. Empty filter object, should receive all
  const listEmpty = await api.functional.cartOrder.orderItem.patch(connection, { body: {} });
  typia.assert(listEmpty);
  TestValidator.equals("all items count, empty filter")(5)(listEmpty.data.length);

  // 9. Invalid/fake UUID
  const listInvalid = await api.functional.cartOrder.orderItem.patch(connection, { body: { order_id: "11111111-1111-1111-1111-111111111111" } });
  typia.assert(listInvalid);
  TestValidator.equals("no results for bad UUID")(0)(listInvalid.data.length);

  // 10. (If API supports soft-deletion; skipping: no DELETE or soft-delete support exposed in SDK or scenario)

  // 11. Paging metadata checks
  TestValidator.equals("records field")(5)(listAll.pagination.records);
  TestValidator.equals("pages field")(1)(listAll.pagination.pages);
}

