 * 3. Query with filter by specific order_id – only matching records expected.
 * 4. Query with filter by status_code – only matching records expected.
 * 5. Query by changed_at_range (timestamp window) covering/excluding records.
 * 6. Query with empty filter – all records paginated.
 * 7. Query with filter that gives zero results.
 * 8. Confirm returned records are sorted by changed_at ascendingly.
 *
 * This process ensures reliability of audit logs, compliance reporting, and analytics workflows that depend upon the order_status evidence chain.
 */
export async function test_api_order_status_list_with_pagination_and_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple order_status records
  const now = new Date();
  const orderIds = [
    typia.random<string>(),
    typia.random<string>(),
  ];

  const statusEvents: IOrderStatus[] = [];
  for (const [i, status_code] of ["pending", "paid", "shipped"].entries()) {
    const rec: IOrderStatus = await api.functional.cartOrder.orderStatus.post(
      connection,
      {
        body: {
          order_id: orderIds[i % orderIds.length] as string,
          status_code,
          changed_at: new Date(now.getTime() + i * 1000 * 60).toISOString(),
        } satisfies IOrderStatus.ICreate,
      },
    );
    typia.assert(rec);
    statusEvents.push(rec);
  }

  // 2. List all status records
  const allResult: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  TestValidator.equals("total records")(statusEvents.length)(allResult.data.length);

  // 3. Filter by a specific order_id
  const filteredByOrder: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: { order_id: statusEvents[0].order_id },
  });
  typia.assert(filteredByOrder);
  for (const r of filteredByOrder.data) {
    TestValidator.equals("order_id match")(statusEvents[0].order_id)(r.order_id);
  }

  // 4. Filter by a specific status_code
  const filteredByStatus: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: { status_code: statusEvents[1].status_code },
  });
  typia.assert(filteredByStatus);
  for (const r of filteredByStatus.data) {
    TestValidator.equals("status code match")(statusEvents[1].status_code)(r.status_code);
  }

  // 5. Filter by a changed_at_range
  const timeStart = statusEvents[0].changed_at;
  const timeEnd = statusEvents[2].changed_at;
  const filteredByTime: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      changed_at_range: [timeStart, timeEnd],
    },
  });
  typia.assert(filteredByTime);
  for (const r of filteredByTime.data) {
    TestValidator.equals("in range")(
      r.changed_at >= timeStart && r.changed_at <= timeEnd
    )(true);
  }

  // 6. Query with empty filter (should return all)
  const emptyFilterResult: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {},
  });
  typia.assert(emptyFilterResult);
  TestValidator.equals("all records count")(statusEvents.length)(emptyFilterResult.data.length);

  // 7. Query with filter that yields zero results
  const zeroResult: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: { order_id: "00000000-0000-0000-0000-000000000000" },
  });
  typia.assert(zeroResult);
  TestValidator.equals("zero records")(0)(zeroResult.data.length);

  // 8. Check sorting by changed_at (ascending)
  const sortedTimes = [...allResult.data].map(x => x.changed_at).sort();
  const realTimes = allResult.data.map(x => x.changed_at);
  TestValidator.equals("changed_at sorting")(sortedTimes)(realTimes);
}

