import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import { IPersonalizationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationEvent";

/**
 * Update an existing personalization event by a valid ID, changing updatable fields and verifying the change. Then attempt to update with invalid data or an invalid/non-existent ID, expecting proper error handling and no unintended updates.
 *
 * Steps:
 * 1. Create a personalization event using valid data (serves as the entity to update).
 * 2. Update the created event by its ID, only changing updatable fields: event_type, model_version, context, timestamp, product_id, and optionally recommendation_id.
 * 3. Validate that the returned updated event reflects the changes and retains original values for untouched fields.
 * 4. Attempt to update using an invalid/non-existent ID, expect error (404/400 or similar).
 * 5. Attempt to update by sending invalid data (malformed UUID or invalid timestamp/type), expect error (validation failure, typically 400).
 */
export async function test_api_personalization_event_update_with_valid_and_invalid_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a personalization event
  const initial: IFavoritesPersonalization.IPersonalizationEvent = await api.functional.favoritesPersonalization.personalizationEvents.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      recommendation_id: typia.random<string & tags.Format<"uuid">>(),
      product_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "view",
      model_version: "1.0.0",
      context: "original-request",
    } satisfies IFavoritesPersonalization.IPersonalizationEventCreate,
  });
  typia.assert(initial);

  // 2. Update the created event by its ID
  const updateBody: IPersonalizationEvent.IUpdate = {
    event_type: "click",
    model_version: "2.0.0",
    context: "user-mobile",
    timestamp: new Date().toISOString(),
    product_id: initial.product_id,
    recommendation_id: initial.recommendation_id,
  };
  const updated: IPersonalizationEvent = await api.functional.favoritesPersonalization.personalizationEvents.putById(connection, {
    id: initial.id,
    body: updateBody,
  });
  typia.assert(updated);
  // 3. Validate changes
  TestValidator.equals("event_type")(updateBody.event_type)(updated.event_type);
  TestValidator.equals("model_version")(updateBody.model_version)(updated.model_version);
  TestValidator.equals("context")(updateBody.context)(updated.context);
  TestValidator.equals("timestamp")(updateBody.timestamp)(updated.timestamp);
  TestValidator.equals("product_id")(updateBody.product_id)(updated.product_id);
  TestValidator.equals("recommendation_id")(updateBody.recommendation_id)(updated.recommendation_id);
  TestValidator.equals("user_id: should remain unchanged")(initial.user_id)(updated.user_id);

  // 4. Attempt to update using an invalid/non-existent ID
  await TestValidator.httpError("update non-existent id should fail")(404)(() =>
    api.functional.favoritesPersonalization.personalizationEvents.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    }),
  );

  // 5. Attempt invalid update (invalid UUID, malformed timestamp, etc.)
  const invalidBody: IPersonalizationEvent.IUpdate = {
    ...updateBody,
    timestamp: "not-a-date" as any, // invalid timestamp
    product_id: "not-a-uuid" as any, // invalid UUID
  };
  await TestValidator.httpError("update with invalid body should fail")(400)(() =>
