import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";
import { IPageIRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRecommendation";
import typia from "typia";

/**
 * Retrieve a paginated and filtered list of recommendations.
 *
 * This test validates correct searching, filtering, and pagination functionality for the recommendations resource.
 *
 * 1. Create multiple recommendation records with varying user_id, product_id, model_id, model_version, rationale, and times for filter variety.
 * 2. Search: Filter by user_id. Confirm only recommendations for the specific user are returned.
 * 3. Search: Filter by product_id. Confirm only relevant recommendations are returned.
 * 4. Search: Filter by model_id and model_version (combined). Results must match both filters.
 * 5. Search: Apply rationale substring filter, expect only matching records.
 * 6. Search: Use recommendation_time_from and recommendation_time_to to verify time-based filtering.
 * 7. Pagination: Use limit/offset to get data in valid segments, confirm pagination metadata (current, limit, records, pages).
 * 8. Pagination: Search with criteria for which no records should exist (expect empty data and valid pagination info).
 * 9. Type validation: Use typia.assert on all responses for type safety.
 * 10. Data validation: Use TestValidator.equals to ensure matching data/IDs as appropriate.
 */
export async function test_api_recommendation_search_and_paginate_recommendations_with_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple diverse recommendations
  const baseTime = new Date();
  const users = [typia.random<string>(), typia.random<string>()];
  const products = [typia.random<string>(), typia.random<string>()];
  const modelIds = ["gpt-rec", "bert-suggester"];
  const modelVersions = ["1.0", "2.0"];
  const rationales = ["reasoned selection", "novelty", "promotion"];
  const recommendations: IRecommendation[] = [];

  for (let i = 0; i < 5; ++i) {
    const rec = await api.functional.favoritesPersonalization.recommendations.post(connection, {
      body: {
        user_id: users[i % users.length] as any,
        product_id: products[i % products.length] as any,
        model_id: modelIds[i % modelIds.length],
        model_version: modelVersions[i % modelVersions.length],
        rationale: rationales[i % rationales.length],
        recommendation_time: new Date(baseTime.getTime() + i * 60000).toISOString(),
      } satisfies IRecommendation.ICreate,
    });
    typia.assert(rec);
    recommendations.push(rec);
  }

  // 2. Search: by user_id
  const user_id = recommendations[0].user_id;
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { user_id },
    });
    typia.assert(output);
    for (const rec of output.data) TestValidator.equals("user_id")(user_id)(rec.user_id);
  }

  // 3. Search: by product_id
  const product_id = recommendations[1].product_id;
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { product_id },
    });
    typia.assert(output);
    for (const rec of output.data) TestValidator.equals("product_id")(product_id)(rec.product_id);
  }

  // 4. Search: by model_id + model_version
  const model_id = modelIds[0], model_version = modelVersions[0];
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { model_id, model_version },
    });
    typia.assert(output);
    for (const rec of output.data) {
      TestValidator.equals("model_id")(model_id)(rec.model_id);
      TestValidator.equals("model_version")(model_version)(rec.model_version);
    }
  }

  // 5. Search: by rationale substring
  const rationale_substring = "novelty";
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { rationale: rationale_substring },
    });
    typia.assert(output);
    for (const rec of output.data) {
      if(rec.rationale !== null && rec.rationale !== undefined)
        TestValidator.equals("rationale includes")(true)(rec.rationale.includes(rationale_substring));
    }
  }

  // 6. Time range filtering
  const time_from = new Date(baseTime.getTime() + 2 * 60000).toISOString();
  const time_to = new Date(baseTime.getTime() + 4 * 60000).toISOString();
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: {
        recommendation_time_from: time_from,
        recommendation_time_to: time_to,
      },
    });
    typia.assert(output);
    for (const rec of output.data) {
      TestValidator.equals("time >= from")(true)(rec.recommendation_time >= time_from);
      TestValidator.equals("time <= to")(true)(rec.recommendation_time <= time_to);
    }
  }

  // 7. Pagination: limit/offset
  {
    const limit = 2, offset = 1;
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: { limit, offset },
    });
    typia.assert(output);
    TestValidator.equals("pagination.limit")(limit)(output.pagination.limit);
    TestValidator.equals("pagination.current")(Math.floor(offset/limit))(output.pagination.current);
    TestValidator.equals("pagination.records")(recommendations.length)(output.pagination.records);
    for(const rec of output.data) typia.assert(rec);
  }

  // 8. Pagination: empty result case
  {
    const output = await api.functional.favoritesPersonalization.recommendations.patch(connection, {
      body: {
        user_id: typia.random<string>(), // unlikely to match any created
        product_id: typia.random<string>(),
      },
    });
    typia.assert(output);
    TestValidator.equals("empty data array")([], output.data);
    TestValidator.equals("pagination.records")(0)(output.pagination.records);
  }
}

