import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";

/**
 * Test creation of recommendation records including validation and duplicate checks.
 *
 * This test verifies that new recommendation entries can be created with valid input, that validation errors are raised for missing or invalid fields, and that duplicate recommendation attempts are properly handled.
 *
 * Steps:
 * 1. Create a recommendation with valid unique data.
 * 2. Validate the response structure and property correctness.
 * 3. Negative: Try missing required fields (should fail).
 * 4. Negative: Try invalid field values (should fail).
 * 5. Edge: Try to create a duplicate (should fail or return duplicate error).
 */
export async function test_api_recommendation_creation_and_validation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a recommendation with valid data
  const validRecommendation: IRecommendation.ICreate = {
    user_id: typia.random<string & typia.tags.Format<"uuid">>(),
    product_id: typia.random<string & typia.tags.Format<"uuid">>(),
    model_id: "gpt-recsys-cf-v1",
    model_version: "20240601",
    rationale: "Recommended for you via collaborative filtering (v1) with strong user-product affinity.",
    recommendation_time: new Date().toISOString(),
  };

  const created: IRecommendation = await api.functional.favoritesPersonalization.recommendations.post(
    connection,
    { body: validRecommendation },
  );
  typia.assert(created);
  TestValidator.equals("user_id")(validRecommendation.user_id)(created.user_id);
  TestValidator.equals("product_id")(validRecommendation.product_id)(created.product_id);
  TestValidator.equals("model_id")(validRecommendation.model_id)(created.model_id);
  TestValidator.equals("model_version")(validRecommendation.model_version)(created.model_version);
  TestValidator.equals("recommendation_time")(validRecommendation.recommendation_time)(created.recommendation_time);
  TestValidator.equals("rationale")(validRecommendation.rationale)(created.rationale);
  // 'id' must also be a uuid
  expect(typeof created.id).toBe("string");
  expect(created.id).toMatch(/^([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i);

  // 2. Negative: Try missing required fields (invalidate each required field)
  const missingFields: Partial<IRecommendation.ICreate>[] = [
    { ...validRecommendation, user_id: undefined as any },
    { ...validRecommendation, product_id: undefined as any },
    { ...validRecommendation, model_id: undefined as any },
    { ...validRecommendation, model_version: undefined as any },
    { ...validRecommendation, recommendation_time: undefined as any },
  ];
  for (const body of missingFields) {
    await TestValidator.httpError("missing required field")(400)(() =>
      api.functional.favoritesPersonalization.recommendations.post(connection, { body: body as any }),
    );
  }

  // 3. Negative: Try invalid field values
  const invalids: IRecommendation.ICreate[] = [
    { ...validRecommendation, user_id: "not-a-uuid" as any },
    { ...validRecommendation, product_id: "not-a-uuid" as any },
    { ...validRecommendation, recommendation_time: "bad-timestamp" as any },
    { ...validRecommendation, model_id: "" },
    { ...validRecommendation, model_version: "" },
  ];
  for (const body of invalids) {
    await TestValidator.httpError("invalid field value")(400)(() =>
      api.functional.favoritesPersonalization.recommendations.post(connection, { body }),
    );
  }

  // 4. Edge: Try to create a duplicate (same user/product/model/recommendation_time)
  await TestValidator.httpError("duplicate recommendation")(409)(() =>
    api.functional.favoritesPersonalization.recommendations.post(connection, { body: validRecommendation }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";

/**
 * Update a recommendation record by a valid ID and test invalid updates.
 *
 * This scenario ensures the update capability for recommendation records works as expected, including proper error handling for invalid requests.
 *
 * 1. Create a new recommendation record for update testing
 * 2. Update the recommendation's metadata (model_version/rationale/time) by valid ID and verify changes are reflected
 * 3. Attempt to update using a non-existent ID and confirm an error is returned
 * 4. Attempt to update forbidden/immutable fields (user_id/product_id) and validate those are not changed or an error is thrown
 */
export async function test_api_recommendation_update_by_id_and_invalid_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a recommendation for update
  const created: IRecommendation = await api.functional.favoritesPersonalization.recommendations.post(connection, {
    body: {
      user_id: "d55a8b2d-c4a1-4952-90b6-d8b646c1b1a0",
      product_id: "e37d0f00-7651-49da-93b6-48434618abfc",
      model_id: "ai-recommender-1",
      model_version: "v1.0.0",
      rationale: "Initial test rationale",
      recommendation_time: new Date().toISOString(),
    } satisfies IRecommendation.ICreate,
  });
  typia.assert(created);

  // 2. Update the recommendation's model_version/rationale/recommendation_time
  const updatedFields = {
    model_version: "v1.0.1",
    rationale: "Updated after experiment",
    recommendation_time: new Date(Date.now() + 3600000).toISOString(),
  } satisfies IRecommendation.IUpdate;
  const updated: IRecommendation = await api.functional.favoritesPersonalization.recommendations.putById(connection, {
    id: created.id,
    body: updatedFields,
  });
  typia.assert(updated);
  TestValidator.equals("id unchanged")(created.id)(updated.id);
  TestValidator.equals("model_version updated")(updatedFields.model_version)(updated.model_version);
  TestValidator.equals("rationale updated")(updatedFields.rationale)(updated.rationale);
  TestValidator.equals("recommendation_time updated")(updatedFields.recommendation_time)(updated.recommendation_time);
  TestValidator.equals("user_id should not change")(created.user_id)(updated.user_id);
  TestValidator.equals("product_id should not change")(created.product_id)(updated.product_id);
  TestValidator.equals("model_id should not change")(created.model_id)(updated.model_id);

  // 3. Attempt to update using a non-existent ID -- should return an error (404 or similar)
  const badId = "00000000-0000-4000-8000-000000000999" as string & tags.Format<"uuid">;
  await TestValidator.httpError("update with non-existent id")(404)(() =>
    api.functional.favoritesPersonalization.recommendations.putById(connection, {
      id: badId,
      body: updatedFields,
    })
  );

  // 4. Attempt forbidden field update: user_id or product_id, which are not in IUpdate
  // This should be ignored or an error according to backend logic. We enforce the fields are unchanged.
  // This negative case uses a direct cast to include illegal fields and checks only for immutability.
  const forbiddenUpdate = {
    user_id: "99999999-aaaa-bbbb-cccc-222222222222",
    product_id: "99999999-aaaa-bbbb-cccc-222222222222",
    model_version: "v9.9.9",
  } as any;
  const illegalUpdate: IRecommendation = await api.functional.favoritesPersonalization.recommendations.putById(connection, {
    id: created.id,
    body: forbiddenUpdate,
  });
  typia.assert(illegalUpdate);
  TestValidator.equals("forbidden fields not updated")(created.user_id)(illegalUpdate.user_id);
  TestValidator.equals("forbidden fields not updated")(created.product_id)(illegalUpdate.product_id);
}

