 *
 * 1. 감사(Audit) 레코드 2개 생성 (user_id, action_type 등 속성 다르게 생성)
 * 2. 필터 없이 전체 목록 요청 – 생성된 레코드 포함 여부 검증
 * 3. user_id로 필터 요청 – 해당 user_id만 결과로 반환되는지 검증
 * 4. action_type, evidence_hash, 타임스탬프 별 개별 필터, 조합형 필터 동작 확인
 * 5. limit/offset으로 페이징 및 빈 페이지 요청 시 빈 데이터 반환 검증
 * 6. timestamp 내림차순 정렬 확인 (여러 레코드 생성 시)
 * 7. 반환 데이터 타입 검증 (typia.assert)
 * 8. TestValidator.equals로 목록 및 필터 결과 체크
 */
export async function test_api_personalization_audit_search_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 감사(Audit) 레코드 2개 생성 (user_id, action_type, evidence_hash 다르게)
  const now = new Date();
  const isoNow = now.toISOString();
  const isoPast = new Date(now.getTime() - 1000 * 60 * 30).toISOString(); // 30분 전

  const audit1Create: IPersonalizationAudit.ICreate = {
