    timestamp: isoPast,
  };
  const audit2Create: IPersonalizationAudit.ICreate = {
    user_id: typia.random<string>(),
    favorite_id: null,
    bookmark_id: null,
    recommendation_id: null,
    personalization_event_id: null,
    action_type: "REMOVE_BOOKMARK",
    evidence_hash: "evidence-hash-2-" + Math.random().toString(36).slice(2),
    timestamp: isoNow,
  };

  const audit1: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    { body: audit1Create }
  );
  typia.assert(audit1);

  const audit2: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    { body: audit2Create }
  );
  typia.assert(audit2);

  // 2. 전체 목록 조회 (필터 없음)
  const allResult: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: {} }
  );
  typia.assert(allResult);
  // 두 레코드 모두 포함되는지 확인
  TestValidator.equals("records >= 2")(true)(allResult.data.some((x) => x.id === audit1.id) && allResult.data.some((x) => x.id === audit2.id));

  // 3. user_id 필터 (audit1 기준)
  const filterByUser: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { user_id: audit1.user_id } }
  );
  typia.assert(filterByUser);
  TestValidator.equals("user_id 필터 결과")(true)(filterByUser.data.every((x) => x.user_id === audit1.user_id));

  // 4. action_type 필터 (audit2 기준)
  const filterByAction: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { action_type: audit2.action_type } }
  );
  typia.assert(filterByAction);
  TestValidator.equals("action_type 필터 결과")(true)(filterByAction.data.every((x) => x.action_type === audit2.action_type));

  // 5. 증거 해시 evidence_hash 필터 (audit1)
  const filterByHash: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { evidence_hash: audit1.evidence_hash } }
  );
  typia.assert(filterByHash);
  TestValidator.equals("evidence_hash 필터 결과")(1)(filterByHash.data.length);
  TestValidator.equals("evidence_hash 값 확인")(audit1.evidence_hash)(filterByHash.data[0]?.evidence_hash);

  // 6. 타임스탬프 필터 (timestamp_from ~ timestamp_to)
  const filterByTimestamp: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { timestamp_from: isoPast, timestamp_to: isoNow } }
  );
  typia.assert(filterByTimestamp);
  TestValidator.equals("timestamp 범위 내 존재 확인")(true)(filterByTimestamp.data.some(x => x.id === audit1.id || x.id === audit2.id));

  // 7. pagination: limit/offset (limit 1)
  const paged: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { limit: 1, offset: 0 } }
  );
  typia.assert(paged);
  TestValidator.equals("limit=1")(1)(paged.data.length);
  // limit/offset beyond: 빈 데이터
  const noDataPage: IPageIPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: { limit: 1, offset: 1000 } }
  );
  typia.assert(noDataPage);
  TestValidator.equals("빈 페이지")(0)(noDataPage.data.length);

  // 8. 정렬순: timestamp 내림차순(최신순)
  if (paged.data.length === 1 && allResult.data.length >=2 ) {
    const first = allResult.data[0];
    const second = allResult.data[1];
    if (first.timestamp < second.timestamp) {
      TestValidator.equals("timestamp 내림차순")(true)(false); // 실패일 때만 true 반환
    }
  }
}

