import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";
import typia, { tags } from "typia";

/**
 * Update a personalization audit by valid ID, and negative attempts.
 *
 * This test validates that personalization audit records can be updated only for permitted fields (action_type, evidence_hash, timestamp), and changes to immutable or non-existent records are either reflected correctly or rejected.
 *
 * Steps:
 * 1. Create a personalization audit record
 * 2. Update it by ID using a valid payload (modifying allowed fields)
 * 3. Check that only permitted fields are changed, and identity is preserved
 * 4. Try updating with an invalid payload (invalid action_type, evidence_hash, or timestamp)
 * 5. Try updating restricted fields (user_id or extra properties)
 * 6. Try updating a non-existent record (random UUID)
 * 7. Assert all success and error responses as per schema and business rules
 */
export async function test_api_personalization_audit_update_and_negative(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a personalization audit record
  const createBody: IPersonalizationAudit.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "ACTIONS",
    evidence_hash: "hash1234567890abcdef",
    timestamp: new Date().toISOString(),
    favorite_id: typia.random<string & tags.Format<"uuid">>(),
    bookmark_id: null,
    recommendation_id: null,
    personalization_event_id: null,
  };
  const created: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    { body: createBody }
  );
  typia.assert(created);
  TestValidator.equals("user_id non-mutable")(createBody.user_id)(created.user_id);

  // 2. Update it by ID with valid updatable fields
  const updateBody: IPersonalizationAudit.IUpdate = {
    action_type: "ANNOTATED",
    evidence_hash: "hashupdatedabcdef987",
    timestamp: new Date(Date.now() + 1000).toISOString(),
  };
  const updated: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.putById(
    connection,
    {
      id: created.id,
      body: updateBody,
    },
  );
  typia.assert(updated);
  TestValidator.equals("id preserved")(created.id)(updated.id);
  TestValidator.equals("action_type updated")(updateBody.action_type)(updated.action_type);
  TestValidator.equals("evidence_hash updated")(updateBody.evidence_hash)(updated.evidence_hash);
  TestValidator.equals("timestamp updated")(updateBody.timestamp)(updated.timestamp);
  TestValidator.equals("immutable user_id")(created.user_id)(updated.user_id);
  TestValidator.equals("favorite_id persists")(created.favorite_id)(updated.favorite_id);
  TestValidator.equals("bookmark_id persists")(created.bookmark_id)(updated.bookmark_id);

  // 3. Try updating with invalid/malformed data
  await TestValidator.httpError("invalid action_type")(400)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: created.id,
        body: {
          action_type: "", // Empty string validation fail
        },
      }
    )
  );
  await TestValidator.httpError("invalid timestamp")(400)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: created.id,
        body: {
          timestamp: "not-a-date",
        },
      }
    )
  );
  await TestValidator.httpError("invalid evidence_hash")(400)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: created.id,
        body: {
          evidence_hash: "", // Should be non-empty and valid in real situation
        },
      }
    )
  );

  // 4. Try forbidden/restricted field update (user_id is immutable)
  await TestValidator.httpError("forbidden user_id patch")(400)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: created.id,
        // @ts-expect-error intentional wrong input for test
        body: {
          user_id: typia.random<string & tags.Format<"uuid">>(),
        },
      }
    )
  );
  // 5. Try updating a non-existent record
  await TestValidator.httpError("update non-existent id")(404)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.putById(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: { action_type: "SHOULD_FAIL" },
      }
    )
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";

/**
 * E2E test: Archive/Delete a personalization audit record and validate error scenarios.
 *
 * This test validates the compliance-driven deletion (archival) of a personalization audit record.
 * It covers:
 *  - Creating a unique audit record as a target for archival
 *  - Deleting (archiving) the record and verifying the returned result
 *  - Verifying that the archived record is not re-deletable and that attempting a duplicate or invalid deletion returns the correct error
 *
 * Steps:
 * 1. Create a valid personalization audit record
 * 2. Archive (DELETE) the created personalization audit record by ID
 * 3. Attempt to delete (archive) the same record again—expect failure (error)
 * 4. Attempt to delete (archive) a completely invalid/nonexistent UUID—expect error
 */
export async function test_api_personalization_audit_archive_and_invalid_delete(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid personalization audit record
  const audit: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        favorite_id: null,
        bookmark_id: null,
        recommendation_id: null,
        personalization_event_id: null,
        action_type: "ACTIONS",
        evidence_hash: "evidence-hash-test",
        timestamp: new Date().toISOString(),
      } satisfies IPersonalizationAudit.ICreate,
    },
  );
  typia.assert(audit);

  // 2. Archive (DELETE) the created personalization audit record by ID
  const deleted: IPersonalizationAudit = await api.functional.favoritesPersonalization.personalizationAudits.eraseById(
    connection,
    {
      id: audit.id,
    },
  );
  typia.assert(deleted);
  TestValidator.equals("deleted audit id")(audit.id)(deleted.id);

  // 3. Attempt to delete (archive) the same record again—should fail with error
  await TestValidator.httpError("duplicate delete should fail")(404)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.eraseById(
      connection,
      {
        id: audit.id,
      },
    ),
  );

  // 4. Attempt to delete with a completely invalid UUID—should fail with error
  const invalidId = "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">;
  await TestValidator.httpError("delete non-existent audit should fail")(404)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.eraseById(
      connection,
      {
        id: invalidId,
      },
    ),
  );
}

import { TestValidator } from "@nestia/e2e";
