    }
    // 결과 반드시 1개 이상이어야만 함
    TestValidator.equals("model_type 필터 최소 1건 반환")(true)(byType.data.length >= 1);
  }

  // 4. owner_id 필터
  for (const req of createReqs) {
    const byOwner: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(connection, {
