    }
    TestValidator.equals("owner_id 필터 최소 1건 반환")(true)(byOwner.data.length >= 1);
  }

  // 5. organization_id 필터
  for (const req of createReqs) {
    const byOrg: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(connection, {
      body: { organization_id: req.organization_id },
