  if (page1.pagination.pages >= 2) {
    const page2: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(connection, {
      body: { limit: 1, page: 2 },
    });
    typia.assert(page2);
    TestValidator.equals("page2 limit 1, 데이터 길이 1")(1)(page2.data.length);
    TestValidator.equals("page2 pagination.current")(2)(page2.pagination.current);
    // 두 페이지 결과의 id 달라야 정상
    if (page1.data.length && page2.data.length) {
      TestValidator.equals("다른 페이지면 모델 id 다름")(false)(page1.data[0].id === page2.data[0].id);
    }
  }

  // 8. 빈결과(불일치)
  const neverModelName = "zzzzzzzzzzzzzzzzzzzzzzzzz";
  const emptyResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(connection, {
    body: { name: neverModelName },
  });
  typia.assert(emptyResult);
  TestValidator.equals("빈 결과 data[] 길이 0")(0)(emptyResult.data.length);
  // pagination 정상
  TestValidator.equals("emptyResult pagination.records==0")(0)(emptyResult.pagination.records);
}

