import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { v4 as uuidv4 } from "uuid";
import { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";

/**
 * Validate the creation of new AI models, including handling of malformed and duplicate data.
 *
 * This test covers the following:
 * - Creating a new AI model with valid metadata and configuration
 * - Asserting the returned model's structure and fields
 * - Attempting creation with missing and invalid data to verify validation errors
 * - Attempting to create a duplicate model to check enforcement of uniqueness constraints
 *
 * Business context: AI/ML model registries must enforce rigorous metadata and uniqueness rules.
 * Models should be atomically registered, and creation must fail gracefully on validation or duplicate issues.
 *
 * Steps:
 * 1. Prepare valid AI model create payload (random organization/owner/fields)
 * 2. Create model → Assert success response/shape
 * 3. Try to create with missing/invalid fields → Expect validation errors
 * 4. Try to create a duplicate model (same name/org) → Expect duplicate/409 error
 * 5. (Optional) Validate model appears in list (if such endpoint exists)
 */
export async function test_api_ai_model_create_valid_invalid_and_duplicate(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare valid payload (random UUIDs for org/owner, required fields)
  const organization_id = uuidv4();
  const owner_id = uuidv4();
  const validPayload: IAiModel.ICreate = {
    organization_id,
    owner_id,
    name: `Model_${Date.now()}`,
    model_type: "classification",
    description: "A sample test model",
  };

  // 2. Create model with valid data
  const model = await api.functional.advancedAI.aiModels.post(connection, {
    body: validPayload,
  });
  typia.assert(model);
  TestValidator.equals("name")(validPayload.name)(model.name);
  TestValidator.equals("organization_id")(organization_id)(model.organization_id);
  TestValidator.equals("owner_id")(owner_id)(model.owner_id);
  TestValidator.equals("model_type")("classification")(model.model_type);
  if (validPayload.description)
    TestValidator.equals("description")(validPayload.description)(model.description);

  // 3. Try to create with missing required field (omit name)
  const invalidPayload = { ...validPayload };
  delete (invalidPayload as any).name;
  await TestValidator.httpError("missing field:name")(400)(() =>
    api.functional.advancedAI.aiModels.post(connection, {
      body: invalidPayload as IAiModel.ICreate,
    }),
  );

  // 4. Try malformed type (model_type not string)
  const malformedPayload = { ...validPayload, model_type: 123 as any };
  await TestValidator.httpError("model_type: wrong type")(400)(() =>
    api.functional.advancedAI.aiModels.post(connection, {
      body: malformedPayload as IAiModel.ICreate,
    }),
  );

  // 5. Try duplicate model (same name/org/version)
  await TestValidator.httpError("duplicate model")(409)(() =>
    api.functional.advancedAI.aiModels.post(connection, {
      body: validPayload,
    }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";

/**
 * Validate AI model metadata update scenarios, both successful and erroneous.
 *
 * AI/ML 모델 메타데이터(설명, 소유자 등)를 PUT /advancedAI/aiModels/:id 로 갱신하는 여러 시나리오를 검증합니다.
 * 정상적인 업데이트 성공 케이스를 포함해, 잘못된 ID 또는 잘못된 필드 타입으로 요청했을 때 오류와 감사기록(Audit)의 트리거 여부도 함께 확인합니다.
 *
 * 절차:
 * 1. AI 모델 메타데이터를 신규로 생성한다. (POST /advancedAI/aiModels)
 * 2. 정상적인 필드 변경을 위한 PUT 업데이트 수행 (설명, 소유자 등 변경)
 *    - 응답에서 변경이 반영됐는지 확인한다.
 * 3. 존재하지 않거나 잘못된 id로 PUT 시도 → 404 등 오류 반환을 검증
 * 4. 잘못된 본문(필드명/타입 오류)으로 PUT 시도 → 400/422 등 오류 검증
 */
export async function test_update_ai_model_metadata_with_valid_and_invalid_scenarios(
  connection: api.IConnection,
): Promise<void> {
  // 1. AI 모델 생성 (정상 케이스를 위한 베이스 데이터 생성)
  const createBody: IAiModel.ICreate = {
    organization_id: typia.random<string & tags.Format<"uuid">>(),
    owner_id: typia.random<string & tags.Format<"uuid">>(),
    name: `e2e-test-model-${Date.now()}`,
    model_type: "classification",
    description: "original description",
  };
  const baseModel: IAiModel = await api.functional.advancedAI.aiModels.post(connection, { body: createBody });
  typia.assert(baseModel);

  // 2. 정상 업데이트: 설명, 소유자 필드 변경
  const updateBody: IAiModel.IUpdate = {
    description: "updated for e2e",
    name: `e2e-updated-${Date.now()}`,
    owner_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const updated: IAiModel = await api.functional.advancedAI.aiModels.putById(
    connection, { id: baseModel.id, body: updateBody }
  );
  typia.assert(updated);
  TestValidator.equals("model id should remain the same")(baseModel.id)(updated.id);
  TestValidator.equals("description updated")("updated for e2e")(updated.description!);
  TestValidator.equals("owner_id updated")(updateBody.owner_id)(updated.owner_id);
  TestValidator.equals("name updated")(updateBody.name)(updated.name);

  // 3. 오류 케이스: 존재하지 않는 ID (UUID는 랜덤, 실제 DB에는 없음)
  await TestValidator.httpError("update non-existent ai-model should fail")(404)(() =>
    api.functional.advancedAI.aiModels.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    })
  );

  // 4. 오류 케이스: 잘못된 필드 타입/미지정 필드 포함
  // @ts-expect-error: 테스트 목적의 고의적 필드오류 삽입
  const invalidBody = { ...updateBody, model_type: 123, non_existing_field: "bad" };
  await TestValidator.httpError("invalid update body triggers 400/422 error")([400, 422])(() =>
    api.functional.advancedAI.aiModels.putById(connection, {
      id: baseModel.id,
      // @ts-expect-error
      body: invalidBody,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
