/**
 * Delete an AI model by valid ID and verify it is no longer discoverable in lists, preserving audit evidence as required. 
 * Also checks idempotency and proper error handling for attempts to delete with nonexistent or already deleted model IDs.
 *
 * Test Process:
 * 1. Create a new AI model (POST /advancedAI/aiModels) to provide a target for deletion.
 * 2. Delete the created AI model using DELETE /advancedAI/aiModels/{id}. Verify correct deletion response and structure.
 * 3. Attempt to delete the same model again. Validate idempotency or appropriate error response.
 * 4. Attempt to delete a random non-existent model ID. Expect a 404 or appropriate error/idempotent response.
 * 5. (Optional) Validate that the deleted model cannot be found or re-listed, if such API exists.
 * 6. Assert appropriate types and responses at every step for end-to-end safety.
 */
export async function test_api_ai_model_delete_and_handle_nonexistent_id_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new AI model
  const aiModel: IAiModel = await api.functional.advancedAI.aiModels.post(connection, {
    body: {
      organization_id: typia.random<string & tags.Format<"uuid">>(),
      owner_id: typia.random<string & tags.Format<"uuid">>(),
      name: `AI Model to Delete ${Date.now()}`,
      model_type: "test-type",
      description: "For E2E delete test.",
    } satisfies IAiModel.ICreate,
  });
  typia.assert(aiModel);

  // 2. Delete the AI model by its ID
  const deleted: ICommon.IIdDeleted = await api.functional.advancedAI.aiModels.eraseById(connection, {
    id: aiModel.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted id")(aiModel.id)(deleted.id);
  TestValidator.equals("deletion status")("deleted")(deleted.status);
  if (deleted.deleted_at) {
    // Optionally, validate date format
    TestValidator.pass("deleted_at date format")(!!Date.parse(deleted.deleted_at));
  }

  // 3. Attempt to delete the same model again -- expect 404 or idempotency error
  await TestValidator.httpError("already deleted model")(404)(() =>
    api.functional.advancedAI.aiModels.eraseById(connection, { id: aiModel.id }),
  );

  // 4. Delete with a random UUID that should not exist
  const randomUuid = typia.random<string & tags.Format<"uuid">>() as string;
  await TestValidator.httpError("delete nonexistent model")(404)(() =>
    api.functional.advancedAI.aiModels.eraseById(connection, { id: randomUuid }),
  );
}

