import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";
import { ICommon } from "@ORGANIZATION/PROJECT-api/lib/structures/ICommon";
import typia, { tags } from "typia";

/**
 * Delete an AI model version by ID and handle edge conditions.
 *
 * 이 테스트는 고급 AI 모델 관리 시스템에서 모델 버전의 삭제 기능과 예외 상황 처리 능력을 검증합니다.
 * 모델 버전 삭제가 올바르게 적용되어 목록에서도 제거되는지, 증적/감사 대응이 적절한지 확인하며,
 * 존재하지 않는 버전에 대해 삭제 시도할 때 올바른 예외 처리가 동작하는지도 테스트합니다.
 *
 * 1. 신규 AI 모델 버전을 생성 (삭제 테스트 준비)
 * 2. 생성된 모델 버전의 ID로 삭제 요청
 * 3. 삭제 응답의 구조와 상태(id, deleted_at, status) 검증
 * 4. 무작위(존재하지 않는) UUID로 삭제 시도
 * 5. 에러 응답(예: 404 또는 주요 에러코드) 및 증적 구조 검증
 */
export async function test_api_advancedAI_aiModelVersions_delete_and_handle_edge_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. AI 모델 버전 생성
  const created: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(
    connection,
    {
      body: {
        ai_model_id: typia.random<string & tags.Format<"uuid">>(),
        version: "v1.0.0",
        version_hash: "dummy-hash-a1b2c3d4",
        artifact_url: "s3://ai-models-bucket/models/model-a/v1.0.0/weights.bin",
        framework: "PyTorch",
        metadata: JSON.stringify({ accuracy: 0.94, note: "Initial upload" }),
      } satisfies IAiModelVersion.ICreate,
    },
  );
  typia.assert(created);

  // 2. 생성된 모델 버전 삭제 요청
  const deleted: ICommon.IIdDeleted = await api.functional.advancedAI.aiModelVersions.eraseById(
    connection,
    {
      id: created.id,
    },
  );
  typia.assert(deleted);
  TestValidator.equals("deleted id")(created.id)(deleted.id);
  TestValidator.equals("delete status")("deleted")(deleted.status);

  // deleted_at은 존재, 값이 정상 date-time
  if (!deleted.deleted_at || isNaN(new Date(deleted.deleted_at).getTime())) {
    throw new Error("deleted_at 필드는 유효한 날짜-시간 문자열이어야 합니다.");
  }

  // 3. 존재하지 않는 모델 버전(무작위 UUID) 삭제 시도 (실패 케이스)
  const unknownId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("delete not found error")(404)(async () =>
    api.functional.advancedAI.aiModelVersions.eraseById(connection, { id: unknownId })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAITrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAITrainingData";
import { IPageIAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiTrainingData";
import { IAiTrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiTrainingData";
import typia from "typia";

/**
 * Validate paginated and filtered search of AI training datasets.
 *
 * This test ensures that the AI training data listing (PATCH /advancedAI/aiTrainingData) correctly implements
 * complex filter predicates, pagination, and empty result scenarios across varied dataset metadata.
 *
 * 1. Register several AI training datasets with heterogenous metadata (unique name, version, ai_model_id, hashes, etc)
 * 2. Perform paginated searches:
 *    a. No filter (should return all datasets, paginated)
 *    b. Name (exact & partial)
 *    c. Version
 *    d. ai_model_id
 *    e. schema_hash
 *    f. record_count from/to
 *    g. created_at from/to
 *    h. Pagination (page 2, small limit)
 *    i. Combination filters
 *    j. Impossible filter (should return empty)
 * 3. For each:
 *    - Assert typia.assert() passes on responses
 *    - Validate result objects match query constraints (expect subset)
 *    - Validate pagination correctness (limit respected, pages accurate)
 *    - Validate empty for no-match
 */
export async function test_api_ai_training_data_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register three distinct AI training datasets
  const now = new Date();
  const baseTime = now.toISOString();
  // Unique AI model IDs for diversity
  const modelIdA = crypto.randomUUID();
  const modelIdB = crypto.randomUUID();

  const datasetA: IAITrainingData = await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      ai_model_id: modelIdA,
      name: "dataset_a_keyword",
      version: "v1",
      source_uri: "s3://bucket/dataset_a_v1.csv",
      schema_hash: "hashA123",
      record_count: 1000,
    } satisfies IAITrainingData.ICreate,
  });
  typia.assert(datasetA);

  const datasetB: IAITrainingData = await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      ai_model_id: modelIdB,
      name: "dataset_b_foo",
      version: "v2",
      source_uri: "s3://bucket/dataset_b_v2.csv",
      schema_hash: "hashB456",
      record_count: 500,
    } satisfies IAITrainingData.ICreate,
  });
  typia.assert(datasetB);

  const datasetC: IAITrainingData = await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      ai_model_id: null,
      name: "test_c",
      version: "v3",
      source_uri: "s3://bucket/test_c_v3.csv",
      schema_hash: "hashC789",
      record_count: 10,
    } satisfies IAITrainingData.ICreate,
  });
  typia.assert(datasetC);

  // Helper: search utility
  async function search(body: IAiTrainingData.IRequest): Promise<IPageIAiTrainingData> {
    const out = await api.functional.advancedAI.aiTrainingData.patch(connection, {body});
    typia.assert(out);
    return out;
  }

  // 2a. Unfiltered search (should return all, paginated)
  {
    const resp = await search({});
    TestValidator.equals("should include datasetA")(true)(resp.data.some(d => d.id === datasetA.id));
    TestValidator.equals("should include datasetB")(true)(resp.data.some(d => d.id === datasetB.id));
    TestValidator.equals("should include datasetC")(true)(resp.data.some(d => d.id === datasetC.id));
  }
  // 2b. Name search (exact)
  {
    const resp = await search({ name: "dataset_a_keyword" });
    TestValidator.equals("only datasetA matches")(1)(resp.data.length);
    TestValidator.equals("datasetA id")(datasetA.id)(resp.data[0]?.id);
  }
  // 2b2. Partial name search (assume backend supports contains)
  {
    const resp = await search({ name: "dataset" });
    TestValidator.equals("should match A and B")(2)(resp.data.length);
    TestValidator.equals("has datasetA")(true)(resp.data.some(r => r.id === datasetA.id));
    TestValidator.equals("has datasetB")(true)(resp.data.some(r => r.id === datasetB.id));
  }
  // 2c. Version search
  {
    const resp = await search({ version: "v2" });
    TestValidator.equals("only datasetB matches")(1)(resp.data.length);
    TestValidator.equals("datasetB id")(datasetB.id)(resp.data[0]?.id);
  }
  // 2d. ai_model_id
  {
    const resp = await search({ ai_model_id: modelIdA });
    TestValidator.equals("only datasetA")(1)(resp.data.length);
    TestValidator.equals("datasetA id")(datasetA.id)(resp.data[0]?.id);
  }
  // 2e. schema_hash
  {
    const resp = await search({ schema_hash: "hashB456" });
    TestValidator.equals("only datasetB")(1)(resp.data.length);
    TestValidator.equals("datasetB id")(datasetB.id)(resp.data[0]?.id);
  }
  // 2f. record_count_from / to
  {
    const resp = await search({ record_count_from: 20 });
    TestValidator.equals("datasetA and B only")(2)(resp.data.length);
    TestValidator.equals("has A")(true)(resp.data.some(r => r.id === datasetA.id));
    TestValidator.equals("has B")(true)(resp.data.some(r => r.id === datasetB.id));
    TestValidator.equals("!has C")(false)(resp.data.some(r => r.id === datasetC.id));
  }
  {
    const resp = await search({ record_count_to: 499 });
    TestValidator.equals("only C matches")(1)(resp.data.length);
    TestValidator.equals("datasetC id")(datasetC.id)(resp.data[0]?.id);
  }
  // 2g. created_at from/to (use ISO from test registrations)
  {
    // Created_from = just before first
    const before = new Date(Date.now() - 60 * 1000).toISOString();
    const resp = await search({ created_from: before });
    // All should be present because just registered
    TestValidator.equals("all present")(true)(resp.data.length >= 3);
  }
  // 2h. Pagination (limit = 2, page = 2)
  {
    const respPg1 = await search({ limit: 2, page: 1 });
    TestValidator.equals("limit is 2")(2)(respPg1.data.length);
    if (respPg1.pagination.pages > 1) {
      const respPg2 = await search({ limit: 2, page: 2 });
      // Ensure unique, non-overlapping sets
      const idsPg1 = respPg1.data.map(x => x.id);
      const idsPg2 = respPg2.data.map(x => x.id);
      const intersect = idsPg1.filter(id => idsPg2.includes(id));
      TestValidator.equals("Pages are distinct")(0)(intersect.length);
    }
  }
  // 2i. Combination filters: name+version+model_id
  {
    const resp = await search({
      name: "dataset_a_keyword",
      version: "v1",
      ai_model_id: modelIdA,
    });
    TestValidator.equals("all fields ANDed")(1)(resp.data.length);
    TestValidator.equals("datasetA id")(datasetA.id)(resp.data[0]?.id);
  }
  // 2j. Impossible filter: schema_hash definitely not present
  {
    const resp = await search({ schema_hash: "not_a_real_hash_value" });
    TestValidator.equals("empty for impossible filter")(0)(resp.data.length);
  }
}

