import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolicy";
import { IPageIPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolicy";

/**
 * Validate policy listing, filtering, and pagination for permission policies.
 *
 * This test ensures that the policy registry can be queried/paginated/filtered in various ways, that policies are returned as expected, and that error scenarios for invalid filters are handled correctly.
 *
 * Test Steps:
 * 1. List policies with no filters; check all returned, records >= 0, paging info.
 * 2. List with a 'name' filter matching existing policy/policies; verify result subset.
 * 3. List with a filter matching no policies; expect empty data array.
 * 4. List using pagination (page/limit) and verify correct slicing and pagination metadata.
 * 5. Test 'sort_field'/'sort_direction', verify order of result.
 * 6. List with advanced filters (created_from, created_to, conditions).
 * 7. Attempt listing with invalid filters (bad date, negative limit, etc.); expect validation error.
 * 8. For all successes: assert response (IPageIPolicy), response.data[] (IPolicy), and pagination fields integrity.
 */
export async function test_api_policy_list_filter_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. List all policies
  const all: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.equals("pagination.records >= 0")(true)(all.pagination.records >= 0);
  for (const policy of all.data) typia.assert(policy);

  // 2. List with name filter matching 1+ policy (if any exists)
  let nameToTest: string | undefined = all.data.length ? all.data[0].name : undefined;
  if (nameToTest) {
    const filtered: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { name: nameToTest },
    });
    typia.assert(filtered);
    for (const policy of filtered.data) {
      typia.assert(policy);
      TestValidator.equals(`policy.name matches filter`)(nameToTest)(policy.name);
    }
  }

  // 3. List with name filter for non-existent
  const nonExistentName = "!@@doesnotexist";
  const none: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
    body: { name: nonExistentName },
  });
  typia.assert(none);
  TestValidator.equals("empty list for non-existent name")([], none.data);
  TestValidator.equals("pagination.records is 0")(0)(none.pagination.records);

  // 4. Pagination check: page=1, limit=1
  const paged: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("limit=1 length")(paged.data.length)(1);
  TestValidator.equals("pagination.limit=1")(1)(paged.pagination.limit);
  for (const policy of paged.data) typia.assert(policy);

  // 5. Sort_field/sort_direction test (only if 2+ policies exist)
  if (all.data.length > 1) {
    const asc: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { sort_field: "name", sort_direction: "asc" },
    });
    const desc: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { sort_field: "name", sort_direction: "desc" },
    });
    typia.assert(asc), typia.assert(desc);
    if (asc.data.length === desc.data.length && asc.data.length > 1) {
      const namesAsc = asc.data.map((p) => p.name).join();
      const namesDesc = desc.data.map((p) => p.name).split("").reverse().join("");
      TestValidator.equals("asc/desc produce different order")(
        false
      )(namesAsc === namesDesc);
    }
  }

  // 6. Advanced filters: created_from/created_to, conditions
  if (all.data.length) {
    const testCreated = all.data[0].created_at;
    const query: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { created_from: testCreated, created_to: testCreated },
    });
    typia.assert(query);
    for (const policy of query.data) typia.assert(policy);
  }

  // 7. Invalid filters: negative limit, bad date
  await TestValidator.httpError("negative limit error")(400)(() =>
    api.functional.securityCompliance.policy.patch(connection, { body: { limit: -1 } })
  );
  await TestValidator.httpError("bad date error")(400)(() =>
    api.functional.securityCompliance.policy.patch(connection, { body: { created_from: "not-a-date" } })
  );
}

