 * with invalid data. Also, verifies if audit trail or change evidence is produced via returned timestamps/fields.
 *
 * Steps:
 * 1. Create a new permission policy (valid initial data)
 * 2. Update some fields of the created policy with valid data and confirm changes are saved
 * 3. Try to update with an invalid/non-existent ID, expect 404 not found error
 * 4. Try to update with invalid data (e.g., empty name/conditions), expect validation error (4xx)
 */
export async function test_api_policy_update_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new permission policy
  const createInput: IPolicy.ICreate = {
    name: `POLICY_${Date.now()}`,
    conditions: JSON.stringify({ allow: true, segment: "beta-users" }),
  };
  const created: IPolicy = await api.functional.securityCompliance.policy.post(connection, {
    body: createInput,
  });
  typia.assert(created);
  TestValidator.equals("created policy name")(createInput.name)(created.name);
  TestValidator.equals("created policy conditions")(createInput.conditions)(created.conditions);

  // 2. Update some fields with valid data
  const updateInput: IPolicy.IUpdate = {
    name: createInput.name + "_EDITED",
    conditions: JSON.stringify({ allow: false, reason: "manual lock" }),
  };
