  TestValidator.not.equals("updated_at changed?")(created.created_at)(updated.created_at);
  // (If only created_at exists and no updated_at, at least created_at should change)

  // 3. Try to update with a non-existent ID (expect 404)
  const fakeId = "00000000-0000-4000-a000-000000000404" as string & tags.Format<"uuid">;
  await TestValidator.httpError("update non-existent policy")(404)(() =>
    api.functional.securityCompliance.policy.putById(connection, {
      id: fakeId,
      body: updateInput,
    })
  );

  // 4. Try to update with invalid data (empty name, empty conditions)
  await TestValidator.httpError("update with empty name")(400)(() =>
    api.functional.securityCompliance.policy.putById(connection, {
      id: created.id,
      body: {
        name: "",
        conditions: updateInput.conditions,
      },
    })
  );
  await TestValidator.httpError("update with empty conditions")(400)(() =>
    api.functional.securityCompliance.policy.putById(connection, {
      id: created.id,
      body: {
        name: updateInput.name,
        conditions: "",
      },
    })
  );
}

