import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";
import { IPageIAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAuditLog";

/**
 * Test listing and searching audit log entries with pagination and filtering.
 *
 * Validates:
 * 1. Listing all audit logs without filters returns results and correct pagination.
 * 2. Filtering by specific action, user_id, entity_type, entity_id, or time window returns only matching records.
 * 3. Pagination limit and current page (offset) are respected.
 * 4. Filtering with nonsense yields zero results.
 * 5. All response objects strictly match IPageIAuditLog and IAuditLog.
 * 6. The context field (JSON string) is valid JSON on returned records.
 */
export async function test_api_auditlog_list_with_filtering_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. List all audit logs, no filters
  const resAll: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
    body: {},
  });
  typia.assert(resAll);
  TestValidator.equals("has data")(true)(resAll.data.length > 0);
  TestValidator.equals("pagination info present")(true)(!!resAll.pagination && typeof resAll.pagination.current === "number");
  for (const log of resAll.data)
    typia.assert<IAuditLog>(log);

  // Prepare filter values if any data exists
  const sampleLog = resAll.data[0];

  // 2. Filter by action
  if (sampleLog) {
    const resAction: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
      body: { action: sampleLog.action },
    });
    typia.assert(resAction);
    for (const log of resAction.data) {
      typia.assert<IAuditLog>(log);
      TestValidator.equals("action filtering")(sampleLog.action)(log.action);
    }
  }

  // 3. Filter by user_id
  if (sampleLog?.user_id) {
    const resUser: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, { body: { actor_id: sampleLog.user_id } });
    typia.assert(resUser);
    for (const log of resUser.data) {
      typia.assert<IAuditLog>(log);
      TestValidator.equals("user_id filtering")(sampleLog.user_id)(log.user_id);
    }
  }

  // 4. Filter by entity_type and entity_id
  if (sampleLog) {
    const resEntity: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, { body: { entity_type: sampleLog.entity_type, entity_id: sampleLog.entity_id } });
    typia.assert(resEntity);
    for (const log of resEntity.data) {
      typia.assert<IAuditLog>(log);
      TestValidator.equals("entity_type")(sampleLog.entity_type)(log.entity_type);
      if (sampleLog.entity_id)
        TestValidator.equals("entity_id")(sampleLog.entity_id)(log.entity_id);
    }
  }

  // 5. Filter by time window
  if (sampleLog) {
    const from = new Date(sampleLog.created_at).toISOString();
    const resTime: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
      body: {
        time_from: from,
        time_to: from,
      },
    });
    typia.assert(resTime);
    for (const log of resTime.data) {
      typia.assert<IAuditLog>(log);
      TestValidator.equals("created_at eq")(from)(log.created_at);
    }
  }

  // 6. Test pagination limit
  const resPage: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
    body: {},
  });
  typia.assert(resPage);
  if (resPage.data.length > 1) {
    const limited: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
      body: {},
    });
    typia.assert(limited);
    TestValidator.equals("pagination count matches")(resPage.data.length)(limited.data.length);
  }

  // 7. Filter with nonsense value
  const nonsenseAction = "NO_SUCH_ACTION_TYPE_" + Math.random();
  const resNone: IPageIAuditLog = await api.functional.securityCompliance.auditLog.patch(connection, {
    body: { action: nonsenseAction },
  });
  typia.assert(resNone);
  TestValidator.equals("empty result")(0)(resNone.data.length);

  // 8. Optionally confirm context JSON: should parse
  for (const log of resAll.data) {
    try {
      if (log.context) JSON.parse(log.context);
    } catch {
      throw new Error(`Audit log id=${log.id} context is not valid JSON`);
    }
  }
}

