/**
 * Test updating an existing compliance report via PUT, with validation of:
 * - Successful update (status or published_at) for a real report
 * - 404 Not Found for non-existent report ID
 * - 400/validation error for invalid input (malformed status, bad published_at, or extra fields)
 *
 * 1. Create a new compliance report for test via POST
 * 2. Update the created report's status via PUT, validate expected changes
 * 3. Attempt update of non-existent report (random UUID), expect 404
 * 4. Attempt invalid update (empty status, invalid published_at), expect 400
 *
 * Ensures permitted fields are accepted, invalid attempts rejected,
 * and regulatory audit trace requirements are met from a business flow perspective.
 */
export async function test_api_compliance_report_update_put_scenarios(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a compliance report
  const baseCreate = {
    report_type: "GDPR_EXPORT",
    status: "pending",
    generated_at: new Date().toISOString(),
    user_id: undefined, // nullable
    organization_id: undefined,
    published_at: undefined,
  } satisfies IComplianceReport.ICreate;

  const report: IComplianceReport = await api.functional.securityCompliance.complianceReport.post(
    connection,
    { body: baseCreate }
  );
  typia.assert(report);

  // 2. Update that report's status and published_at
  const updatePayload = {
    status: "published",
    published_at: new Date().toISOString(),
  } satisfies IComplianceReport.IUpdate;
  const updated: IComplianceReport = await api.functional.securityCompliance.complianceReport.putById(
    connection,
    { id: report.id, body: updatePayload }
  );
  typia.assert(updated);
  TestValidator.equals("status updated")("published")(updated.status);
  TestValidator.equals("published_at updated")(updatePayload.published_at)(updated.published_at);

  // 3. Attempt to update a non-existent report (should 404)
  await TestValidator.httpError("non-existent report update")(404)(() =>
    api.functional.securityCompliance.complianceReport.putById(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: { status: "published" } satisfies IComplianceReport.IUpdate,
      },
    ),
  );

  // 4. Attempt update with invalid values
  // 4a. Invalid status (empty string)
  await TestValidator.httpError("empty status invalid")(400)(() =>
    api.functional.securityCompliance.complianceReport.putById(
      connection,
      {
        id: report.id,
        body: { status: "" } satisfies IComplianceReport.IUpdate,
      },
    )
  );

  // 4b. Invalid published_at (not ISO date)
  await TestValidator.httpError("invalid published_at format")(400)(() =>
    api.functional.securityCompliance.complianceReport.putById(
      connection,
      {
        id: report.id,
        body: { published_at: "not-a-date" as any } satisfies IComplianceReport.IUpdate,
      },
    )
  );

  // 4c. Extra field (should be rejected strictly)
  await TestValidator.httpError("update with extra fields")(400)(() =>
    api.functional.securityCompliance.complianceReport.putById(
      connection,
      {
        id: report.id,
        // @ts-expect-error purposely adding invalid field
        body: { status: "published", foo: "bar" } as any,
      },
    )
  );
}

