import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IDataRetention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDataRetention";

/**
 * Test creation of data retention policy and input validation.
 *
 * This test covers normal creation, field validation, and duplicate submission prevention
 * for data retention compliance policies. It ensures the endpoint properly creates valid
 * records, and enforces schema and uniqueness constraints.
 *
 * Steps:
 * 1. Prepare valid request data for all required fields (entity_type, retention_period_days, is_legal_hold). Optionally, set organization_id.
 * 2. Call the POST /securityCompliance/dataRetention API to create a policy.
 * 3. Validate response structure and field values.
 * 4. Try to create with required fields omitted, one at a time. Validate each causes an error.
 * 5. Try to create with invalid (wrong-type, out-of-range) field values, e.g., negative retention_period_days. Validate error response.
 * 6. Attempt duplicate creation with same entity_type and organization_id. Confirm duplication is not allowed.
 * 7. Optionally, try another entity_type or organization_id to confirm duplicates are specific.
 */
export async function test_api_data_retention_create_and_validate(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare valid input
  const req: IDataRetention.ICreate = {
    entity_type: "user",
    retention_period_days: 365,
    is_legal_hold: false,
    organization_id: typia.random<string>(),
  };

  // 2. Create the new policy
  const created: IDataRetention = await api.functional.securityCompliance.dataRetention.post(connection, {
    body: req,
  });
  typia.assert(created);
  TestValidator.equals("entity_type")(req.entity_type)(created.entity_type);
  TestValidator.equals("retention_period_days")(req.retention_period_days)(created.retention_period_days);
  TestValidator.equals("is_legal_hold")(req.is_legal_hold)(created.is_legal_hold);
  if (req.organization_id)
    TestValidator.equals("organization_id")(req.organization_id)(created.organization_id);

  // 3. Required field validation: try omitting each required field
  for (const field of ["entity_type", "retention_period_days", "is_legal_hold"]) {
    const body = { ...req } as Record<string, any>;
    delete body[field];
    await TestValidator.httpError(`missing required ${field}`)(400)(() =>
      api.functional.securityCompliance.dataRetention.post(connection, {
        body: body as any,
      })
    );
  }

  // 4. Invalid value checks
  // 4a. Negative retention_period_days
  await TestValidator.httpError("negative retention_period_days")(400)(() =>
    api.functional.securityCompliance.dataRetention.post(connection, {
      body: { ...req, retention_period_days: -5 },
    })
  );
  // 4b. Wrong type for entity_type
  await TestValidator.httpError("non-string entity_type")(400)(() =>
    api.functional.securityCompliance.dataRetention.post(connection, {
      body: { ...req, entity_type: 12345 } as any,
    })
  );
  // 4c. Non-boolean is_legal_hold
  await TestValidator.httpError("non-boolean is_legal_hold")(400)(() =>
    api.functional.securityCompliance.dataRetention.post(connection, {
      body: { ...req, is_legal_hold: "yes" } as any,
    })
  );
  // 4d. Bad organization_id UUID
  await TestValidator.httpError("bad uuid organization_id")(400)(() =>
    api.functional.securityCompliance.dataRetention.post(connection, {
      body: { ...req, organization_id: "not-a-uuid" },
    })
  );

  // 5. Duplicate creation attempt (same entity_type, organization_id)
  await TestValidator.httpError("duplicate policy")(409)(() =>
    api.functional.securityCompliance.dataRetention.post(connection, {
      body: req,
    })
