import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IEvidenceArchive";
import { IPageIEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEvidenceArchive";

/**
 * Search and list evidence archive records with filtering and pagination.
 *
 * This test validates that the evidence archive search endpoint correctly processes: filter criteria, date/time ranges, exact/checksum lookups, and pagination mechanics. It ensures both expected results and edge/error cases.
 *
 * 1. List all archives without filter or pagination; validate total result count and content structure.
 * 2. Apply evidence_type filter for a known value; verify filtered result integrity.
 * 3. Search using a specific checksum; require single/exact match.
 * 4. Filter by created_at window; ensure all results' timestamps are within bounds.
 * 5. Paginate with limit and page; validate pagination correctness and slice.
 * 6. Send a filter that leads to no results (non-existent value); expect zero records and valid pagination.
 * 7. Send an invalid page/limit; verify system handles error or returns empty/first page gracefully.
 * 8. typia.assert is used for all API responses; TestValidator asserts on pagination/data correctness and error scenarios.
 */
export async function test_api_evidence_archive_list_with_filter_and_pagination(
  connection: api.IConnection
): Promise<void> {
  // 1. List all archives (no filters, default pagination)
  const all: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, { body: {} });
  typia.assert(all);
  const totalRecords = all.pagination.records;
  TestValidator.equals("has total records")(true)(totalRecords > 0);

  // If no records exist, skip the rest of the steps.
  if (!all.data.length) return;
  const reference = all.data[0];

  // 2. evidence_type filter
  if (reference.evidence_type) {
    const byType: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { evidence_type: reference.evidence_type }
    });
    typia.assert(byType);
    TestValidator.equals("all evidence_type matched")(
      true
    )(byType.data.every(r => r.evidence_type === reference.evidence_type));
    TestValidator.equals("records count shrank or equal")(
      true
    )(byType.pagination.records <= totalRecords);
  }

  // 3. checksum filter
  if (reference.checksum) {
    const byChecksum: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { checksum: reference.checksum }
    });
    typia.assert(byChecksum);
    TestValidator.equals("single checksum match")(
      1
    )(byChecksum.data.length);
    TestValidator.equals("checksum accurate")(
      true
    )(byChecksum.data[0]?.checksum === reference.checksum);
  }

  // 4. created_at window
  if (reference.created_at) {
    const from = new Date(reference.created_at);
    from.setMilliseconds(0);
    const isoFrom = from.toISOString();
    const isoTo = new Date(from.getTime() + 60 * 60 * 1000).toISOString();
    const byDate: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: {
        created_at_from: isoFrom,
        created_at_to: isoTo,
      }
    });
    typia.assert(byDate);
    TestValidator.equals("all within date window")(
      true
    )(byDate.data.every(r => r.created_at >= isoFrom && r.created_at <= isoTo));
  }

  // 5. Pagination logic
  const PAGE_LIMIT = 2;
  if (all.data.length > PAGE_LIMIT) {
    const page1: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { limit: PAGE_LIMIT, page: 1 }
    });
    typia.assert(page1);
    TestValidator.equals("page 1 correct length")(
      true
    )(page1.data.length <= PAGE_LIMIT);
    const page2: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { limit: PAGE_LIMIT, page: 2 }
    });
    typia.assert(page2);
    TestValidator.equals("page 2 correct length")(
      true
    )(page2.data.length <= PAGE_LIMIT);
    // Optional: Check that page1 and page2 have different IDs if enough data exists
    if (page2.data.length > 0)
      TestValidator.equals("pagination slices differ")(
        false
      )(page1.data.some(a => page2.data.some(b => a.id === b.id)));
  }

  // 6. No results: Unlikely evidence_type
  const noResults: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { evidence_type: "NON_EXISTENT_TYPE_" + Date.now() }
  });
  typia.assert(noResults);
  TestValidator.equals("no records")(0)(noResults.data.length);

  // 7. Bad filter (invalid page/limit)
  await TestValidator.error("invalid limit")(() =>
    api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { limit: 0 }
    })
  );
  await TestValidator.error("invalid page")(() =>
    api.functional.securityCompliance.evidenceArchive.patch(connection, {
      body: { page: -1 }
    })
  );
}

