 * 4. page, limit 등 잘못된 값으로 요청시(예: 음수, 0) 에러가 반환되는지 검증
 * 5. 비어있지 않은 목록의 경우 pagination의 current/limit/pages/records가 일관적인지 확인
 * 6. 마지막 페이지, 페이지 범위를 넘는 케이스 등도 확인
 * 7. 항상 typia.assert로 결과 타입 보장, 값 비교가 필요한 경우 TestValidator.equals 활용
 */
export async function test_api_api_client_list_filter_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 기본 전체 목록 조회
  const listAll: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
    connection,
    { body: {} }
  );
  typia.assert(listAll);
  TestValidator.equals("pagination.structure")(typeof listAll.pagination === "object" && Array.isArray(listAll.data))(true);

  // 2. 조건별 필터 검색 - client_name, is_active, contact_email를 활용
  if (listAll.data.length > 0) {
    const sample = listAll.data[0];
    // client_name으로 필터
    const filteredByName: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
      connection,
      {
        body: {
          client_name: sample.client_name,
        },
      }
    );
    typia.assert(filteredByName);
    TestValidator.equals("client_name filter has item")(true)(filteredByName.data.length > 0);
    TestValidator.equals("contains sample")(true)(filteredByName.data.some(x => x.id === sample.id));

    // is_active
    const filteredByActive: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
      connection,
      {
        body: {
          is_active: sample.is_active,
        },
      }
    );
    typia.assert(filteredByActive);
    TestValidator.equals("is_active filter")(true)(filteredByActive.data.some(x => x.is_active === sample.is_active));

    // contact_email
    const filteredByEmail: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
      connection,
      {
        body: {
          contact_email: sample.contact_email,
        },
      }
    );
    typia.assert(filteredByEmail);
    TestValidator.equals("contact_email filter")(true)(filteredByEmail.data.some(x => x.contact_email === sample.contact_email));
  }

  // 3. 존재하지 않는 값으로의 검색 -> 결과가 empty array여야 함
  const noMatch: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
    connection,
    {
      body: {
        client_name: "ThisNameShouldNotExist___!__",
      },
    }
  );
  typia.assert(noMatch);
  TestValidator.equals("no-match results")(0)(noMatch.data.length);
  TestValidator.equals("no-match pagination.data type")(true)(Array.isArray(noMatch.data));

  // 4. 잘못된 page/limit 입력값 처리: -1이나 0 등은 오류여야 함
  await TestValidator.httpError("negative page")(400)(() =>
    api.functional.apiOmnichannel.apiClients.patch(connection, { body: { page: -1 } })
  );
  await TestValidator.httpError("zero limit")(400)(() =>
    api.functional.apiOmnichannel.apiClients.patch(connection, { body: { limit: 0 } })
  );

  // 5. 페이지네이션 정보 일관성 체크 (last page, page 초과 요청 등)
  if (listAll.pagination && listAll.pagination.pages > 1) {
    const lastPage: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
      connection,
      { body: { page: listAll.pagination.pages } }
    );
    typia.assert(lastPage);
    TestValidator.equals("last-page current")(listAll.pagination.pages)(lastPage.pagination.current);

    // 초과 페이지(존재하지 않는 page)
    const overPage: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(
      connection,
      { body: { page: listAll.pagination.pages + 1 } }
    );
    typia.assert(overPage);
    TestValidator.equals("over-page empty")(0)(overPage.data.length);
  }
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * Validate retrieval of API client by ID and appropriate error handling for invalid IDs.
 *
 * Scenario background: 
 *   Omnichannel API client registry is used for onboarding and platform integration. Retrieving a client by ID is a core administrative/read operation and must return the correct record, or appropriate error for invalid/nonexistent IDs. Ensures registry auditability and data consistency.
 *
 * Step-by-step process:
 * 1. Create a new API client via POST /apiOmnichannel/apiClients, with required fields populated.
 * 2. Retrieve the API client just created using GET /apiOmnichannel/apiClients/{id}. Assert all fields match expected values.
 * 3. Attempt to retrieve an API client using a random (non-existent) valid UUID. Confirm a 404 NOT FOUND is thrown.
 * 4. Attempt to retrieve using a clearly malformed (non-UUID) string. Confirm error handling (404 or validation error).
 */
export async function test_api_apiClient_get_by_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new API client for lookup
  const createInput: IApiClients.ICreate = {
    client_name: `TestClient_${Date.now()}`,
    contact_email: `e2e_${Date.now()}@wrtn.io`,
    public_key: "test_public_key_example",
    description: "API E2E test client."
  };
  const created: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: createInput satisfies IApiClients.ICreate,
  });
  typia.assert(created);
  // Confirm the minimum fields
  TestValidator.equals("client_name")(createInput.client_name)(created.client_name);
  TestValidator.equals("contact_email")(createInput.contact_email)(created.contact_email);
  TestValidator.equals("public_key")(createInput.public_key)(created.public_key);
  TestValidator.equals("description")(createInput.description)(created.description);

  // 2. Retrieve by valid ID
  const read: IApiClients = await api.functional.apiOmnichannel.apiClients.getById(connection, {
    id: created.id,
  });
  typia.assert(read);
  TestValidator.equals("id")(created.id)(read.id);
  TestValidator.equals("client_name")(created.client_name)(read.client_name);
  TestValidator.equals("contact_email")(created.contact_email)(read.contact_email);
  TestValidator.equals("public_key")(created.public_key)(read.public_key);
  TestValidator.equals("description")(created.description)(read.description);
  TestValidator.equals("is_active")(created.is_active)(read.is_active);
  TestValidator.equals("created_at")(created.created_at)(read.created_at);
  TestValidator.equals("deleted_at")(created.deleted_at ?? null)(read.deleted_at ?? null);

  // 3. Attempt fetch with random valid UUID (should 404)
  await TestValidator.httpError("get with non-existent UUID")(404)(() =>
    api.functional.apiOmnichannel.apiClients.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 4. Attempt fetch with an obviously invalid ID (should 404 or 400)
  await TestValidator.error("get with malformed id")(() =>
    api.functional.apiOmnichannel.apiClients.getById(connection, {
      id: "not-a-uuid-format" as any,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

/**
 * Validate creation of a new API client with proper required and optional fields, and check error handling on invalid inputs.
 *
 * This checks business and DB constraints for onboarding new API clients.
 * Covers success, required-field error, and unique constraint error scenarios.
 *
 * 1. Prepare valid API client creation payload (all required and optional fields)
 * 2. Create client (POST /apiOmnichannel/apiClients)
 * 3. Validate: Response matches IApiClients, and round-trip integrity of values
 * 4. Attempt creation with missing required fields (client_name, contact_email): expect validation error
 * 5. Attempt creation with duplicate client_name or contact_email: expect unique constraint error
 * 6. [Optional] Try forbidden/restricted values if such policies exist
 * 7. Confirm error shape and code for all error scenarios
 */
export async function test_api_client_create_with_required_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Prepare valid payload
  const createInput: IApiClients.ICreate = {
    client_name: `partner-e2e-${Math.random().toString(36).slice(2,10)}`,
    contact_email: `qa${Math.floor(Math.random()*10000)}@example.com`,
    public_key: "-----BEGIN PUBLIC KEY-----\nABCD1234KEYMOCK\n-----END PUBLIC KEY-----",
    description: "Automated test API client for onboarding scenario.",
  };

  // Step 2: Create new API client
  const output: IApiClients =
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: createInput,
    });
  typia.assert(output);
  TestValidator.equals("client_name")(createInput.client_name)(output.client_name);
  TestValidator.equals("contact_email")(createInput.contact_email)(output.contact_email);
  TestValidator.equals("is_active")(true)(output.is_active);
  // Optionals may round-trip as null if absent, so skip strict check on them

  // Step 4: Test required field validation (missing client_name)
  await TestValidator.httpError("missing client_name should fail")(400)(async () => {
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        // client_name missing
        contact_email: "missing@ex.com",
        public_key: "FAKEKEY",
      } as any,
    });
  });

  // Step 4: Test required field validation (missing contact_email)
  await TestValidator.httpError("missing contact_email should fail")(400)(async () => {
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        client_name: "no-email-client",
        // contact_email missing
        public_key: "FAKEKEY",
      } as any,
    });
  });

  // Step 5: Unique constraint (duplicate client_name)
  await TestValidator.httpError("duplicate client_name should fail")(409)(async () => {
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        ...createInput,
        contact_email: `unique${Math.random().toString(36).slice(2,10)}@dup.com`, // Change email to keep only name duplicated
      },
    });
  });

  // Step 5: Unique constraint (duplicate contact_email)
  await TestValidator.httpError("duplicate contact_email should fail")(409)(async () => {
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        ...createInput,
        client_name: `other-unique-name-${Math.random().toString(36).slice(2,10)}`,
      },
    });
  });

  // Step 6 (Optional): Try forbidden values (example: reserved name)
  // This is speculative - add a real value if business policy present
  await TestValidator.httpError("reserved client_name should fail")(400)(async () => {
    await api.functional.apiOmnichannel.apiClients.post(connection, {
      body: {
        ...createInput,
        client_name: "admin", // Example reserved word
        contact_email: `special${Math.random().toString(36).slice(2,10)}@ex.com`,
      },
    });
  });
}
